INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-little-fox', 'the-little-fox', 'The Little Fox', 'The Little Fox', 'A curious little fox sets off into the forest and discovers that being brave means asking for help too.', 'Seekor rubah kecil yang penasaran menjelajahi hutan dan belajar bahwa berani juga berarti berani meminta bantuan.', 'cat_adventure', 'aut_axto-creative-team', 'sunrise', '🦊', 3, 7, 0, 'published', 8, 2392, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_1', 'bok_the-little-fox', 1, 'fox-1', 'Once upon a time, in a beautiful forest, there lived a little fox. He was curious, brave, and loved adventures.', 'Pada suatu waktu, di sebuah hutan yang indah, hiduplah seekor rubah kecil. Ia penasaran, berani, dan suka berpetualang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_2', 'bok_the-little-fox', 2, 'fox-2', 'Every morning, the little fox woke up early to explore a new corner of the forest.', 'Setiap pagi, rubah kecil itu bangun lebih awal untuk menjelajahi sudut hutan yang baru.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_3', 'bok_the-little-fox', 3, 'fox-3', 'One day, he found a path he had never seen before. It wound deep into the tall, whispering trees.', 'Suatu hari, ia menemukan jalan setapak yang belum pernah dilihatnya. Jalan itu berkelok masuk ke rimbunnya pepohonan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_4', 'bok_the-little-fox', 4, 'fox-4', 'He walked and walked, until suddenly the path split into three directions. The little fox did not know which way to go.', 'Ia berjalan terus, sampai tiba-tiba jalan itu bercabang menjadi tiga arah. Rubah kecil tidak tahu harus memilih arah mana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_5', 'bok_the-little-fox', 5, 'fox-5', 'A wise old owl saw him standing there. "Being brave doesn''t mean you have to know everything," she said. "It''s also brave to ask for help."', 'Seekor burung hantu tua yang bijak melihatnya berdiri kebingungan. "Berani bukan berarti harus tahu segalanya," katanya. "Meminta bantuan juga adalah keberanian."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_6', 'bok_the-little-fox', 6, 'fox-6', 'So the little fox asked the owl for directions. Together, they found the most beautiful meadow he had ever seen.', 'Maka rubah kecil pun bertanya arah kepada burung hantu. Bersama-sama, mereka menemukan padang rumput terindah yang pernah ia lihat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_7', 'bok_the-little-fox', 7, 'fox-7', 'From that day on, the little fox explored the forest with new friends by his side.', 'Sejak hari itu, rubah kecil menjelajahi hutan bersama teman-teman baru di sisinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-fox_8', 'bok_the-little-fox', 8, 'fox-8', 'And he learned that the best adventures are the ones we share with others. The end.', 'Dan ia belajar bahwa petualangan terbaik adalah yang dibagikan bersama orang lain. Selesai.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-fox_1', 'bok_the-little-fox', 1, 'What did the little fox love to do?', 'Apa yang disukai rubah kecil?', '["Sleeping all day","Exploring the forest","Baking cookies","Swimming in the sea"]', '["Tidur seharian","Menjelajahi hutan","Membuat kue","Berenang di laut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-fox_2', 'bok_the-little-fox', 2, 'Who helped the little fox when the path split into three?', 'Siapa yang membantu rubah kecil saat jalan bercabang tiga?', '["A rabbit","A wise old owl","A fisherman","His mother"]', '["Seekor kelinci","Burung hantu tua yang bijak","Seorang nelayan","Ibunya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-fox_3', 'bok_the-little-fox', 3, 'What is the lesson of the story?', 'Apa pelajaran dari cerita ini?', '["Never leave home","Asking for help is also brave","Foxes cannot get lost","Owls are scary"]', '["Jangan pernah keluar rumah","Meminta bantuan juga sebuah keberanian","Rubah tidak bisa tersesat","Burung hantu itu menakutkan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-brave-lion', 'the-brave-lion', 'The Brave Lion', 'The Brave Lion', 'A young lion who is afraid of the dark discovers that even the bravest hearts can feel scared sometimes.', 'Seekor singa muda yang takut gelap belajar bahwa hati yang paling berani pun boleh merasa takut.', 'cat_fairy-tales', 'aut_axto-creative-team', 'candy', '🦁', 3, 7, 0, 'published', 7, 3268, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_1', 'bok_the-brave-lion', 1, 'lion-1', 'In the golden savanna lived a young lion named Rico, with the fluffiest mane in the whole pride.', 'Di padang savana keemasan hiduplah seekor singa muda bernama Rico, dengan surai paling lebat di seluruh kawanan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_2', 'bok_the-brave-lion', 2, 'lion-2', 'Everyone said lions were the bravest animals of all. But at night, Rico was afraid of the dark.', 'Semua orang berkata singa adalah hewan paling berani. Tapi di malam hari, Rico takut pada gelap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_3', 'bok_the-brave-lion', 3, 'lion-3', 'He worried the other animals would laugh if they knew his secret, so he hid his fear every night.', 'Ia khawatir hewan lain akan menertawakannya jika tahu rahasianya, jadi ia menyembunyikan rasa takutnya setiap malam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_4', 'bok_the-brave-lion', 4, 'lion-4', 'One evening, his little sister Lulu saw him trembling by the rocks. "What is wrong, big brother?" she asked gently.', 'Suatu malam, adiknya, Lulu, melihatnya gemetar di dekat bebatuan. "Kenapa, Kak?" tanyanya lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_5', 'bok_the-brave-lion', 5, 'lion-5', 'Rico took a deep breath and told her the truth. Lulu smiled and said, "Even lions can be scared. That is okay."', 'Rico menarik napas dalam dan menceritakan yang sebenarnya. Lulu tersenyum, "Singa pun boleh takut. Itu tidak apa-apa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_6', 'bok_the-brave-lion', 6, 'lion-6', 'From then on, Lulu stayed close to him at night, and together they watched the stars until Rico felt brave again.', 'Sejak itu, Lulu selalu menemaninya di malam hari, dan bersama-sama mereka memandangi bintang hingga Rico merasa berani lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-brave-lion_7', 'bok_the-brave-lion', 7, 'lion-7', 'Rico learned that real bravery is not about never being afraid — it is about sharing your feelings with someone who loves you.', 'Rico belajar bahwa keberanian sejati bukan berarti tidak pernah takut — melainkan berani berbagi perasaan dengan orang yang menyayangimu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-brave-lion_1', 'bok_the-brave-lion', 1, 'What was Rico afraid of?', 'Apa yang ditakuti Rico?', '["Water","The dark","Loud noises","Other lions"]', '["Air","Gelap","Suara keras","Singa lain"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-brave-lion_2', 'bok_the-brave-lion', 2, 'Who helped Rico feel better?', 'Siapa yang membantu Rico merasa lebih baik?', '["His father","A zebra","His little sister Lulu","A hunter"]', '["Ayahnya","Seekor zebra","Adiknya, Lulu","Seorang pemburu"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-brave-lion_3', 'bok_the-brave-lion', 3, 'What does the story teach about bravery?', 'Apa yang diajarkan cerita ini tentang keberanian?', '["Brave means never being scared","It is okay to share your fears with someone who loves you","Only lions can be brave","You should hide your feelings"]', '["Berani berarti tidak pernah takut","Boleh berbagi rasa takut dengan orang yang menyayangimu","Hanya singa yang bisa berani","Kamu harus menyembunyikan perasaanmu"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_under-the-sea', 'under-the-sea', 'Under the Sea', 'Under the Sea', 'A little clownfish explores the coral reef and learns why every creature in the ocean matters.', 'Seekor ikan badut kecil menjelajahi terumbu karang dan belajar mengapa setiap makhluk laut itu penting.', 'cat_animals', 'aut_emily-clark', 'ocean', '🐠', 3, 8, 0, 'published', 7, 4986, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_1', 'bok_under-the-sea', 1, 'sea-1', 'Deep in the turquoise sea, a little clownfish named Coral lived in a soft anemone home.', 'Jauh di laut biru toska, seekor ikan badut kecil bernama Coral tinggal di rumah anemon yang lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_2', 'bok_under-the-sea', 2, 'sea-2', 'Coral loved to swim around the reef, waving hello to crabs, starfish, and gentle sea turtles.', 'Coral suka berenang mengelilingi terumbu karang, menyapa kepiting, bintang laut, dan penyu laut yang ramah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_3', 'bok_under-the-sea', 3, 'sea-3', 'One day, Coral noticed the coral reef looked pale and tired. "Why do you look sad?" she asked.', 'Suatu hari, Coral melihat terumbu karang tampak pucat dan lesu. "Kenapa kau terlihat sedih?" tanyanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_4', 'bok_under-the-sea', 4, 'sea-4', 'A wise sea turtle explained, "The reef needs clean water and all of us working together to stay healthy."', '"Terumbu karang butuh air bersih dan kita semua yang saling menjaga agar tetap sehat," jelas penyu laut yang bijak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_5', 'bok_under-the-sea', 5, 'sea-5', 'So Coral gathered her friends — crabs, shrimp, and small fish — to help clean up plastic that had drifted in.', 'Maka Coral mengajak teman-temannya — kepiting, udang, dan ikan-ikan kecil — untuk membersihkan sampah plastik yang hanyut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_6', 'bok_under-the-sea', 6, 'sea-6', 'Slowly, the reef began to sparkle with color again, and all the sea creatures cheered together.', 'Perlahan, terumbu karang mulai bersinar penuh warna kembali, dan semua makhluk laut bersorak bersama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_under-the-sea_7', 'bok_under-the-sea', 7, 'sea-7', 'Coral learned that even a small fish can help take care of a big, beautiful ocean.', 'Coral belajar bahwa ikan kecil pun bisa membantu menjaga lautan yang luas dan indah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_under-the-sea_1', 'bok_under-the-sea', 1, 'What kind of fish is Coral?', 'Ikan jenis apakah Coral?', '["A shark","A clownfish","A jellyfish","A dolphin"]', '["Hiu","Ikan badut","Ubur-ubur","Lumba-lumba"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_under-the-sea_2', 'bok_under-the-sea', 2, 'What did the reef need to stay healthy?', 'Apa yang dibutuhkan terumbu karang agar tetap sehat?', '["More sand","Clean water and teamwork","Loud music","More plastic"]', '["Lebih banyak pasir","Air bersih dan kerja sama","Musik keras","Lebih banyak plastik"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_under-the-sea_3', 'bok_under-the-sea', 3, 'What is the moral of the story?', 'Apa pesan moral dari cerita ini?', '["Only big animals matter","Even small creatures can help protect the ocean","Fish should stay alone","Plastic is good for the sea"]', '["Hanya hewan besar yang penting","Makhluk kecil pun bisa membantu menjaga laut","Ikan sebaiknya sendirian","Plastik baik untuk laut"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_dinosaur-world', 'dinosaur-world', 'Dinosaur World', 'Dinosaur World', 'A gentle young dinosaur discovers that being different from the other dinosaurs is what makes him special.', 'Seekor dinosaurus muda yang lembut menyadari bahwa perbedaannya justru membuatnya istimewa.', 'cat_dinosaur', 'aut_axto-creative-team', 'forest', '🦕', 4, 9, 0, 'published', 7, 3748, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_1', 'bok_dinosaur-world', 1, 'dino-1', 'Long, long ago, in a valley full of ferns, a little long-necked dinosaur named Dot hatched from her egg.', 'Dahulu kali, di sebuah lembah penuh pakis, seekor dinosaurus leher panjang kecil bernama Dot menetas dari telurnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_2', 'bok_dinosaur-world', 2, 'dino-2', 'All the other dinosaurs in the valley were loud and fast. But Dot liked to move slowly and look at little things.', 'Semua dinosaurus lain di lembah itu berisik dan cepat. Tapi Dot suka bergerak pelan dan memperhatikan hal-hal kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_3', 'bok_dinosaur-world', 3, 'dino-3', 'She noticed tiny flowers between the rocks, and patterns in the clouds that no one else seemed to see.', 'Ia memperhatikan bunga-bunga kecil di antara bebatuan, dan bentuk-bentuk awan yang tak disadari yang lain.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_4', 'bok_dinosaur-world', 4, 'dino-4', 'One day, a big storm confused the herd — they could not find the safe cave they always used.', 'Suatu hari, badai besar membuat kawanan itu bingung — mereka tidak bisa menemukan gua aman yang biasa mereka pakai.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_5', 'bok_dinosaur-world', 5, 'dino-5', 'But Dot, who always noticed small details, remembered a hidden path marked by a patch of blue flowers.', 'Tapi Dot, yang selalu memperhatikan detail kecil, mengingat jalan tersembunyi yang ditandai bunga biru.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_6', 'bok_dinosaur-world', 6, 'dino-6', 'She led the whole herd safely to the cave. Everyone cheered for careful, curious little Dot!', 'Ia memimpin seluruh kawanan dengan selamat ke gua itu. Semua bersorak untuk Dot yang teliti dan penasaran!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_dinosaur-world_7', 'bok_dinosaur-world', 7, 'dino-7', 'From that day, Dot understood that being different was not a weakness — it was her very own kind of strength.', 'Sejak hari itu, Dot mengerti bahwa menjadi berbeda bukanlah kelemahan — itu adalah kekuatannya sendiri.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_dinosaur-world_1', 'bok_dinosaur-world', 1, 'What did Dot like to do differently from the other dinosaurs?', 'Apa yang Dot suka lakukan berbeda dari dinosaurus lain?', '["Run very fast","Move slowly and notice small things","Roar loudly","Sleep all day"]', '["Berlari sangat cepat","Bergerak pelan dan memperhatikan hal kecil","Meraung keras","Tidur seharian"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_dinosaur-world_2', 'bok_dinosaur-world', 2, 'How did Dot help the herd during the storm?', 'Bagaimana Dot membantu kawanan saat badai?', '["She hid alone","She remembered a hidden path with blue flowers","She called for help loudly","She ran away"]', '["Ia bersembunyi sendirian","Ia mengingat jalan tersembunyi dengan bunga biru","Ia berteriak minta tolong","Ia melarikan diri"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_dinosaur-world_3', 'bok_dinosaur-world', 3, 'What is the lesson of the story?', 'Apa pelajaran dari cerita ini?', '["Being different can be a strength","Everyone must be the same","Storms are not dangerous","Only fast dinosaurs are useful"]', '["Menjadi berbeda bisa menjadi kekuatan","Semua orang harus sama","Badai tidak berbahaya","Hanya dinosaurus cepat yang berguna"]', 0, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_a-journey-to-space', 'a-journey-to-space', 'A Journey to Space', 'A Journey to Space', 'A young astronaut travels past the moon and stars, discovering how small — and how connected — our world truly is.', 'Seorang astronaut cilik terbang melewati bulan dan bintang, dan menyadari betapa kecil serta saling terhubungnya dunia kita.', 'cat_space', 'aut_axto-creative-team', 'cosmic', '🚀', 5, 10, 0, 'published', 7, 3542, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_1', 'bok_a-journey-to-space', 1, 'space-1', 'Maya always dreamed of the stars. One quiet night, a tiny silver rocket landed softly in her backyard.', 'Maya selalu memimpikan bintang-bintang. Suatu malam yang tenang, sebuah roket perak kecil mendarat lembut di halaman belakangnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_2', 'bok_a-journey-to-space', 2, 'space-2', 'A friendly robot named Orbit opened the hatch. "Would you like to see the universe?" it asked.', 'Sebuah robot ramah bernama Orbit membuka pintunya. "Mau melihat alam semesta?" tanyanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_3', 'bok_a-journey-to-space', 3, 'space-3', 'They zoomed past the Moon, where Maya bounced in the low gravity and giggled with delight.', 'Mereka melesat melewati Bulan, tempat Maya melompat-lompat dalam gravitasi rendah sambil tertawa senang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_4', 'bok_a-journey-to-space', 4, 'space-4', 'Next, they flew by Saturn, its icy rings sparkling like a giant necklace made of diamonds.', 'Selanjutnya, mereka terbang melewati Saturnus, cincin esnya berkilau seperti kalung raksasa dari berlian.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_5', 'bok_a-journey-to-space', 5, 'space-5', 'Looking back, Maya saw planet Earth — a tiny blue marble glowing gently in the dark.', 'Menoleh ke belakang, Maya melihat planet Bumi — kelereng biru kecil yang bersinar lembut di kegelapan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_6', 'bok_a-journey-to-space', 6, 'space-6', '"It looks so small," Maya whispered. "That is our whole home," said Orbit. "Everyone we love is right there."', '"Kecil sekali," bisik Maya. "Itulah rumah kita semua," kata Orbit. "Semua orang yang kita sayangi ada di sana."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-journey-to-space_7', 'bok_a-journey-to-space', 7, 'space-7', 'Maya returned home with a new feeling in her heart — Earth was small in the universe, but full of everything she loved.', 'Maya pulang dengan perasaan baru di hatinya — Bumi memang kecil di alam semesta, tapi penuh dengan segala yang ia cintai.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-journey-to-space_1', 'bok_a-journey-to-space', 1, 'Who was Maya''s robot friend?', 'Siapa nama robot teman Maya?', '["Orbit","Rocket","Star","Luna"]', '["Orbit","Rocket","Star","Luna"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-journey-to-space_2', 'bok_a-journey-to-space', 2, 'What did Maya see that looked like a necklace of diamonds?', 'Apa yang dilihat Maya yang tampak seperti kalung berlian?', '["The Moon''s dust","Saturn''s rings","The Sun","A comet"]', '["Debu Bulan","Cincin Saturnus","Matahari","Komet"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-journey-to-space_3', 'bok_a-journey-to-space', 3, 'What did Maya learn about Earth?', 'Apa yang dipelajari Maya tentang Bumi?', '["It is the biggest planet","It is small but full of everyone she loves","It has rings like Saturn","It is not important"]', '["Bumi adalah planet terbesar","Bumi kecil tapi penuh orang yang ia sayangi","Bumi memiliki cincin seperti Saturnus","Bumi tidak penting"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_robot-and-me', 'robot-and-me', 'Robot and Me', 'Robot and Me', 'A shy inventor builds a small robot friend and learns how curiosity and kindness go hand in hand.', 'Seorang anak pemalu membuat teman robot kecil dan belajar bahwa rasa ingin tahu dan kebaikan hati berjalan beriringan.', 'cat_science', 'aut_david-lee', 'meadow', '🤖', 5, 10, 0, 'published', 7, 1968, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_1', 'bok_robot-and-me', 1, 'robot-1', 'Ken loved building things out of old boxes, gears, and batteries in his garage workshop.', 'Ken suka membuat berbagai hal dari kardus bekas, roda gigi, dan baterai di bengkel garasinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_2', 'bok_robot-and-me', 2, 'robot-2', 'One rainy afternoon, he finally finished his biggest project yet: a small robot he named Bolt.', 'Suatu sore yang hujan, ia akhirnya menyelesaikan proyek terbesarnya: robot kecil yang ia beri nama Bolt.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_3', 'bok_robot-and-me', 3, 'robot-3', 'Bolt could not talk, but it beeped happily and rolled after Ken wherever he went.', 'Bolt tidak bisa berbicara, tapi ia berbunyi "beep" gembira dan mengikuti Ken ke mana pun ia pergi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_4', 'bok_robot-and-me', 4, 'robot-4', 'At school, Ken was too shy to share his invention. He worried the other kids might laugh.', 'Di sekolah, Ken terlalu malu untuk menunjukkan ciptaannya. Ia khawatir teman-teman akan menertawakannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_5', 'bok_robot-and-me', 5, 'robot-5', 'But Bolt rolled out of his backpack by accident — and beeped so cheerfully that the whole class laughed with joy, not mockery.', 'Namun Bolt tidak sengaja menggelinding keluar dari tasnya — dan berbunyi begitu ceria hingga seisi kelas tertawa senang, bukan mengejek.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_6', 'bok_robot-and-me', 6, 'robot-6', 'Soon, every classmate wanted to help Ken build more robot friends, using boxes and gears of their own.', 'Segera, semua teman sekelas ingin membantu Ken membuat lebih banyak teman robot, menggunakan kardus dan roda gigi mereka sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_robot-and-me_7', 'bok_robot-and-me', 7, 'robot-7', 'Ken learned that sharing what you love can turn a quiet idea into something everyone enjoys together.', 'Ken belajar bahwa berbagi apa yang kita sukai bisa mengubah ide yang sunyi menjadi sesuatu yang dinikmati bersama.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_robot-and-me_1', 'bok_robot-and-me', 1, 'What did Ken name his robot?', 'Siapa nama yang Ken berikan untuk robotnya?', '["Bolt","Spark","Gizmo","Circuit"]', '["Bolt","Spark","Gizmo","Circuit"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_robot-and-me_2', 'bok_robot-and-me', 2, 'Why was Ken afraid to share his invention at school?', 'Kenapa Ken takut menunjukkan ciptaannya di sekolah?', '["He forgot it at home","He worried classmates would laugh","It was broken","He did not like robots"]', '["Ia lupa membawanya","Ia khawatir teman-teman menertawakannya","Robotnya rusak","Ia tidak suka robot"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_robot-and-me_3', 'bok_robot-and-me', 3, 'What happened when the class saw Bolt?', 'Apa yang terjadi saat kelas melihat Bolt?', '["They ignored it","They laughed with joy and wanted to help build more","The teacher took it away","Everyone got scared"]', '["Mereka mengabaikannya","Mereka tertawa senang dan ingin membantu membuat lebih banyak","Guru mengambilnya","Semua orang ketakutan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_goodnight-little-owl', 'goodnight-little-owl', 'Goodnight, Little Owl', 'Selamat Malam, Burung Hantu Kecil', 'A tiny owl who is afraid of the daylight learns that everyone has their own perfect time to shine.', 'Burung hantu kecil yang takut cahaya siang belajar bahwa setiap makhluk punya waktunya sendiri untuk bersinar.', 'cat_bedtime', 'aut_siti-aminah', 'night', '🦉', 2, 6, 0, 'published', 7, 3856, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_1', 'bok_goodnight-little-owl', 1, 'owl-1', 'High in an old oak tree lived a tiny owl named Pip, who loved the cool, quiet night.', 'Tinggi di pohon ek tua, hiduplah burung hantu kecil bernama Pip, yang menyukai malam yang sejuk dan tenang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_2', 'bok_goodnight-little-owl', 2, 'owl-2', 'While other animals slept, Pip opened her big round eyes and watched the moon rise softly.', 'Saat hewan lain tertidur, Pip membuka mata bulatnya yang besar dan menyaksikan bulan terbit perlahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_3', 'bok_goodnight-little-owl', 3, 'owl-3', 'She gently glided from branch to branch, humming a soft tune only the stars could hear.', 'Ia terbang lembut dari dahan ke dahan, bersenandung pelan yang hanya bisa didengar oleh bintang-bintang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_4', 'bok_goodnight-little-owl', 4, 'owl-4', 'Down below, a little firefly blinked her light. "Aren''t you scared of the dark?" she asked.', 'Di bawah sana, seekor kunang-kunang kecil berkedip. "Kamu tidak takut gelap?" tanyanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_5', 'bok_goodnight-little-owl', 5, 'owl-5', '"The dark is my favorite blanket," said Pip with a smile. "It is soft, quiet, and full of stars."', '"Gelap adalah selimut favoritku," kata Pip sambil tersenyum. "Lembut, tenang, dan penuh bintang."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_6', 'bok_goodnight-little-owl', 6, 'owl-6', 'The firefly smiled back and lit up beside her, and together they made the night feel warm and cozy.', 'Kunang-kunang itu tersenyum balik dan bersinar di sampingnya, dan bersama-sama mereka membuat malam terasa hangat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_goodnight-little-owl_7', 'bok_goodnight-little-owl', 7, 'owl-7', 'As the forest grew sleepy and still, Pip whispered goodnight to the moon — and so do you. Sweet dreams.', 'Saat hutan mulai lelap dan tenang, Pip berbisik selamat malam pada bulan — begitu juga kamu. Mimpi indah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_goodnight-little-owl_1', 'bok_goodnight-little-owl', 1, 'What is Pip''s name?', 'Siapa nama burung hantu kecil itu?', '["Pip","Hoot","Luna","Star"]', '["Pip","Hoot","Luna","Star"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_goodnight-little-owl_2', 'bok_goodnight-little-owl', 2, 'What did Pip call the dark?', 'Apa julukan Pip untuk kegelapan?', '["Her favorite blanket","Something scary","A monster","Cold and lonely"]', '["Selimut favoritnya","Sesuatu yang menakutkan","Monster","Dingin dan sepi"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_goodnight-little-owl_3', 'bok_goodnight-little-owl', 3, 'Who became friends with Pip?', 'Siapa yang berteman dengan Pip?', '["A firefly","A wolf","A cat","A bear"]', '["Kunang-kunang","Serigala","Kucing","Beruang"]', 0, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-letter-parade', 'the-letter-parade', 'The Letter Parade', 'Parade Huruf', 'The letters of the alphabet come to life for a parade, helping a little girl fall in love with reading.', 'Huruf-huruf abjad hidup dan berbaris dalam parade, membuat seorang gadis kecil jatuh cinta pada membaca.', 'cat_learning', 'aut_axto-creative-team', 'dusk', '🔤', 3, 6, 0, 'published', 6, 1613, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_1', 'bok_the-letter-parade', 1, 'letter-1', 'Every night before bed, little Nadia said, "I don''t like letters. They look like squiggly lines."', 'Setiap malam sebelum tidur, Nadia kecil berkata, "Aku tidak suka huruf. Bentuknya seperti garis-garis aneh."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_2', 'bok_the-letter-parade', 2, 'letter-2', 'One night, a shining letter A hopped off her book. "Would you like to meet my friends?" it asked cheerfully.', 'Suatu malam, huruf A yang berkilau melompat keluar dari bukunya. "Mau berkenalan dengan teman-temanku?" tanyanya riang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_3', 'bok_the-letter-parade', 3, 'letter-3', 'Suddenly, B bounced in like a ball, C curled up like a smiling moon, and D marched like a little drum.', 'Tiba-tiba, B memantul seperti bola, C melengkung seperti bulan yang tersenyum, dan D berbaris seperti drum kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_4', 'bok_the-letter-parade', 4, 'letter-4', 'The letters lined up into a parade, and when they marched together, they spelled Nadia''s name!', 'Huruf-huruf itu berbaris membentuk parade, dan ketika berjalan bersama, mereka mengeja nama Nadia!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_5', 'bok_the-letter-parade', 5, 'letter-5', '"Every letter is a puzzle piece," said A. "Put enough pieces together, and you can tell any story in the world."', '"Setiap huruf adalah kepingan puzzle," kata A. "Kumpulkan cukup banyak kepingan, dan kamu bisa menceritakan kisah apa pun di dunia."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-parade_6', 'bok_the-letter-parade', 6, 'letter-6', 'From that night on, Nadia looked at every book with new excitement, ready to meet the letters inside.', 'Sejak malam itu, Nadia memandang setiap buku dengan semangat baru, siap bertemu huruf-huruf di dalamnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-parade_1', 'bok_the-letter-parade', 1, 'What did Nadia think of letters at first?', 'Apa pendapat Nadia tentang huruf pada awalnya?', '["She loved them","She thought they were squiggly lines","She thought they were tasty","She ignored them"]', '["Ia menyukainya","Ia pikir bentuknya aneh","Ia pikir rasanya enak","Ia mengabaikannya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-parade_2', 'bok_the-letter-parade', 2, 'What did the letters spell when they marched together?', 'Apa yang dieja huruf-huruf saat berbaris bersama?', '["Nadia''s name","A number","A song","Nothing"]', '["Nama Nadia","Sebuah angka","Sebuah lagu","Tidak ada apa-apa"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-parade_3', 'bok_the-letter-parade', 3, 'What did letter A compare letters to?', 'Huruf A membandingkan huruf dengan apa?', '["Puzzle pieces","Rocks","Clouds","Shoes"]', '["Kepingan puzzle","Batu","Awan","Sepatu"]', 0, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-honest-woodcutter', 'the-honest-woodcutter', 'The Honest Woodcutter', 'Tukang Kayu yang Jujur', 'A retelling of a timeless folk tale about a poor woodcutter whose honesty is rewarded beyond measure.', 'Kisah rakyat abadi tentang tukang kayu miskin yang kejujurannya diganjar dengan berlipat ganda.', 'cat_moral-stories', 'aut_axto-creative-team', 'meadow', '🪓', 4, 9, 0, 'published', 7, 2050, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_1', 'bok_the-honest-woodcutter', 1, 'wood-1', 'Near a quiet village lived a poor woodcutter named Tomo, who worked hard every single day to feed his family.', 'Dekat sebuah desa yang tenang, hiduplah tukang kayu miskin bernama Tomo, yang bekerja keras setiap hari demi keluarganya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_2', 'bok_the-honest-woodcutter', 2, 'wood-2', 'One afternoon, while cutting wood by the river, his old iron axe slipped from his hands and sank into the water.', 'Suatu siang, saat menebang kayu di tepi sungai, kapak besinya yang tua terlepas dari tangannya dan tenggelam ke dalam air.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_3', 'bok_the-honest-woodcutter', 3, 'wood-3', 'Tomo sat down and cried, for that old axe was his only tool to earn a living. Suddenly, the river sparkled with light.', 'Tomo duduk dan menangis, sebab kapak tua itu adalah satu-satunya alat untuk mencari nafkah. Tiba-tiba, sungai itu berkilau cahaya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_4', 'bok_the-honest-woodcutter', 4, 'wood-4', 'A kind spirit of the river rose up, holding a golden axe. "Is this your axe?" she asked gently.', 'Seorang roh sungai yang baik hati muncul, membawa kapak emas. "Apakah ini kapakmu?" tanyanya lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_5', 'bok_the-honest-woodcutter', 5, 'wood-5', '"No," said Tomo honestly, "mine was old and made of iron, not gold." The spirit smiled and dove again, returning with a silver axe — but Tomo said the same.', '"Bukan," jawab Tomo jujur, "milikku sudah tua dan terbuat dari besi, bukan emas." Roh itu tersenyum dan menyelam lagi, kembali membawa kapak perak — namun Tomo tetap berkata jujur bahwa itu bukan miliknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_6', 'bok_the-honest-woodcutter', 6, 'wood-6', 'Finally, she returned his old iron axe. "Because you told the truth," she said, "please accept all three axes as a gift."', 'Akhirnya, ia mengembalikan kapak besi milik Tomo. "Karena kau berkata jujur," katanya, "terimalah ketiga kapak ini sebagai hadiah."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter_7', 'bok_the-honest-woodcutter', 7, 'wood-7', 'Tomo thanked her with a full heart, and from that day, his honesty was known throughout the whole village.', 'Tomo berterima kasih dengan hati yang penuh, dan sejak hari itu, kejujurannya dikenal di seluruh desa.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter_1', 'bok_the-honest-woodcutter', 1, 'What happened to Tomo''s axe?', 'Apa yang terjadi pada kapak Tomo?', '["It broke","It fell into the river","It was stolen","It turned to gold"]', '["Patah","Jatuh ke sungai","Dicuri","Berubah jadi emas"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter_2', 'bok_the-honest-woodcutter', 2, 'What did Tomo say when shown the golden axe?', 'Apa jawaban Tomo saat ditunjukkan kapak emas?', '["\"Yes, that is mine!\"","\"No, mine was iron\"","He said nothing","He took it anyway"]', '["\"Ya, itu milikku!\"","\"Bukan, milikku dari besi\"","Ia diam saja","Ia tetap mengambilnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter_3', 'bok_the-honest-woodcutter', 3, 'Why did the river spirit reward Tomo?', 'Mengapa roh sungai memberi hadiah kepada Tomo?', '["Because he was rich","Because he was honest","Because he was fast","Because he asked for gold"]', '["Karena ia kaya","Karena ia jujur","Karena ia cepat","Karena ia meminta emas"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-magic-forest', 'the-magic-forest', 'The Magic Forest', 'Hutan Ajaib', 'Two siblings discover a hidden forest where every tree grants a wish — as long as it is a kind one.', 'Dua bersaudara menemukan hutan tersembunyi tempat setiap pohon mengabulkan permintaan — asal permintaan itu baik.', 'cat_fairy-tales', 'aut_sarah-johnson', 'forest', '🌳', 3, 8, 0, 'published', 7, 3680, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_1', 'bok_the-magic-forest', 1, 'forest-1', 'Siblings Aya and Budi were chasing a butterfly when they stumbled into a part of the forest they had never seen.', 'Kakak beradik Aya dan Budi sedang mengejar kupu-kupu ketika tiba-tiba mereka tersesat ke bagian hutan yang belum pernah mereka lihat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_2', 'bok_the-magic-forest', 2, 'forest-2', 'The leaves shimmered like silver, and the air smelled like warm honey and rain.', 'Daun-daunnya berkilau seperti perak, dan udaranya beraroma madu hangat dan hujan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_3', 'bok_the-magic-forest', 3, 'forest-3', 'An old tree with kind, glowing eyes spoke softly: "This is the Wishing Forest. Every tree here can grant one kind wish."', 'Sebatang pohon tua bermata lembut dan bercahaya berkata pelan, "Ini Hutan Permintaan. Setiap pohon di sini bisa mengabulkan satu permintaan baik."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_4', 'bok_the-magic-forest', 4, 'forest-4', 'Budi wished for a mountain of candy, but the tree only rustled and stayed silent — that wish was not kind, only for himself.', 'Budi meminta gunung permen, tapi pohon itu hanya bergemerisik dan diam — permintaan itu tidak baik, hanya untuk dirinya sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_5', 'bok_the-magic-forest', 5, 'forest-5', 'Then Aya wished for the nearby stream to always have clean water for every animal in the forest.', 'Lalu Aya berharap agar sungai di dekat sana selalu memiliki air bersih untuk semua hewan di hutan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_6', 'bok_the-magic-forest', 6, 'forest-6', 'The tree glowed brightly, and the stream sparkled clean and clear. "A wish for others always grows the strongest," it said.', 'Pohon itu bersinar terang, dan sungai berkilau bersih dan jernih. "Permintaan untuk orang lain selalu tumbuh paling kuat," katanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-forest_7', 'bok_the-magic-forest', 7, 'forest-7', 'Budi learned from his sister, and the next year, he returned to wish for shelter for the forest''s smallest animals.', 'Budi belajar dari kakaknya, dan tahun berikutnya, ia kembali untuk berharap ada tempat berlindung bagi hewan-hewan terkecil di hutan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-forest_1', 'bok_the-magic-forest', 1, 'What did the trees in the Wishing Forest grant?', 'Apa yang dikabulkan pohon-pohon di Hutan Permintaan?', '["Any wish at all","Only kind wishes","Only wishes for candy","No wishes"]', '["Semua jenis permintaan","Hanya permintaan baik","Hanya permintaan permen","Tidak ada permintaan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-forest_2', 'bok_the-magic-forest', 2, 'Why didn''t Budi''s first wish come true?', 'Mengapa permintaan pertama Budi tidak dikabulkan?', '["It was too big","It was only for himself","The tree was asleep","He asked incorrectly"]', '["Terlalu besar","Hanya untuk dirinya sendiri","Pohonnya sedang tidur","Ia salah bertanya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-forest_3', 'bok_the-magic-forest', 3, 'What did Aya wish for?', 'Apa yang diminta Aya?', '["A mountain of candy","Clean water for the animals","A new toy","To go home"]', '["Gunung permen","Air bersih untuk hewan-hewan","Mainan baru","Pulang ke rumah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_princess-aira-and-the-lost-kite', 'princess-aira-and-the-lost-kite', 'Princess Aira and the Lost Kite', 'Putri Aira dan Layang-Layang yang Hilang', 'A young princess sets aside her crown to chase her kite across the kingdom, making unlikely friends along the way.', 'Seorang putri kecil melepas mahkotanya untuk mengejar layang-layangnya, dan menemukan sahabat-sahabat baru yang tak terduga.', 'cat_fairy-tales', 'aut_siti-aminah', 'dusk', '👑', 4, 8, 0, 'published', 7, 1273, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_1', 'bok_princess-aira-and-the-lost-kite', 1, 'aira-1', 'In a kingdom by the hills, Princess Aira loved flying her red kite more than wearing her golden crown.', 'Di sebuah kerajaan di antara bukit-bukit, Putri Aira lebih suka menerbangkan layang-layang merahnya daripada memakai mahkota emas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_2', 'bok_princess-aira-and-the-lost-kite', 2, 'aira-2', 'One windy afternoon, a strong gust snatched her kite away, carrying it over the castle walls.', 'Suatu sore yang berangin, hembusan kencang merenggut layang-layangnya, membawanya melewati tembok istana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_3', 'bok_princess-aira-and-the-lost-kite', 3, 'aira-3', 'Without a second thought, Aira took off her crown, put on her walking boots, and ran after it.', 'Tanpa berpikir dua kali, Aira melepas mahkotanya, memakai sepatu botnya, dan berlari mengejarnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_4', 'bok_princess-aira-and-the-lost-kite', 4, 'aira-4', 'She met a baker boy who showed her a shortcut through the market, and a farmer girl who pointed toward the hills.', 'Ia bertemu seorang anak tukang roti yang menunjukkan jalan pintas melalui pasar, dan seorang anak petani yang menunjuk ke arah bukit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_5', 'bok_princess-aira-and-the-lost-kite', 5, 'aira-5', 'At last, she found her kite gently caught in a tall apple tree, with new friends cheering beside her.', 'Akhirnya, ia menemukan layang-layangnya tersangkut lembut di pohon apel yang tinggi, dengan teman-teman baru bersorak di sampingnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_6', 'bok_princess-aira-and-the-lost-kite', 6, 'aira-6', 'Together they climbed and freed the kite, laughing as it soared back into the golden evening sky.', 'Bersama-sama mereka memanjat dan melepaskan layang-layang itu, tertawa saat ia kembali terbang ke langit senja keemasan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-aira-and-the-lost-kite_7', 'bok_princess-aira-and-the-lost-kite', 7, 'aira-7', 'Aira returned to the castle without her crown, but with something far more precious — new friends from every corner of the kingdom.', 'Aira kembali ke istana tanpa mahkotanya, tetapi membawa sesuatu yang jauh lebih berharga — sahabat baru dari setiap penjuru kerajaan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-aira-and-the-lost-kite_1', 'bok_princess-aira-and-the-lost-kite', 1, 'What did Princess Aira love more than her crown?', 'Apa yang lebih disukai Putri Aira daripada mahkotanya?', '["Flying her kite","Eating cake","Reading books","Playing music"]', '["Menerbangkan layang-layang","Makan kue","Membaca buku","Bermain musik"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-aira-and-the-lost-kite_2', 'bok_princess-aira-and-the-lost-kite', 2, 'Who helped Aira find her way?', 'Siapa yang membantu Aira menemukan jalan?', '["A baker boy and a farmer girl","The king","A dragon","No one"]', '["Anak tukang roti dan anak petani","Sang raja","Seekor naga","Tidak ada yang membantu"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-aira-and-the-lost-kite_3', 'bok_princess-aira-and-the-lost-kite', 3, 'What did Aira gain by the end of the story?', 'Apa yang didapat Aira di akhir cerita?', '["A new crown","New friends","A new kite","Gold coins"]', '["Mahkota baru","Sahabat baru","Layang-layang baru","Koin emas"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_counting-stars-with-mira', 'counting-stars-with-mira', 'Counting Stars with Mira', 'Menghitung Bintang Bersama Mira', 'Mira and her grandfather count stars one by one and discover that numbers can be magical.', 'Mira dan kakeknya menghitung bintang satu per satu dan menemukan bahwa angka bisa terasa ajaib.', 'cat_numbers', 'aut_axto-creative-team', 'cosmic', '⭐', 3, 6, 0, 'published', 6, 1408, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_1', 'bok_counting-stars-with-mira', 1, 'mira-1', 'Every clear night, Mira climbed onto the roof with Grandpa to look at the sky.', 'Setiap malam cerah, Mira naik ke atap bersama Kakek untuk memandangi langit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_2', 'bok_counting-stars-with-mira', 2, 'mira-2', '"Let''s count the stars," said Grandpa. "One star, two stars, three stars!"', '"Ayo kita hitung bintangnya," kata Kakek. "Satu bintang, dua bintang, tiga bintang!"');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_3', 'bok_counting-stars-with-mira', 3, 'mira-3', 'Mira giggled and pointed at four twinkling stars shaped like a kite, then five more near the moon.', 'Mira tertawa dan menunjuk empat bintang berkelip berbentuk layang-layang, lalu lima lagi dekat bulan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_4', 'bok_counting-stars-with-mira', 4, 'mira-4', 'By the time they reached ten, Mira could count all on her own, without any help at all.', 'Saat mereka sampai hitungan sepuluh, Mira sudah bisa menghitung sendiri tanpa bantuan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_5', 'bok_counting-stars-with-mira', 5, 'mira-5', '"Numbers help us see how big the world is," said Grandpa, "from one tiny star to a thousand."', '"Angka membantu kita melihat seberapa besar dunia ini," kata Kakek, "dari satu bintang kecil sampai seribu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_counting-stars-with-mira_6', 'bok_counting-stars-with-mira', 6, 'mira-6', 'From that night on, Mira counted everything she loved — her toys, her books, and her stars.', 'Sejak malam itu, Mira menghitung semua yang ia sukai — mainannya, bukunya, dan bintang-bintangnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_counting-stars-with-mira_1', 'bok_counting-stars-with-mira', 1, 'Who did Mira count stars with?', 'Bersama siapa Mira menghitung bintang?', '["Her teacher","Grandpa","Her dog","A neighbor"]', '["Gurunya","Kakek","Anjingnya","Tetangga"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_counting-stars-with-mira_2', 'bok_counting-stars-with-mira', 2, 'How many stars could Mira count by the end?', 'Sampai angka berapa Mira bisa menghitung di akhir cerita?', '["Five","Ten","Twenty","One hundred"]', '["Lima","Sepuluh","Dua puluh","Seratus"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_counting-stars-with-mira_3', 'bok_counting-stars-with-mira', 3, 'What did Mira start counting after that night?', 'Apa yang mulai dihitung Mira setelah malam itu?', '["Only stars","Everything she loved","Nothing","Only numbers on a clock"]', '["Hanya bintang","Semua yang ia sukai","Tidak ada","Hanya angka di jam"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_two-best-friends-and-one-umbrella', 'two-best-friends-and-one-umbrella', 'Two Best Friends and One Umbrella', 'Dua Sahabat dan Satu Payung', 'When sudden rain catches two friends with only one umbrella, they learn that sharing makes any storm smaller.', 'Saat hujan tiba-tiba turun dan hanya ada satu payung, dua sahabat belajar bahwa berbagi membuat badai apa pun terasa lebih kecil.', 'cat_friendship', 'aut_axto-creative-team', 'ocean', '☂️', 3, 7, 0, 'published', 6, 1631, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_1', 'bok_two-best-friends-and-one-umbrella', 1, 'friends-1', 'Dara and Beni walked home from school together every single day, rain or shine.', 'Dara dan Beni selalu berjalan pulang sekolah bersama setiap hari, hujan atau cerah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_2', 'bok_two-best-friends-and-one-umbrella', 2, 'friends-2', 'One afternoon, dark clouds rolled in fast, and only Dara remembered to bring an umbrella.', 'Suatu sore, awan gelap datang dengan cepat, dan hanya Dara yang ingat membawa payung.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_3', 'bok_two-best-friends-and-one-umbrella', 3, 'friends-3', '"You take it," said Dara. "No, you take it," said Beni. Neither wanted the other to get wet.', '"Kamu pakai saja," kata Dara. "Tidak, kamu saja," kata Beni. Tak ada yang mau temannya basah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_4', 'bok_two-best-friends-and-one-umbrella', 4, 'friends-4', 'Then Dara had an idea. "Let''s hold it together, in the middle, so we both stay dry!"', 'Lalu Dara punya ide. "Ayo kita pegang bersama, di tengah, supaya kita berdua tetap kering!"');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_5', 'bok_two-best-friends-and-one-umbrella', 5, 'friends-5', 'They laughed as they splashed through puddles, shoulder to shoulder under the small umbrella.', 'Mereka tertawa sambil menerjang genangan air, berdampingan di bawah payung kecil itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_two-best-friends-and-one-umbrella_6', 'bok_two-best-friends-and-one-umbrella', 6, 'friends-6', 'They reached home a little damp at the edges, but happier than any dry walk alone.', 'Mereka sampai rumah dengan sedikit basah di ujung baju, tapi lebih bahagia daripada jalan sendirian dalam keadaan kering.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_two-best-friends-and-one-umbrella_1', 'bok_two-best-friends-and-one-umbrella', 1, 'Who remembered to bring an umbrella?', 'Siapa yang ingat membawa payung?', '["Beni","Dara","Their teacher","No one"]', '["Beni","Dara","Gurunya","Tidak ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_two-best-friends-and-one-umbrella_2', 'bok_two-best-friends-and-one-umbrella', 2, 'How did they solve the umbrella problem?', 'Bagaimana mereka menyelesaikan masalah payung itu?', '["They ran home separately","They held it together","They waited for the rain to stop","They called a taxi"]', '["Mereka lari pulang sendiri-sendiri","Mereka memegangnya bersama","Mereka menunggu hujan reda","Mereka memanggil taksi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_two-best-friends-and-one-umbrella_3', 'bok_two-best-friends-and-one-umbrella', 3, 'What is the lesson of this story?', 'Apa pelajaran dari cerita ini?', '["Always walk home alone","Sharing makes hard moments easier together","Umbrellas are not useful","Rain should be avoided at all costs"]', '["Selalu jalan pulang sendirian","Berbagi membuat saat sulit terasa lebih ringan bersama","Payung tidak berguna","Hujan harus dihindari dengan segala cara"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_captain-kindness-saves-the-day', 'captain-kindness-saves-the-day', 'Captain Kindness Saves the Day', 'Captain Kindness Menyelamatkan Hari', 'A boy discovers that his cardboard cape and a kind heart make him a real kind of hero.', 'Seorang anak menyadari bahwa jubah kardusnya dan hati yang baik menjadikannya pahlawan sungguhan.', 'cat_superheroes', 'aut_axto-creative-team', 'dusk', '🦸', 4, 8, 0, 'published', 6, 1755, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_1', 'bok_captain-kindness-saves-the-day', 1, 'hero-1', 'Eli wore a cardboard cape everywhere he went, pretending to be a mighty superhero.', 'Eli memakai jubah kardus ke mana pun ia pergi, berpura-pura menjadi pahlawan super yang hebat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_2', 'bok_captain-kindness-saves-the-day', 2, 'hero-2', 'He practiced flying poses and superhero landings, but he had never actually saved anyone.', 'Ia berlatih pose terbang dan gaya mendarat pahlawan, tapi belum pernah benar-benar menolong siapa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_3', 'bok_captain-kindness-saves-the-day', 3, 'hero-3', 'At the park, he saw a little girl crying because her balloon had floated into a tall tree.', 'Di taman, ia melihat seorang gadis kecil menangis karena balonnya tersangkut di pohon tinggi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_4', 'bok_captain-kindness-saves-the-day', 4, 'hero-4', '"Don''t worry! Captain Kindness is here!" Eli called out, and he found a long stick to help.', '"Jangan khawatir! Captain Kindness datang!" seru Eli, dan ia mencari tongkat panjang untuk membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_5', 'bok_captain-kindness-saves-the-day', 5, 'hero-5', 'With a gentle poke, the balloon floated back down, and the little girl smiled brightly.', 'Dengan colekan lembut, balon itu melayang turun kembali, dan gadis kecil itu tersenyum cerah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-kindness-saves-the-day_6', 'bok_captain-kindness-saves-the-day', 6, 'hero-6', 'Eli realized his real superpower was not flying — it was noticing when someone needed help.', 'Eli menyadari kekuatan sejatinya bukanlah terbang — melainkan peka saat ada yang membutuhkan bantuan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-kindness-saves-the-day_1', 'bok_captain-kindness-saves-the-day', 1, 'What did Eli wear as his superhero costume?', 'Apa yang dipakai Eli sebagai kostum pahlawannya?', '["A cardboard cape","A real cape","A crown","Wings"]', '["Jubah kardus","Jubah sungguhan","Mahkota","Sayap"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-kindness-saves-the-day_2', 'bok_captain-kindness-saves-the-day', 2, 'How did Eli help the little girl?', 'Bagaimana Eli membantu gadis kecil itu?', '["He flew up to get the balloon","He used a long stick","He called her parents","He gave her a new balloon"]', '["Ia terbang mengambil balon","Ia menggunakan tongkat panjang","Ia memanggil orang tuanya","Ia memberi balon baru"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-kindness-saves-the-day_3', 'bok_captain-kindness-saves-the-day', 3, 'What did Eli learn was his real superpower?', 'Apa yang Eli sadari sebagai kekuatan sejatinya?', '["Flying","Noticing when someone needs help","Being invisible","Super strength"]', '["Terbang","Peka saat ada yang butuh bantuan","Menghilang","Kekuatan super"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_trucky-the-brave-fire-truck', 'trucky-the-brave-fire-truck', 'Trucky the Brave Fire Truck', 'Trucky, Mobil Pemadam yang Berani', 'A young fire truck who feels too small learns that courage, not size, is what makes a rescue vehicle brave.', 'Sebuah mobil pemadam kebakaran kecil yang merasa terlalu mungil belajar bahwa keberanian, bukan ukuran, yang membuatnya hebat.', 'cat_vehicles', 'aut_axto-creative-team', 'candy', '🚒', 3, 7, 0, 'published', 6, 1690, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_1', 'bok_trucky-the-brave-fire-truck', 1, 'truck-1', 'At Maple Street Fire Station, the newest fire truck was small and shiny red. His name was Trucky.', 'Di Stasiun Pemadam Jalan Maple, mobil pemadam terbaru berukuran kecil dan merah mengkilap. Namanya Trucky.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_2', 'bok_trucky-the-brave-fire-truck', 2, 'truck-2', 'The big trucks could carry tall ladders and huge hoses. Trucky worried he was too small to help.', 'Truk-truk besar bisa membawa tangga tinggi dan selang raksasa. Trucky khawatir ia terlalu kecil untuk membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_3', 'bok_trucky-the-brave-fire-truck', 3, 'truck-3', 'One day, an alarm rang for a kitten stuck in a narrow drainpipe that no big truck could reach.', 'Suatu hari, alarm berbunyi untuk seekor kucing kecil yang terjebak di pipa saluran sempit yang tak terjangkau truk besar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_4', 'bok_trucky-the-brave-fire-truck', 4, 'truck-4', '"This is a job for someone small and brave," said the fire chief, looking right at Trucky.', '"Ini tugas untuk yang kecil dan berani," kata kepala pemadam, menatap langsung ke Trucky.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_5', 'bok_trucky-the-brave-fire-truck', 5, 'truck-5', 'Trucky squeezed carefully through the narrow lane, and his crew gently rescued the frightened kitten.', 'Trucky menyelinap hati-hati melewati gang sempit, dan krunya menyelamatkan kucing ketakutan itu dengan lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_trucky-the-brave-fire-truck_6', 'bok_trucky-the-brave-fire-truck', 6, 'truck-6', 'That day, Trucky learned that every size has its own superpower — his was fitting where big trucks could not.', 'Hari itu, Trucky belajar bahwa setiap ukuran punya kekuatannya sendiri — miliknya adalah bisa masuk ke tempat yang tak terjangkau truk besar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_trucky-the-brave-fire-truck_1', 'bok_trucky-the-brave-fire-truck', 1, 'What was Trucky worried about?', 'Apa yang dikhawatirkan Trucky?', '["Being too loud","Being too small to help","Being too fast","Being too red"]', '["Terlalu berisik","Terlalu kecil untuk membantu","Terlalu cepat","Terlalu merah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_trucky-the-brave-fire-truck_2', 'bok_trucky-the-brave-fire-truck', 2, 'Who needed rescuing in the drainpipe?', 'Siapa yang perlu diselamatkan di pipa saluran?', '["A kitten","A puppy","A bird","A ball"]', '["Seekor kucing","Seekor anjing","Seekor burung","Sebuah bola"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_trucky-the-brave-fire-truck_3', 'bok_trucky-the-brave-fire-truck', 3, 'What did Trucky learn about his size?', 'Apa yang dipelajari Trucky tentang ukurannya?', '["Small size has its own superpower","He should become bigger","Size does not matter at all","Only big trucks can help"]', '["Ukuran kecil punya kekuatannya sendiri","Ia harus menjadi lebih besar","Ukuran sama sekali tidak penting","Hanya truk besar yang bisa membantu"]', 0, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-drum-that-traveled-the-world', 'the-drum-that-traveled-the-world', 'The Drum That Traveled the World', 'Gendang yang Berkeliling Dunia', 'A magical drum passes from child to child around the world, teaching that music speaks every language.', 'Sebuah gendang ajaib berpindah dari satu anak ke anak lain di seluruh dunia, mengajarkan bahwa musik bisa dimengerti semua orang.', 'cat_world-cultures', 'aut_siti-aminah', 'meadow', '🥁', 4, 9, 0, 'published', 6, 790, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_1', 'bok_the-drum-that-traveled-the-world', 1, 'drum-1', 'In a village by the mountains, a boy named Bayu carved a small wooden drum from a fallen branch.', 'Di sebuah desa dekat pegunungan, seorang anak bernama Bayu mengukir gendang kecil dari kayu dahan yang jatuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_2', 'bok_the-drum-that-traveled-the-world', 2, 'drum-2', 'He played a joyful beat, and the sound traveled on the wind, over oceans, to a girl in West Africa.', 'Ia memainkan irama gembira, dan suaranya terbawa angin, melintasi lautan, hingga ke seorang gadis di Afrika Barat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_3', 'bok_the-drum-that-traveled-the-world', 3, 'drum-3', 'She answered with her own rhythm on a talking drum, and children in Brazil began to dance to it.', 'Ia membalas dengan iramanya sendiri di gendang berbicara, dan anak-anak di Brasil mulai menari mengikutinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_4', 'bok_the-drum-that-traveled-the-world', 4, 'drum-4', 'From Brazil, the beat reached Japan, where a boy added the tap of his taiko drum to the song.', 'Dari Brasil, irama itu sampai ke Jepang, tempat seorang anak menambahkan ketukan taiko-nya ke lagu tersebut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_5', 'bok_the-drum-that-traveled-the-world', 5, 'drum-5', 'One by one, children from every corner of the world joined in, each adding their own special rhythm.', 'Satu per satu, anak-anak dari setiap penjuru dunia ikut bergabung, masing-masing menambahkan irama khas mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-drum-that-traveled-the-world_6', 'bok_the-drum-that-traveled-the-world', 6, 'drum-6', 'Though none of them spoke the same words, together they made one beautiful song everyone understood.', 'Meski tak satu pun berbicara bahasa yang sama, bersama-sama mereka menciptakan satu lagu indah yang dimengerti semua orang.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-drum-that-traveled-the-world_1', 'bok_the-drum-that-traveled-the-world', 1, 'What did Bayu make the drum from?', 'Dari apa Bayu membuat gendangnya?', '["Metal","A fallen branch","Plastic","Stone"]', '["Logam","Dahan yang jatuh","Plastik","Batu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-drum-that-traveled-the-world_2', 'bok_the-drum-that-traveled-the-world', 2, 'Which country did the rhythm travel to first?', 'Ke negara mana irama itu pertama kali sampai?', '["Japan","West Africa","Brazil","Indonesia"]', '["Jepang","Afrika Barat","Brasil","Indonesia"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-drum-that-traveled-the-world_3', 'bok_the-drum-that-traveled-the-world', 3, 'What is the message of the story?', 'Apa pesan dari cerita ini?', '["Only one country can make music","Music can be understood across every language","Drums are difficult to play","Children should not share instruments"]', '["Hanya satu negara yang bisa membuat musik","Musik bisa dimengerti melintasi semua bahasa","Gendang sulit dimainkan","Anak-anak tidak boleh berbagi alat musik"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-sneezing-elephant', 'the-sneezing-elephant', 'The Sneezing Elephant', 'Gajah yang Bersin', 'A silly, giant sneeze causes a chain of giggles across the savanna in this gentle story about laughing together.', 'Sebuah bersin raksasa yang konyol memicu deretan tawa di seluruh savana dalam cerita hangat tentang tertawa bersama.', 'cat_humor', 'aut_axto-creative-team', 'sunrise', '🐘', 2, 6, 0, 'published', 6, 4710, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_1', 'bok_the-sneezing-elephant', 1, 'elephant-1', 'Ellie the elephant felt a tickle in her big trunk. "Ah... ah... AH-CHOO!"', 'Ellie si gajah merasa geli di belalainya yang besar. "Hah... hah... HATCHIII!"');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_2', 'bok_the-sneezing-elephant', 2, 'elephant-2', 'The sneeze was SO big that it blew all the leaves off the nearest tree in one gust!', 'Bersinnya begitu besar sehingga menerbangkan semua daun dari pohon terdekat dalam sekali hembusan!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_3', 'bok_the-sneezing-elephant', 3, 'elephant-3', 'A monkey fell off his branch laughing, which made a giraffe laugh so hard she got hiccups.', 'Seekor monyet jatuh dari dahannya karena tertawa, membuat seekor jerapah tertawa begitu keras sampai cegukan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_4', 'bok_the-sneezing-elephant', 4, 'elephant-4', 'The giraffe''s "HIC! HIC!" made a family of zebras giggle so much they rolled in the dust.', '"HIK! HIK!" jerapah itu membuat sekeluarga zebra tertawa terpingkal-pingkal hingga berguling di tanah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_5', 'bok_the-sneezing-elephant', 5, 'elephant-5', 'Soon the whole savanna was laughing together, though none of them quite remembered why anymore!', 'Tak lama, seluruh savana tertawa bersama, meski tak satu pun lagi ingat kenapa mereka mulai tertawa!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-sneezing-elephant_6', 'bok_the-sneezing-elephant', 6, 'elephant-6', '"Bless you, Ellie," they all said at last, still smiling. One little sneeze had made everyone''s day brighter.', '"Semoga sehat, Ellie," kata mereka semua akhirnya, masih tersenyum. Satu bersin kecil membuat hari semua orang lebih cerah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-sneezing-elephant_1', 'bok_the-sneezing-elephant', 1, 'What happened when Ellie sneezed?', 'Apa yang terjadi saat Ellie bersin?', '["Nothing happened","It blew leaves off a tree","It started raining","All the animals ran away"]', '["Tidak ada yang terjadi","Menerbangkan daun dari pohon","Mulai hujan","Semua hewan lari"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-sneezing-elephant_2', 'bok_the-sneezing-elephant', 2, 'What happened to the giraffe?', 'Apa yang terjadi pada jerapah?', '["She got hiccups from laughing","She fell asleep","She sneezed too","She got scared"]', '["Ia cegukan karena tertawa","Ia tertidur","Ia juga bersin","Ia ketakutan"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-sneezing-elephant_3', 'bok_the-sneezing-elephant', 3, 'What is this story mainly about?', 'Cerita ini terutama tentang apa?', '["A scary storm","A funny chain reaction of laughter","A dangerous adventure","A sad goodbye"]', '["Badai yang menakutkan","Reaksi berantai tawa yang lucu","Petualangan berbahaya","Perpisahan yang sedih"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_ellies-alphabet-adventure', 'ellies-alphabet-adventure', 'Ellie''s Alphabet Adventure', 'Petualangan Abjad Ellie', 'Ellie meets a shy letter who is scared to appear in words, and helps it find its courage.', 'Ellie bertemu sebuah huruf pemalu yang takut muncul di dalam kata, dan membantunya menemukan keberanian.', 'cat_alphabet', 'aut_axto-creative-team', 'candy', '🔤', 2, 5, 0, 'published', 6, 2584, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_1', 'bok_ellies-alphabet-adventure', 1, 'alphabet-1', 'Ellie loved singing the alphabet every morning. A, B, C, all the way to Z!', 'Ellie suka menyanyikan lagu abjad setiap pagi. A, B, C, sampai ke Z!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_2', 'bok_ellies-alphabet-adventure', 2, 'alphabet-2', 'One day, she noticed the letter Q hiding behind a big book, looking very shy.', 'Suatu hari, ia melihat huruf Q bersembunyi di balik buku besar, terlihat sangat pemalu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_3', 'bok_ellies-alphabet-adventure', 3, 'alphabet-3', '"Why are you hiding?" Ellie asked. Q whispered, "I don''t show up in as many words as the other letters."', '"Kenapa kamu sembunyi?" tanya Ellie. Q berbisik, "Aku tidak muncul di banyak kata seperti huruf lain."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_4', 'bok_ellies-alphabet-adventure', 4, 'alphabet-4', 'Ellie smiled. "But you make wonderful words like queen, quiet, and quilt!" she said.', 'Ellie tersenyum. "Tapi kamu membuat kata-kata hebat seperti queen, quiet, dan quilt!" katanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_5', 'bok_ellies-alphabet-adventure', 5, 'alphabet-5', 'Together they found five words that needed Q, and Q felt proud for the very first time.', 'Bersama-sama mereka menemukan lima kata yang butuh Q, dan Q merasa bangga untuk pertama kalinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_ellies-alphabet-adventure_6', 'bok_ellies-alphabet-adventure', 6, 'alphabet-6', 'From that day, Q always stood tall in the alphabet parade, right between P and R.', 'Sejak hari itu, Q selalu berdiri tegak di barisan abjad, tepat di antara P dan R.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_ellies-alphabet-adventure_1', 'bok_ellies-alphabet-adventure', 1, 'Which letter was hiding?', 'Huruf apa yang bersembunyi?', '["A","Q","Z","M"]', '["A","Q","Z","M"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_ellies-alphabet-adventure_2', 'bok_ellies-alphabet-adventure', 2, 'Why was the letter shy?', 'Kenapa huruf itu pemalu?', '["It was too loud","It was in fewer words than others","It was upside down","It was too big"]', '["Terlalu keras","Muncul di lebih sedikit kata","Terbalik","Terlalu besar"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_ellies-alphabet-adventure_3', 'bok_ellies-alphabet-adventure', 3, 'How did Ellie help?', 'Bagaimana Ellie membantu?', '["She ignored it","She found words that use it","She erased it","She hid too"]', '["Mengabaikannya","Mencari kata yang memakainya","Menghapusnya","Ikut bersembunyi"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_a-day-with-grandma', 'a-day-with-grandma', 'A Day With Grandma', 'Sehari Bersama Nenek', 'A little girl spends a warm afternoon learning her grandmother''s favorite recipe and stories.', 'Seorang gadis kecil menghabiskan sore yang hangat belajar resep dan cerita favorit neneknya.', 'cat_family', 'aut_siti-aminah', 'sunrise', '👵', 3, 7, 0, 'published', 6, 1741, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_1', 'bok_a-day-with-grandma', 1, 'family-1', 'Every Sunday, Nadia visited her grandmother''s little house at the end of the street.', 'Setiap hari Minggu, Nadia mengunjungi rumah kecil neneknya di ujung jalan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_2', 'bok_a-day-with-grandma', 2, 'family-2', 'Grandma always smelled like cinnamon and warm bread. "Come help me cook," she said with a smile.', 'Nenek selalu berbau kayu manis dan roti hangat. "Ayo bantu Nenek memasak," katanya sambil tersenyum.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_3', 'bok_a-day-with-grandma', 3, 'family-3', 'They mixed flour, sugar, and a secret ingredient Grandma would only whisper: a pinch of love.', 'Mereka mengaduk tepung, gula, dan bahan rahasia yang hanya dibisikkan Nenek: sejumput cinta.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_4', 'bok_a-day-with-grandma', 4, 'family-4', 'While the cookies baked, Grandma told stories about when she was a little girl, just like Nadia.', 'Sambil kue dipanggang, Nenek bercerita tentang masa kecilnya, sama seperti Nadia sekarang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_5', 'bok_a-day-with-grandma', 5, 'family-5', 'When the cookies were ready, they shared them with the whole family at the dinner table.', 'Ketika kue matang, mereka membagikannya untuk seluruh keluarga di meja makan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-grandma_6', 'bok_a-day-with-grandma', 6, 'family-6', 'Nadia hugged Grandma tight. "Family is the warmest place in the world," she thought.', 'Nadia memeluk Nenek erat. "Keluarga adalah tempat paling hangat di dunia," pikirnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-grandma_1', 'bok_a-day-with-grandma', 1, 'What day did Nadia visit Grandma?', 'Hari apa Nadia mengunjungi Nenek?', '["Monday","Sunday","Friday","Saturday"]', '["Senin","Minggu","Jumat","Sabtu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-grandma_2', 'bok_a-day-with-grandma', 2, 'What was Grandma''s secret ingredient?', 'Apa bahan rahasia Nenek?', '["Salt","A pinch of love","Extra sugar","Chocolate"]', '["Garam","Sejumput cinta","Gula ekstra","Cokelat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-grandma_3', 'bok_a-day-with-grandma', 3, 'What did they do while the cookies baked?', 'Apa yang mereka lakukan sambil kue dipanggang?', '["Watched TV","Told stories","Went shopping","Took a nap"]', '["Menonton TV","Bercerita","Berbelanja","Tidur siang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_milos-big-feelings', 'milos-big-feelings', 'Milo and His Big Feelings', 'Milo dan Perasaan Besarnya', 'Milo learns that it''s okay to feel angry, sad, or scared, as long as he knows how to talk about it.', 'Milo belajar bahwa tidak apa-apa merasa marah, sedih, atau takut, selama ia tahu cara membicarakannya.', 'cat_emotions', 'aut_sarah-johnson', 'meadow', '😊', 3, 7, 0, 'published', 6, 4332, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_1', 'bok_milos-big-feelings', 1, 'emotions-1', 'Milo''s tower of blocks fell down with a crash. His face turned red and hot.', 'Menara balok Milo runtuh dengan suara keras. Wajahnya memerah dan panas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_2', 'bok_milos-big-feelings', 2, 'emotions-2', '"I feel like yelling!" Milo said. His mom sat beside him. "That''s okay. That feeling is called anger."', '"Aku ingin berteriak!" kata Milo. Ibunya duduk di sampingnya. "Tidak apa-apa. Perasaan itu namanya marah."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_3', 'bok_milos-big-feelings', 3, 'emotions-3', '"You can feel angry, but we don''t throw things. Let''s take a deep breath together," said Mom.', '"Kamu boleh merasa marah, tapi kita tidak melempar barang. Yuk tarik napas dalam-dalam bersama," kata Ibu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_4', 'bok_milos-big-feelings', 4, 'emotions-4', 'Milo breathed in slowly, then out slowly. The hot feeling started to cool down.', 'Milo menarik napas perlahan, lalu menghembuskannya perlahan. Rasa panas itu mulai mereda.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_5', 'bok_milos-big-feelings', 5, 'emotions-5', '"Now let''s build the tower again, together," Mom said. Milo smiled a little.', '"Sekarang ayo bangun menaranya lagi, bersama-sama," kata Ibu. Milo tersenyum sedikit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_milos-big-feelings_6', 'bok_milos-big-feelings', 6, 'emotions-6', 'Milo learned that every feeling has a name, and every feeling can be talked about.', 'Milo belajar bahwa setiap perasaan punya nama, dan setiap perasaan bisa dibicarakan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_milos-big-feelings_1', 'bok_milos-big-feelings', 1, 'Why did Milo feel upset?', 'Kenapa Milo merasa kesal?', '["He lost a toy","His tower fell down","He was hungry","He was tired"]', '["Kehilangan mainan","Menaranya runtuh","Lapar","Mengantuk"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_milos-big-feelings_2', 'bok_milos-big-feelings', 2, 'What helped Milo feel calmer?', 'Apa yang membuat Milo lebih tenang?', '["Throwing blocks","Taking deep breaths","Yelling louder","Running away"]', '["Melempar balok","Menarik napas dalam","Berteriak lebih keras","Lari"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_milos-big-feelings_3', 'bok_milos-big-feelings', 3, 'What is the name for the feeling Milo had?', 'Apa nama perasaan yang dirasakan Milo?', '["Happiness","Anger","Sleepiness","Hunger"]', '["Bahagia","Marah","Ngantuk","Lapar"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-whispering-wand', 'the-whispering-wand', 'The Whispering Wand', 'Tongkat yang Berbisik', 'A young girl finds a wand that only grants wishes that help others, teaching her real magic is kindness.', 'Seorang gadis kecil menemukan tongkat yang hanya mengabulkan permintaan untuk menolong orang lain.', 'cat_fantasy', 'aut_axto-creative-team', 'cosmic', '🪄', 5, 9, 0, 'published', 6, 4086, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_1', 'bok_the-whispering-wand', 1, 'fantasy-1', 'Deep in the Whisper Woods, Lira found a wand glowing softly beneath a silver leaf.', 'Jauh di dalam Hutan Bisikan, Lira menemukan tongkat yang bersinar lembut di bawah daun perak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_2', 'bok_the-whispering-wand', 2, 'fantasy-2', 'She waved it and wished for a mountain of candy — but nothing happened at all.', 'Ia mengayunkannya dan berharap gunung permen muncul — tapi tidak terjadi apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_3', 'bok_the-whispering-wand', 3, 'fantasy-3', 'A tiny voice giggled from the wand. "I only grant wishes that help someone else," it said.', 'Suara kecil terkekeh dari tongkat itu. "Aku hanya mengabulkan permintaan yang menolong orang lain," katanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_4', 'bok_the-whispering-wand', 4, 'fantasy-4', 'Lira thought of her neighbor, old Mr. Yusuf, whose garden had wilted in the summer heat.', 'Lira teringat tetangganya, Pak Yusuf, yang kebunnya layu karena panas musim kemarau.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_5', 'bok_the-whispering-wand', 5, 'fantasy-5', 'She wished for rain for his garden. The wand glowed bright, and soft rain fell that very night.', 'Ia berharap hujan turun untuk kebun itu. Tongkat itu bersinar terang, dan hujan lembut turun malam itu juga.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whispering-wand_6', 'bok_the-whispering-wand', 6, 'fantasy-6', 'The next morning, Mr. Yusuf''s flowers bloomed again. Lira realized real magic was kindness.', 'Keesokan paginya, bunga-bunga Pak Yusuf mekar kembali. Lira sadar bahwa sihir sejati adalah kebaikan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whispering-wand_1', 'bok_the-whispering-wand', 1, 'What kind of wish did the wand grant?', 'Permintaan seperti apa yang dikabulkan tongkat itu?', '["Wishes for candy","Wishes that help someone else","Wishes for toys","Any wish at all"]', '["Permen","Yang menolong orang lain","Mainan","Apa saja"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whispering-wand_2', 'bok_the-whispering-wand', 2, 'Who did Lira help?', 'Siapa yang ditolong Lira?', '["Her teacher","Mr. Yusuf","Her sister","A stranger"]', '["Gurunya","Pak Yusuf","Adiknya","Orang asing"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whispering-wand_3', 'bok_the-whispering-wand', 3, 'What did Lira learn in the end?', 'Apa yang dipelajari Lira pada akhirnya?', '["Wands are useless","Real magic is kindness","Candy is best","Rain is scary"]', '["Tongkat tidak berguna","Sihir sejati adalah kebaikan","Permen paling enak","Hujan menakutkan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-case-of-the-missing-cookies', 'the-case-of-the-missing-cookies', 'The Case of the Missing Cookies', 'Kasus Kue Kering yang Hilang', 'Detective Nina uses clues, not accusations, to solve the mystery of the empty cookie jar.', 'Detektif Nina menggunakan petunjuk, bukan tuduhan, untuk memecahkan misteri toples kue yang kosong.', 'cat_mystery', 'aut_david-lee', 'dusk', '🔍', 5, 9, 0, 'published', 6, 3913, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_1', 'bok_the-case-of-the-missing-cookies', 1, 'mystery-1', 'The cookie jar was empty! Nina put on her detective hat and grabbed her magnifying glass.', 'Toples kue itu kosong! Nina memakai topi detektifnya dan mengambil kaca pembesar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_2', 'bok_the-case-of-the-missing-cookies', 2, 'mystery-2', 'Clue one: crumbs led from the kitchen counter across the floor toward the living room.', 'Petunjuk pertama: remah-remah kue mengarah dari meja dapur ke ruang tamu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_3', 'bok_the-case-of-the-missing-cookies', 3, 'mystery-3', 'Clue two: a small paw print was pressed into a smear of chocolate on the rug.', 'Petunjuk kedua: jejak kaki kecil tercetak di noda cokelat di atas karpet.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_4', 'bok_the-case-of-the-missing-cookies', 4, 'mystery-4', 'Nina followed the trail behind the couch, where she found her dog Max fast asleep, crumbs on his nose.', 'Nina mengikuti jejak itu ke belakang sofa, dan menemukan anjingnya Max tertidur pulas, remah di hidungnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_5', 'bok_the-case-of-the-missing-cookies', 5, 'mystery-5', '"Case closed!" Nina laughed. "Max, you''re a cookie thief, but I still love you."', '"Kasus selesai!" Nina tertawa. "Max, kamu pencuri kue, tapi aku tetap sayang kamu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-case-of-the-missing-cookies_6', 'bok_the-case-of-the-missing-cookies', 6, 'mystery-6', 'From then on, Nina always kept the cookie jar somewhere Max''s nose couldn''t reach.', 'Sejak itu, Nina selalu menyimpan toples kue di tempat yang tidak terjangkau hidung Max.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-case-of-the-missing-cookies_1', 'bok_the-case-of-the-missing-cookies', 1, 'What tool did Nina use?', 'Alat apa yang digunakan Nina?', '["A telescope","A magnifying glass","A flashlight","A camera"]', '["Teropong","Kaca pembesar","Senter","Kamera"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-case-of-the-missing-cookies_2', 'bok_the-case-of-the-missing-cookies', 2, 'Who ate the cookies?', 'Siapa yang memakan kue itu?', '["Her brother","Her dog Max","A neighbor","Nobody"]', '["Kakaknya","Anjingnya Max","Tetangga","Tidak ada yang makan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-case-of-the-missing-cookies_3', 'bok_the-case-of-the-missing-cookies', 3, 'What clue was on the rug?', 'Petunjuk apa yang ada di karpet?', '["A footprint","A paw print in chocolate","A torn paper","A missing shoe"]', '["Jejak kaki manusia","Jejak kaki dengan cokelat","Kertas sobek","Sepatu hilang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_captain-nanos-treasure-map', 'captain-nanos-treasure-map', 'Captain Nano''s Treasure Map', 'Peta Harta Karun Kapten Nano', 'A young pirate learns that the greatest treasure on the island is the friends who sailed with her.', 'Seorang bajak laut kecil belajar bahwa harta terbesar di pulau itu adalah teman-teman seperjalanannya.', 'cat_pirates', 'aut_axto-creative-team', 'ocean', '🏴‍☠️', 4, 8, 0, 'published', 6, 2188, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_1', 'bok_captain-nanos-treasure-map', 1, 'pirates-1', 'Captain Nano and her crew found an old map hidden inside a bottle on the beach.', 'Kapten Nano dan awaknya menemukan peta tua tersembunyi di dalam botol di pantai.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_2', 'bok_captain-nanos-treasure-map', 2, 'pirates-2', 'The map showed an X on Coconut Island, three days of sailing across the Blue Sea.', 'Peta itu menunjukkan tanda X di Pulau Kelapa, tiga hari berlayar melintasi Laut Biru.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_3', 'bok_captain-nanos-treasure-map', 3, 'pirates-3', 'Along the way, a storm rocked their little ship, but the crew worked together to steer it safely.', 'Di tengah jalan, badai mengguncang kapal kecil mereka, tapi awak kapal bekerja sama untuk mengemudikannya dengan selamat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_4', 'bok_captain-nanos-treasure-map', 4, 'pirates-4', 'When they finally dug at the X, they found only a small wooden box with an old note inside.', 'Ketika akhirnya mereka menggali di tanda X, mereka hanya menemukan kotak kayu kecil berisi catatan tua.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_5', 'bok_captain-nanos-treasure-map', 5, 'pirates-5', 'The note read: "The real treasure was the friends who sailed with you." Captain Nano smiled.', 'Catatan itu berbunyi: "Harta sesungguhnya adalah teman yang berlayar bersamamu." Kapten Nano tersenyum.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_captain-nanos-treasure-map_6', 'bok_captain-nanos-treasure-map', 6, 'pirates-6', 'They sailed home laughing, already planning their next adventure together.', 'Mereka berlayar pulang sambil tertawa, sudah merencanakan petualangan berikutnya bersama.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-nanos-treasure-map_1', 'bok_captain-nanos-treasure-map', 1, 'Where did they find the map?', 'Di mana mereka menemukan peta itu?', '["In a bottle on the beach","In a cave","In a chest","In a book"]', '["Dalam botol di pantai","Dalam gua","Dalam peti","Dalam buku"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-nanos-treasure-map_2', 'bok_captain-nanos-treasure-map', 2, 'What happened during the journey?', 'Apa yang terjadi selama perjalanan?', '["They got lost forever","A storm rocked their ship","They found gold early","Nothing happened"]', '["Tersesat selamanya","Badai mengguncang kapal","Menemukan emas lebih awal","Tidak terjadi apa-apa"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_captain-nanos-treasure-map_3', 'bok_captain-nanos-treasure-map', 3, 'What was the real treasure?', 'Apa harta yang sesungguhnya?', '["Gold coins","Friendship","A map","A ship"]', '["Koin emas","Persahabatan","Peta","Kapal"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_princess-rosa-and-the-kind-knight', 'princess-rosa-and-the-kind-knight', 'Princess Rosa and the Kind Knight', 'Putri Rosa dan Ksatria yang Baik Hati', 'Princess Rosa learns that true bravery is protecting others with kindness, not just a sword.', 'Putri Rosa belajar bahwa keberanian sejati adalah melindungi orang lain dengan kebaikan, bukan hanya pedang.', 'cat_princess-knights', 'aut_sarah-johnson', 'candy', '👑', 4, 8, 0, 'published', 6, 4713, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_1', 'bok_princess-rosa-and-the-kind-knight', 1, 'princess-1', 'In the Kingdom of Meadowlight, Princess Rosa wanted to become a knight more than anything.', 'Di Kerajaan Meadowlight, Putri Rosa sangat ingin menjadi seorang ksatria.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_2', 'bok_princess-rosa-and-the-kind-knight', 2, 'princess-2', 'She trained every day with Sir Callum, the gentlest knight in the castle.', 'Ia berlatih setiap hari bersama Sir Callum, ksatria paling lembut di istana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_3', 'bok_princess-rosa-and-the-kind-knight', 3, 'princess-3', 'One day, a baby dragon got stuck in the castle well, crying for help.', 'Suatu hari, seekor bayi naga terjebak di sumur istana, menangis meminta tolong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_4', 'bok_princess-rosa-and-the-kind-knight', 4, 'princess-4', 'Other knights wanted to chase it away, but Rosa knelt down and spoke to it softly.', 'Ksatria lain ingin mengusirnya, tapi Rosa berlutut dan berbicara dengan lembut padanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_5', 'bok_princess-rosa-and-the-kind-knight', 5, 'princess-5', 'The dragon calmed down and let Rosa gently guide it out of the well with a rope of flowers.', 'Naga itu tenang dan membiarkan Rosa menuntunnya keluar dari sumur dengan tali bunga.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_princess-rosa-and-the-kind-knight_6', 'bok_princess-rosa-and-the-kind-knight', 6, 'princess-6', 'The whole kingdom cheered. Sir Callum said, "You are the bravest knight I know, Rosa."', 'Seluruh kerajaan bersorak. Sir Callum berkata, "Kamu ksatria paling berani yang kukenal, Rosa."');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-rosa-and-the-kind-knight_1', 'bok_princess-rosa-and-the-kind-knight', 1, 'Who trained Princess Rosa?', 'Siapa yang melatih Putri Rosa?', '["The King","Sir Callum","The dragon","Her sister"]', '["Sang Raja","Sir Callum","Sang naga","Kakaknya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-rosa-and-the-kind-knight_2', 'bok_princess-rosa-and-the-kind-knight', 2, 'What was stuck in the well?', 'Apa yang terjebak di sumur?', '["A cat","A baby dragon","A bucket","A ball"]', '["Kucing","Bayi naga","Ember","Bola"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_princess-rosa-and-the-kind-knight_3', 'bok_princess-rosa-and-the-kind-knight', 3, 'How did Rosa help the dragon?', 'Bagaimana Rosa menolong naga itu?', '["She scared it away","She spoke to it gently","She ignored it","She called guards to attack"]', '["Mengusirnya","Berbicara dengan lembut","Mengabaikannya","Memanggil penjaga untuk menyerang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_bubbles-the-dolphins-new-friend', 'bubbles-the-dolphins-new-friend', 'Bubbles the Dolphin''s New Friend', 'Teman Baru Bubbles si Lumba-Lumba', 'A playful dolphin helps a lost baby turtle find its way back to its family in the reef.', 'Seekor lumba-lumba periang membantu bayi penyu yang tersesat kembali ke keluarganya di terumbu karang.', 'cat_ocean-life', 'aut_emily-clark', 'ocean', '🐬', 3, 7, 0, 'published', 6, 482, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_1', 'bok_bubbles-the-dolphins-new-friend', 1, 'ocean-1', 'Bubbles the dolphin loved doing flips near the coral reef every morning.', 'Bubbles si lumba-lumba suka melompat-lompat dekat terumbu karang setiap pagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_2', 'bok_bubbles-the-dolphins-new-friend', 2, 'ocean-2', 'One day, she found a tiny turtle named Kiko, swimming alone and crying softly.', 'Suatu hari, ia menemukan penyu kecil bernama Kiko, berenang sendirian dan menangis pelan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_3', 'bok_bubbles-the-dolphins-new-friend', 3, 'ocean-3', '"I got separated from my family during the current," Kiko said. Bubbles promised to help.', '"Aku terpisah dari keluargaku saat ada arus deras," kata Kiko. Bubbles berjanji akan membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_4', 'bok_bubbles-the-dolphins-new-friend', 4, 'ocean-4', 'They swam past colorful fish and swaying seaweed, following the scent of Kiko''s home reef.', 'Mereka berenang melewati ikan-ikan warna-warni dan rumput laut yang bergoyang, mengikuti aroma terumbu rumah Kiko.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_5', 'bok_bubbles-the-dolphins-new-friend', 5, 'ocean-5', 'At last, they spotted Kiko''s family waiting anxiously near a big sea sponge.', 'Akhirnya, mereka melihat keluarga Kiko menunggu cemas dekat spons laut besar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_bubbles-the-dolphins-new-friend_6', 'bok_bubbles-the-dolphins-new-friend', 6, 'ocean-6', 'Kiko''s family thanked Bubbles with a happy underwater dance, and Bubbles had a new best friend.', 'Keluarga Kiko berterima kasih pada Bubbles dengan tarian bahagia di bawah air, dan Bubbles punya sahabat baru.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_bubbles-the-dolphins-new-friend_1', 'bok_bubbles-the-dolphins-new-friend', 1, 'What is the turtle''s name?', 'Siapa nama penyu itu?', '["Kiko","Bubbles","Rex","Fin"]', '["Kiko","Bubbles","Rex","Fin"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_bubbles-the-dolphins-new-friend_2', 'bok_bubbles-the-dolphins-new-friend', 2, 'Why was Kiko alone?', 'Kenapa Kiko sendirian?', '["He was hiding","He got separated in the current","He ran away","He was sleeping"]', '["Bersembunyi","Terpisah karena arus","Kabur","Tidur"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_bubbles-the-dolphins-new-friend_3', 'bok_bubbles-the-dolphins-new-friend', 3, 'How did the story end?', 'Bagaimana akhir ceritanya?', '["Kiko stayed lost","Kiko found his family","Bubbles got lost too","They never met again"]', '["Kiko tetap tersesat","Kiko menemukan keluarganya","Bubbles juga tersesat","Mereka tidak pernah bertemu lagi"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_zuri-and-the-lost-cub', 'zuri-and-the-lost-cub', 'Zuri and the Lost Cub', 'Zuri dan Anak Singa yang Tersesat', 'A young elephant helps a lost lion cub find its pride, learning that kindness has no borders.', 'Seekor anak gajah membantu anak singa yang tersesat menemukan kelompoknya, belajar bahwa kebaikan tak mengenal batas.', 'cat_jungle-safari', 'aut_axto-creative-team', 'meadow', '🦁', 4, 8, 0, 'published', 6, 4722, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_1', 'bok_zuri-and-the-lost-cub', 1, 'safari-1', 'Zuri the young elephant was drinking at the waterhole when she heard a tiny roar.', 'Zuri si anak gajah sedang minum di lubang air ketika ia mendengar auman kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_2', 'bok_zuri-and-the-lost-cub', 2, 'safari-2', 'A lion cub named Jabari was stuck between two rocks, too small to climb out alone.', 'Seekor anak singa bernama Jabari terjepit di antara dua batu, terlalu kecil untuk memanjat keluar sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_3', 'bok_zuri-and-the-lost-cub', 3, 'safari-3', 'Even though lions and elephants usually kept their distance, Zuri gently lifted Jabari with her trunk.', 'Meski singa dan gajah biasanya menjaga jarak, Zuri dengan lembut mengangkat Jabari dengan belalainya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_4', 'bok_zuri-and-the-lost-cub', 4, 'safari-4', '"Thank you," Jabari said, shaking with fear. "I can''t find my pride anywhere."', '"Terima kasih," kata Jabari, gemetar ketakutan. "Aku tidak bisa menemukan kelompokku."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_5', 'bok_zuri-and-the-lost-cub', 5, 'safari-5', 'Zuri used her long trunk to sniff the air and followed the scent all the way to the acacia trees.', 'Zuri menggunakan belalai panjangnya untuk mencium udara dan mengikuti aromanya sampai ke pohon akasia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_zuri-and-the-lost-cub_6', 'bok_zuri-and-the-lost-cub', 6, 'safari-6', 'There, Jabari''s mother waited, relieved. From that day, elephants and lions in that savanna were the best of friends.', 'Di sana, ibu Jabari menunggu, lega. Sejak hari itu, gajah dan singa di sabana itu menjadi sahabat terbaik.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_zuri-and-the-lost-cub_1', 'bok_zuri-and-the-lost-cub', 1, 'Who got stuck between two rocks?', 'Siapa yang terjepit di antara dua batu?', '["Zuri","Jabari the lion cub","A zebra","A bird"]', '["Zuri","Jabari si anak singa","Zebra","Burung"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_zuri-and-the-lost-cub_2', 'bok_zuri-and-the-lost-cub', 2, 'How did Zuri find Jabari''s family?', 'Bagaimana Zuri menemukan keluarga Jabari?', '["She asked a bird","She followed the scent with her trunk","She guessed","She waited for them"]', '["Bertanya pada burung","Mengikuti aroma dengan belalainya","Menebak","Menunggu mereka"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_zuri-and-the-lost-cub_3', 'bok_zuri-and-the-lost-cub', 3, 'What lesson does the story teach?', 'Pelajaran apa yang diajarkan cerita ini?', '["Only help your own kind","Kindness has no borders","Stay away from strangers","Lions are scary"]', '["Hanya tolong sejenis","Kebaikan tak mengenal batas","Jauhi orang asing","Singa menakutkan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_old-macfarms-missing-rooster', 'old-macfarms-missing-rooster', 'Old MacFarm and the Missing Rooster', 'Peternakan Tua dan Ayam Jantan yang Hilang', 'When the rooster who wakes the farm disappears, the animals must learn to work together.', 'Ketika ayam jantan yang membangunkan peternakan menghilang, para hewan harus belajar bekerja sama.', 'cat_farm', 'aut_siti-aminah', 'sunrise', '🐓', 3, 6, 0, 'published', 6, 1242, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_1', 'bok_old-macfarms-missing-rooster', 1, 'farm-1', 'Every morning, Rudi the rooster crowed "Cock-a-doodle-doo!" to wake up the whole farm.', 'Setiap pagi, Rudi si ayam jantan berkokok "Kukuruyuk!" untuk membangunkan seluruh peternakan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_2', 'bok_old-macfarms-missing-rooster', 2, 'farm-2', 'One morning, there was silence. No crowing at all. Rudi was nowhere to be found!', 'Suatu pagi, semua sunyi. Tidak ada kokokan sama sekali. Rudi tidak ditemukan di mana pun!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_3', 'bok_old-macfarms-missing-rooster', 3, 'farm-3', 'The cow, the sheep, and the pig searched everywhere, calling his name across the barn.', 'Sapi, domba, dan babi mencari ke mana-mana, memanggil namanya di seluruh kandang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_4', 'bok_old-macfarms-missing-rooster', 4, 'farm-4', 'The little duck found him stuck in the mud near the pond, his feathers all muddy.', 'Bebek kecil menemukannya terjebak di lumpur dekat kolam, bulunya penuh lumpur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_5', 'bok_old-macfarms-missing-rooster', 5, 'farm-5', 'All the animals worked together, pulling gently, until Rudi popped free with a happy squelch.', 'Semua hewan bekerja sama, menarik dengan lembut, sampai Rudi terlepas dengan suara lucu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_old-macfarms-missing-rooster_6', 'bok_old-macfarms-missing-rooster', 6, 'farm-6', 'The next morning, Rudi crowed louder than ever, thankful for his wonderful farm friends.', 'Keesokan paginya, Rudi berkokok lebih keras dari biasanya, berterima kasih pada teman-teman peternakannya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_old-macfarms-missing-rooster_1', 'bok_old-macfarms-missing-rooster', 1, 'What does Rudi do every morning?', 'Apa yang dilakukan Rudi setiap pagi?', '["He sleeps in","He crows to wake everyone","He eats breakfast","He swims"]', '["Tidur lagi","Berkokok membangunkan semua","Sarapan","Berenang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_old-macfarms-missing-rooster_2', 'bok_old-macfarms-missing-rooster', 2, 'Where was Rudi stuck?', 'Di mana Rudi terjebak?', '["In a tree","In the mud near the pond","In the barn","On the roof"]', '["Di pohon","Di lumpur dekat kolam","Di kandang","Di atap"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_old-macfarms-missing-rooster_3', 'bok_old-macfarms-missing-rooster', 3, 'How was Rudi rescued?', 'Bagaimana Rudi diselamatkan?', '["He escaped alone","All the animals worked together","The farmer used a machine","He was left there"]', '["Kabur sendiri","Semua hewan bekerja sama","Petani pakai mesin","Dibiarkan saja"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_buddys-first-day-home', 'buddys-first-day-home', 'Buddy the Puppy''s First Day Home', 'Hari Pertama Buddy si Anak Anjing di Rumah Baru', 'A nervous new puppy learns that his new family will love and take care of him always.', 'Seekor anak anjing yang gugup belajar bahwa keluarga barunya akan selalu mencintai dan merawatnya.', 'cat_pets', 'aut_sarah-johnson', 'sunrise', '🐶', 2, 6, 0, 'published', 6, 1340, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_1', 'bok_buddys-first-day-home', 1, 'pets-1', 'Buddy the puppy arrived at his new home in a little basket, feeling small and nervous.', 'Buddy si anak anjing tiba di rumah barunya dalam keranjang kecil, merasa kecil dan gugup.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_2', 'bok_buddys-first-day-home', 2, 'pets-2', 'A little boy named Dimas knelt down slowly and held out his hand. "Hi Buddy, I''m your friend now."', 'Seorang anak laki-laki bernama Dimas berlutut pelan dan mengulurkan tangannya. "Hai Buddy, aku temanmu sekarang."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_3', 'bok_buddys-first-day-home', 3, 'pets-3', 'Buddy sniffed his hand carefully, then wagged his tail just a little bit.', 'Buddy mengendus tangan itu hati-hati, lalu mengibaskan ekornya sedikit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_4', 'bok_buddys-first-day-home', 4, 'pets-4', 'Dimas showed him his cozy new bed, a bowl of fresh water, and a soft squeaky toy.', 'Dimas menunjukkan tempat tidur baru yang nyaman, mangkuk berisi air segar, dan mainan lembut yang berbunyi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_5', 'bok_buddys-first-day-home', 5, 'pets-5', 'That night, Buddy curled up next to Dimas''s bed, feeling safe for the very first time.', 'Malam itu, Buddy meringkuk di samping tempat tidur Dimas, merasa aman untuk pertama kalinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_buddys-first-day-home_6', 'bok_buddys-first-day-home', 6, 'pets-6', 'By morning, Buddy was already best friends with his whole new family.', 'Menjelang pagi, Buddy sudah menjadi sahabat bagi seluruh keluarga barunya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_buddys-first-day-home_1', 'bok_buddys-first-day-home', 1, 'How did Buddy feel when he first arrived?', 'Bagaimana perasaan Buddy saat pertama tiba?', '["Excited and loud","Small and nervous","Angry","Sleepy all day"]', '["Bersemangat dan berisik","Kecil dan gugup","Marah","Ngantuk seharian"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_buddys-first-day-home_2', 'bok_buddys-first-day-home', 2, 'Who welcomed Buddy?', 'Siapa yang menyambut Buddy?', '["A cat","A boy named Dimas","A stranger","Nobody"]', '["Kucing","Anak bernama Dimas","Orang asing","Tidak ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_buddys-first-day-home_3', 'bok_buddys-first-day-home', 3, 'Where did Buddy sleep that night?', 'Di mana Buddy tidur malam itu?', '["Outside","Next to Dimas''s bed","In the kitchen","In a basket outside"]', '["Di luar","Di samping tempat tidur Dimas","Di dapur","Dalam keranjang di luar"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_beep-and-the-broken-toy', 'beep-and-the-broken-toy', 'Beep and the Broken Toy', 'Beep dan Mainan yang Rusak', 'A helpful little robot learns that not everything broken needs fixing — sometimes it just needs care.', 'Seekor robot kecil yang suka menolong belajar bahwa tidak semua yang rusak perlu diperbaiki — kadang cukup dirawat.', 'cat_robots-tech', 'aut_david-lee', 'cosmic', '🤖', 4, 9, 0, 'published', 6, 2310, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_1', 'bok_beep-and-the-broken-toy', 1, 'robots-1', 'Beep the robot loved fixing things. Squeaky doors, wobbly tables, anything at all.', 'Beep si robot suka memperbaiki barang. Pintu berdecit, meja goyang, apa saja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_2', 'bok_beep-and-the-broken-toy', 2, 'robots-2', 'One day, he found a little girl named Wina crying over her torn teddy bear, Coco.', 'Suatu hari, ia menemukan gadis kecil bernama Wina menangis karena boneka beruangnya, Coco, robek.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_3', 'bok_beep-and-the-broken-toy', 3, 'robots-3', '"I can fix him with my tools!" Beep said, reaching for his glue and needle.', '"Aku bisa memperbaikinya dengan peralatanku!" kata Beep, mengambil lem dan jarumnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_4', 'bok_beep-and-the-broken-toy', 4, 'robots-4', '"Wait," Wina said softly. "Coco doesn''t need to be perfect. He just needs a hug and some love."', '"Tunggu," kata Wina lembut. "Coco tidak perlu sempurna. Ia hanya butuh pelukan dan kasih sayang."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_5', 'bok_beep-and-the-broken-toy', 5, 'robots-5', 'Beep paused his tools and thought about it. He gently helped Wina sew one small stitch instead.', 'Beep menghentikan peralatannya dan berpikir. Ia membantu Wina menjahit satu jahitan kecil saja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_beep-and-the-broken-toy_6', 'bok_beep-and-the-broken-toy', 6, 'robots-6', 'Coco was still a little worn, but Wina hugged him tight and smiled. Beep learned love fixes more than tools.', 'Coco masih agak usang, tapi Wina memeluknya erat dan tersenyum. Beep belajar bahwa cinta memperbaiki lebih dari sekadar alat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_beep-and-the-broken-toy_1', 'bok_beep-and-the-broken-toy', 1, 'What did Beep love to do?', 'Apa yang disukai Beep?', '["Sleeping","Fixing things","Singing","Cooking"]', '["Tidur","Memperbaiki barang","Bernyanyi","Memasak"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_beep-and-the-broken-toy_2', 'bok_beep-and-the-broken-toy', 2, 'What was broken?', 'Apa yang rusak?', '["A chair","Wina''s teddy bear","A robot arm","A window"]', '["Kursi","Boneka beruang Wina","Lengan robot","Jendela"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_beep-and-the-broken-toy_3', 'bok_beep-and-the-broken-toy', 3, 'What did Wina say Coco really needed?', 'Apa yang menurut Wina benar-benar dibutuhkan Coco?', '["New stuffing","A hug and love","A new owner","To be thrown away"]', '["Isi baru","Pelukan dan kasih sayang","Pemilik baru","Dibuang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-tree-everyone-forgot', 'the-tree-everyone-forgot', 'The Tree That Everyone Forgot', 'Pohon yang Terlupakan', 'Children rediscover an old forgotten tree in their neighborhood and learn to care for nature together.', 'Anak-anak menemukan kembali sebuah pohon tua yang terlupakan di lingkungan mereka dan belajar merawat alam bersama.', 'cat_nature-environment', 'aut_axto-creative-team', 'forest', '🌳', 4, 9, 0, 'published', 6, 2202, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_1', 'bok_the-tree-everyone-forgot', 1, 'nature-1', 'At the end of Melati Street stood an old tree, its leaves dusty and branches drooping.', 'Di ujung Jalan Melati berdiri sebuah pohon tua, daunnya berdebu dan rantingnya menunduk.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_2', 'bok_the-tree-everyone-forgot', 2, 'nature-2', 'Every day, children walked past it without even noticing it was there.', 'Setiap hari, anak-anak melewatinya tanpa menyadari keberadaannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_3', 'bok_the-tree-everyone-forgot', 3, 'nature-3', 'One afternoon, little Arka stopped and looked up. "Why is this tree so sad?" he wondered.', 'Suatu sore, Arka kecil berhenti dan menengadah. "Kenapa pohon ini terlihat sedih?" pikirnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_4', 'bok_the-tree-everyone-forgot', 4, 'nature-4', 'He gathered his friends, and together they watered its roots and cleared the trash around it.', 'Ia mengumpulkan teman-temannya, dan bersama-sama mereka menyiram akarnya dan membersihkan sampah di sekitarnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_5', 'bok_the-tree-everyone-forgot', 5, 'nature-5', 'Week by week, the tree grew greener. Birds began building nests in its branches again.', 'Minggu demi minggu, pohon itu semakin hijau. Burung-burung mulai membuat sarang di rantingnya lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tree-everyone-forgot_6', 'bok_the-tree-everyone-forgot', 6, 'nature-6', 'Now the children call it "Our Tree," and every child on Melati Street helps take care of it.', 'Sekarang anak-anak menyebutnya "Pohon Kita," dan setiap anak di Jalan Melati ikut merawatnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tree-everyone-forgot_1', 'bok_the-tree-everyone-forgot', 1, 'What was wrong with the tree at first?', 'Apa yang salah dengan pohon itu di awal?', '["It was cut down","It looked dusty and drooping","It was on fire","It moved away"]', '["Ditebang","Terlihat berdebu dan lesu","Terbakar","Berpindah tempat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tree-everyone-forgot_2', 'bok_the-tree-everyone-forgot', 2, 'What did Arka and his friends do?', 'Apa yang dilakukan Arka dan teman-temannya?', '["Ignored it","Watered it and cleared trash","Cut it down","Painted it"]', '["Mengabaikannya","Menyiram dan membersihkan sampah","Menebangnya","Mengecatnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tree-everyone-forgot_3', 'bok_the-tree-everyone-forgot', 3, 'What happened after they cared for it?', 'Apa yang terjadi setelah mereka merawatnya?', '["It died anyway","It grew greener and birds returned","Nothing changed","It was cut down"]', '["Tetap mati","Semakin hijau dan burung kembali","Tidak ada yang berubah","Ditebang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-rainbow-after-the-rain', 'the-rainbow-after-the-rain', 'The Rainbow After the Rain', 'Pelangi Setelah Hujan', 'A little boy learns why rainbows appear and discovers that even rainy days can lead to something beautiful.', 'Seorang anak laki-laki belajar kenapa pelangi muncul dan menemukan bahwa hari hujan pun bisa berujung indah.', 'cat_weather-seasons', 'aut_axto-creative-team', 'dusk', '🌦️', 2, 6, 0, 'published', 6, 2152, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_1', 'bok_the-rainbow-after-the-rain', 1, 'weather-1', 'Dark clouds rolled in, and rain began to fall. Bayu sighed, "No playing outside today."', 'Awan gelap datang, dan hujan mulai turun. Bayu menghela napas, "Tidak bisa main di luar hari ini."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_2', 'bok_the-rainbow-after-the-rain', 2, 'weather-2', 'His grandfather smiled. "Every rain has a surprise waiting at the end, if you''re patient."', 'Kakeknya tersenyum. "Setiap hujan menyimpan kejutan di akhir, kalau kamu sabar menunggu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_3', 'bok_the-rainbow-after-the-rain', 3, 'weather-3', 'They watched from the window as the rain slowed down, drop by drop, until it finally stopped.', 'Mereka menonton dari jendela saat hujan melambat, tetes demi tetes, sampai akhirnya berhenti.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_4', 'bok_the-rainbow-after-the-rain', 4, 'weather-4', 'The sun peeked out from behind a cloud, and light passed through the tiny raindrops in the air.', 'Matahari mengintip dari balik awan, dan cahaya melewati tetesan air kecil di udara.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_5', 'bok_the-rainbow-after-the-rain', 5, 'weather-5', 'Suddenly, a rainbow stretched across the sky — red, orange, yellow, green, blue, and purple.', 'Tiba-tiba, sebuah pelangi terbentang di langit — merah, jingga, kuning, hijau, biru, dan ungu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-rainbow-after-the-rain_6', 'bok_the-rainbow-after-the-rain', 6, 'weather-6', '"The rain made room for the rainbow," Grandfather said. Bayu smiled, no longer sad about the rain.', '"Hujan memberi ruang untuk pelangi," kata Kakek. Bayu tersenyum, tak lagi sedih karena hujan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-rainbow-after-the-rain_1', 'bok_the-rainbow-after-the-rain', 1, 'What was Bayu sad about?', 'Apa yang membuat Bayu sedih?', '["He lost a toy","He couldn''t play outside because of rain","He was hungry","School was cancelled"]', '["Kehilangan mainan","Tidak bisa main di luar karena hujan","Lapar","Sekolah diliburkan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-rainbow-after-the-rain_2', 'bok_the-rainbow-after-the-rain', 2, 'What appeared after the rain?', 'Apa yang muncul setelah hujan?', '["Snow","A rainbow","A storm","Fog"]', '["Salju","Pelangi","Badai","Kabut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-rainbow-after-the-rain_3', 'bok_the-rainbow-after-the-rain', 3, 'What lesson did Bayu learn?', 'Pelajaran apa yang dipetik Bayu?', '["Rain is always bad","Rain can lead to something beautiful","Rainbows are scary","Never go outside"]', '["Hujan selalu buruk","Hujan bisa berujung indah","Pelangi menakutkan","Jangan pernah keluar rumah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_a-day-with-officer-dan', 'a-day-with-officer-dan', 'A Day With Officer Dan', 'Sehari Bersama Petugas Dan', 'A curious boy spends a day shadowing a police officer and learns how community helpers keep everyone safe.', 'Seorang anak yang penasaran menghabiskan sehari mengikuti seorang polisi dan belajar bagaimana profesi membantu menjaga keselamatan semua orang.', 'cat_community-helpers', 'aut_axto-creative-team', 'night', '👮', 3, 7, 0, 'published', 6, 4992, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_1', 'bok_a-day-with-officer-dan', 1, 'community-1', 'On School Career Day, Farrel got to spend the morning with Officer Dan, the friendliest police officer in town.', 'Di Hari Profesi Sekolah, Farrel menghabiskan pagi bersama Petugas Dan, polisi paling ramah di kota.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_2', 'bok_a-day-with-officer-dan', 2, 'community-2', 'First, they helped a group of children cross the busy street safely, holding up a bright stop sign.', 'Pertama, mereka membantu sekelompok anak menyeberang jalan ramai dengan aman, mengangkat rambu berhenti yang cerah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_3', 'bok_a-day-with-officer-dan', 3, 'community-3', 'Next, they helped an elderly man who couldn''t find his way home, guiding him gently back to his street.', 'Selanjutnya, mereka membantu seorang kakek yang tersesat, menuntunnya kembali ke jalannya dengan lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_4', 'bok_a-day-with-officer-dan', 4, 'community-4', '"Being a helper means noticing when someone needs you," Officer Dan explained with a warm smile.', '"Menjadi penolong berarti peka saat seseorang membutuhkanmu," jelas Petugas Dan dengan senyum hangat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_5', 'bok_a-day-with-officer-dan', 5, 'community-5', 'Farrel even got to wave to cars from a bicycle, helping keep the school zone safe at pickup time.', 'Farrel bahkan boleh melambai ke mobil dari sepeda, membantu menjaga keamanan zona sekolah saat jam jemput.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_a-day-with-officer-dan_6', 'bok_a-day-with-officer-dan', 6, 'community-6', 'That night, Farrel told his family, "I want to be a helper like Officer Dan when I grow up."', 'Malam itu, Farrel bercerita ke keluarganya, "Aku ingin jadi penolong seperti Petugas Dan kalau sudah besar."');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-officer-dan_1', 'bok_a-day-with-officer-dan', 1, 'Who did Farrel spend the day with?', 'Farrel menghabiskan hari bersama siapa?', '["A doctor","Officer Dan","A firefighter","A teacher"]', '["Dokter","Petugas Dan","Pemadam kebakaran","Guru"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-officer-dan_2', 'bok_a-day-with-officer-dan', 2, 'What did they help the elderly man with?', 'Apa yang mereka bantu untuk kakek itu?', '["Carrying groceries","Finding his way home","Fixing his bike","Crossing a river"]', '["Membawa belanjaan","Menemukan jalan pulang","Memperbaiki sepeda","Menyeberangi sungai"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_a-day-with-officer-dan_3', 'bok_a-day-with-officer-dan', 3, 'What did Farrel decide he wanted to be?', 'Farrel ingin menjadi apa?', '["A chef","A helper like Officer Dan","A pilot","A painter"]', '["Koki","Penolong seperti Petugas Dan","Pilot","Pelukis"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_team-sunflowers-big-game', 'team-sunflowers-big-game', 'Team Sunflower''s Big Game', 'Pertandingan Besar Tim Bunga Matahari', 'A young player learns that supporting your teammates matters more than winning.', 'Seorang pemain kecil belajar bahwa mendukung teman satu tim lebih penting daripada menang.', 'cat_sports', 'aut_axto-creative-team', 'meadow', '⚽', 5, 10, 0, 'published', 6, 4357, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_1', 'bok_team-sunflowers-big-game', 1, 'sports-1', 'Team Sunflower had practiced all season for the final match against Team Comet.', 'Tim Bunga Matahari sudah berlatih sepanjang musim untuk pertandingan final melawan Tim Komet.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_2', 'bok_team-sunflowers-big-game', 2, 'sports-2', 'Rayhan, the fastest runner on the team, was so nervous his hands were shaking before the whistle blew.', 'Rayhan, pelari tercepat di tim, sangat gugup hingga tangannya gemetar sebelum peluit ditiup.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_3', 'bok_team-sunflowers-big-game', 3, 'sports-3', 'In the second half, Rayhan missed an easy goal, and his shoulders slumped in disappointment.', 'Di babak kedua, Rayhan gagal mencetak gol yang mudah, dan bahunya turun kecewa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_4', 'bok_team-sunflowers-big-game', 4, 'sports-4', 'His teammate Bimo ran over and patted his back. "We win and lose together. Keep playing!"', 'Rekan setimnya, Bimo, berlari dan menepuk punggungnya. "Kita menang dan kalah bersama. Ayo terus main!"');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_5', 'bok_team-sunflowers-big-game', 5, 'sports-5', 'Cheered on by his team, Rayhan ran faster than ever and passed the ball perfectly to score in the last minute.', 'Didukung timnya, Rayhan berlari lebih cepat dari sebelumnya dan mengoper bola dengan sempurna untuk mencetak gol di menit terakhir.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_team-sunflowers-big-game_6', 'bok_team-sunflowers-big-game', 6, 'sports-6', 'Team Sunflower won, but Rayhan said the best part was his team believing in him even after a mistake.', 'Tim Bunga Matahari menang, tapi bagi Rayhan yang terbaik adalah timnya tetap percaya padanya walau ia sempat gagal.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_team-sunflowers-big-game_1', 'bok_team-sunflowers-big-game', 1, 'What team did Rayhan play for?', 'Rayhan bermain untuk tim apa?', '["Team Comet","Team Sunflower","Team Star","Team Ocean"]', '["Tim Komet","Tim Bunga Matahari","Tim Bintang","Tim Laut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_team-sunflowers-big-game_2', 'bok_team-sunflowers-big-game', 2, 'What happened when Rayhan missed a goal?', 'Apa yang terjadi saat Rayhan gagal mencetak gol?', '["His team got angry","His teammate encouraged him","He was sent home","The game stopped"]', '["Tim marah","Rekan setimnya menyemangatinya","Ia dipulangkan","Pertandingan berhenti"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_team-sunflowers-big-game_3', 'bok_team-sunflowers-big-game', 3, 'What did Rayhan say was the best part?', 'Apa menurut Rayhan bagian terbaiknya?', '["Winning the trophy","His team believing in him","Being the fastest","Getting a prize"]', '["Memenangkan trofi","Timnya tetap percaya padanya","Menjadi tercepat","Mendapat hadiah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-song-that-made-the-village-dance', 'the-song-that-made-the-village-dance', 'The Song That Made the Village Dance', 'Lagu yang Membuat Desa Menari', 'A shy girl discovers her singing voice can bring an entire village together in joy.', 'Seorang gadis pemalu menemukan suara nyanyiannya bisa menyatukan seluruh desa dalam kebahagiaan.', 'cat_music-rhymes', 'aut_siti-aminah', 'candy', '🎵', 3, 7, 0, 'published', 6, 3838, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_1', 'bok_the-song-that-made-the-village-dance', 1, 'music-1', 'Sari loved to hum little tunes, but she was too shy to sing in front of anyone.', 'Sari suka menggumamkan lagu-lagu kecil, tapi ia terlalu malu untuk bernyanyi di depan orang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_2', 'bok_the-song-that-made-the-village-dance', 2, 'music-2', 'One evening, the village harvest festival felt quiet and a little sad — the usual singer was sick.', 'Suatu malam, festival panen desa terasa sepi dan sedikit sedih — penyanyi biasa sedang sakit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_3', 'bok_the-song-that-made-the-village-dance', 3, 'music-3', 'Sari''s grandmother whispered, "Music is a gift you share, not something to hide."', 'Nenek Sari berbisik, "Musik adalah hadiah yang kau bagikan, bukan yang kau sembunyikan."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_4', 'bok_the-song-that-made-the-village-dance', 4, 'music-4', 'With shaking knees, Sari stepped up and began to sing a gentle rhyme about the moon and rice fields.', 'Dengan lutut gemetar, Sari maju dan mulai menyanyikan pantun lembut tentang bulan dan sawah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_5', 'bok_the-song-that-made-the-village-dance', 5, 'music-5', 'One by one, the villagers began clapping along, then swaying, then dancing under the stars.', 'Satu per satu, warga desa mulai bertepuk tangan, lalu bergoyang, lalu menari di bawah bintang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-that-made-the-village-dance_6', 'bok_the-song-that-made-the-village-dance', 6, 'music-6', 'From that night on, Sari sang at every festival, no longer afraid to share her gift.', 'Sejak malam itu, Sari bernyanyi di setiap festival, tak lagi takut membagikan hadiahnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-that-made-the-village-dance_1', 'bok_the-song-that-made-the-village-dance', 1, 'Why was the festival feeling sad?', 'Kenapa festival terasa sedih?', '["It was raining","The usual singer was sick","There was no food","It was cancelled"]', '["Sedang hujan","Penyanyi biasa sedang sakit","Tidak ada makanan","Dibatalkan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-that-made-the-village-dance_2', 'bok_the-song-that-made-the-village-dance', 2, 'What did Sari sing about?', 'Sari bernyanyi tentang apa?', '["Cars and roads","The moon and rice fields","Robots","The ocean"]', '["Mobil dan jalan","Bulan dan sawah","Robot","Laut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-that-made-the-village-dance_3', 'bok_the-song-that-made-the-village-dance', 3, 'What did the villagers do while Sari sang?', 'Apa yang dilakukan warga desa saat Sari bernyanyi?', '["They left","They clapped and danced","They fell asleep","They argued"]', '["Pergi","Bertepuk tangan dan menari","Tertidur","Bertengkar"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_grandmas-lantern-festival', 'grandmas-lantern-festival', 'Grandma''s Lantern Festival', 'Festival Lampion Nenek', 'A boy learns the meaning behind his family''s lantern festival tradition and why celebrations bring people together.', 'Seorang anak belajar makna di balik tradisi festival lampion keluarganya dan kenapa perayaan menyatukan orang.', 'cat_holidays-culture', 'aut_siti-aminah', 'night', '🏮', 4, 8, 0, 'published', 6, 440, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_1', 'bok_grandmas-lantern-festival', 1, 'holidays-1', 'Every year, Bram''s family made paper lanterns together for the village Lantern Festival.', 'Setiap tahun, keluarga Bram membuat lampion kertas bersama untuk Festival Lampion desa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_2', 'bok_grandmas-lantern-festival', 2, 'holidays-2', '"Why do we do this every year, Grandma?" Bram asked, folding red paper carefully.', '"Kenapa kita melakukan ini setiap tahun, Nek?" tanya Bram, sambil melipat kertas merah hati-hati.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_3', 'bok_grandmas-lantern-festival', 3, 'holidays-3', '"The lanterns carry our wishes for the new year, and light guides family back home," Grandma explained.', '"Lampion membawa harapan kita untuk tahun baru, dan cahayanya menuntun keluarga kembali pulang," jelas Nenek.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_4', 'bok_grandmas-lantern-festival', 4, 'holidays-4', 'That evening, the whole village gathered, lighting their lanterns one by one until the sky glowed gold.', 'Malam itu, seluruh desa berkumpul, menyalakan lampion satu per satu hingga langit bersinar keemasan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_5', 'bok_grandmas-lantern-festival', 5, 'holidays-5', 'Bram wrote his wish on his lantern: "I wish everyone I love stays happy and healthy."', 'Bram menulis harapannya di lampionnya: "Aku berharap semua yang kucintai tetap bahagia dan sehat."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_grandmas-lantern-festival_6', 'bok_grandmas-lantern-festival', 6, 'holidays-6', 'Watching hundreds of lanterns float into the sky, Bram finally understood why the tradition mattered.', 'Melihat ratusan lampion melayang ke langit, Bram akhirnya paham kenapa tradisi ini begitu berarti.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_grandmas-lantern-festival_1', 'bok_grandmas-lantern-festival', 1, 'What did Bram''s family make together?', 'Apa yang dibuat keluarga Bram bersama?', '["Kites","Paper lanterns","Cookies","Masks"]', '["Layang-layang","Lampion kertas","Kue","Topeng"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_grandmas-lantern-festival_2', 'bok_grandmas-lantern-festival', 2, 'What do the lanterns carry, according to Grandma?', 'Menurut Nenek, apa yang dibawa lampion?', '["Food","Wishes for the new year","Money","Nothing special"]', '["Makanan","Harapan untuk tahun baru","Uang","Tidak ada yang khusus"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_grandmas-lantern-festival_3', 'bok_grandmas-lantern-festival', 3, 'What did Bram write on his lantern?', 'Apa yang ditulis Bram di lampionnya?', '["A joke","A wish for loved ones to be happy and healthy","His name only","A drawing"]', '["Lelucon","Harapan agar orang tercinta bahagia dan sehat","Namanya saja","Gambar"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_why-teeth-need-brushing', 'why-teeth-need-brushing', 'Why Teeth Need Brushing', 'Kenapa Gigi Perlu Disikat', 'A friendly visit to the dentist teaches a reluctant boy why brushing his teeth every day matters.', 'Kunjungan yang menyenangkan ke dokter gigi mengajarkan seorang anak yang malas kenapa menyikat gigi setiap hari itu penting.', 'cat_health-body', 'aut_axto-creative-team', 'ocean', '🦷', 3, 7, 0, 'published', 6, 3734, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_1', 'bok_why-teeth-need-brushing', 1, 'health-1', 'Ega never liked brushing his teeth. "It takes too long," he always complained.', 'Ega tidak pernah suka menyikat gigi. "Terlalu lama," ia selalu mengeluh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_2', 'bok_why-teeth-need-brushing', 2, 'health-2', 'One day, his tooth started to hurt, so Mom took him to see Dr. Nisa, the dentist.', 'Suatu hari, giginya mulai sakit, jadi Ibu membawanya ke Dr. Nisa, dokter gigi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_3', 'bok_why-teeth-need-brushing', 3, 'health-3', 'Dr. Nisa showed him a picture: tiny sugar bugs love hiding in unbrushed teeth and cause holes.', 'Dr. Nisa menunjukkan gambar: kuman gula kecil suka bersembunyi di gigi yang tak disikat dan menyebabkan lubang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_4', 'bok_why-teeth-need-brushing', 4, 'health-4', '"Brushing twice a day chases the sugar bugs away before they can make a home in your teeth," she said.', '"Menyikat gigi dua kali sehari mengusir kuman gula sebelum mereka bisa tinggal di gigimu," katanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_5', 'bok_why-teeth-need-brushing', 5, 'health-5', 'Dr. Nisa gently fixed Ega''s tooth, and gave him a fun new toothbrush shaped like a dinosaur.', 'Dr. Nisa memperbaiki gigi Ega dengan lembut, dan memberinya sikat gigi baru berbentuk dinosaurus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-teeth-need-brushing_6', 'bok_why-teeth-need-brushing', 6, 'health-6', 'Now Ega brushes every morning and night, proud that his teeth are strong and sugar-bug-free.', 'Sekarang Ega menyikat gigi setiap pagi dan malam, bangga giginya kuat dan bebas kuman gula.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-teeth-need-brushing_1', 'bok_why-teeth-need-brushing', 1, 'Why did Ega go to the dentist?', 'Kenapa Ega pergi ke dokter gigi?', '["For a checkup only","His tooth started to hurt","To get a toy","For fun"]', '["Cek rutin saja","Giginya mulai sakit","Untuk dapat mainan","Untuk senang-senang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-teeth-need-brushing_2', 'bok_why-teeth-need-brushing', 2, 'What did Dr. Nisa say causes holes in teeth?', 'Menurut Dr. Nisa, apa yang menyebabkan lubang di gigi?', '["Cold water","Sugar bugs on unbrushed teeth","Sunlight","Too much sleep"]', '["Air dingin","Kuman gula di gigi tak disikat","Sinar matahari","Terlalu banyak tidur"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-teeth-need-brushing_3', 'bok_why-teeth-need-brushing', 3, 'How often should you brush your teeth?', 'Seberapa sering sebaiknya menyikat gigi?', '["Once a week","Twice a day","Only when it hurts","Never"]', '["Sekali seminggu","Dua kali sehari","Hanya saat sakit","Tidak pernah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-magic-words', 'the-magic-words', 'The Magic Words: Please and Thank You', 'Kata Ajaib: Tolong dan Terima Kasih', 'A young rabbit discovers that two small words can turn a grumpy day into a wonderful one.', 'Seekor kelinci kecil menemukan bahwa dua kata sederhana bisa mengubah hari yang buruk menjadi menyenangkan.', 'cat_manners', 'aut_axto-creative-team', 'sunrise', '🙏', 2, 6, 0, 'published', 6, 2486, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_1', 'bok_the-magic-words', 1, 'manners-1', 'Kiki the rabbit wanted a carrot from the market stall. "Give me a carrot!" she demanded.', 'Kiki si kelinci ingin sebuah wortel dari kios pasar. "Kasih aku wortel!" katanya menuntut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_2', 'bok_the-magic-words', 2, 'manners-2', 'The shopkeeper, Mr. Beaver, looked a little sad and slowly turned away without a word.', 'Pemilik toko, Pak Berang-berang, terlihat sedikit sedih dan perlahan berbalik tanpa berkata apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_3', 'bok_the-magic-words', 3, 'manners-3', 'Kiki''s mother whispered gently, "Try asking with the magic words, sweetheart."', 'Ibu Kiki berbisik lembut, "Coba minta dengan kata ajaib, Sayang."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_4', 'bok_the-magic-words', 4, 'manners-4', '"Could I please have a carrot?" Kiki asked, softer this time. Mr. Beaver''s face lit up with a smile.', '"Bolehkah aku minta wortel, tolong?" tanya Kiki, kali ini lebih lembut. Wajah Pak Berang-berang langsung ceria.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_5', 'bok_the-magic-words', 5, 'manners-5', 'He handed her the biggest, crunchiest carrot in the stall. "Thank you so much!" Kiki said happily.', 'Ia memberikan wortel terbesar dan paling renyah di kiosnya. "Terima kasih banyak!" kata Kiki riang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-words_6', 'bok_the-magic-words', 6, 'manners-6', 'From that day, Kiki always remembered: please and thank you make everyone''s day a little brighter.', 'Sejak hari itu, Kiki selalu ingat: tolong dan terima kasih membuat hari semua orang sedikit lebih cerah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-words_1', 'bok_the-magic-words', 1, 'How did Kiki first ask for a carrot?', 'Bagaimana Kiki pertama kali meminta wortel?', '["Politely","By demanding it rudely","By singing","By writing a note"]', '["Dengan sopan","Dengan menuntut kasar","Dengan bernyanyi","Dengan menulis catatan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-words_2', 'bok_the-magic-words', 2, 'What are the "magic words"?', 'Apa "kata ajaib" itu?', '["Hello and goodbye","Please and thank you","Yes and no","Sorry and okay"]', '["Halo dan sampai jumpa","Tolong dan terima kasih","Ya dan tidak","Maaf dan oke"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-words_3', 'bok_the-magic-words', 3, 'How did Mr. Beaver react to the magic words?', 'Bagaimana reaksi Pak Berang-berang mendengar kata ajaib?', '["He got angrier","He smiled and gave the best carrot","He ignored her","He closed his shop"]', '["Makin marah","Tersenyum dan memberi wortel terbaik","Mengabaikannya","Menutup tokonya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-girl-who-planted-a-forest', 'the-girl-who-planted-a-forest', 'The Girl Who Planted a Forest', 'Gadis yang Menanam Hutan', 'Inspired by real young environmentalists around the world, this story follows a girl whose one small act of planting trees grows into a movement.', 'Terinspirasi dari anak-anak pencinta lingkungan di dunia nyata, kisah ini mengikuti seorang gadis yang aksi kecilnya menanam pohon tumbuh menjadi gerakan besar.', 'cat_true-stories', 'aut_axto-creative-team', 'forest', '🌟', 6, 11, 0, 'published', 6, 1226, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_1', 'bok_the-girl-who-planted-a-forest', 1, 'true-1', 'When Maya was seven, she noticed the hill behind her school had no trees left — only dry, cracked earth.', 'Ketika Maya berusia tujuh tahun, ia menyadari bukit di belakang sekolahnya tak ada pohon lagi — hanya tanah kering yang retak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_2', 'bok_the-girl-who-planted-a-forest', 2, 'true-2', 'Her teacher explained that without trees, the soil couldn''t hold rainwater, and animals had nowhere to live.', 'Gurunya menjelaskan bahwa tanpa pohon, tanah tak bisa menahan air hujan, dan hewan tak punya tempat tinggal.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_3', 'bok_the-girl-who-planted-a-forest', 3, 'true-3', 'Maya decided to plant just one small seedling that weekend. It felt tiny compared to the whole bare hill.', 'Maya memutuskan menanam satu bibit kecil akhir pekan itu. Rasanya kecil sekali dibanding seluruh bukit gundul.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_4', 'bok_the-girl-who-planted-a-forest', 4, 'true-4', 'She asked her friends to help the next weekend. Ten children came, then twenty, then the whole school.', 'Ia mengajak teman-temannya membantu akhir pekan berikutnya. Sepuluh anak datang, lalu dua puluh, lalu seluruh sekolah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_5', 'bok_the-girl-who-planted-a-forest', 5, 'true-5', 'Within two years, hundreds of young trees covered the hill, and birds and butterflies began to return.', 'Dalam dua tahun, ratusan pohon muda menutupi bukit itu, dan burung serta kupu-kupu mulai kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-planted-a-forest_6', 'bok_the-girl-who-planted-a-forest', 6, 'true-6', 'Maya learned that one small act, shared with others, can grow into something as big as a forest.', 'Maya belajar bahwa satu tindakan kecil, jika dibagikan bersama orang lain, bisa tumbuh menjadi sebesar hutan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-planted-a-forest_1', 'bok_the-girl-who-planted-a-forest', 1, 'What did Maya notice about the hill?', 'Apa yang disadari Maya tentang bukit itu?', '["It had too many trees","It had no trees left","It was covered in flowers","It was underwater"]', '["Terlalu banyak pohon","Tidak ada pohon lagi","Penuh bunga","Terendam air"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-planted-a-forest_2', 'bok_the-girl-who-planted-a-forest', 2, 'How did Maya''s small act grow?', 'Bagaimana tindakan kecil Maya berkembang?', '["It stayed just her alone","Friends and eventually the whole school joined","She gave up","Nobody noticed"]', '["Tetap sendirian","Teman-teman dan akhirnya seluruh sekolah ikut","Ia menyerah","Tidak ada yang peduli"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-planted-a-forest_3', 'bok_the-girl-who-planted-a-forest', 3, 'What returned to the hill after the trees grew?', 'Apa yang kembali ke bukit setelah pohon tumbuh?', '["Cars","Birds and butterflies","Buildings","Nothing changed"]', '["Mobil","Burung dan kupu-kupu","Gedung","Tidak ada yang berubah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-lion-and-the-mouse', 'the-lion-and-the-mouse', 'The Lion and the Mouse', 'Singa dan Tikus Kecil', 'A tiny mouse promises to help a mighty lion — and one day, against all odds, she keeps her word.', 'Seekor tikus kecil berjanji menolong singa yang perkasa — dan suatu hari, ia benar-benar menepatinya.', 'cat_moral-stories', 'aut_axto-creative-team', 'sunrise', '🦁', 3, 8, 0, 'published', 14, 617, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_1', 'bok_the-lion-and-the-mouse', 1, 'lion-mouse-1', 'Deep in the golden grasslands of Africa lived a great lion. He was the strongest animal for miles around, and when he roared, even the wind seemed to hold its breath.', 'Jauh di padang rumput keemasan Afrika, hiduplah seekor singa besar. Ia hewan terkuat sejauh mata memandang, dan ketika ia mengaum, angin pun seakan menahan napas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_2', 'bok_the-lion-and-the-mouse', 2, 'lion-mouse-2', 'One warm afternoon, the lion lay sleeping under a shady acacia tree, his huge paws stretched out in the soft grass.', 'Suatu siang yang hangat, singa itu tertidur di bawah pohon akasia yang rindang, cakar besarnya terjulur di rerumputan lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_3', 'bok_the-lion-and-the-mouse', 3, 'lion-mouse-3', 'A little mouse, hurrying home with a seed for her supper, did not see the sleeping lion. She scampered right up his warm back — and woke him with a start!', 'Seekor tikus kecil yang tergesa pulang membawa biji untuk makan malamnya tak melihat singa yang tidur. Ia berlari tepat ke punggung hangat sang singa — dan membangunkannya!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_4', 'bok_the-lion-and-the-mouse', 4, 'lion-mouse-4', 'The lion''s giant paw came down and trapped her gently against the ground. ''How dare you wake me!'' he growled. The mouse trembled from her whiskers to her tail.', 'Cakar raksasa singa turun dan menahannya lembut ke tanah. ''Berani sekali kau membangunkanku!'' geramnya. Tikus itu gemetar dari kumis sampai ekornya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_5', 'bok_the-lion-and-the-mouse', 5, 'lion-mouse-5', '''Please, mighty lion, let me go,'' she squeaked. ''I am only small, and I meant no harm. If you set me free, perhaps one day I can help you.''', '''Tolong, singa yang perkasa, lepaskan aku,'' cicitnya. ''Aku hanya kecil dan tak bermaksud jahat. Jika kau membebaskanku, mungkin suatu hari aku bisa menolongmu.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_6', 'bok_the-lion-and-the-mouse', 6, 'lion-mouse-6', 'The lion laughed a great rumbling laugh. ''You? Help me? What a funny little thought!'' But he was in a kind mood, so he lifted his paw and let her go.', 'Singa itu tertawa menggelegar. ''Kau? Menolongku? Sungguh lucu!'' Namun hatinya sedang baik, maka ia mengangkat cakarnya dan melepaskan tikus itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_7', 'bok_the-lion-and-the-mouse', 7, 'lion-mouse-7', '''Thank you, thank you!'' cried the mouse, and she darted away into the grass, her small heart pounding with relief.', '''Terima kasih, terima kasih!'' seru tikus itu, lalu melesat ke rerumputan, jantung kecilnya berdebar lega.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_8', 'bok_the-lion-and-the-mouse', 8, 'lion-mouse-8', 'Many days passed. Then one evening, hunters came to the grasslands. They spread a strong rope net between the trees, and the great lion walked straight into their trap.', 'Berhari-hari berlalu. Lalu suatu senja, pemburu datang ke padang. Mereka membentangkan jaring tali yang kuat di antara pohon, dan singa besar itu berjalan tepat ke perangkap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_9', 'bok_the-lion-and-the-mouse', 9, 'lion-mouse-9', 'The more he struggled, the tighter the net held him. He roared and roared, but the ropes would not break. For the first time, the mighty lion felt truly helpless.', 'Semakin ia meronta, semakin erat jaring itu mengikatnya. Ia mengaum berkali-kali, tetapi tali itu tak putus. Untuk pertama kalinya, singa perkasa itu merasa benar-benar tak berdaya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_10', 'bok_the-lion-and-the-mouse', 10, 'lion-mouse-10', 'Far away, the little mouse heard the desperate roars. ''That is my friend the lion!'' she said, and she ran as fast as her tiny legs could carry her.', 'Jauh di sana, tikus kecil mendengar aumannya yang putus asa. ''Itu sahabatku, sang singa!'' katanya, lalu ia berlari secepat kaki kecilnya bisa membawanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_11', 'bok_the-lion-and-the-mouse', 11, 'lion-mouse-11', 'She reached the net and began to gnaw — nibble, nibble, nibble — with her sharp little teeth. One rope snapped. Then another. Then another.', 'Ia sampai di jaring dan mulai menggerogoti — kriuk, kriuk, kriuk — dengan gigi kecilnya yang tajam. Satu tali putus. Lalu satu lagi. Lalu satu lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_12', 'bok_the-lion-and-the-mouse', 12, 'lion-mouse-12', 'At last the net fell open, and the great lion stepped free. He looked down at the tiny mouse in wonder. ''You truly did help me,'' he said softly.', 'Akhirnya jaring itu terbuka, dan singa besar melangkah bebas. Ia menunduk memandang tikus mungil itu dengan takjub. ''Kau sungguh menolongku,'' katanya lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_13', 'bok_the-lion-and-the-mouse', 13, 'lion-mouse-13', 'From that day on, the lion and the mouse were the closest of friends. And the lion never again laughed at anyone for being small.', 'Sejak hari itu, singa dan tikus menjadi sahabat terdekat. Dan singa tak pernah lagi menertawakan siapa pun karena tubuhnya kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lion-and-the-mouse_14', 'bok_the-lion-and-the-mouse', 14, 'lion-mouse-14', 'For kindness is never wasted, and even the smallest friend can do the greatest thing. The end.', 'Sebab kebaikan tak pernah sia-sia, dan sahabat sekecil apa pun bisa melakukan hal terbesar. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lion-and-the-mouse_1', 'bok_the-lion-and-the-mouse', 1, 'Why did the lion let the mouse go?', 'Mengapa singa melepaskan tikus?', '["He was hungry","He was in a kind mood","The mouse ran away","He was afraid"]', '["Ia lapar","Hatinya sedang baik","Tikus melarikan diri","Ia takut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lion-and-the-mouse_2', 'bok_the-lion-and-the-mouse', 2, 'How did the mouse save the lion?', 'Bagaimana tikus menyelamatkan singa?', '["She roared loudly","She called the hunters","She gnawed through the net","She dug a hole"]', '["Ia mengaum keras","Ia memanggil pemburu","Ia menggerogoti jaring","Ia menggali lubang"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lion-and-the-mouse_3', 'bok_the-lion-and-the-mouse', 3, 'What is the lesson of the story?', 'Apa pelajaran dari cerita ini?', '["Big is always best","Kindness is never wasted","Never sleep outside","Run fast"]', '["Besar selalu terbaik","Kebaikan tak pernah sia-sia","Jangan tidur di luar","Berlari cepat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_momotaro-the-peach-boy', 'momotaro-the-peach-boy', 'Momotaro, the Peach Boy', 'Momotaro, Anak dari Buah Persik', 'A brave boy born from a giant peach sets off with three animal friends to bring peace back to his island.', 'Anak pemberani yang lahir dari buah persik raksasa berpetualang bersama tiga sahabat hewan untuk membawa kedamaian kembali ke pulaunya.', 'cat_adventure', 'aut_axto-creative-team', 'sunrise', '🍑', 4, 9, 0, 'published', 15, 3473, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_1', 'bok_momotaro-the-peach-boy', 1, 'momo-1', 'Long ago in Japan, an old woodcutter and his wife lived at the edge of a quiet village. They were kind and gentle, but they had no children, and their little house often felt empty.', 'Dahulu kala di Jepang, seorang penebang kayu tua dan istrinya tinggal di tepi desa yang tenang. Mereka baik dan lembut, tetapi tak punya anak, dan rumah kecil mereka sering terasa sepi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_2', 'bok_momotaro-the-peach-boy', 2, 'momo-2', 'One morning, while the old woman washed clothes by the river, an enormous peach came bobbing down the water — the biggest peach she had ever seen.', 'Suatu pagi, ketika nenek mencuci pakaian di sungai, sebuah buah persik raksasa hanyut di air — persik terbesar yang pernah ia lihat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_3', 'bok_momotaro-the-peach-boy', 3, 'momo-3', 'She carried it home, and when the old man raised his knife to slice it, the peach split open by itself — and inside sat a healthy, laughing baby boy!', 'Ia membawanya pulang, dan ketika kakek mengangkat pisau untuk membelahnya, persik itu terbuka dengan sendirinya — dan di dalamnya duduk seorang bayi laki-laki yang sehat dan tertawa!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_4', 'bok_momotaro-the-peach-boy', 4, 'momo-4', '''A gift from heaven!'' they cried with joy. They named him Momotaro, which means Peach Boy, and raised him with all their love.', '''Anugerah dari langit!'' seru mereka penuh gembira. Mereka menamainya Momotaro, yang berarti Anak Persik, dan membesarkannya dengan segenap cinta.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_5', 'bok_momotaro-the-peach-boy', 5, 'momo-5', 'Momotaro grew strong and kind. But across the sea lay Ogre Island, where fierce ogres sailed out to trouble the villages and take what was not theirs.', 'Momotaro tumbuh kuat dan baik hati. Namun di seberang laut ada Pulau Raksasa, tempat para raksasa buas berlayar untuk mengganggu desa dan merampas yang bukan milik mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_6', 'bok_momotaro-the-peach-boy', 6, 'momo-6', 'When he was old enough, Momotaro said, ''I will sail to Ogre Island and ask the ogres to stop, so our people can live in peace.'' His parents packed him millet dumplings for the journey.', 'Ketika cukup besar, Momotaro berkata, ''Aku akan berlayar ke Pulau Raksasa dan meminta mereka berhenti, agar rakyat kita hidup damai.'' Orang tuanya membekali kue millet untuk perjalanannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_7', 'bok_momotaro-the-peach-boy', 7, 'momo-7', 'On the road he met a spotted dog. ''Where are you going, Momotaro?'' ''To Ogre Island, for peace.'' ''Give me a dumpling and I will come too!'' So they walked on together.', 'Di jalan ia bertemu anjing belang. ''Mau ke mana, Momotaro?'' ''Ke Pulau Raksasa, demi kedamaian.'' ''Beri aku sekue dan aku ikut!'' Maka mereka berjalan bersama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_8', 'bok_momotaro-the-peach-boy', 8, 'momo-8', 'Next came a clever monkey, and then a bright-eyed pheasant. Each shared a dumpling, and each joined the quest. Now they were four brave friends.', 'Lalu datang seekor monyet cerdik, dan seekor burung pegar bermata cerah. Masing-masing berbagi kue, dan masing-masing ikut serta. Kini mereka berempat sahabat pemberani.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_9', 'bok_momotaro-the-peach-boy', 9, 'momo-9', 'They built a little boat and rowed across the wide blue sea. The pheasant flew ahead to scout, the monkey climbed the mast, and the dog watched the waves.', 'Mereka membuat perahu kecil dan mendayung menyeberangi laut biru yang luas. Pegar terbang memandu, monyet memanjat tiang, dan anjing mengawasi ombak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_10', 'bok_momotaro-the-peach-boy', 10, 'momo-10', 'At last they reached Ogre Island, ringed by tall black walls. The ogres laughed from their fortress. ''Go home, little boy!'' they shouted.', 'Akhirnya mereka sampai di Pulau Raksasa, dikelilingi tembok hitam yang tinggi. Para raksasa tertawa dari benteng mereka. ''Pulanglah, anak kecil!'' teriak mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_11', 'bok_momotaro-the-peach-boy', 11, 'momo-11', 'But Momotaro and his friends worked as a team. The pheasant swooped and distracted the ogres, the monkey unlocked the gate, and the dog and Momotaro walked bravely inside.', 'Namun Momotaro dan sahabatnya bekerja sebagai satu tim. Pegar menukik mengalihkan perhatian raksasa, monyet membuka gerbang, dan anjing bersama Momotaro melangkah masuk dengan berani.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_12', 'bok_momotaro-the-peach-boy', 12, 'momo-12', 'The ogre king was surprised by their courage and teamwork. ''We surrender!'' he said. ''We are sorry for the trouble we caused.''', 'Raja raksasa terkejut oleh keberanian dan kerja sama mereka. ''Kami menyerah!'' katanya. ''Kami minta maaf atas kekacauan yang kami buat.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_13', 'bok_momotaro-the-peach-boy', 13, 'momo-13', 'Momotaro did not wish to be cruel. ''Return what you have taken, and promise to trouble the villages no more.'' The ogres agreed and gave back every stolen treasure.', 'Momotaro tak ingin kejam. ''Kembalikan yang kalian rampas, dan berjanjilah tak lagi mengganggu desa.'' Para raksasa setuju dan mengembalikan setiap harta yang mereka curi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_14', 'bok_momotaro-the-peach-boy', 14, 'momo-14', 'Momotaro and his three friends sailed home as heroes. The village celebrated, and the old couple hugged their brave Peach Boy with happy tears.', 'Momotaro dan tiga sahabatnya berlayar pulang sebagai pahlawan. Desa bersukacita, dan pasangan tua itu memeluk Anak Persik pemberani mereka dengan air mata bahagia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_momotaro-the-peach-boy_15', 'bok_momotaro-the-peach-boy', 15, 'momo-15', 'And from that day, the island lived in peace — because Momotaro knew that courage and good friends can solve even the biggest troubles. The end.', 'Dan sejak hari itu, pulau itu hidup damai — sebab Momotaro tahu bahwa keberanian dan sahabat yang baik dapat mengatasi masalah terbesar sekalipun. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_momotaro-the-peach-boy_1', 'bok_momotaro-the-peach-boy', 1, 'Where was Momotaro found?', 'Di mana Momotaro ditemukan?', '["In a basket","Inside a giant peach","Under a tree","In a boat"]', '["Dalam keranjang","Di dalam persik raksasa","Di bawah pohon","Di perahu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_momotaro-the-peach-boy_2', 'bok_momotaro-the-peach-boy', 2, 'Who joined Momotaro on his journey?', 'Siapa yang menemani Momotaro?', '["A dog, a monkey, and a pheasant","Three ogres","His teacher","No one"]', '["Anjing, monyet, dan pegar","Tiga raksasa","Gurunya","Tak seorang pun"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_momotaro-the-peach-boy_3', 'bok_momotaro-the-peach-boy', 3, 'How did they defeat the ogres?', 'Bagaimana mereka mengalahkan raksasa?', '["By fighting alone","With teamwork","By running away","With magic"]', '["Bertarung sendiri","Dengan kerja sama","Dengan melarikan diri","Dengan sihir"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_anansi-and-the-pot-of-wisdom', 'anansi-and-the-pot-of-wisdom', 'Anansi and the Pot of Wisdom', 'Anansi dan Periuk Kebijaksanaan', 'A clever spider tries to keep all the world''s wisdom for himself — and learns something wiser than he expected.', 'Laba-laba cerdik berusaha menyimpan semua kebijaksanaan dunia untuk dirinya sendiri — lalu belajar sesuatu yang lebih bijak dari dugaannya.', 'cat_moral-stories', 'aut_axto-creative-team', 'forest', '🕷️', 4, 9, 0, 'published', 12, 3471, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_1', 'bok_anansi-and-the-pot-of-wisdom', 1, 'anansi-1', 'In the warm forests of West Africa, there lived a clever spider named Anansi. He loved to know things — more than anyone else in the whole world.', 'Di hutan hangat Afrika Barat, hiduplah laba-laba cerdik bernama Anansi. Ia suka mengetahui banyak hal — lebih dari siapa pun di seluruh dunia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_2', 'bok_anansi-and-the-pot-of-wisdom', 2, 'anansi-2', 'One day Anansi had an idea. ''If I gather ALL the wisdom in the world into one pot,'' he thought, ''then I will be the wisest of all, and everyone will need me.''', 'Suatu hari Anansi punya gagasan. ''Jika kukumpulkan SEMUA kebijaksanaan dunia ke dalam satu periuk,'' pikirnya, ''aku akan menjadi yang paling bijak, dan semua orang membutuhkanku.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_3', 'bok_anansi-and-the-pot-of-wisdom', 3, 'anansi-3', 'So he traveled far and wide, collecting wise sayings, clever ideas, and useful knowledge, and he poured every drop into a great clay pot.', 'Maka ia mengembara jauh, mengumpulkan kata-kata bijak, ide cerdas, dan pengetahuan berguna, lalu menuang setiap tetesnya ke dalam periuk tanah liat yang besar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_4', 'bok_anansi-and-the-pot-of-wisdom', 4, 'anansi-4', 'When the pot was full, Anansi wanted to hide it where no one could ever reach it. ''I will keep it at the very top of the tallest tree,'' he decided.', 'Ketika periuk itu penuh, Anansi ingin menyembunyikannya di tempat yang tak terjangkau siapa pun. ''Akan kusimpan di puncak pohon tertinggi,'' putusnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_5', 'bok_anansi-and-the-pot-of-wisdom', 5, 'anansi-5', 'He tied the heavy pot to the front of his belly and began to climb. But the pot kept bumping against the trunk and getting in his way.', 'Ia mengikat periuk berat itu di depan perutnya dan mulai memanjat. Namun periuk itu terus terbentur batang pohon dan menghalangi jalannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_6', 'bok_anansi-and-the-pot-of-wisdom', 6, 'anansi-6', 'Again and again he slipped back down. The pot was simply too big and awkward to carry up the front of him. Anansi grew tired and cross.', 'Berulang kali ia melorot turun. Periuk itu terlalu besar dan menyusahkan untuk dibawa di depan tubuhnya. Anansi menjadi lelah dan kesal.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_7', 'bok_anansi-and-the-pot-of-wisdom', 7, 'anansi-7', 'Down below, his young son had been watching quietly. ''Father,'' he called up, ''wouldn''t it be easier to tie the pot on your BACK? Then you could climb freely.''', 'Di bawah, anaknya yang kecil memperhatikan dengan tenang. ''Ayah,'' serunya, ''bukankah lebih mudah mengikat periuk di PUNGGUNG? Agar Ayah bisa memanjat dengan leluasa.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_8', 'bok_anansi-and-the-pot-of-wisdom', 8, 'anansi-8', 'Anansi stopped. The idea was so simple — and so clever — and it had come from his little son, not from the great pot of wisdom at all.', 'Anansi terdiam. Gagasan itu begitu sederhana — dan begitu cerdas — dan datang dari anak kecilnya, bukan dari periuk kebijaksanaan yang besar itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_9', 'bok_anansi-and-the-pot-of-wisdom', 9, 'anansi-9', '''I gathered all the wisdom in the world,'' Anansi said slowly, ''yet my own son knew something I did not. Wisdom cannot belong to just one person.''', '''Aku mengumpulkan semua kebijaksanaan dunia,'' kata Anansi perlahan, ''namun anakku sendiri tahu sesuatu yang tak kuketahui. Kebijaksanaan tak bisa menjadi milik satu orang saja.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_10', 'bok_anansi-and-the-pot-of-wisdom', 10, 'anansi-10', 'In that moment Anansi understood. He lifted the pot high and let it tip. The wisdom spilled out and scattered on the wind, drifting to every corner of the earth.', 'Saat itu Anansi mengerti. Ia mengangkat periuk itu tinggi-tinggi dan menumpahkannya. Kebijaksanaan tumpah dan berhamburan tertiup angin, melayang ke setiap sudut bumi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_11', 'bok_anansi-and-the-pot-of-wisdom', 11, 'anansi-11', 'That is why, to this day, a little bit of wisdom can be found in everyone — in the old and the young, the big and the small.', 'Itulah sebabnya, hingga kini, sedikit kebijaksanaan bisa ditemukan pada setiap orang — pada yang tua dan yang muda, yang besar dan yang kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_anansi-and-the-pot-of-wisdom_12', 'bok_anansi-and-the-pot-of-wisdom', 12, 'anansi-12', 'And Anansi learned the wisest lesson of all: that we grow wiser not by keeping knowledge to ourselves, but by sharing it. The end.', 'Dan Anansi belajar pelajaran paling bijak: bahwa kita menjadi lebih bijak bukan dengan menyimpan pengetahuan sendiri, melainkan dengan membagikannya. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_anansi-and-the-pot-of-wisdom_1', 'bok_anansi-and-the-pot-of-wisdom', 1, 'What did Anansi try to collect?', 'Apa yang Anansi coba kumpulkan?', '["Gold coins","All the wisdom in the world","Ripe fruit","Spider webs"]', '["Koin emas","Semua kebijaksanaan dunia","Buah matang","Jaring laba-laba"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_anansi-and-the-pot-of-wisdom_2', 'bok_anansi-and-the-pot-of-wisdom', 2, 'Who gave Anansi the clever idea?', 'Siapa yang memberi Anansi ide cerdas?', '["A wise king","His young son","A bird","No one"]', '["Raja bijak","Anaknya yang kecil","Seekor burung","Tak seorang pun"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_anansi-and-the-pot-of-wisdom_3', 'bok_anansi-and-the-pot-of-wisdom', 3, 'What did Anansi learn?', 'Apa yang Anansi pelajari?', '["To keep everything","That wisdom grows by sharing","To climb faster","To stay quiet"]', '["Menyimpan segalanya","Kebijaksanaan tumbuh dengan berbagi","Memanjat lebih cepat","Diam saja"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-fisherman-and-the-golden-fish', 'the-fisherman-and-the-golden-fish', 'The Fisherman and the Golden Fish', 'Nelayan dan Ikan Emas', 'A kind old fisherman frees a magical fish — but when wishes grow greedy, he learns what truly matters.', 'Nelayan tua yang baik hati membebaskan ikan ajaib — namun ketika permintaan berubah tamak, ia belajar apa yang sungguh berharga.', 'cat_moral-stories', 'aut_axto-creative-team', 'ocean', '🐟', 4, 9, 0, 'published', 14, 2898, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_1', 'bok_the-fisherman-and-the-golden-fish', 1, 'gfish-1', 'By the shore of a wide grey sea lived a poor old fisherman and his wife, in a tiny hut with a leaky roof and one old fishing net.', 'Di tepi laut kelabu yang luas, tinggallah nelayan tua yang miskin dan istrinya, di gubuk kecil beratap bocor dengan satu jala tua.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_2', 'bok_the-fisherman-and-the-golden-fish', 2, 'gfish-2', 'One morning the fisherman cast his net and pulled up something that shimmered like sunlight — a beautiful golden fish.', 'Suatu pagi nelayan menebar jala dan menarik sesuatu yang berkilau seperti cahaya matahari — seekor ikan emas yang indah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_3', 'bok_the-fisherman-and-the-golden-fish', 3, 'gfish-3', 'To his amazement, the fish spoke. ''Kind fisherman, please let me go, and I will grant you a wish in return.''', 'Betapa terkejutnya ia, ikan itu berbicara. ''Nelayan yang baik, tolong lepaskan aku, dan aku akan mengabulkan satu permintaanmu.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_4', 'bok_the-fisherman-and-the-golden-fish', 4, 'gfish-4', 'The fisherman had a gentle heart. ''You need no reward, little fish. Go home to your family.'' And he slipped the golden fish back into the waves.', 'Nelayan itu berhati lembut. ''Kau tak perlu memberi imbalan, ikan kecil. Pulanglah ke keluargamu.'' Dan ia melepas ikan emas itu kembali ke ombak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_5', 'bok_the-fisherman-and-the-golden-fish', 5, 'gfish-5', 'When he told his wife, she frowned. ''You foolish man! Go back and ask for a fine new loaf of bread — ours is stale.''', 'Ketika ia bercerita pada istrinya, sang istri mengernyit. ''Suami bodoh! Kembalilah dan minta sepotong roti baru yang enak — roti kita sudah basi.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_6', 'bok_the-fisherman-and-the-golden-fish', 6, 'gfish-6', 'The fisherman called the fish, and at once fresh warm bread appeared on their table. But the next day, his wife wanted more.', 'Nelayan memanggil ikan itu, dan seketika roti hangat yang segar muncul di meja mereka. Namun keesokan harinya, istrinya ingin lebih.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_7', 'bok_the-fisherman-and-the-golden-fish', 7, 'gfish-7', '''Ask for a new house!'' she said. So he did, and their leaky hut became a snug cottage with a solid roof and a warm fire.', '''Minta rumah baru!'' katanya. Maka ia melakukannya, dan gubuk bocor mereka menjadi pondok nyaman beratap kokoh dengan perapian yang hangat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_8', 'bok_the-fisherman-and-the-golden-fish', 8, 'gfish-8', 'But a cottage was not enough. ''Now ask for a grand mansion, with servants and gardens!'' Again the fish granted it. Yet still she was not happy.', 'Namun pondok itu tak cukup. ''Sekarang minta rumah megah, dengan pelayan dan taman!'' Lagi-lagi ikan itu mengabulkannya. Namun sang istri tetap tak bahagia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_9', 'bok_the-fisherman-and-the-golden-fish', 9, 'gfish-9', '''I do not want to be rich,'' she declared. ''I want to be Queen of all the land!'' The fisherman''s heart sank, but he went to the shore once more.', '''Aku tak mau hanya kaya,'' katanya. ''Aku ingin menjadi Ratu seluruh negeri!'' Hati nelayan itu tenggelam, tetapi ia pergi ke pantai sekali lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_10', 'bok_the-fisherman-and-the-golden-fish', 10, 'gfish-10', 'The sea had turned dark and stormy. The golden fish rose from the churning waves. ''What does she wish for now?'' it asked quietly.', 'Laut menjadi gelap dan bergolak. Ikan emas muncul dari ombak yang bergemuruh. ''Apa lagi yang ia inginkan sekarang?'' tanyanya perlahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_11', 'bok_the-fisherman-and-the-golden-fish', 11, 'gfish-11', '''She wishes to be Queen,'' the fisherman whispered, ashamed. The fish looked at him with sad, wise eyes, then vanished beneath the water without a word.', '''Ia ingin menjadi Ratu,'' bisik nelayan itu dengan malu. Ikan itu menatapnya dengan mata sedih nan bijak, lalu lenyap di bawah air tanpa sepatah kata.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_12', 'bok_the-fisherman-and-the-golden-fish', 12, 'gfish-12', 'When the fisherman walked home, the mansion was gone. The gardens were gone. There stood only their tiny old hut, with its leaky roof, just as before.', 'Ketika nelayan pulang, rumah megah itu lenyap. Tamannya lenyap. Yang tersisa hanya gubuk tua kecil mereka, dengan atap bocornya, persis seperti dulu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_13', 'bok_the-fisherman-and-the-golden-fish', 13, 'gfish-13', 'His wife sat quietly by the door. For the first time in a long while, she looked at all they still had — each other, a roof, and the wide kind sea.', 'Istrinya duduk diam di dekat pintu. Untuk pertama kalinya sejak lama, ia memandang semua yang masih mereka miliki — satu sama lain, sebuah atap, dan laut yang luas dan ramah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-golden-fish_14', 'bok_the-fisherman-and-the-golden-fish', 14, 'gfish-14', '''I am sorry,'' she said softly. ''I forgot to be thankful.'' And from that day they lived simply and gratefully, and were happier than any king or queen. The end.', '''Maafkan aku,'' katanya lirih. ''Aku lupa bersyukur.'' Dan sejak hari itu mereka hidup sederhana dan penuh syukur, lebih bahagia dari raja atau ratu mana pun. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-golden-fish_1', 'bok_the-fisherman-and-the-golden-fish', 1, 'Why did the fisherman first let the fish go?', 'Mengapa nelayan mula-mula melepas ikan itu?', '["He wasn''t hungry","He had a kind heart","The fish was too small","He was afraid"]', '["Ia tak lapar","Ia berhati baik","Ikannya terlalu kecil","Ia takut"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-golden-fish_2', 'bok_the-fisherman-and-the-golden-fish', 2, 'What happened when the wife grew greedy?', 'Apa yang terjadi saat istrinya menjadi tamak?', '["She became Queen","Everything vanished","The fish gave more","Nothing changed"]', '["Ia jadi Ratu","Semuanya lenyap","Ikan memberi lebih","Tak ada yang berubah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-golden-fish_3', 'bok_the-fisherman-and-the-golden-fish', 3, 'What did the wife finally learn?', 'Apa yang akhirnya dipelajari istrinya?', '["To wish for more","To be thankful","To catch fish","To build houses"]', '["Meminta lebih banyak","Bersyukur","Menangkap ikan","Membangun rumah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-magic-paintbrush', 'the-magic-paintbrush', 'The Magic Paintbrush', 'Kuas Ajaib', 'A poor but generous boy is given a paintbrush that brings drawings to life — and uses its magic to help everyone but the greedy.', 'Anak miskin yang murah hati diberi kuas yang menghidupkan gambar — dan memakai keajaibannya untuk menolong semua orang, kecuali yang tamak.', 'cat_fairy-tales', 'aut_axto-creative-team', 'sunrise', '🖌️', 4, 9, 0, 'published', 13, 1877, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_1', 'bok_the-magic-paintbrush', 1, 'brush-1', 'In a village in old China lived a poor boy named Ma Liang. He had no paints and no brush, but more than anything in the world, he longed to draw.', 'Di sebuah desa di Tiongkok kuno, tinggallah anak miskin bernama Ma Liang. Ia tak punya cat maupun kuas, tetapi lebih dari apa pun di dunia, ia ingin menggambar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_2', 'bok_the-magic-paintbrush', 2, 'brush-2', 'He practiced with a twig in the sand and a wet finger on stone. Every bird, every fish, every leaf he drew looked almost ready to move.', 'Ia berlatih dengan ranting di pasir dan jari basah di atas batu. Setiap burung, ikan, dan daun yang ia gambar tampak nyaris bergerak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_3', 'bok_the-magic-paintbrush', 3, 'brush-3', 'One night an old man with a kind, glowing face appeared in his dream. ''You have a good and generous heart, Ma Liang. Here is a gift.''', 'Suatu malam, seorang kakek berwajah ramah dan bercahaya muncul dalam mimpinya. ''Hatimu baik dan murah hati, Ma Liang. Ini sebuah hadiah.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_4', 'bok_the-magic-paintbrush', 4, 'brush-4', 'When Ma Liang woke, a beautiful paintbrush lay in his hand. He dipped it and painted a crane — and the crane flapped its wings and flew off the paper into the sky!', 'Ketika Ma Liang bangun, sebuah kuas indah ada di tangannya. Ia mencelupkannya dan melukis burung bangau — dan bangau itu mengepakkan sayap dan terbang dari kertas ke langit!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_5', 'bok_the-magic-paintbrush', 5, 'brush-5', 'It was a magic paintbrush: whatever he painted came to life. But Ma Liang remembered his empty stomach and his poor neighbours.', 'Itu kuas ajaib: apa pun yang ia lukis menjadi hidup. Namun Ma Liang teringat perutnya yang lapar dan tetangganya yang miskin.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_6', 'bok_the-magic-paintbrush', 6, 'brush-6', 'He did not paint gold for himself. Instead he painted a plough for the farmer, a bucket for the water-carrier, and a warm blanket for a shivering old woman.', 'Ia tak melukis emas untuk dirinya. Ia justru melukis bajak untuk petani, ember untuk pembawa air, dan selimut hangat untuk nenek yang kedinginan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_7', 'bok_the-magic-paintbrush', 7, 'brush-7', 'Soon the whole village had what it needed, and everyone loved the kind boy with the magic brush.', 'Tak lama, seluruh desa memiliki apa yang mereka butuhkan, dan semua orang menyayangi anak baik dengan kuas ajaib itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_8', 'bok_the-magic-paintbrush', 8, 'brush-8', 'But news of the brush reached a greedy rich lord. He sent his guards to seize Ma Liang and lock him in a cold stone room. ''Paint me a mountain of gold!'' he demanded.', 'Namun kabar tentang kuas itu sampai ke telinga tuan tanah yang tamak. Ia mengirim pengawal menangkap Ma Liang dan menguncinya di ruang batu yang dingin. ''Lukiskan aku gunung emas!'' perintahnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_9', 'bok_the-magic-paintbrush', 9, 'brush-9', 'Ma Liang thought carefully. He agreed — but he was clever. First he painted a wide blue sea. ''Where is my gold?'' snapped the lord.', 'Ma Liang berpikir hati-hati. Ia setuju — tetapi ia cerdik. Pertama ia melukis laut biru yang luas. ''Mana emasku?'' bentak sang tuan tanah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_10', 'bok_the-magic-paintbrush', 10, 'brush-10', '''The gold is on an island across the water,'' said Ma Liang, and he painted a fine ship. The greedy lord and his guards jumped aboard at once.', '''Emasnya ada di pulau seberang,'' kata Ma Liang, lalu ia melukis kapal yang bagus. Tuan tanah tamak dan pengawalnya langsung melompat naik.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_11', 'bok_the-magic-paintbrush', 11, 'brush-11', '''Faster! Faster!'' cried the lord. So Ma Liang painted a strong wind. He painted it stronger, and stronger — until the waves rose and carried the ship far, far over the horizon.', '''Lebih cepat! Lebih cepat!'' teriak sang tuan tanah. Maka Ma Liang melukis angin kencang. Ia melukisnya makin kencang, makin kencang — hingga ombak meninggi dan membawa kapal itu jauh, jauh melewati cakrawala.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_12', 'bok_the-magic-paintbrush', 12, 'brush-12', 'The greedy lord was never seen troubling the village again. Ma Liang returned home free, and to the people who were kind and worked hard.', 'Tuan tanah tamak itu tak pernah lagi terlihat mengganggu desa. Ma Liang pulang dengan bebas, kembali kepada orang-orang yang baik dan pekerja keras.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-magic-paintbrush_13', 'bok_the-magic-paintbrush', 13, 'brush-13', 'For the rest of his days, Ma Liang used his magic brush only to help those in need — for he knew that a gift is truest when it is shared. The end.', 'Sepanjang sisa hidupnya, Ma Liang memakai kuas ajaibnya hanya untuk menolong yang membutuhkan — sebab ia tahu bahwa sebuah anugerah paling berarti ketika dibagikan. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-paintbrush_1', 'bok_the-magic-paintbrush', 1, 'What did the magic paintbrush do?', 'Apa yang dilakukan kuas ajaib itu?', '["Made things invisible","Brought drawings to life","Turned things to gold","Told stories"]', '["Membuat benda tak terlihat","Menghidupkan gambar","Mengubah benda jadi emas","Bercerita"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-paintbrush_2', 'bok_the-magic-paintbrush', 2, 'What did Ma Liang paint for the village?', 'Apa yang Ma Liang lukis untuk desa?', '["Gold for himself","Tools and blankets to help others","A castle","Nothing"]', '["Emas untuk dirinya","Alat dan selimut untuk menolong","Sebuah istana","Tidak ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-magic-paintbrush_3', 'bok_the-magic-paintbrush', 3, 'How did Ma Liang outwit the greedy lord?', 'Bagaimana Ma Liang mengecoh tuan tanah tamak?', '["He gave him gold","He painted a storm at sea","He ran away","He apologised"]', '["Memberinya emas","Melukis badai di laut","Melarikan diri","Meminta maaf"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_stone-soup', 'stone-soup', 'Stone Soup', 'Sup Batu', 'Three tired travellers arrive at a village with nothing but a stone — and teach everyone the magic of sharing.', 'Tiga pengembara lelah tiba di desa hanya dengan sebuah batu — dan mengajarkan semua orang keajaiban berbagi.', 'cat_friendship', 'aut_axto-creative-team', 'forest', '🍲', 3, 8, 0, 'published', 12, 2832, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_1', 'bok_stone-soup', 1, 'soup-1', 'Three tired travellers walked a long dusty road until they reached a small village at dusk. They were hungry, and they had no food at all.', 'Tiga pengembara yang lelah menyusuri jalan berdebu yang panjang hingga tiba di desa kecil saat senja. Mereka lapar, dan sama sekali tak punya makanan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_2', 'bok_stone-soup', 2, 'soup-2', 'They knocked on doors, but times were hard. ''We have nothing to spare,'' said each villager, and quietly closed the door.', 'Mereka mengetuk pintu-pintu, tetapi masa itu sulit. ''Kami tak punya lebih,'' kata setiap warga, lalu menutup pintu perlahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_3', 'bok_stone-soup', 3, 'soup-3', 'The travellers were not angry. Instead, they smiled. ''Then we shall make Stone Soup, and share it with the whole village!''', 'Para pengembara tidak marah. Mereka justru tersenyum. ''Kalau begitu kami akan membuat Sup Batu, dan membaginya dengan seluruh desa!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_4', 'bok_stone-soup', 4, 'soup-4', 'In the village square they lit a fire, set a big black pot of water to boil, and gently placed one smooth grey stone inside.', 'Di alun-alun desa mereka menyalakan api, menjerang periuk hitam besar berisi air, dan meletakkan sebuah batu kelabu yang halus ke dalamnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_5', 'bok_stone-soup', 5, 'soup-5', 'Curious villagers gathered round. ''Stone soup?'' ''Oh yes,'' said a traveller, stirring. ''It is delicious — though a pinch of salt would make it even better.''', 'Warga yang penasaran berkumpul. ''Sup batu?'' ''Oh ya,'' kata seorang pengembara sambil mengaduk. ''Rasanya lezat — meski sejumput garam akan membuatnya lebih enak lagi.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_6', 'bok_stone-soup', 6, 'soup-6', '''I have salt!'' said a woman, and hurried to fetch some. Soon a man said, ''I have a few carrots in my cellar,'' and in they went.', '''Aku punya garam!'' kata seorang perempuan, lalu bergegas mengambilnya. Tak lama seorang lelaki berkata, ''Aku punya beberapa wortel di gudang,'' dan wortel pun dimasukkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_7', 'bok_stone-soup', 7, 'soup-7', '''Onions would help,'' said a traveller kindly. ''I have onions!'' called a boy. Then came potatoes, then barley, then a handful of fresh green herbs.', '''Bawang akan menambah rasa,'' kata pengembara dengan ramah. ''Aku punya bawang!'' seru seorang anak. Lalu datang kentang, jelai, dan segenggam rempah hijau segar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_8', 'bok_stone-soup', 8, 'soup-8', 'One by one, each villager brought a little of what they had — a cabbage, some beans, a bit of milk — and stirred it into the bubbling pot.', 'Satu per satu, tiap warga membawa sedikit yang mereka punya — sebutir kubis, sedikit kacang, seteguk susu — dan mengaduknya ke dalam periuk yang mendidih.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_9', 'bok_stone-soup', 9, 'soup-9', 'The smell that rose from the pot was wonderful. Something that had begun with a single stone was becoming a feast for everyone.', 'Aroma yang naik dari periuk itu sungguh menggoda. Sesuatu yang bermula dari sebutir batu kini menjadi jamuan untuk semua orang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_10', 'bok_stone-soup', 10, 'soup-10', 'When the soup was ready, the whole village sat together in the square, sharing bowls, bread, and laughter under the first stars.', 'Ketika sup matang, seluruh desa duduk bersama di alun-alun, berbagi mangkuk, roti, dan tawa di bawah bintang-bintang pertama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_11', 'bok_stone-soup', 11, 'soup-11', '''What magic stone makes such a soup?'' the villagers asked. The travellers smiled. ''The stone is just a stone. The magic was you — sharing what you had.''', '''Batu ajaib apa yang membuat sup seperti ini?'' tanya warga. Para pengembara tersenyum. ''Batu itu hanyalah batu. Keajaibannya adalah kalian — berbagi apa yang kalian punya.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_stone-soup_12', 'bok_stone-soup', 12, 'soup-12', 'The next morning the travellers walked on, leaving behind a village that had learned the sweetest recipe of all: that a little from everyone becomes plenty for all. The end.', 'Keesokan paginya para pengembara melanjutkan perjalanan, meninggalkan desa yang telah belajar resep termanis: bahwa sedikit dari setiap orang menjadi berlimpah untuk semua. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_stone-soup_1', 'bok_stone-soup', 1, 'What did the travellers put in the pot first?', 'Apa yang pertama dimasukkan pengembara ke periuk?', '["A carrot","A stone","An onion","Salt"]', '["Wortel","Sebuah batu","Bawang","Garam"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_stone-soup_2', 'bok_stone-soup', 2, 'How did the soup become a feast?', 'Bagaimana sup itu menjadi jamuan besar?', '["By magic","Everyone shared a little food","The stone grew","They bought it"]', '["Dengan sihir","Semua berbagi sedikit makanan","Batunya membesar","Mereka membelinya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_stone-soup_3', 'bok_stone-soup', 3, 'What was the real ''magic''?', 'Apa ''keajaiban'' yang sebenarnya?', '["The stone","Sharing together","The big pot","The fire"]', '["Batunya","Berbagi bersama","Periuk besar","Apinya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-clever-rabbit-and-the-lion', 'the-clever-rabbit-and-the-lion', 'The Clever Rabbit and the Lion', 'Kelinci Cerdik dan Singa', 'From the ancient Panchatantra of India: a small rabbit uses a big idea to save the whole forest from a greedy lion.', 'Dari Panchatantra kuno India: kelinci kecil memakai ide besar untuk menyelamatkan seluruh hutan dari singa yang serakah.', 'cat_moral-stories', 'aut_axto-creative-team', 'meadow', '🐇', 4, 9, 0, 'published', 14, 471, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_1', 'bok_the-clever-rabbit-and-the-lion', 1, 'rabbit-lion-1', 'Long ago, in a deep green forest in India, there lived a lion who was never, ever satisfied. Every day he hunted more than he could eat, and the animals of the forest lived in fear.', 'Dahulu kala, di hutan hijau nan lebat di India, hiduplah seekor singa yang tak pernah puas. Setiap hari ia berburu lebih dari yang bisa ia makan, dan hewan-hewan hutan hidup dalam ketakutan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_2', 'bok_the-clever-rabbit-and-the-lion', 2, 'rabbit-lion-2', 'At last the animals gathered under the great banyan tree. ''If this goes on,'' said the old elephant, ''soon there will be no one left in the forest at all.''', 'Akhirnya hewan-hewan berkumpul di bawah pohon beringin besar. ''Kalau begini terus,'' kata gajah tua, ''sebentar lagi tak akan ada yang tersisa di hutan ini.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_3', 'bok_the-clever-rabbit-and-the-lion', 3, 'rabbit-lion-3', 'So they made a brave bargain with the lion: every day, one animal would come to him by lot, and in return he would leave all the others in peace. The lion licked his lips and agreed.', 'Maka mereka membuat kesepakatan berani dengan singa: setiap hari, satu hewan akan datang kepadanya berdasarkan undian, dan sebagai gantinya ia membiarkan yang lain hidup tenang. Singa menjilat bibirnya dan setuju.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_4', 'bok_the-clever-rabbit-and-the-lion', 4, 'rabbit-lion-4', 'One morning, the lot fell to a small grey rabbit. The other animals hung their heads. ''Poor little one,'' they whispered. But the rabbit''s bright eyes were already thinking.', 'Suatu pagi, undian jatuh pada seekor kelinci kecil abu-abu. Hewan-hewan lain menunduk sedih. ''Kasihan si kecil,'' bisik mereka. Namun mata cerah kelinci itu sudah mulai berpikir.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_5', 'bok_the-clever-rabbit-and-the-lion', 5, 'rabbit-lion-5', 'The rabbit did not hurry. He hopped slowly through the forest, stopped to nibble sweet grass, and arrived at the lion''s den when the sun was already high and hot.', 'Kelinci itu tidak terburu-buru. Ia melompat pelan menembus hutan, berhenti mengunyah rumput manis, dan tiba di sarang singa saat matahari sudah tinggi dan panas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_6', 'bok_the-clever-rabbit-and-the-lion', 6, 'rabbit-lion-6', 'The lion was pacing and roaring with hunger. ''You are LATE, and you are SMALL!'' he thundered. ''Is this how the forest keeps its promise?''', 'Singa mondar-mandir dan mengaum kelaparan. ''Kau TERLAMBAT, dan kau KECIL!'' geramnya. ''Beginikah cara hutan menepati janjinya?''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_7', 'bok_the-clever-rabbit-and-the-lion', 7, 'rabbit-lion-7', 'The rabbit bowed very low. ''Forgive me, Your Majesty. Five rabbits were sent to you this morning — but on the way, another lion leapt out and ate the other four!''', 'Kelinci membungkuk dalam-dalam. ''Ampuni hamba, Baginda. Lima kelinci dikirim untukmu pagi ini — tetapi di tengah jalan, singa lain melompat keluar dan memakan empat lainnya!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_8', 'bok_the-clever-rabbit-and-the-lion', 8, 'rabbit-lion-8', '''ANOTHER lion? In MY forest?'' The lion''s mane bristled like a storm cloud. ''Where is this thief? Take me to him at once!''', '''Singa LAIN? Di hutan-KU?'' Surai singa berdiri bagai awan badai. ''Di mana pencuri itu? Antarkan aku kepadanya sekarang juga!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_9', 'bok_the-clever-rabbit-and-the-lion', 9, 'rabbit-lion-9', 'The clever rabbit led him down a winding path to an old stone well, deep and still and full of clear water. ''He lives down there, Your Majesty,'' whispered the rabbit.', 'Kelinci cerdik menuntunnya melewati jalan berliku menuju sumur batu tua, dalam, tenang, dan penuh air jernih. ''Ia tinggal di bawah sana, Baginda,'' bisik kelinci.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_10', 'bok_the-clever-rabbit-and-the-lion', 10, 'rabbit-lion-10', 'The lion looked over the edge — and there, in the water, glared a mighty lion with a great dark mane, staring straight back at him!', 'Singa menjenguk ke tepi sumur — dan di sana, di dalam air, seekor singa perkasa bersurai gelap menatapnya tajam!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_11', 'bok_the-clever-rabbit-and-the-lion', 11, 'rabbit-lion-11', '''THIEF!'' roared the lion, and the well roared back. That was too much. He leapt at his rival with all his strength — and splashed into the deep, deep water.', '''PENCURI!'' aum sang singa, dan sumur itu mengaum balik. Itu keterlaluan baginya. Ia melompat menerkam lawannya sekuat tenaga — dan tercebur ke air yang dalam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_12', 'bok_the-clever-rabbit-and-the-lion', 12, 'rabbit-lion-12', 'The lion splashed and spluttered and finally dragged himself out, soaked and shivering and very much smaller-feeling. Without a word, he slunk away from the forest and never returned.', 'Singa itu megap-megap dan akhirnya merangkak keluar, basah kuyup, menggigil, dan merasa jauh lebih kecil. Tanpa sepatah kata pun, ia pergi meninggalkan hutan dan tak pernah kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_13', 'bok_the-clever-rabbit-and-the-lion', 13, 'rabbit-lion-13', 'The animals danced under the banyan tree and lifted the little rabbit onto the elephant''s back. ''The smallest of us saved us all!'' they cheered.', 'Hewan-hewan menari di bawah pohon beringin dan mengangkat kelinci kecil ke punggung gajah. ''Yang terkecil di antara kita menyelamatkan kita semua!'' sorak mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-clever-rabbit-and-the-lion_14', 'bok_the-clever-rabbit-and-the-lion', 14, 'rabbit-lion-14', 'For strength wins many fights, says the old Panchatantra — but wisdom wins the ones that matter. The end.', 'Sebab kekuatan memenangkan banyak pertarungan, kata Panchatantra tua — tetapi kecerdikan memenangkan pertarungan yang paling penting. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-clever-rabbit-and-the-lion_1', 'bok_the-clever-rabbit-and-the-lion', 1, 'Why were the forest animals afraid?', 'Mengapa hewan-hewan hutan ketakutan?', '["A storm was coming","The lion hunted too much","The well was empty","The elephant was angry"]', '["Badai akan datang","Singa berburu terlalu banyak","Sumur kering","Gajah sedang marah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-clever-rabbit-and-the-lion_2', 'bok_the-clever-rabbit-and-the-lion', 2, 'What did the rabbit show the lion in the well?', 'Apa yang ditunjukkan kelinci kepada singa di sumur?', '["A fish","A treasure","His own reflection","Another rabbit"]', '["Seekor ikan","Harta karun","Bayangannya sendiri","Kelinci lain"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-clever-rabbit-and-the-lion_3', 'bok_the-clever-rabbit-and-the-lion', 3, 'What does the story teach?', 'Apa pesan cerita ini?', '["Bigger is stronger","Wisdom can beat strength","Never be late","Lions are bad"]', '["Besar berarti kuat","Kecerdikan bisa mengalahkan kekuatan","Jangan pernah terlambat","Singa itu jahat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_timun-mas-and-the-giant', 'timun-mas-and-the-giant', 'Timun Mas and the Giant', 'Timun Mas dan Raksasa', 'A beloved Indonesian legend: a girl born from a golden cucumber outruns a giant with four small magical gifts and her own great courage.', 'Legenda Indonesia yang dicintai: gadis yang lahir dari timun emas mengalahkan raksasa dengan empat bingkisan ajaib dan keberaniannya sendiri.', 'cat_adventure', 'aut_axto-creative-team', 'meadow', '🥒', 4, 10, 0, 'published', 14, 1208, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_1', 'bok_timun-mas-and-the-giant', 1, 'timun-1', 'On the green slopes of a Javanese mountain lived a widow named Mbok Srini, who wished for a child more than for anything under the sky.', 'Di lereng hijau sebuah gunung di Jawa, hiduplah seorang janda bernama Mbok Srini, yang menginginkan seorang anak melebihi apa pun di kolong langit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_2', 'bok_timun-mas-and-the-giant', 2, 'timun-2', 'One night a giant came striding over the hills, tall as a coconut tree, with a laugh like falling rocks. ''Plant this seed, little woman,'' he rumbled, ''and you shall have your child. But when she turns seventeen, she is MINE.''', 'Suatu malam, seorang raksasa datang melangkahi bukit-bukit, tinggi bagai pohon kelapa, dengan tawa seperti batu runtuh. ''Tanamlah biji ini, wahai ibu,'' gemuruhnya, ''dan kau akan mendapat anak. Tapi saat ia berusia tujuh belas tahun, ia MILIKKU.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_3', 'bok_timun-mas-and-the-giant', 3, 'timun-3', 'Frightened but longing, Mbok Srini planted the seed. It grew into a vine, and on the vine swelled one enormous golden cucumber that glowed like the morning sun.', 'Takut namun penuh harap, Mbok Srini menanam biji itu. Tumbuhlah sulur menjalar, dan pada sulur itu membesar sebuah timun emas raksasa yang berkilau bagai matahari pagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_4', 'bok_timun-mas-and-the-giant', 4, 'timun-4', 'When she split it open, inside lay a baby girl with cheeks like rose petals. Mbok Srini named her Timun Mas — Golden Cucumber — and loved her more each day.', 'Ketika dibelahnya, di dalamnya terbaring bayi perempuan berpipi bagai kelopak mawar. Mbok Srini menamainya Timun Mas — Timun Emas — dan menyayanginya lebih setiap hari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_5', 'bok_timun-mas-and-the-giant', 5, 'timun-5', 'The years flew like birds. Timun Mas grew clever and kind and quick as a mountain stream. But the night before her seventeenth birthday, the ground began to shake.', 'Tahun-tahun berlalu bagai burung terbang. Timun Mas tumbuh cerdas, baik hati, dan gesit bagai aliran sungai gunung. Namun malam sebelum ulang tahunnya yang ketujuh belas, tanah mulai berguncang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_6', 'bok_timun-mas-and-the-giant', 6, 'timun-6', '''Run, my child!'' cried Mbok Srini, pressing a small cloth bundle into her hands. ''A wise hermit gave me these four gifts long ago. Use them when all seems lost!''', '''Larilah, anakku!'' seru Mbok Srini sambil menyelipkan buntelan kain kecil ke tangannya. ''Seorang pertapa bijak memberiku empat bingkisan ini dulu. Gunakan saat semua terasa hilang!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_7', 'bok_timun-mas-and-the-giant', 7, 'timun-7', 'Timun Mas ran through the moonlit forest, and the giant''s footsteps boomed behind her like thunder. Closer... closer... She opened the bundle and threw the first gift: a handful of cucumber seeds.', 'Timun Mas berlari menembus hutan bermandi cahaya bulan, dan langkah raksasa menggelegar di belakangnya bagai guntur. Makin dekat... makin dekat... Ia membuka buntelan dan melempar bingkisan pertama: segenggam biji timun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_8', 'bok_timun-mas-and-the-giant', 8, 'timun-8', 'Instantly a tangle of vines burst from the earth, thick with heavy golden cucumbers. The greedy giant stopped to gobble them up — and Timun Mas flew ahead.', 'Seketika sulur-sulur menyembur dari tanah, lebat dengan timun emas yang berat. Raksasa yang rakus berhenti untuk melahapnya — dan Timun Mas melesat jauh ke depan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_9', 'bok_timun-mas-and-the-giant', 9, 'timun-9', 'But soon the thunder-steps returned. She threw the second gift: needles. They sprang up into a forest of bamboo, sharp as spears. The giant crashed through, roaring, scratched from head to toe.', 'Namun tak lama, langkah guntur itu kembali. Ia melempar bingkisan kedua: jarum-jarum. Semuanya menjelma hutan bambu runcing bagai tombak. Raksasa menerobos sambil mengaum, tergores dari kepala sampai kaki.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_10', 'bok_timun-mas-and-the-giant', 10, 'timun-10', 'The third gift was a handful of salt. It became a wide rolling sea! The giant waded in, gasping and swallowing waves, but still he came on.', 'Bingkisan ketiga adalah segenggam garam. Garam itu menjelma lautan luas bergelombang! Raksasa menyeberang, megap-megap menelan ombak, tapi ia terus mengejar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_11', 'bok_timun-mas-and-the-giant', 11, 'timun-11', 'At last, with trembling fingers, Timun Mas threw the final gift: a paste of hot shrimp sauce. Where it landed, the earth bubbled into a lake of boiling mud, and the giant sank down, down, down — and was gone.', 'Akhirnya, dengan jari gemetar, Timun Mas melempar bingkisan terakhir: terasi. Di tempat jatuhnya, bumi menggelegak menjadi danau lumpur mendidih, dan raksasa itu tenggelam, tenggelam, tenggelam — lalu lenyap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_12', 'bok_timun-mas-and-the-giant', 12, 'timun-12', 'The forest fell silent. The moon came out from behind the clouds. Timun Mas walked home on shaking legs, and her mother ran to meet her with tears of joy.', 'Hutan menjadi sunyi. Bulan muncul dari balik awan. Timun Mas berjalan pulang dengan kaki gemetar, dan ibunya berlari menyambut dengan air mata bahagia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_13', 'bok_timun-mas-and-the-giant', 13, 'timun-13', 'From that day, mother and daughter lived in peace on their green mountainside, and no giant ever troubled the valley again.', 'Sejak hari itu, ibu dan anak hidup damai di lereng gunung yang hijau, dan tak ada raksasa yang mengganggu lembah itu lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_timun-mas-and-the-giant_14', 'bok_timun-mas-and-the-giant', 14, 'timun-14', 'For courage is not being unafraid, says the old tale — it is running on even when your legs tremble, and using every gift you are given. The end.', 'Sebab keberanian bukan berarti tak takut, kata dongeng lama — melainkan terus berlari meski kakimu gemetar, dan menggunakan setiap bekal yang kau miliki. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_timun-mas-and-the-giant_1', 'bok_timun-mas-and-the-giant', 1, 'Where was baby Timun Mas found?', 'Di mana bayi Timun Mas ditemukan?', '["In a basket","Inside a golden cucumber","Under a tree","By the river"]', '["Di dalam keranjang","Di dalam timun emas","Di bawah pohon","Di tepi sungai"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_timun-mas-and-the-giant_2', 'bok_timun-mas-and-the-giant', 2, 'Which gift finally stopped the giant?', 'Bingkisan mana yang akhirnya menghentikan raksasa?', '["Cucumber seeds","Needles","Salt","Shrimp paste"]', '["Biji timun","Jarum","Garam","Terasi"]', 3, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_timun-mas-and-the-giant_3', 'bok_timun-mas-and-the-giant', 3, 'What does the story say courage is?', 'Menurut cerita, apa itu keberanian?', '["Never feeling afraid","Running on even when afraid","Being the biggest","Hiding well"]', '["Tak pernah takut","Terus berlari meski takut","Menjadi yang terbesar","Pandai bersembunyi"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-ugly-duckling', 'the-ugly-duckling', 'The Ugly Duckling', 'Itik Buruk Rupa', 'Hans Christian Andersen''s gentle classic: a little bird who never fit in discovers, after a long hard year, exactly who he was born to be.', 'Klasik lembut Hans Christian Andersen: seekor anak unggas yang tak pernah diterima akhirnya menemukan, setelah setahun yang berat, siapa dirinya sebenarnya.', 'cat_emotions', 'aut_axto-creative-team', 'sky', '🦢', 3, 8, 0, 'published', 14, 1802, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_1', 'bok_the-ugly-duckling', 1, 'duckling-1', 'By a quiet pond on a summer farm, a mother duck sat on her nest, waiting. One by one the eggs cracked open — peep! peep! — until only the biggest egg was left.', 'Di tepi kolam yang tenang di sebuah ladang musim panas, induk bebek duduk mengerami telurnya, menunggu. Satu per satu telur menetas — piyik! piyik! — hingga tersisa telur yang paling besar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_2', 'bok_the-ugly-duckling', 2, 'duckling-2', 'At last it split, and out tumbled a chick — big, grey, and clumsy. ''Well,'' said the mother duck, ''you don''t look like the others. But you are mine, and I love you.''', 'Akhirnya telur itu terbelah, dan keluarlah seekor anak unggas — besar, abu-abu, dan canggung. ''Hmm,'' kata induk bebek, ''kau tak mirip yang lain. Tapi kau anakku, dan aku menyayangimu.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_3', 'bok_the-ugly-duckling', 3, 'duckling-3', 'But the farmyard was not kind. The hens pecked him, the turkey puffed at him, and even his brothers and sisters quacked, ''Go away, ugly duckling!''', 'Namun penghuni ladang tidaklah ramah. Ayam-ayam mematuknya, kalkun menggembungkan bulunya, bahkan saudara-saudaranya berkwek, ''Pergilah, itik buruk rupa!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_4', 'bok_the-ugly-duckling', 4, 'duckling-4', 'One grey evening, his heart heavier than his little wings, the duckling slipped under the fence and wandered away alone.', 'Suatu senja kelabu, dengan hati yang lebih berat daripada sayap kecilnya, itik itu menyelinap di bawah pagar dan mengembara sendirian.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_5', 'bok_the-ugly-duckling', 5, 'duckling-5', 'Autumn came with cold rain. The duckling hid among the reeds of a marsh, where wild ducks laughed at his strange looks but let him stay.', 'Musim gugur datang membawa hujan dingin. Itik itu bersembunyi di antara gelagah rawa, tempat bebek-bebek liar menertawakan rupanya yang aneh namun membiarkannya tinggal.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_6', 'bok_the-ugly-duckling', 6, 'duckling-6', 'One evening a flock of great white birds flew overhead, their long necks stretched toward the south, their wings singing in the wind. The duckling did not know their name — but his heart ached to follow them.', 'Suatu senja, sekawanan burung putih besar terbang di atasnya, leher panjang mereka terjulur ke selatan, sayap mereka berdesir di angin. Itik itu tak tahu nama mereka — namun hatinya nyeri ingin ikut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_7', 'bok_the-ugly-duckling', 7, 'duckling-7', 'Winter was long and bitter. The duckling nearly froze in the pond ice, and a kind farmer carried him home — but he knocked over the milk pail in fright, and had to flee again.', 'Musim dingin panjang dan menggigit. Itik itu nyaris membeku di es kolam, dan seorang petani baik hati membawanya pulang — namun karena ketakutan ia menumpahkan ember susu, dan harus lari lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_8', 'bok_the-ugly-duckling', 8, 'duckling-8', 'Somehow, through frost and hunger and loneliness, the little bird survived until the willows turned green and the air smelled of spring.', 'Entah bagaimana, melewati embun beku, lapar, dan sepi, unggas kecil itu bertahan hingga pohon willow menghijau dan udara berbau musim semi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_9', 'bok_the-ugly-duckling', 9, 'duckling-9', 'He spread his wings — and they were strong now, wide and white, and they carried him high over the gardens to a shining lake where three great white birds glided like ships.', 'Ia mengembangkan sayapnya — kini kuat, lebar, dan putih, membawanya tinggi melintasi taman menuju danau berkilau tempat tiga burung putih besar meluncur bagai kapal.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_10', 'bok_the-ugly-duckling', 10, 'duckling-10', '''They will chase me away, like everyone else,'' he thought sadly. ''But better to be chased by such beautiful birds than pecked by hens.'' And he flew down to meet them.', '''Mereka pasti akan mengusirku, seperti yang lain,'' pikirnya sedih. ''Tapi lebih baik diusir burung-burung seindah itu daripada dipatuki ayam.'' Lalu ia turun menghampiri mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_11', 'bok_the-ugly-duckling', 11, 'duckling-11', 'He bowed his head, waiting for the pecks — and saw, in the still water, his own reflection: not a clumsy grey duckling at all, but a swan, white as snow, graceful as morning.', 'Ia menundukkan kepala, siap dipatuk — dan melihat, di air yang tenang, bayangannya sendiri: sama sekali bukan itik abu-abu yang canggung, melainkan seekor angsa, putih bagai salju, anggun bagai pagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_12', 'bok_the-ugly-duckling', 12, 'duckling-12', 'The great swans swam around him and stroked him with their beaks. Children on the shore clapped and cried, ''The new one is the most beautiful of all!''', 'Angsa-angsa besar berenang mengelilinginya dan membelainya dengan paruh mereka. Anak-anak di tepi danau bertepuk tangan dan berseru, ''Yang baru itu paling indah dari semuanya!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_13', 'bok_the-ugly-duckling', 13, 'duckling-13', 'And the young swan felt shy and hid his head under his wing — for a heart that has known sorrow is never proud. He was happy, deeply happy, but not proud.', 'Angsa muda itu tersipu dan menyembunyikan kepala di bawah sayapnya — sebab hati yang pernah mengenal duka tak pernah menjadi sombong. Ia bahagia, sungguh bahagia, tapi tidak sombong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ugly-duckling_14', 'bok_the-ugly-duckling', 14, 'duckling-14', 'It does not matter, said Andersen, if you are born in a duckyard — so long as you are hatched from a swan''s egg. You are becoming who you truly are. The end.', 'Tak masalah, kata Andersen, jika kau lahir di kandang bebek — selama kau menetas dari telur angsa. Kau sedang tumbuh menjadi dirimu yang sebenarnya. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ugly-duckling_1', 'bok_the-ugly-duckling', 1, 'Why did the duckling leave the farmyard?', 'Mengapa itik itu meninggalkan ladang?', '["He wanted adventure","Everyone was unkind to him","He was hungry","The pond froze"]', '["Ia ingin bertualang","Semua bersikap tak baik padanya","Ia lapar","Kolam membeku"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ugly-duckling_2', 'bok_the-ugly-duckling', 2, 'What did he see in the water in spring?', 'Apa yang dilihatnya di air saat musim semi?', '["A fish","A boat","His reflection — a swan","Another duckling"]', '["Seekor ikan","Sebuah perahu","Bayangannya — seekor angsa","Itik lain"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ugly-duckling_3', 'bok_the-ugly-duckling', 3, 'How did the swan behave when praised?', 'Bagaimana sikap angsa saat dipuji?', '["Proud and loud","Happy but humble","Angry","He flew away"]', '["Sombong dan berisik","Bahagia tapi rendah hati","Marah","Ia terbang pergi"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-bremen-town-musicians', 'the-bremen-town-musicians', 'The Bremen Town Musicians', 'Para Pemusik Kota Bremen', 'The Brothers Grimm classic: four old animals nobody wanted team up, scare off a band of robbers, and find a home — together.', 'Klasik Grimm bersaudara: empat hewan tua yang tak diinginkan bersatu, mengusir kawanan perampok, dan menemukan rumah — bersama-sama.', 'cat_friendship', 'aut_axto-creative-team', 'sunset', '🎺', 4, 9, 0, 'published', 14, 432, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_1', 'bok_the-bremen-town-musicians', 1, 'bremen-1', 'There was once a donkey who had carried sacks to the mill for many long years. When he grew too old to work, his master decided to send him away — so the donkey set off down the road to Bremen. ''I shall be a town musician,'' he said.', 'Alkisah seekor keledai telah bertahun-tahun memikul karung ke penggilingan. Ketika ia terlalu tua untuk bekerja, tuannya hendak membuangnya — maka keledai itu berangkat menyusuri jalan ke Bremen. ''Aku akan menjadi pemusik kota,'' katanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_2', 'bok_the-bremen-town-musicians', 2, 'bremen-2', 'On the road he found an old hunting dog lying in the grass, panting sadly. ''I am too slow to hunt now, and my master has no use for me.'' ''Come to Bremen!'' said the donkey. ''You shall play the drum.''', 'Di jalan ia menemukan seekor anjing pemburu tua terbaring di rumput, terengah sedih. ''Aku terlalu lambat untuk berburu sekarang, dan tuanku tak membutuhkanku lagi.'' ''Ikutlah ke Bremen!'' kata keledai. ''Kau akan menabuh genderang.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_3', 'bok_the-bremen-town-musicians', 3, 'bremen-3', 'Soon they met a cat sitting by the road with a face like three days of rain. ''I am old, my teeth are dull, and I would rather sit by the stove than chase mice — so no one wants me.'' ''Join us! You shall sing soprano.''', 'Tak lama mereka bertemu seekor kucing duduk di tepi jalan dengan wajah bagai hujan tiga hari. ''Aku tua, gigiku tumpul, dan aku lebih suka duduk dekat tungku daripada mengejar tikus — jadi tak ada yang menginginkanku.'' ''Bergabunglah! Kau akan menyanyi sopran.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_4', 'bok_the-bremen-town-musicians', 4, 'bremen-4', 'At a farmyard gate, a rooster was crowing with all his might. ''Guests are coming on Sunday,'' he wailed, ''and the cook means to put me in the soup! I crow while I still can.'' ''Come with us to Bremen — anything is better than the soup!''', 'Di gerbang sebuah ladang, seekor ayam jantan berkokok sekuat tenaga. ''Tamu akan datang hari Minggu,'' ratapnya, ''dan juru masak hendak memasukkanku ke dalam sup! Aku berkokok selagi bisa.'' ''Ikutlah kami ke Bremen — apa pun lebih baik daripada sup!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_5', 'bok_the-bremen-town-musicians', 5, 'bremen-5', 'Night fell before they reached the city, and deep in the forest they saw a light. Through the window of a little house they spied a table heaped with food and drink — and around it, a band of robbers counting stolen gold.', 'Malam tiba sebelum mereka sampai di kota, dan jauh di dalam hutan mereka melihat cahaya. Lewat jendela sebuah rumah kecil mereka mengintip meja penuh makanan dan minuman — dan di sekelilingnya, kawanan perampok tengah menghitung emas curian.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_6', 'bok_the-bremen-town-musicians', 6, 'bremen-6', 'The four friends put their heads together and made a plan. The donkey stood at the window, the dog climbed on his back, the cat on the dog, and the rooster perched on top of them all.', 'Keempat sahabat itu berunding dan menyusun rencana. Keledai berdiri di dekat jendela, anjing naik ke punggungnya, kucing naik ke atas anjing, dan ayam jantan bertengger paling atas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_7', 'bok_the-bremen-town-musicians', 7, 'bremen-7', 'Then, at a signal, they made their music all at once: the donkey brayed, the dog barked, the cat yowled, and the rooster crowed — and they crashed through the window in a shower of glass!', 'Lalu, pada satu aba-aba, mereka bermusik serentak: keledai meringkik, anjing menggonggong, kucing mengeong keras, dan ayam berkokok — dan mereka menerjang jendela hingga kaca berhamburan!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_8', 'bok_the-bremen-town-musicians', 8, 'bremen-8', 'The robbers leapt up in terror. ''A ghost! A monster! A judge with a sword!'' they cried, falling over each other as they fled into the dark forest.', 'Para perampok melompat ketakutan. ''Hantu! Monster! Hakim bersama pedang!'' teriak mereka, jatuh bertumpukan sambil lari ke hutan gelap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_9', 'bok_the-bremen-town-musicians', 9, 'bremen-9', 'The four musicians sat down at the table and ate as if they had been hungry for a month — which, in truth, they had. Then each found a sleeping place to his liking, and the lights went out.', 'Keempat pemusik duduk di meja dan makan seolah sudah lapar sebulan — dan memang begitulah adanya. Lalu masing-masing mencari tempat tidur kesukaannya, dan lampu pun padam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_10', 'bok_the-bremen-town-musicians', 10, 'bremen-10', 'At midnight, the bravest robber crept back to the dark house. In the kitchen, the cat''s eyes glowed — he took them for burning coals, and reached out to light a match.', 'Tengah malam, perampok yang paling berani menyelinap kembali ke rumah gelap itu. Di dapur, mata kucing berpendar — dikiranya bara api, dan ia mengulurkan tangan hendak menyalakan korek.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_11', 'bok_the-bremen-town-musicians', 11, 'bremen-11', 'The cat flew at his face, spitting and scratching. He stumbled to the door — the dog bit his leg. He staggered through the yard — the donkey kicked him high over the fence. And from the roof the rooster screamed, ''Cock-a-doodle-doo!''', 'Kucing menerkam wajahnya, mendesis dan mencakar. Ia terhuyung ke pintu — anjing menggigit kakinya. Ia sempoyongan melewati halaman — keledai menendangnya tinggi melewati pagar. Dan dari atap ayam jantan berteriak, ''Kukuruyuk!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_12', 'bok_the-bremen-town-musicians', 12, 'bremen-12', '''A witch scratched me, a man stabbed my leg, a monster beat me with a club,'' the robber gasped to his friends, ''and on the roof a judge shouted: Bring the rogue to me!'' The robbers never went near the house again.', '''Penyihir mencakarku, seorang pria menusuk kakiku, monster memukulku dengan pentungan,'' perampok itu tersengal pada kawan-kawannya, ''dan di atap seorang hakim berteriak: Bawa penjahat itu padaku!'' Para perampok tak pernah berani mendekati rumah itu lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_13', 'bok_the-bremen-town-musicians', 13, 'bremen-13', 'As for the four musicians, they liked their little house in the forest so well that they never went to Bremen at all. They had found something better than a stage: a home, and each other.', 'Adapun keempat pemusik, mereka begitu betah di rumah kecil di hutan itu hingga tak pernah pergi ke Bremen sama sekali. Mereka menemukan sesuatu yang lebih baik daripada panggung: sebuah rumah, dan satu sama lain.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bremen-town-musicians_14', 'bok_the-bremen-town-musicians', 14, 'bremen-14', 'For no one is ever too old to start again, say the Brothers Grimm — and friends who sing together are never homeless. The end.', 'Sebab tak ada yang terlalu tua untuk memulai lagi, kata Grimm bersaudara — dan sahabat yang bernyanyi bersama tak akan pernah kehilangan rumah. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bremen-town-musicians_1', 'bok_the-bremen-town-musicians', 1, 'Why did the animals leave their homes?', 'Mengapa hewan-hewan itu meninggalkan rumah mereka?', '["They were bored","Their owners no longer wanted them","They loved music","They were lost"]', '["Mereka bosan","Pemiliknya tak menginginkan mereka lagi","Mereka cinta musik","Mereka tersesat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bremen-town-musicians_2', 'bok_the-bremen-town-musicians', 2, 'How did they scare the robbers the first time?', 'Bagaimana mereka mengusir perampok pertama kali?', '["They called the police","They made loud music together and crashed in","They threw stones","They lit a fire"]', '["Memanggil polisi","Bermusik keras bersama dan menerjang masuk","Melempar batu","Menyalakan api"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bremen-town-musicians_3', 'bok_the-bremen-town-musicians', 3, 'What did the four friends find in the end?', 'Apa yang akhirnya ditemukan keempat sahabat?', '["Gold","A stage in Bremen","A home together","A new master"]', '["Emas","Panggung di Bremen","Rumah bersama","Tuan baru"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-tortoise-and-the-hare', 'the-tortoise-and-the-hare', 'The Tortoise and the Hare', 'Kura-kura dan Kelinci', 'The fastest runner in the meadow laughs at the slowest — until race day teaches everyone what steady really means.', 'Pelari tercepat di padang menertawakan yang paling lambat — sampai hari perlombaan mengajarkan arti kata ''tekun'' pada semua.', 'cat_moral-stories', 'aut_axto-creative-team', 'meadow', '🐢', 3, 8, 0, 'published', 12, 962, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_1', 'bok_the-tortoise-and-the-hare', 1, 'tortoise-hare-1', 'In a wide green meadow lived a hare who could run like the wind. He knew it, too, and told everyone about it every single day.', 'Di padang hijau yang luas hiduplah seekor kelinci yang bisa berlari secepat angin. Ia tahu itu, dan menceritakannya kepada semua hewan setiap hari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_2', 'bok_the-tortoise-and-the-hare', 2, 'tortoise-hare-2', '''I am the fastest animal in the whole meadow!'' he boasted. ''Nobody could ever beat me. Especially not... a tortoise!'' And he laughed and laughed.', '''Akulah hewan tercepat di seluruh padang!'' sombongnya. ''Tak ada yang bisa mengalahkanku. Apalagi... seekor kura-kura!'' Lalu ia tertawa terbahak-bahak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_3', 'bok_the-tortoise-and-the-hare', 3, 'tortoise-hare-3', 'The old tortoise looked up slowly. ''Then let us race, friend hare,'' she said in her calm, quiet voice. ''To the big oak tree on the hill.''', 'Kura-kura tua itu mengangkat kepalanya pelan-pelan. ''Kalau begitu, ayo kita berlomba, sahabat kelinci,'' katanya dengan suara tenang. ''Sampai pohon ek besar di atas bukit.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_4', 'bok_the-tortoise-and-the-hare', 4, 'tortoise-hare-4', 'All the animals gathered to watch. The fox raised his paw. ''Ready... steady... GO!'' The hare shot away like an arrow. The tortoise took one small step.', 'Semua hewan berkumpul untuk menonton. Rubah mengangkat cakarnya. ''Bersedia... siap... MULAI!'' Kelinci melesat bagai anak panah. Kura-kura melangkah satu langkah kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_5', 'bok_the-tortoise-and-the-hare', 5, 'tortoise-hare-5', 'In no time at all, the hare was so far ahead he could not even see the tortoise behind him. ''This is too easy,'' he yawned. ''I have time for a little nap.''', 'Dalam sekejap, kelinci sudah jauh sekali di depan sampai kura-kura tak terlihat lagi. ''Ini terlalu mudah,'' ia menguap. ''Aku masih sempat tidur sebentar.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_6', 'bok_the-tortoise-and-the-hare', 6, 'tortoise-hare-6', 'He curled up under a shady bush, and the warm afternoon sun soon rocked him into a deep, deep sleep.', 'Ia meringkuk di bawah semak yang teduh, dan matahari sore yang hangat segera membuainya ke dalam tidur yang sangat lelap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_7', 'bok_the-tortoise-and-the-hare', 7, 'tortoise-hare-7', 'Meanwhile, the tortoise kept walking. Step... step... step. She did not stop to rest. She did not stop to chat. She just kept going, slow and steady.', 'Sementara itu, kura-kura terus berjalan. Langkah... langkah... langkah. Ia tak berhenti untuk beristirahat. Ia tak berhenti untuk mengobrol. Ia terus maju, pelan tapi pasti.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_8', 'bok_the-tortoise-and-the-hare', 8, 'tortoise-hare-8', 'She passed the sleeping hare very quietly. Her little legs were tired, but she whispered to herself: ''One more step. And one more. And one more.''', 'Ia melewati kelinci yang tertidur dengan sangat pelan. Kaki kecilnya lelah, tetapi ia berbisik pada dirinya: ''Satu langkah lagi. Satu lagi. Satu lagi.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_9', 'bok_the-tortoise-and-the-hare', 9, 'tortoise-hare-9', 'When the hare finally woke, the sun was already low. He stretched, laughed — and then he saw it: far up the hill, the tortoise was almost at the oak tree!', 'Ketika kelinci akhirnya terbangun, matahari sudah rendah. Ia menggeliat, tertawa — lalu ia melihatnya: jauh di atas bukit, kura-kura hampir sampai di pohon ek!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_10', 'bok_the-tortoise-and-the-hare', 10, 'tortoise-hare-10', 'The hare ran faster than he had ever run in his life. His ears flew back, his paws barely touched the ground — but it was too late.', 'Kelinci berlari lebih cepat daripada yang pernah ia lakukan seumur hidupnya. Telinganya melambai ke belakang, kakinya nyaris tak menyentuh tanah — tapi semuanya terlambat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_11', 'bok_the-tortoise-and-the-hare', 11, 'tortoise-hare-11', 'The tortoise touched the great oak tree, and the whole meadow cheered. ''Slow and steady wins the race!'' cried the fox.', 'Kura-kura menyentuh pohon ek besar itu, dan seluruh padang bersorak. ''Pelan tapi pasti memenangkan lomba!'' seru rubah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-tortoise-and-the-hare_12', 'bok_the-tortoise-and-the-hare', 12, 'tortoise-hare-12', 'The hare hung his head — then he did something brave: he walked up and shook the tortoise''s hand. ''You taught me a big lesson today, little friend.'' And from that day, he never boasted again. The end.', 'Kelinci menundukkan kepala — lalu ia melakukan sesuatu yang berani: ia menghampiri dan menjabat tangan kura-kura. ''Kau mengajariku pelajaran besar hari ini, sahabat kecil.'' Dan sejak hari itu, ia tak pernah menyombong lagi. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tortoise-and-the-hare_1', 'bok_the-tortoise-and-the-hare', 1, 'Why did the hare lose the race?', 'Mengapa kelinci kalah dalam perlombaan?', '["He hurt his leg","He stopped to sleep","He got lost"]', '["Kakinya terluka","Ia berhenti untuk tidur","Ia tersesat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tortoise-and-the-hare_2', 'bok_the-tortoise-and-the-hare', 2, 'What did the tortoise keep doing all through the race?', 'Apa yang terus dilakukan kura-kura sepanjang lomba?', '["Resting under bushes","Walking without stopping","Asking for help"]', '["Beristirahat di bawah semak","Berjalan tanpa berhenti","Meminta bantuan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-tortoise-and-the-hare_3', 'bok_the-tortoise-and-the-hare', 3, 'What lesson did the hare learn?', 'Pelajaran apa yang didapat kelinci?', '["Never race again","Boasting is fun","Do not mock others; steady effort wins"]', '["Jangan pernah berlomba lagi","Menyombong itu menyenangkan","Jangan meremehkan orang lain; ketekunan yang menang"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-honest-woodcutter-and-the-golden-axe', 'the-honest-woodcutter-and-the-golden-axe', 'The Honest Woodcutter and the Golden Axe', 'Penebang Kayu yang Jujur dan Kapak Emas', 'A poor woodcutter drops his only axe into the deep river — and a shining spirit rises with a test that will change his life.', 'Seorang penebang kayu miskin menjatuhkan satu-satunya kapaknya ke sungai yang dalam — dan seorang peri sungai muncul membawa ujian yang mengubah hidupnya.', 'cat_manners', 'aut_axto-creative-team', 'forest', '🪓', 4, 9, 0, 'published', 13, 3741, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_1', 'bok_the-honest-woodcutter-and-the-golden-axe', 1, 'woodcutter-1', 'Long ago, beside a deep green river, lived a poor woodcutter. Every morning he walked into the forest with his old iron axe — the only precious thing he owned.', 'Dahulu kala, di tepi sungai hijau yang dalam, hiduplah seorang penebang kayu miskin. Setiap pagi ia masuk hutan membawa kapak besinya yang tua — satu-satunya benda berharga miliknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_2', 'bok_the-honest-woodcutter-and-the-golden-axe', 2, 'woodcutter-2', 'One day, as he chopped a tree that leaned over the water, his hands slipped. The axe flew from his fingers — splash! — and sank into the deepest part of the river.', 'Suatu hari, saat menebang pohon yang condong ke air, tangannya terpeleset. Kapak itu terlempar dari genggamannya — byur! — dan tenggelam ke bagian sungai yang paling dalam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_3', 'bok_the-honest-woodcutter-and-the-golden-axe', 3, 'woodcutter-3', 'The woodcutter sat on the bank and covered his face. ''Without my axe I cannot work. Without work I cannot eat. What will become of me?''', 'Penebang kayu itu duduk di tepi sungai dan menutupi wajahnya. ''Tanpa kapak aku tak bisa bekerja. Tanpa bekerja aku tak bisa makan. Bagaimana nasibku nanti?''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_4', 'bok_the-honest-woodcutter-and-the-golden-axe', 4, 'woodcutter-4', 'Suddenly the water began to glow. Out of the river rose a gentle spirit with eyes like moonlight. ''Why do you weep, woodcutter?'' she asked.', 'Tiba-tiba air sungai mulai bercahaya. Dari dalam sungai muncul peri lembut bermata seperti cahaya bulan. ''Mengapa engkau menangis, penebang kayu?'' tanyanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_5', 'bok_the-honest-woodcutter-and-the-golden-axe', 5, 'woodcutter-5', '''I have lost my axe in the river,'' he said. The spirit smiled, dived down, and rose again holding an axe of pure shining gold. ''Is this yours?''', '''Kapakku jatuh ke sungai,'' katanya. Peri itu tersenyum, menyelam, lalu muncul kembali membawa kapak dari emas murni yang berkilauan. ''Inikah milikmu?''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_6', 'bok_the-honest-woodcutter-and-the-golden-axe', 6, 'woodcutter-6', 'The woodcutter''s eyes grew wide — gold! Enough to buy food for years. But he shook his head. ''No, kind spirit. That is not my axe.''', 'Mata penebang kayu terbelalak — emas! Cukup untuk membeli makanan bertahun-tahun. Tapi ia menggeleng. ''Bukan, peri yang baik. Itu bukan kapakku.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_7', 'bok_the-honest-woodcutter-and-the-golden-axe', 7, 'woodcutter-7', 'The spirit dived again and rose with an axe of bright silver. ''Then surely this one is yours?'' Again the woodcutter shook his head. ''No. Mine was only old iron.''', 'Peri itu menyelam lagi dan muncul membawa kapak perak yang berkilap. ''Kalau begitu, pasti yang ini milikmu?'' Penebang kayu kembali menggeleng. ''Bukan. Kapakku hanya besi tua.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_8', 'bok_the-honest-woodcutter-and-the-golden-axe', 8, 'woodcutter-8', 'A third time the spirit dived, and this time she held up the old iron axe with its worn wooden handle. ''That one is mine!'' cried the woodcutter joyfully.', 'Untuk ketiga kalinya peri itu menyelam, dan kali ini ia mengangkat kapak besi tua dengan gagang kayu yang usang. ''Yang itu milikku!'' seru penebang kayu gembira.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_9', 'bok_the-honest-woodcutter-and-the-golden-axe', 9, 'woodcutter-9', 'The spirit''s smile shone brighter than the gold. ''You spoke the truth, though you are poor and gold was in your reach. Honesty like yours deserves a reward.''', 'Senyum peri itu bersinar lebih terang daripada emas. ''Engkau berkata jujur, padahal engkau miskin dan emas ada di depan mata. Kejujuran seperti ini pantas mendapat hadiah.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_10', 'bok_the-honest-woodcutter-and-the-golden-axe', 10, 'woodcutter-10', '''Take all three axes — the iron, the silver, and the gold. Let them remind you that a true heart is the greatest treasure of all.'' And the river fell quiet again.', '''Ambillah ketiga kapak ini — besi, perak, dan emas. Biarlah semuanya mengingatkanmu bahwa hati yang jujur adalah harta yang paling besar.'' Lalu sungai itu tenang kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_11', 'bok_the-honest-woodcutter-and-the-golden-axe', 11, 'woodcutter-11', 'A greedy neighbour heard the story and threw his own axe into the river on purpose. When the spirit offered him the golden axe, he shouted, ''Yes! That one is mine!''', 'Seorang tetangga yang serakah mendengar kisah itu dan sengaja melempar kapaknya ke sungai. Ketika peri menawarkan kapak emas, ia berteriak, ''Ya! Itu milikku!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_12', 'bok_the-honest-woodcutter-and-the-golden-axe', 12, 'woodcutter-12', 'The spirit looked at him sadly — and sank beneath the water, taking the golden axe, the silver axe, and even his own iron axe with her. He went home with nothing at all.', 'Peri itu memandangnya dengan sedih — lalu tenggelam ke dalam air, membawa kapak emas, kapak perak, bahkan kapak besinya sendiri. Ia pulang tanpa membawa apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-honest-woodcutter-and-the-golden-axe_13', 'bok_the-honest-woodcutter-and-the-golden-axe', 13, 'woodcutter-13', 'But the honest woodcutter lived well and happily, and whenever anyone asked about his three axes, he would say: ''The gold is pretty — but the truth bought it.'' The end.', 'Namun penebang kayu yang jujur hidup senang dan berkecukupan, dan bila ada yang bertanya tentang ketiga kapaknya, ia menjawab: ''Emas memang indah — tapi kejujuranlah yang membelinya.'' Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter-and-the-golden-axe_1', 'bok_the-honest-woodcutter-and-the-golden-axe', 1, 'What did the woodcutter say when shown the golden axe?', 'Apa kata penebang kayu saat ditunjukkan kapak emas?', '["''That is mine!''","''That is not my axe.''","''Keep it for yourself.''"]', '["''Itu milikku!''","''Itu bukan kapakku.''","''Simpan saja untukmu.''"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter-and-the-golden-axe_2', 'bok_the-honest-woodcutter-and-the-golden-axe', 2, 'Why did the spirit give him all three axes?', 'Mengapa peri memberinya ketiga kapak itu?', '["Because he cried loudly","Because he was honest","Because he asked politely"]', '["Karena ia menangis keras","Karena ia jujur","Karena ia meminta dengan sopan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-honest-woodcutter-and-the-golden-axe_3', 'bok_the-honest-woodcutter-and-the-golden-axe', 3, 'What happened to the greedy neighbour?', 'Apa yang terjadi pada tetangga yang serakah?', '["He got the golden axe","He lost even his own axe","He became the spirit''s friend"]', '["Ia mendapat kapak emas","Ia kehilangan kapaknya sendiri","Ia menjadi sahabat peri"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_sang-kancil-and-the-crocodiles', 'sang-kancil-and-the-crocodiles', 'Sang Kancil and the Crocodiles', 'Sang Kancil dan Buaya-buaya', 'A tiny mouse-deer must cross a river full of hungry crocodiles — armed with nothing but a very big idea.', 'Kancil kecil harus menyeberangi sungai yang penuh buaya lapar — hanya berbekal satu ide yang sangat besar.', 'cat_world-cultures', 'aut_siti-aminah', 'ocean', '🐊', 3, 8, 0, 'published', 12, 3283, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_1', 'bok_sang-kancil-and-the-crocodiles', 1, 'kancil-1', 'In the warm forests of the Nusantara lived Sang Kancil, the mouse-deer — the smallest of the big animals and the cleverest of the small ones.', 'Di hutan Nusantara yang hangat hiduplah Sang Kancil — yang paling kecil di antara hewan besar, dan yang paling cerdik di antara hewan kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_2', 'bok_sang-kancil-and-the-crocodiles', 2, 'kancil-2', 'One morning, Kancil saw the ripest, sweetest rambutan trees he had ever seen — on the other side of the wide brown river.', 'Suatu pagi, Kancil melihat pohon rambutan paling ranum dan manis yang pernah ia lihat — di seberang sungai cokelat yang lebar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_3', 'bok_sang-kancil-and-the-crocodiles', 3, 'kancil-3', 'But the river was full of crocodiles. Big ones, long ones, hungry ones. Their yellow eyes watched Kancil from the water like floating lanterns.', 'Tapi sungai itu penuh buaya. Yang besar, yang panjang, yang lapar. Mata kuning mereka mengawasi Kancil dari dalam air seperti lentera terapung.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_4', 'bok_sang-kancil-and-the-crocodiles', 4, 'kancil-4', 'Kancil thought and thought. Then he smiled his small clever smile, stood tall on a rock, and called out: ''Crocodiles! Wonderful news! The King has sent me to count you all for a great feast!''', 'Kancil berpikir dan berpikir. Lalu ia tersenyum kecil penuh akal, berdiri di atas batu, dan berseru: ''Buaya-buaya! Kabar gembira! Raja mengutusku menghitung kalian semua untuk pesta besar!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_5', 'bok_sang-kancil-and-the-crocodiles', 5, 'kancil-5', '''A feast?'' the biggest crocodile rumbled, lifting his huge head. ''With food for all of us?'' — ''Mountains of it!'' said Kancil. ''But only crocodiles who are counted may come!''', '''Pesta?'' gumam buaya terbesar sambil mengangkat kepala raksasanya. ''Dengan makanan untuk kami semua?'' — ''Bergunung-gunung!'' kata Kancil. ''Tapi hanya buaya yang terhitung yang boleh datang!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_6', 'bok_sang-kancil-and-the-crocodiles', 6, 'kancil-6', '''Then count us! Count us!'' the crocodiles cried. ''Very well,'' said Kancil. ''Line up from this bank to the far bank — straight and still, nose to tail, so I miss nobody!''', '''Kalau begitu hitunglah kami! Hitung kami!'' seru para buaya. ''Baiklah,'' kata Kancil. ''Berbarislah dari tepi sini sampai tepi seberang — lurus dan diam, dari hidung ke ekor, supaya tak ada yang terlewat!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_7', 'bok_sang-kancil-and-the-crocodiles', 7, 'kancil-7', 'The crocodiles hurried into a line across the river, floating side by side like a bridge of bumpy green logs.', 'Buaya-buaya bergegas berbaris melintasi sungai, mengapung berdampingan seperti jembatan dari batang kayu hijau yang berbonggol-bonggol.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_8', 'bok_sang-kancil-and-the-crocodiles', 8, 'kancil-8', '''One!'' said Kancil, hopping onto the first crocodile''s back. ''Two!'' — hop. ''Three!'' — hop. He counted his way lightly across the whole river.', '''Satu!'' kata Kancil sambil melompat ke punggung buaya pertama. ''Dua!'' — lompat. ''Tiga!'' — lompat. Ia menghitung sambil melompat ringan menyeberangi seluruh sungai.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_9', 'bok_sang-kancil-and-the-crocodiles', 9, 'kancil-9', '''...and TWELVE!'' he cried, landing safely on the far bank, right beneath the rambutan trees. The crocodiles waited eagerly. ''And now? When is the feast?''', '''...dan DUA BELAS!'' serunya sambil mendarat selamat di tepi seberang, tepat di bawah pohon rambutan. Para buaya menunggu tak sabar. ''Lalu? Kapan pestanya?''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_10', 'bok_sang-kancil-and-the-crocodiles', 10, 'kancil-10', 'Kancil picked a sweet rambutan and grinned. ''Thank you for the bridge, friends! The only feast today is mine!'' And he skipped away into the trees.', 'Kancil memetik rambutan manis dan menyeringai. ''Terima kasih atas jembatannya, kawan-kawan! Satu-satunya pesta hari ini adalah pestaku!'' Lalu ia melompat riang ke balik pepohonan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_11', 'bok_sang-kancil-and-the-crocodiles', 11, 'kancil-11', 'The crocodiles snapped and splashed and grumbled all afternoon. But secretly, even the biggest one had to admit: ''That little Kancil... has a very big brain.''', 'Para buaya menggertak, mencipratkan air, dan menggerutu sepanjang sore. Tapi diam-diam, buaya terbesar pun harus mengakui: ''Kancil kecil itu... otaknya besar sekali.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_sang-kancil-and-the-crocodiles_12', 'bok_sang-kancil-and-the-crocodiles', 12, 'kancil-12', 'And that is why, to this day, parents in the Nusantara tell their children: when the problem is bigger than you are, think bigger than the problem. The end.', 'Dan itulah sebabnya, sampai hari ini, orang tua di Nusantara berpesan kepada anak-anaknya: bila masalah lebih besar daripada dirimu, berpikirlah lebih besar daripada masalahmu. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_sang-kancil-and-the-crocodiles_1', 'bok_sang-kancil-and-the-crocodiles', 1, 'Why did Kancil need to cross the river?', 'Mengapa Kancil perlu menyeberangi sungai?', '["To visit the King","To reach the sweet rambutan trees","To swim with the crocodiles"]', '["Untuk menemui Raja","Untuk mencapai pohon rambutan yang manis","Untuk berenang dengan buaya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_sang-kancil-and-the-crocodiles_2', 'bok_sang-kancil-and-the-crocodiles', 2, 'How did Kancil get the crocodiles to make a bridge?', 'Bagaimana Kancil membuat buaya-buaya menjadi jembatan?', '["He said the King wanted to count them for a feast","He paid them with fruit","He asked politely"]', '["Ia berkata Raja ingin menghitung mereka untuk pesta","Ia membayar mereka dengan buah","Ia meminta dengan sopan"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_sang-kancil-and-the-crocodiles_3', 'bok_sang-kancil-and-the-crocodiles', 3, 'What is the lesson of the story?', 'Apa pelajaran dari cerita ini?', '["Crocodiles are kind","Being big always wins","A clever mind can solve a big problem"]', '["Buaya itu baik hati","Yang besar selalu menang","Akal yang cerdik bisa memecahkan masalah besar"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-crow-and-the-pitcher', 'the-crow-and-the-pitcher', 'The Crow and the Pitcher', 'Gagak dan Kendi Air', 'A thirsty crow finds water she cannot reach — and shows that patience plus a good idea can move the impossible.', 'Seekor gagak yang kehausan menemukan air yang tak terjangkau — dan membuktikan bahwa kesabaran dan ide cerdas bisa mengalahkan yang mustahil.', 'cat_science', 'aut_axto-creative-team', 'dusk', '🐦‍⬛', 3, 7, 0, 'published', 12, 3651, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_1', 'bok_the-crow-and-the-pitcher', 1, 'crow-pitcher-1', 'It had not rained for many, many days. The streams were dry, the puddles were gone, and a tired crow flew across the hot fields looking for one thing only: water.', 'Hujan tak turun berhari-hari lamanya. Sungai kecil mengering, genangan lenyap, dan seekor gagak yang lelah terbang melintasi ladang panas mencari satu hal saja: air.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_2', 'bok_the-crow-and-the-pitcher', 2, 'crow-pitcher-2', 'Her throat burned and her wings felt heavy. ''Water,'' she croaked. ''Just a little water...''', 'Tenggorokannya terasa terbakar dan sayapnya berat. ''Air,'' seraknya. ''Sedikit saja air...''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_3', 'bok_the-crow-and-the-pitcher', 3, 'crow-pitcher-3', 'Then, near an old farmhouse, she saw it: a tall clay pitcher! She peered inside — and yes! At the very bottom gleamed a little pool of cool, clear water.', 'Lalu, di dekat rumah tani tua, ia melihatnya: sebuah kendi tanah liat yang tinggi! Ia mengintip ke dalam — dan ya! Di dasar kendi berkilau sedikit air yang sejuk dan jernih.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_4', 'bok_the-crow-and-the-pitcher', 4, 'crow-pitcher-4', 'She pushed her beak into the pitcher. Too short! The water lay far below, and the pitcher''s neck was narrow and deep.', 'Ia memasukkan paruhnya ke dalam kendi. Terlalu pendek! Air itu jauh di bawah, dan leher kendi sempit lagi dalam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_5', 'bok_the-crow-and-the-pitcher', 5, 'crow-pitcher-5', 'She pushed the pitcher with her wings — it was too heavy to tip. She flapped and pecked and pushed again. Nothing. The water only trembled, far out of reach.', 'Ia mendorong kendi dengan sayapnya — terlalu berat untuk dimiringkan. Ia mengepak, mematuk, dan mendorong lagi. Sia-sia. Air itu hanya bergetar, jauh dari jangkauan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_6', 'bok_the-crow-and-the-pitcher', 6, 'crow-pitcher-6', 'Many birds would have flown away. But this crow sat down, tilted her shiny black head, and looked at the problem the way clever birds do.', 'Burung lain mungkin sudah terbang pergi. Tapi gagak ini duduk, memiringkan kepala hitamnya yang berkilau, dan menatap masalah itu seperti burung-burung cerdik biasanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_7', 'bok_the-crow-and-the-pitcher', 7, 'crow-pitcher-7', 'Beside the pitcher lay a scattering of small pebbles. The crow looked at the pebbles. She looked at the water. And her bright eyes sparkled with an idea.', 'Di samping kendi berserakan kerikil-kerikil kecil. Gagak menatap kerikil. Ia menatap air. Dan matanya yang cerah berbinar oleh sebuah ide.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_8', 'bok_the-crow-and-the-pitcher', 8, 'crow-pitcher-8', 'She picked up a pebble and dropped it into the pitcher. Plop! The water rose — just a tiny, tiny bit.', 'Ia mengambil sebutir kerikil dan menjatuhkannya ke dalam kendi. Plung! Air naik — sedikit, sedikit sekali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_9', 'bok_the-crow-and-the-pitcher', 9, 'crow-pitcher-9', 'Another pebble. Plop! And another. Plop! Pebble after pebble, the busy crow worked in the hot sun, and pebble after pebble, the water crept higher.', 'Kerikil lagi. Plung! Lagi. Plung! Kerikil demi kerikil, gagak yang rajin itu bekerja di bawah matahari panas, dan kerikil demi kerikil, air merayap semakin tinggi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_10', 'bok_the-crow-and-the-pitcher', 10, 'crow-pitcher-10', 'At last — plop! — the water rose right up to the pitcher''s neck. The crow dipped her beak and drank the sweetest, coolest drink of her whole life.', 'Akhirnya — plung! — air naik sampai ke leher kendi. Gagak mencelupkan paruhnya dan meneguk minuman termanis dan tersejuk sepanjang hidupnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_11', 'bok_the-crow-and-the-pitcher', 11, 'crow-pitcher-11', '''Little by little does the trick,'' she said happily, ruffling her feathers. And she flew off into the evening, strong and quick again.', '''Sedikit demi sedikit, akhirnya berhasil,'' katanya senang sambil mengibaskan bulunya. Lalu ia terbang ke senja, kembali kuat dan gesit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-and-the-pitcher_12', 'bok_the-crow-and-the-pitcher', 12, 'crow-pitcher-12', 'So when a problem looks too big, remember the crow: do not give up — think, start small, and keep going. Drop by drop, the water rises. The end.', 'Maka bila sebuah masalah tampak terlalu besar, ingatlah sang gagak: jangan menyerah — berpikirlah, mulailah dari yang kecil, dan teruslah berusaha. Setetes demi setetes, air akan naik. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-and-the-pitcher_1', 'bok_the-crow-and-the-pitcher', 1, 'Why couldn''t the crow drink at first?', 'Mengapa gagak tak bisa langsung minum?', '["The water was too deep inside the pitcher","The water was dirty","The pitcher was empty"]', '["Airnya terlalu dalam di dasar kendi","Airnya kotor","Kendinya kosong"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-and-the-pitcher_2', 'bok_the-crow-and-the-pitcher', 2, 'What did the crow drop into the pitcher?', 'Apa yang dijatuhkan gagak ke dalam kendi?', '["Leaves","Pebbles","Seeds"]', '["Daun","Kerikil","Biji-bijian"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-and-the-pitcher_3', 'bok_the-crow-and-the-pitcher', 3, 'What made the water rise?', 'Apa yang membuat air naik?', '["Magic","Each pebble taking up space","The hot sun"]', '["Sihir","Setiap kerikil memenuhi ruang di dalam air","Matahari yang panas"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-elves-and-the-shoemaker', 'the-elves-and-the-shoemaker', 'The Elves and the Shoemaker', 'Peri Kecil dan Tukang Sepatu', 'A kind old shoemaker is down to his last piece of leather — until tiny midnight helpers change everything, and kindness is repaid with kindness.', 'Tukang sepatu tua yang baik hati hanya punya selembar kulit terakhir — sampai para penolong mungil tengah malam mengubah segalanya, dan kebaikan dibalas kebaikan.', 'cat_fairy-tales', 'aut_axto-creative-team', 'night', '👞', 4, 9, 0, 'published', 13, 2772, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_1', 'bok_the-elves-and-the-shoemaker', 1, 'elves-shoemaker-1', 'There was once a shoemaker who was honest and kind, but times were hard, and one evening he found he had leather left for only one last pair of shoes.', 'Dahulu ada seorang tukang sepatu yang jujur dan baik hati, tetapi zaman sedang sulit, dan suatu malam ia sadar kulitnya hanya cukup untuk satu pasang sepatu terakhir.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_2', 'bok_the-elves-and-the-shoemaker', 2, 'elves-shoemaker-2', 'He cut the leather carefully, laid the pieces on his workbench, and sighed. ''I will sew them in the morning.'' Then he blew out the candle and went to bed.', 'Ia memotong kulit itu dengan hati-hati, menata potongannya di meja kerja, lalu menghela napas. ''Besok pagi akan kujahit.'' Kemudian ia meniup lilin dan pergi tidur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_3', 'bok_the-elves-and-the-shoemaker', 3, 'elves-shoemaker-3', 'But in the morning — what a wonder! On the bench stood a finished pair of shoes, so beautifully stitched that every seam was perfect. ''Who could have done this?''', 'Namun pagi harinya — sungguh ajaib! Di atas meja sudah berdiri sepasang sepatu jadi, dijahit begitu indah hingga setiap jahitannya sempurna. ''Siapa gerangan yang mengerjakan ini?''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_4', 'bok_the-elves-and-the-shoemaker', 4, 'elves-shoemaker-4', 'A rich traveller bought the shoes at once, and paid so well that the shoemaker could buy leather for two pairs. That night, he cut the pieces and left them out again.', 'Seorang pelancong kaya langsung membeli sepatu itu, dan membayar sangat mahal hingga tukang sepatu bisa membeli kulit untuk dua pasang. Malam itu ia memotong kulitnya dan menaruhnya lagi di meja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_5', 'bok_the-elves-and-the-shoemaker', 5, 'elves-shoemaker-5', 'In the morning, two perfect pairs! And so it went on, night after night: whatever he cut in the evening was finished by dawn, finer than any shoes in the town.', 'Paginya, dua pasang sepatu sempurna! Begitu seterusnya, malam demi malam: apa pun yang ia potong di senja hari selesai saat fajar, lebih bagus daripada sepatu mana pun di kota.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_6', 'bok_the-elves-and-the-shoemaker', 6, 'elves-shoemaker-6', 'The little shop grew busy and warm again. But the shoemaker and his wife could not stop wondering. ''Tonight,'' said his wife, ''let us hide behind the curtain and watch.''', 'Toko kecil itu kembali ramai dan hangat. Tapi tukang sepatu dan istrinya tak bisa berhenti bertanya-tanya. ''Malam ini,'' kata istrinya, ''mari kita sembunyi di balik tirai dan mengintip.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_7', 'bok_the-elves-and-the-shoemaker', 7, 'elves-shoemaker-7', 'At midnight, the window creaked open — and in slipped two tiny elves, no taller than teacups. Their little clothes were nothing but rags, but their hands flew like hummingbirds.', 'Tepat tengah malam, jendela berderit terbuka — dan masuklah dua peri mungil, tak lebih tinggi dari cangkir teh. Pakaian kecil mereka hanya kain compang-camping, tetapi tangan mereka bekerja secepat kolibri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_8', 'bok_the-elves-and-the-shoemaker', 8, 'elves-shoemaker-8', 'Snip, stitch, tap-tap-tap! In moments the shoes stood finished, gleaming in the moonlight. Then the little elves bowed to each other and slipped away into the night.', 'Gunting, jahit, tok-tok-tok! Dalam sekejap sepatu-sepatu itu selesai, berkilau dalam cahaya bulan. Lalu kedua peri kecil saling membungkuk dan menghilang ke dalam malam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_9', 'bok_the-elves-and-the-shoemaker', 9, 'elves-shoemaker-9', '''They work so hard for us,'' whispered the shoemaker''s wife, ''and their clothes are so thin and torn. Winter is coming. Let us make a gift for them!''', '''Mereka bekerja begitu keras untuk kita,'' bisik istri tukang sepatu, ''padahal baju mereka tipis dan robek. Musim dingin akan tiba. Mari kita buatkan hadiah untuk mereka!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_10', 'bok_the-elves-and-the-shoemaker', 10, 'elves-shoemaker-10', 'So they sewed two tiny shirts, two tiny coats, two tiny caps — and the shoemaker made the smallest, softest pair of boots his hands had ever made.', 'Maka mereka menjahit dua kemeja mungil, dua mantel mungil, dua topi mungil — dan tukang sepatu membuat sepasang sepatu bot terkecil dan terlembut yang pernah dibuat tangannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_11', 'bok_the-elves-and-the-shoemaker', 11, 'elves-shoemaker-11', 'That night they laid the little clothes on the bench instead of leather. When the elves arrived, they clapped their tiny hands with joy, dressed at once, and danced around the workbench!', 'Malam itu mereka menaruh pakaian mungil di meja, bukan kulit sepatu. Ketika para peri datang, mereka bertepuk tangan gembira, langsung berpakaian, dan menari-nari mengelilingi meja kerja!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_12', 'bok_the-elves-and-the-shoemaker', 12, 'elves-shoemaker-12', '''Now we are dressed so fine and neat — no more cobbling, dancing feet!'' they sang, and out of the window they twirled, never to be seen again.', '''Kini kami berpakaian rapi dan indah — tak lagi menjahit, kaki kami menari!'' nyanyi mereka, lalu berputar keluar jendela, dan tak pernah terlihat lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elves-and-the-shoemaker_13', 'bok_the-elves-and-the-shoemaker', 13, 'elves-shoemaker-13', 'But good luck never left that little shop. For kindness given in secret has a way of staying in the walls — and in every pair of shoes the old man made, people said they could feel it. The end.', 'Namun keberuntungan tak pernah meninggalkan toko kecil itu. Sebab kebaikan yang diberikan diam-diam selalu tinggal di dinding rumah — dan pada setiap pasang sepatu buatan pak tua itu, kata orang, kebaikan itu terasa. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elves-and-the-shoemaker_1', 'bok_the-elves-and-the-shoemaker', 1, 'Who finished the shoes at night?', 'Siapa yang menyelesaikan sepatu di malam hari?', '["The shoemaker''s wife","Two tiny elves","The rich traveller"]', '["Istri tukang sepatu","Dua peri mungil","Pelancong kaya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elves-and-the-shoemaker_2', 'bok_the-elves-and-the-shoemaker', 2, 'What gift did the shoemaker and his wife make?', 'Hadiah apa yang dibuat tukang sepatu dan istrinya?', '["Tiny clothes and boots","A little house","Golden coins"]', '["Pakaian dan sepatu bot mungil","Rumah kecil","Koin emas"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elves-and-the-shoemaker_3', 'bok_the-elves-and-the-shoemaker', 3, 'Why did they give the elves a gift?', 'Mengapa mereka memberi hadiah kepada para peri?', '["To make them work harder","To thank them for their secret kindness","To make them leave"]', '["Agar mereka bekerja lebih keras","Untuk berterima kasih atas kebaikan diam-diam mereka","Agar mereka pergi"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-town-mouse-and-the-country-mouse', 'the-town-mouse-and-the-country-mouse', 'The Town Mouse and the Country Mouse', 'Tikus Kota dan Tikus Desa', 'Two cousin mice visit each other''s worlds — fine food in the noisy town, simple food in the peaceful field — and discover what ''home'' really tastes like.', 'Dua tikus bersaudara saling mengunjungi dunia masing-masing — makanan mewah di kota yang bising, makanan sederhana di ladang yang damai — dan menemukan rasa ''rumah'' yang sesungguhnya.', 'cat_family', 'aut_axto-creative-team', 'candy', '🐭', 3, 8, 0, 'published', 12, 471, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_1', 'bok_the-town-mouse-and-the-country-mouse', 1, 'town-country-1', 'Once there were two cousin mice. One lived in the quiet countryside, in a snug burrow under a hazel hedge. The other lived in the big, busy town, inside the wall of a grand house.', 'Dahulu ada dua tikus bersaudara sepupu. Yang satu tinggal di desa yang tenang, dalam liang hangat di bawah pagar tanaman. Yang lain tinggal di kota besar yang sibuk, di balik dinding sebuah rumah megah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_2', 'bok_the-town-mouse-and-the-country-mouse', 2, 'town-country-2', 'One autumn day, the town mouse came to visit. The country mouse proudly served the best he had: barley grains, hazelnuts, and a little piece of cheese rind.', 'Suatu hari di musim gugur, tikus kota datang berkunjung. Tikus desa dengan bangga menghidangkan yang terbaik miliknya: butir jelai, kacang hazel, dan sepotong kecil kulit keju.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_3', 'bok_the-town-mouse-and-the-country-mouse', 3, 'town-country-3', 'The town mouse nibbled politely, then wrinkled his nose. ''Dear cousin, how do you bear such plain food and such a quiet life? Come with me to town — I shall show you how to truly live!''', 'Tikus kota mengunyah dengan sopan, lalu mengernyitkan hidungnya. ''Saudaraku, bagaimana kau tahan dengan makanan sederhana dan hidup sesunyi ini? Ikutlah ke kota — akan kutunjukkan cara hidup yang sesungguhnya!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_4', 'bok_the-town-mouse-and-the-country-mouse', 4, 'town-country-4', 'So off they went. The town glittered with a thousand lights. In the grand house, the dining table was still covered from a feast: cakes, cheeses, figs, and honey!', 'Maka berangkatlah mereka. Kota berkilauan dengan seribu lampu. Di rumah megah itu, meja makan masih penuh sisa pesta: kue, keju, buah ara, dan madu!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_5', 'bok_the-town-mouse-and-the-country-mouse', 5, 'town-country-5', '''Help yourself, cousin!'' said the town mouse grandly. The country mouse had never tasted anything so delicious in all his life. ''Why, this is wonderful!'' he squeaked.', '''Silakan makan sepuasnya, saudaraku!'' kata tikus kota dengan megah. Tikus desa belum pernah mencicipi makanan selezat itu seumur hidupnya. ''Wah, ini luar biasa!'' cicitnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_6', 'bok_the-town-mouse-and-the-country-mouse', 6, 'town-country-6', 'But just as he bit into a fig — BANG! — the door flew open. Servants marched in with heavy boots, and the two mice dashed behind the curtain, hearts drumming.', 'Namun tepat saat ia menggigit buah ara — BRAK! — pintu terbuka lebar. Para pelayan masuk dengan sepatu bot berat, dan kedua tikus melesat ke balik tirai, jantung berdebar kencang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_7', 'bok_the-town-mouse-and-the-country-mouse', 7, 'town-country-7', 'When all was quiet, they crept out again. But hardly had they reached the cheese — ''MEOW!'' A huge cat leapt onto the table, eyes blazing like green fire!', 'Setelah semuanya sunyi, mereka merayap keluar lagi. Namun belum sampai ke keju — ''MEONG!'' Seekor kucing besar melompat ke atas meja, matanya menyala seperti api hijau!');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_8', 'bok_the-town-mouse-and-the-country-mouse', 8, 'town-country-8', 'The mice tumbled into a crack in the wall just in time. The country mouse pressed his paws to his chest. ''Cousin... is it like this every day?'' — ''Oh, one gets used to it,'' said the town mouse airily.', 'Kedua tikus terguling masuk celah dinding tepat pada waktunya. Tikus desa mendekap dadanya. ''Saudaraku... apakah setiap hari seperti ini?'' — ''Ah, lama-lama juga terbiasa,'' jawab tikus kota enteng.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_9', 'bok_the-town-mouse-and-the-country-mouse', 9, 'town-country-9', 'That night, the country mouse lay awake listening to carriages rattle and doors slam. He thought of his hedge, where the loudest sound was the owl saying goodnight.', 'Malam itu, tikus desa terjaga mendengarkan kereta kuda berderak dan pintu-pintu dibanting. Ia teringat pagar tanamannya, tempat suara paling nyaring hanyalah burung hantu yang mengucap selamat malam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_10', 'bok_the-town-mouse-and-the-country-mouse', 10, 'town-country-10', 'In the morning he hugged his cousin. ''Thank you for the feast, truly. But I would rather eat barley in peace than honey in fear. My little hedge is calling me home.''', 'Paginya ia memeluk sepupunya. ''Sungguh terima kasih atas pestanya. Tapi aku lebih suka makan jelai dalam damai daripada madu dalam ketakutan. Pagar kecilku memanggilku pulang.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_11', 'bok_the-town-mouse-and-the-country-mouse', 11, 'town-country-11', 'Back under the hazel hedge, he cooked his plain barley supper and ate it slowly, listening to the wind in the leaves. It tasted, he thought, exactly like happiness.', 'Kembali di bawah pagar tanamannya, ia memasak jelai sederhana untuk makan malam dan menyantapnya pelan-pelan sambil mendengarkan angin di dedaunan. Rasanya, pikirnya, persis seperti kebahagiaan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-town-mouse-and-the-country-mouse_12', 'bok_the-town-mouse-and-the-country-mouse', 12, 'town-country-12', 'For a simple life in peace can be sweeter than a rich life in fear — and the best home is the one where your heart can rest. The end.', 'Sebab hidup sederhana yang damai bisa lebih manis daripada hidup mewah yang penuh ketakutan — dan rumah terbaik adalah tempat hatimu bisa beristirahat. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-town-mouse-and-the-country-mouse_1', 'bok_the-town-mouse-and-the-country-mouse', 1, 'What food did the country mouse serve?', 'Makanan apa yang dihidangkan tikus desa?', '["Cakes and honey","Barley, hazelnuts and cheese rind","Figs and cream"]', '["Kue dan madu","Jelai, kacang hazel, dan kulit keju","Buah ara dan krim"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-town-mouse-and-the-country-mouse_2', 'bok_the-town-mouse-and-the-country-mouse', 2, 'What dangers did the mice meet in town?', 'Bahaya apa yang mereka temui di kota?', '["Rain and thunder","Servants and a huge cat","A hungry owl"]', '["Hujan dan petir","Para pelayan dan kucing besar","Burung hantu lapar"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-town-mouse-and-the-country-mouse_3', 'bok_the-town-mouse-and-the-country-mouse', 3, 'What did the country mouse decide in the end?', 'Apa keputusan tikus desa pada akhirnya?', '["To stay in town forever","That peace at home is sweeter than riches in fear","To become a town mouse"]', '["Tinggal di kota selamanya","Damai di rumah lebih manis daripada kemewahan dalam ketakutan","Menjadi tikus kota"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-little-red-hen', 'the-little-red-hen', 'The Little Red Hen', 'Ayam Merah Kecil', 'Who will help plant the wheat? Not I, said the cat, the dog and the duck — a warm farm tale about work, sharing, and second chances.', 'Siapa mau membantu menanam gandum? Tidak aku, kata kucing, anjing, dan bebek — dongeng peternakan yang hangat tentang kerja, berbagi, dan kesempatan kedua.', 'cat_farm', 'aut_axto-creative-team', 'sunrise', '🐔', 3, 7, 0, 'published', 12, 907, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_1', 'bok_the-little-red-hen', 1, 'red-hen-1', 'On a cosy little farm lived a little red hen with her fluffy yellow chicks — and three lazy friends: a sleepy cat, a dozy dog, and a daydreaming duck.', 'Di sebuah peternakan kecil yang nyaman hiduplah ayam merah kecil bersama anak-anaknya yang kuning berbulu halus — dan tiga sahabat pemalas: kucing yang mengantuk, anjing yang lesu, dan bebek yang suka melamun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_2', 'bok_the-little-red-hen', 2, 'red-hen-2', 'One bright morning, the little red hen found some golden grains of wheat on the path. ''Who will help me plant this wheat?'' she called.', 'Suatu pagi yang cerah, ayam merah kecil menemukan butir-butir gandum keemasan di jalan setapak. ''Siapa mau membantuku menanam gandum ini?'' serunya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_3', 'bok_the-little-red-hen', 3, 'red-hen-3', '''Not I,'' yawned the cat from the windowsill. ''Not I,'' mumbled the dog from his shady spot. ''Not I,'' quacked the duck, watching the clouds.', '''Tidak aku,'' kucing menguap dari jendela. ''Tidak aku,'' gumam anjing dari tempat teduhnya. ''Tidak aku,'' kwek bebek sambil menatap awan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_4', 'bok_the-little-red-hen', 4, 'red-hen-4', '''Then I shall plant it myself,'' said the little red hen. And she did — scratching the soil, tucking in each grain, and patting the earth gently on top.', '''Kalau begitu akan kutanam sendiri,'' kata ayam merah kecil. Dan ia melakukannya — mengais tanah, membenamkan setiap butir, dan menepuk-nepuk tanah dengan lembut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_5', 'bok_the-little-red-hen', 5, 'red-hen-5', 'All summer she watered and weeded. ''Who will help me care for the wheat?'' — ''Not I.'' ''Not I.'' ''Not I.'' So she cared for it herself, day after day.', 'Sepanjang musim ia menyiram dan mencabuti rumput liar. ''Siapa mau membantuku merawat gandum?'' — ''Tidak aku.'' ''Tidak aku.'' ''Tidak aku.'' Maka ia merawatnya sendiri, hari demi hari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_6', 'bok_the-little-red-hen', 6, 'red-hen-6', 'The wheat grew tall and golden as the sun. ''Who will help me cut the wheat?'' asked the hen. ''Not I,'' said the cat, the dog and the duck together.', 'Gandum tumbuh tinggi dan keemasan seperti matahari. ''Siapa mau membantuku memanen gandum?'' tanya si ayam. ''Tidak aku,'' jawab kucing, anjing, dan bebek serempak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_7', 'bok_the-little-red-hen', 7, 'red-hen-7', '''Then I shall cut it myself.'' Swish, swish! She cut and bundled every stalk, and carried it to the mill to be ground into soft white flour.', '''Kalau begitu akan kupanen sendiri.'' Kres, kres! Ia memotong dan mengikat setiap batang, lalu membawanya ke penggilingan untuk dijadikan tepung putih yang halus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_8', 'bok_the-little-red-hen', 8, 'red-hen-8', '''Who will help me bake the bread?'' she asked at last. ''Not I... not I... not I,'' came the three lazy voices. ''Then I shall bake it myself,'' said the little red hen.', '''Siapa mau membantuku memanggang roti?'' tanyanya akhirnya. ''Tidak aku... tidak aku... tidak aku,'' sahut tiga suara pemalas itu. ''Kalau begitu akan kupanggang sendiri,'' kata ayam merah kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_9', 'bok_the-little-red-hen', 9, 'red-hen-9', 'Soon a smell so warm and wonderful floated across the farm that the cat, the dog and the duck all came running. ''We will help you EAT the bread!'' they cried.', 'Tak lama kemudian, aroma yang begitu hangat dan lezat tercium ke seluruh peternakan, sampai kucing, anjing, dan bebek berlari datang. ''Kami mau membantu MAKAN rotinya!'' seru mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_10', 'bok_the-little-red-hen', 10, 'red-hen-10', 'The little red hen looked at them kindly but firmly. ''You did not plant, you did not water, you did not cut, you did not bake. My chicks and I, who did the work, will eat this loaf.''', 'Ayam merah kecil memandang mereka dengan lembut tapi tegas. ''Kalian tidak menanam, tidak menyiram, tidak memanen, tidak memanggang. Aku dan anak-anakku, yang mengerjakan semuanya, yang akan memakan roti ini.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_11', 'bok_the-little-red-hen', 11, 'red-hen-11', 'The three friends hung their heads, for they knew she was right. ''We are sorry, little red hen,'' said the dog quietly. ''Next time, we will help from the very first day.''', 'Ketiga sahabat itu menunduk malu, karena mereka tahu ayam merah benar. ''Maafkan kami, ayam merah kecil,'' kata anjing pelan. ''Lain kali, kami akan membantu sejak hari pertama.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-little-red-hen_12', 'bok_the-little-red-hen', 12, 'red-hen-12', 'And they kept their word! When spring came, four friends planted the wheat together — and when the next loaf came out of the oven, the whole farm shared it, warm slice by warm slice. The end.', 'Dan mereka menepati janji! Saat musim semi tiba, empat sahabat menanam gandum bersama — dan ketika roti berikutnya keluar dari panggangan, seisi peternakan menikmatinya bersama, sepotong demi sepotong yang hangat. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-red-hen_1', 'bok_the-little-red-hen', 1, 'What did the friends say when the hen asked for help?', 'Apa jawaban para sahabat saat si ayam minta tolong?', '["''Yes, of course!''","''Not I.''","''Maybe tomorrow.''"]', '["''Ya, tentu!''","''Tidak aku.''","''Mungkin besok.''"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-red-hen_2', 'bok_the-little-red-hen', 2, 'Why didn''t the hen share the first loaf?', 'Mengapa ayam tidak membagi roti pertamanya?', '["She was unkind","The friends had refused to do any of the work","The bread was too small"]', '["Ia jahat","Para sahabat menolak ikut bekerja","Rotinya terlalu kecil"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-little-red-hen_3', 'bok_the-little-red-hen', 3, 'What happened in spring?', 'Apa yang terjadi saat musim semi?', '["The friends helped from the first day and all shared the bread","The hen moved away","The wheat did not grow"]', '["Para sahabat membantu sejak hari pertama dan semua berbagi roti","Si ayam pindah","Gandumnya tidak tumbuh"]', 0, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-boy-who-cried-wolf', 'the-boy-who-cried-wolf', 'The Boy Who Cried Wolf', 'Anak Gembala yang Berteriak Serigala', 'A bored shepherd boy plays a trick on his village — twice. But when a real wolf comes, he learns what a lie costs.', 'Seorang anak gembala yang bosan mengerjai desanya — dua kali. Namun saat serigala sungguhan datang, ia belajar mahalnya harga sebuah kebohongan.', 'cat_moral-stories', 'aut_axto-creative-team', 'dusk', '🐺', 4, 9, 0, 'published', 12, 4794, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_1', 'bok_the-boy-who-cried-wolf', 1, 'cried-wolf-1', 'On a green hill above a little village, a shepherd boy watched the sheep every day. The sun was warm, the bells went ting-ting, and the days were very, very long.', 'Di bukit hijau di atas sebuah desa kecil, seorang anak gembala menjaga domba setiap hari. Matahari hangat, lonceng domba berdenting-denting, dan hari terasa sangat, sangat panjang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_2', 'bok_the-boy-who-cried-wolf', 2, 'cried-wolf-2', 'One afternoon, the boy grew so bored that a naughty idea popped into his head. He stood up, cupped his hands, and shouted down to the village: ''WOLF! WOLF! A wolf is after the sheep!''', 'Suatu sore, anak itu begitu bosan sampai sebuah ide nakal muncul di kepalanya. Ia berdiri, menangkupkan tangan, dan berteriak ke arah desa: ''SERIGALA! SERIGALA! Ada serigala mengejar domba!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_3', 'bok_the-boy-who-cried-wolf', 3, 'cried-wolf-3', 'The villagers dropped everything. The baker left his oven, the farmer left his plough, and up the hill they ran with sticks and shouts — as fast as their legs could carry them.', 'Warga desa meninggalkan semuanya. Tukang roti meninggalkan panggangannya, petani meninggalkan bajaknya, dan mereka berlari mendaki bukit membawa tongkat sambil berteriak — secepat kaki mereka bisa berlari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_4', 'bok_the-boy-who-cried-wolf', 4, 'cried-wolf-4', 'But at the top they found no wolf at all — only the boy, rolling in the grass with laughter. ''You should see your faces!'' he giggled. The villagers walked home, shaking their heads.', 'Namun di puncak bukit tak ada serigala sama sekali — hanya si anak, berguling-guling di rumput sambil tertawa. ''Coba lihat wajah kalian!'' kikiknya. Warga desa pulang sambil menggeleng-geleng.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_5', 'bok_the-boy-who-cried-wolf', 5, 'cried-wolf-5', 'A few days later, the boy did it again. ''WOLF! WOLF!'' And again the villagers came running — and again there was no wolf, only laughter rolling down the hill.', 'Beberapa hari kemudian, anak itu melakukannya lagi. ''SERIGALA! SERIGALA!'' Dan lagi-lagi warga berlari datang — dan lagi-lagi tak ada serigala, hanya tawa yang bergema menuruni bukit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_6', 'bok_the-boy-who-cried-wolf', 6, 'cried-wolf-6', 'This time nobody smiled. ''Lies are not jokes, boy,'' said the old baker quietly. ''A liar is not believed — even when he tells the truth.'' But the boy only shrugged.', 'Kali ini tak ada yang tersenyum. ''Bohong itu bukan lelucon, nak,'' kata tukang roti tua pelan. ''Pembohong takkan dipercaya — bahkan saat ia berkata benar.'' Tapi anak itu hanya mengangkat bahu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_7', 'bok_the-boy-who-cried-wolf', 7, 'cried-wolf-7', 'Then, one grey evening, the grass rustled — and out of the shadows stepped a real wolf, with hungry yellow eyes fixed on the flock.', 'Lalu, pada suatu senja kelabu, rerumputan bergemerisik — dan dari balik bayangan muncullah serigala sungguhan, dengan mata kuning lapar menatap kawanan domba.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_8', 'bok_the-boy-who-cried-wolf', 8, 'cried-wolf-8', '''WOLF!'' screamed the boy, and this time his voice shook with real fear. ''WOLF! PLEASE! HELP! A REAL WOLF!''', '''SERIGALA!'' jerit anak itu, dan kali ini suaranya gemetar oleh ketakutan yang sungguhan. ''SERIGALA! TOLONG! SERIGALA BETULAN!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_9', 'bok_the-boy-who-cried-wolf', 9, 'cried-wolf-9', 'Down in the village, the baker heard him and sighed. ''That boy again.'' The farmer heard him and kept ploughing. ''He will not fool us a third time.'' Nobody came.', 'Di bawah, di desa, tukang roti mendengarnya dan menghela napas. ''Anak itu lagi.'' Petani mendengarnya dan terus membajak. ''Ia takkan menipu kami untuk ketiga kalinya.'' Tak seorang pun datang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_10', 'bok_the-boy-who-cried-wolf', 10, 'cried-wolf-10', 'The boy could only wave his stick and shout as the wolf scattered the flock and drove off the fattest sheep into the dark woods.', 'Anak itu hanya bisa mengayunkan tongkat dan berteriak saat serigala mencerai-beraikan kawanan dan menggiring domba paling gemuk ke dalam hutan yang gelap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_11', 'bok_the-boy-who-cried-wolf', 11, 'cried-wolf-11', 'When the villagers finally came at nightfall and heard what had happened, the boy hung his head and wept. ''You warned me,'' he whispered to the baker. ''Nobody believes a liar — even when he tells the truth.''', 'Ketika warga akhirnya datang saat malam tiba dan mendengar kejadiannya, anak itu menunduk dan menangis. ''Kalian sudah memperingatkanku,'' bisiknya pada tukang roti. ''Tak ada yang percaya pembohong — bahkan saat ia berkata benar.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-cried-wolf_12', 'bok_the-boy-who-cried-wolf', 12, 'cried-wolf-12', 'From that day on, the boy guarded both his sheep and his words. And when he grew up, they say, he became the most trusted man in the village — because he had learned young how precious the truth is. The end.', 'Sejak hari itu, si anak menjaga dombanya dan juga kata-katanya. Dan ketika ia dewasa, konon ia menjadi orang paling dipercaya di desa — karena ia belajar sejak kecil betapa berharganya kejujuran. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-cried-wolf_1', 'bok_the-boy-who-cried-wolf', 1, 'Why did the boy first shout ''Wolf!''?', 'Mengapa anak itu pertama kali berteriak ''Serigala!''?', '["He saw a real wolf","He was bored and wanted to trick the villagers","He was practising singing"]', '["Ia melihat serigala sungguhan","Ia bosan dan ingin mengerjai warga","Ia sedang latihan bernyanyi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-cried-wolf_2', 'bok_the-boy-who-cried-wolf', 2, 'Why did nobody come when the real wolf appeared?', 'Mengapa tak ada yang datang saat serigala sungguhan muncul?', '["They were asleep","They no longer believed him after his lies","They were afraid of wolves"]', '["Mereka sedang tidur","Mereka tak lagi percaya setelah kebohongannya","Mereka takut serigala"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-cried-wolf_3', 'bok_the-boy-who-cried-wolf', 3, 'What is the lesson of this story?', 'Apa pelajaran dari cerita ini?', '["Wolves are dangerous","Shouting is rude","If you lie, people stop believing you — even when you tell the truth"]', '["Serigala itu berbahaya","Berteriak itu tidak sopan","Jika kau berbohong, orang berhenti mempercayaimu — bahkan saat kau jujur"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-monkey-and-the-crocodile', 'the-monkey-and-the-crocodile', 'The Monkey and the Crocodile', 'Kera dan Buaya', 'A monkey and a crocodile become unlikely river friends — until a dangerous secret tests how quickly a clever heart can think.', 'Seekor kera dan buaya menjadi sahabat sungai yang tak terduga — sampai sebuah rahasia berbahaya menguji secepat apa akal yang cerdik bisa berpikir.', 'cat_jungle-safari', 'aut_axto-creative-team', 'forest', '🐒', 4, 9, 0, 'published', 12, 419, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_1', 'bok_the-monkey-and-the-crocodile', 1, 'monkey-croc-1', 'Long ago, in a jamun tree that leaned over a great river, lived a cheerful monkey. The tree''s purple fruit was the sweetest for miles, and the monkey ate it from morning till night.', 'Dahulu kala, di pohon jamblang yang condong ke sungai besar, hiduplah seekor kera yang riang. Buah ungu pohon itu paling manis sejauh mata memandang, dan si kera memakannya dari pagi sampai malam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_2', 'bok_the-monkey-and-the-crocodile', 2, 'monkey-croc-2', 'One day a crocodile swam up and rested under the tree. ''You look tired, friend,'' said the monkey, and he threw down a pawful of sweet jamun. The crocodile had never tasted anything so fine.', 'Suatu hari seekor buaya berenang mendekat dan beristirahat di bawah pohon. ''Kau tampak lelah, kawan,'' kata kera, lalu ia menjatuhkan segenggam jamblang manis. Buaya itu belum pernah mencicipi buah selezat itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_3', 'bok_the-monkey-and-the-crocodile', 3, 'monkey-croc-3', 'From then on, the crocodile came every day, and the two became true friends — the monkey dropping fruit, the crocodile telling stories of the deep river and the far bank.', 'Sejak itu, buaya datang setiap hari, dan keduanya menjadi sahabat sejati — kera menjatuhkan buah, buaya bercerita tentang sungai yang dalam dan tepian yang jauh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_4', 'bok_the-monkey-and-the-crocodile', 4, 'monkey-croc-4', 'The crocodile carried some jamun home to his wife. She ate them and her eyes narrowed greedily. ''If the fruit is this sweet,'' she said, ''how sweet must be the heart of the monkey who eats them every day! Bring me his heart.''', 'Buaya membawa beberapa jamblang pulang untuk istrinya. Istrinya memakannya dan matanya menyipit serakah. ''Kalau buahnya semanis ini,'' katanya, ''betapa manisnya hati kera yang memakannya setiap hari! Bawakan aku hati kera itu.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_5', 'bok_the-monkey-and-the-crocodile', 5, 'monkey-croc-5', 'The crocodile was horrified. ''He is my friend!'' But his wife pretended to be terribly ill. ''Only a monkey''s heart can cure me,'' she moaned. And the weak-willed crocodile finally agreed.', 'Buaya terkejut dan sedih. ''Ia sahabatku!'' Tapi istrinya berpura-pura sakit parah. ''Hanya hati kera yang bisa menyembuhkanku,'' rintihnya. Dan buaya yang lemah hati itu akhirnya menurut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_6', 'bok_the-monkey-and-the-crocodile', 6, 'monkey-croc-6', '''Friend monkey!'' he called the next morning. ''My wife has cooked a feast to thank you for the fruit. Climb on my back, and I shall carry you across to our home!''', '''Sahabatku kera!'' panggilnya keesokan pagi. ''Istriku memasak jamuan untuk berterima kasih atas buah-buahmu. Naiklah ke punggungku, akan kubawa kau ke rumah kami di seberang!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_7', 'bok_the-monkey-and-the-crocodile', 7, 'monkey-croc-7', 'The monkey, delighted, hopped onto the crocodile''s back. But in the middle of the river, where the water ran deepest, the crocodile began to sink — and told the truth.', 'Kera dengan senang hati melompat ke punggung buaya. Namun di tengah sungai, di bagian air yang paling dalam, buaya mulai menenggelamkan diri — dan mengakui yang sebenarnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_8', 'bok_the-monkey-and-the-crocodile', 8, 'monkey-croc-8', '''Forgive me, friend. My wife is ill, and she says only your heart can cure her.'' The monkey''s blood ran cold — but his clever mind stayed warm, and it worked faster than fear.', '''Maafkan aku, kawan. Istriku sakit, dan katanya hanya hatimu yang bisa menyembuhkannya.'' Darah kera serasa membeku — tapi akal cerdiknya tetap hangat, dan bekerja lebih cepat daripada rasa takut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_9', 'bok_the-monkey-and-the-crocodile', 9, 'monkey-croc-9', '''My heart? Oh, dear friend, why didn''t you say so at the tree!'' cried the monkey. ''We monkeys never carry our hearts around — they are far too precious! Mine is hanging safely in the jamun tree!''', '''Hatiku? Aduh, sahabatku, mengapa tak bilang dari tadi di pohon!'' seru kera. ''Kami para kera tak pernah membawa-bawa hati — terlalu berharga! Hatiku kugantung aman di pohon jamblang!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_10', 'bok_the-monkey-and-the-crocodile', 10, 'monkey-croc-10', '''Then we must go back for it at once!'' said the crocodile, and he turned around and swam swiftly back to the tree.', '''Kalau begitu kita harus kembali mengambilnya sekarang juga!'' kata buaya, lalu ia berbalik dan berenang cepat kembali ke pohon.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_11', 'bok_the-monkey-and-the-crocodile', 11, 'monkey-croc-11', 'The moment they touched the bank, the monkey leapt high into his tree and looked down. ''Foolish friend! Who ever heard of a heart hanging in a tree? A friend who plots against a friend loses the fruit AND the friendship!''', 'Begitu menyentuh tepian, kera melompat tinggi ke pohonnya dan menoleh ke bawah. ''Sahabat yang bodoh! Mana ada hati digantung di pohon? Sahabat yang berkhianat kehilangan buahnya DAN persahabatannya!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-monkey-and-the-crocodile_12', 'bok_the-monkey-and-the-crocodile', 12, 'monkey-croc-12', 'The crocodile swam home ashamed, with no heart, no fruit and no friend. And children by that river still learn the double lesson: keep your wits when danger speaks sweetly — and never trade a true friend for anything. The end.', 'Buaya berenang pulang dengan malu, tanpa hati, tanpa buah, dan tanpa sahabat. Dan anak-anak di tepi sungai itu masih mempelajari pelajaran gandanya: jaga akalmu saat bahaya berbicara manis — dan jangan pernah menukar sahabat sejati dengan apa pun. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-monkey-and-the-crocodile_1', 'bok_the-monkey-and-the-crocodile', 1, 'How did the monkey and crocodile become friends?', 'Bagaimana kera dan buaya bersahabat?', '["The monkey shared his sweet jamun fruit","They raced across the river","The crocodile saved the monkey"]', '["Kera berbagi buah jamblang manisnya","Mereka berlomba menyeberangi sungai","Buaya menyelamatkan kera"]', 0, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-monkey-and-the-crocodile_2', 'bok_the-monkey-and-the-crocodile', 2, 'What did the monkey say to save himself?', 'Apa kata kera untuk menyelamatkan diri?', '["That he could not swim","That his heart was hanging in the jamun tree","That he was not sweet"]', '["Bahwa ia tak bisa berenang","Bahwa hatinya tergantung di pohon jamblang","Bahwa ia tidak manis"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-monkey-and-the-crocodile_3', 'bok_the-monkey-and-the-crocodile', 3, 'What did the crocodile lose in the end?', 'Apa yang hilang dari buaya pada akhirnya?', '["His tail","The fruit and the friendship","His house"]', '["Ekornya","Buah dan persahabatannya","Rumahnya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-empty-pot', 'the-empty-pot', 'The Empty Pot', 'Pot yang Kosong', 'The Emperor will choose his heir with a single flower seed. A whole kingdom grows glorious blooms — except one boy, whose pot stays empty.', 'Kaisar akan memilih penerusnya dengan sebutir benih bunga. Seluruh negeri menumbuhkan bunga-bunga indah — kecuali satu anak, yang potnya tetap kosong.', 'cat_world-cultures', 'aut_david-lee', 'meadow', '🌱', 4, 10, 0, 'published', 12, 1202, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_1', 'bok_the-empty-pot', 1, 'empty-pot-1', 'Long ago in China there lived an old Emperor who loved flowers more than gold. He had no child of his own, and the time had come to choose who would rule after him.', 'Dahulu kala di Tiongkok hiduplah seorang Kaisar tua yang mencintai bunga melebihi emas. Ia tak punya anak, dan tibalah waktunya memilih siapa yang akan memerintah setelahnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_2', 'bok_the-empty-pot', 2, 'empty-pot-2', 'So the Emperor made a proclamation: ''Every child in the kingdom shall receive one seed from my own hand. Whoever grows the finest flower in one year shall be my heir.''', 'Maka Kaisar mengeluarkan pengumuman: ''Setiap anak di negeri ini akan menerima sebutir benih dari tanganku sendiri. Siapa yang menumbuhkan bunga terindah dalam satu tahun akan menjadi penerusku.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_3', 'bok_the-empty-pot', 3, 'empty-pot-3', 'A boy named Ping was among the thousands who came. Ping loved gardening with his whole heart — everything he planted seemed to wake up and dance. He carried his seed home like a treasure.', 'Seorang anak bernama Ping ada di antara ribuan anak yang datang. Ping mencintai berkebun dengan segenap hatinya — apa pun yang ia tanam seakan bangun dan menari. Ia membawa pulang benihnya bagai harta karun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_4', 'bok_the-empty-pot', 4, 'empty-pot-4', 'He chose his best pot, his richest soil, and planted the seed with the gentlest fingers in the kingdom. He watered it every morning. And he waited.', 'Ia memilih pot terbaiknya, tanah tersuburnya, dan menanam benih itu dengan jari-jari terlembut di seluruh negeri. Ia menyiraminya setiap pagi. Lalu ia menunggu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_5', 'bok_the-empty-pot', 5, 'empty-pot-5', 'Nothing grew. Ping moved the pot into the sun. Nothing. He changed the soil, he sang to it, he checked it by moonlight. Still nothing — not even the smallest green tip.', 'Tak ada yang tumbuh. Ping memindahkan pot ke bawah matahari. Nihil. Ia mengganti tanah, bernyanyi untuknya, memeriksanya di bawah cahaya bulan. Tetap nihil — bahkan pucuk hijau terkecil pun tidak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_6', 'bok_the-empty-pot', 6, 'empty-pot-6', 'Meanwhile, all over the kingdom, the other children whispered of their wonderful flowers. ''Mine is red as fire!'' ''Mine is taller than my father!'' Ping''s heart sank lower every day.', 'Sementara itu, di seluruh negeri, anak-anak lain berbisik tentang bunga mereka yang menakjubkan. ''Punyaku merah seperti api!'' ''Punyaku lebih tinggi dari ayahku!'' Hati Ping tenggelam semakin dalam setiap hari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_7', 'bok_the-empty-pot', 7, 'empty-pot-7', 'The year ended. The children marched to the palace carrying pots bursting with magnificent blooms — crimson, gold, purple, white. And Ping walked among them carrying... an empty pot.', 'Tahun pun berakhir. Anak-anak berbaris ke istana membawa pot yang penuh bunga-bunga megah — merah tua, emas, ungu, putih. Dan Ping berjalan di antara mereka membawa... pot yang kosong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_8', 'bok_the-empty-pot', 8, 'empty-pot-8', '''Why do you bring an empty pot?'' the other children laughed. Ping''s cheeks burned, but he answered quietly: ''I did everything I could. This is the truth of what grew.''', '''Mengapa kau membawa pot kosong?'' anak-anak lain tertawa. Pipi Ping memerah, tapi ia menjawab pelan: ''Aku sudah berusaha sebisaku. Inilah yang sebenarnya tumbuh.''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_9', 'bok_the-empty-pot', 9, 'empty-pot-9', 'The Emperor walked slowly down the long line of glorious flowers, his face growing stranger and sadder at every step. Then he stopped — in front of the empty pot.', 'Kaisar berjalan pelan menyusuri barisan panjang bunga-bunga indah itu, wajahnya semakin aneh dan sedih di setiap langkah. Lalu ia berhenti — di depan pot yang kosong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_10', 'bok_the-empty-pot', 10, 'empty-pot-10', '''What is your name, child?'' — ''Ping, Your Majesty. I am sorry. I tried my very best, but your seed would not grow.'' The Emperor''s eyes began to shine.', '''Siapa namamu, nak?'' — ''Ping, Yang Mulia. Maafkan saya. Saya sudah berusaha sebaik mungkin, tapi benih Paduka tidak mau tumbuh.'' Mata Kaisar mulai berbinar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_11', 'bok_the-empty-pot', 11, 'empty-pot-11', 'The Emperor turned to the crowd and raised his voice: ''Hear me! The seeds I gave were all COOKED. Not one of them could ever grow. Yet only one child has brought me the truth!''', 'Kaisar berbalik ke arah kerumunan dan mengangkat suaranya: ''Dengarlah! Semua benih yang kubagikan sudah DIREBUS. Tak satu pun bisa tumbuh. Namun hanya satu anak yang membawakan kepadaku kejujuran!''');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-empty-pot_12', 'bok_the-empty-pot', 12, 'empty-pot-12', '''Courage to tell the truth when it is hard — that is the flower I was looking for.'' And so Ping, the boy with the empty pot, became the Emperor''s heir — and years later, the kingdom''s most honest and beloved ruler. The end.', '''Keberanian berkata jujur saat itu sulit — itulah bunga yang kucari.'' Maka Ping, anak dengan pot kosong itu, menjadi penerus Kaisar — dan bertahun-tahun kemudian, menjadi pemimpin paling jujur dan paling dicintai di negeri itu. Tamat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-empty-pot_1', 'bok_the-empty-pot', 1, 'Why did nothing grow from Ping''s seed?', 'Mengapa benih Ping tidak tumbuh?', '["He forgot to water it","All the seeds had been cooked","He used bad soil"]', '["Ia lupa menyiramnya","Semua benih sudah direbus","Tanahnya jelek"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-empty-pot_2', 'bok_the-empty-pot', 2, 'Where did the other children''s flowers come from?', 'Dari mana bunga anak-anak lain berasal?', '["From the Emperor''s seeds","Not from the Emperor''s seeds — they were not honest","From a magic garden"]', '["Dari benih Kaisar","Bukan dari benih Kaisar — mereka tidak jujur","Dari kebun ajaib"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-empty-pot_3', 'bok_the-empty-pot', 3, 'What ''flower'' was the Emperor really looking for?', '''Bunga'' apa yang sebenarnya dicari Kaisar?', '["The tallest bloom","The rarest color","The courage to tell the truth"]', '["Bunga tertinggi","Warna terlangka","Keberanian untuk berkata jujur"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-letter-that-went-missing', 'the-letter-that-went-missing', 'The Letter That Went Missing', 'Huruf yang Hilang', 'When the letter S wanders off, the whole alphabet has to work together to find it — and nothing sounds right until they do.', 'Ketika huruf S menghilang, seluruh abjad harus bekerja sama mencarinya — dan tidak ada yang terdengar benar sebelum ia ditemukan.', 'cat_alphabet', 'aut_axto-creative-team', 'sunrise', '🔤', 3, 6, 0, 'published', 9, 3657, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_1', 'bok_the-letter-that-went-missing', 1, 'letter-s-1', 'In a quiet little town called Wordville, all twenty-six letters lived together on one long shelf. Every morning they lined up in order, from A all the way to Z, ready for the day''s words.', 'Di sebuah kota kecil yang tenang bernama Wordville, kedua puluh enam huruf tinggal bersama di satu rak panjang. Setiap pagi mereka berbaris berurutan, dari A sampai Z, siap untuk kata-kata hari itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_2', 'bok_the-letter-that-went-missing', 2, 'letter-s-2', 'But one Tuesday morning, there was a gap on the shelf. Right between R and T, where S always stood, there was nothing but empty air.', 'Namun pada suatu Selasa pagi, ada celah di rak itu. Tepat di antara R dan T, tempat S biasa berdiri, hanya ada udara kosong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_3', 'bok_the-letter-that-went-missing', 3, 'letter-s-3', 'Without S, everything went strange. The sun became the un. The stars became the tars. And when little A tried to say sorry, all that came out was orry.', 'Tanpa S, semuanya jadi aneh. Matahari kehilangan namanya. Bintang-bintang terdengar salah. Dan ketika si kecil A mencoba berkata maaf, yang keluar hanyalah bunyi yang tidak lengkap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_4', 'bok_the-letter-that-went-missing', 4, 'letter-s-4', '"We must find S," said B in his steady voice. So the letters set out together, following the sound of a soft hiss through the tall grass.', '"Kita harus menemukan S," kata B dengan suara mantap. Maka huruf-huruf itu berangkat bersama, mengikuti bunyi desis lembut di antara rumput tinggi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_5', 'bok_the-letter-that-went-missing', 5, 'letter-s-5', 'They searched by the stream, where S liked to curve like the water. They searched by the snake''s rock, and by the sleepy old shed. No S anywhere.', 'Mereka mencari di tepi sungai, tempat S suka melengkung seperti air. Mereka mencari di batu tempat ular berjemur, dan di gudang tua yang mengantuk. S tidak ada di mana-mana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_6', 'bok_the-letter-that-went-missing', 6, 'letter-s-6', 'At last, tiny I heard something. Behind the library, curled up small and quiet, sat S with her head down. "Nobody needs me," she whispered. "There are twenty-five other letters."', 'Akhirnya, si mungil I mendengar sesuatu. Di belakang perpustakaan, meringkuk kecil dan diam, duduklah S dengan kepala tertunduk. "Tidak ada yang membutuhkanku," bisiknya. "Masih ada dua puluh lima huruf lain."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_7', 'bok_the-letter-that-went-missing', 7, 'letter-s-7', 'The letters looked at one another. Then O stepped forward. "Say our names," she said gently. "Say them without you." And S tried — and could not make sun, or star, or sister, or smile.', 'Huruf-huruf itu saling berpandangan. Lalu O melangkah maju. "Sebutkan nama-nama kami," katanya lembut. "Sebutkan tanpa dirimu." S mencoba — dan tidak bisa membuat kata matahari, bintang, saudara, atau senyum.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_8', 'bok_the-letter-that-went-missing', 8, 'letter-s-8', 'S stood up slowly. All the way home, the letters walked beside her, and the closer they came to the shelf, the more the words in the air began to sound right again.', 'S berdiri perlahan. Sepanjang jalan pulang, huruf-huruf berjalan di sisinya, dan semakin dekat ke rak, semakin benar pula bunyi kata-kata di udara.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-letter-that-went-missing_9', 'bok_the-letter-that-went-missing', 9, 'letter-s-9', 'That evening, when the sun set over Wordville, every letter was in its place. And S sat between R and T, small and shining, knowing something she had not known that morning: every single one of them mattered.', 'Malam itu, ketika matahari terbenam di atas Wordville, setiap huruf berada di tempatnya. Dan S duduk di antara R dan T, kecil dan bercahaya, mengetahui sesuatu yang belum ia ketahui pagi tadi: setiap huruf itu penting.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-that-went-missing_1', 'bok_the-letter-that-went-missing', 1, 'Which letter went missing?', 'Huruf mana yang menghilang?', '["The letter A","The letter S","The letter Z","The letter M"]', '["Huruf A","Huruf S","Huruf Z","Huruf M"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-that-went-missing_2', 'bok_the-letter-that-went-missing', 2, 'Why did S hide behind the library?', 'Mengapa S bersembunyi di belakang perpustakaan?', '["She was playing a game","She thought nobody needed her","She was tired","She was lost"]', '["Ia sedang bermain","Ia merasa tidak dibutuhkan siapa pun","Ia lelah","Ia tersesat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-letter-that-went-missing_3', 'bok_the-letter-that-went-missing', 3, 'What did the letters help S understand?', 'Apa yang membuat S mengerti berkat bantuan huruf-huruf lain?', '["That she was the best letter","That every letter matters","That she should stay hidden","That words are easy"]', '["Bahwa ia huruf terbaik","Bahwa setiap huruf itu penting","Bahwa ia sebaiknya tetap bersembunyi","Bahwa kata itu mudah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_seven-seeds-for-grandmother', 'seven-seeds-for-grandmother', 'Seven Seeds for Grandmother', 'Tujuh Benih untuk Nenek', 'Dita has seven sunflower seeds and a whole garden to plan. A gentle counting story about sharing, waiting and watching things grow.', 'Dita punya tujuh benih bunga matahari dan sebuah kebun untuk direncanakan. Cerita berhitung yang lembut tentang berbagi, menunggu, dan melihat sesuatu tumbuh.', 'cat_numbers', 'aut_axto-creative-team', 'meadow', '🌻', 3, 6, 0, 'published', 9, 457, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_1', 'bok_seven-seeds-for-grandmother', 1, 'seeds-1', 'Grandmother gave Dita a small paper packet. Inside were seven sunflower seeds — flat, striped, and light as buttons. "Count them," said Grandmother. So Dita did. One, two, three, four, five, six, seven.', 'Nenek memberi Dita sebuah bungkus kertas kecil. Di dalamnya ada tujuh benih bunga matahari — pipih, bergaris, dan seringan kancing. "Hitunglah," kata Nenek. Maka Dita menghitung. Satu, dua, tiga, empat, lima, enam, tujuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_2', 'bok_seven-seeds-for-grandmother', 2, 'seeds-2', 'Dita planted the first seed by the gate, so it could say hello to everyone who came. That left six seeds in the packet.', 'Dita menanam benih pertama di dekat gerbang, supaya ia bisa menyapa siapa pun yang datang. Tinggal enam benih di dalam bungkus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_3', 'bok_seven-seeds-for-grandmother', 3, 'seeds-3', 'She planted the second and third seeds side by side under the window, so they would grow up together like sisters. Five seeds left.', 'Ia menanam benih kedua dan ketiga berdampingan di bawah jendela, supaya keduanya tumbuh bersama seperti kakak beradik. Tinggal lima benih.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_4', 'bok_seven-seeds-for-grandmother', 4, 'seeds-4', 'The fourth seed went to her neighbour Bayu, who had no garden at all, only a blue pot on a step. Four seeds left, and Bayu grinning at his pot.', 'Benih keempat diberikan kepada tetangganya, Bayu, yang tidak punya kebun sama sekali, hanya sebuah pot biru di anak tangga. Tinggal empat benih, dan Bayu tersenyum lebar menatap potnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_5', 'bok_seven-seeds-for-grandmother', 5, 'seeds-5', 'The fifth and sixth seeds she pressed into the earth behind the kitchen, where the afternoon sun stayed longest. Two seeds left, rattling in the packet.', 'Benih kelima dan keenam ia tekan ke dalam tanah di belakang dapur, tempat matahari sore bertahan paling lama. Tinggal dua benih, bergemerincing di dalam bungkus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_6', 'bok_seven-seeds-for-grandmother', 6, 'seeds-6', 'Dita held the last two in her palm and thought for a long time. Then she planted one — and kept one. "For next year," she told herself. "So there is always a beginning left over."', 'Dita menggenggam dua benih terakhir di telapak tangannya dan berpikir lama. Lalu ia menanam satu — dan menyimpan satu. "Untuk tahun depan," katanya pada diri sendiri. "Supaya selalu ada permulaan yang tersisa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_7', 'bok_seven-seeds-for-grandmother', 7, 'seeds-7', 'Then came the hardest part: waiting. Nothing happened on Monday. Nothing happened on Tuesday. Dita checked every single morning, and the soil stayed brown and quiet.', 'Lalu tibalah bagian tersulit: menunggu. Tidak ada apa-apa pada Senin. Tidak ada apa-apa pada Selasa. Dita memeriksa setiap pagi, dan tanah tetap cokelat dan diam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_8', 'bok_seven-seeds-for-grandmother', 8, 'seeds-8', 'On the ninth morning, one green loop pushed up by the gate. By the end of the month there were six green stems, and on Bayu''s blue step, a seventh reaching for the light.', 'Pada pagi kesembilan, satu lengkungan hijau menyembul di dekat gerbang. Menjelang akhir bulan ada enam batang hijau, dan di anak tangga biru milik Bayu, batang ketujuh menjulur ke arah cahaya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_seven-seeds-for-grandmother_9', 'bok_seven-seeds-for-grandmother', 9, 'seeds-9', 'In summer they stood taller than Dita, taller than Grandmother, six golden faces turning slowly through the day. And in Dita''s pocket, wrapped in paper, one seed waited quietly for next year.', 'Di musim panas mereka berdiri lebih tinggi dari Dita, lebih tinggi dari Nenek, enam wajah keemasan yang berputar perlahan sepanjang hari. Dan di saku Dita, terbungkus kertas, satu benih menunggu dengan tenang untuk tahun depan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_seven-seeds-for-grandmother_1', 'bok_seven-seeds-for-grandmother', 1, 'How many seeds did Grandmother give Dita?', 'Berapa benih yang Nenek berikan kepada Dita?', '["Five","Six","Seven","Ten"]', '["Lima","Enam","Tujuh","Sepuluh"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_seven-seeds-for-grandmother_2', 'bok_seven-seeds-for-grandmother', 2, 'Who did Dita give one seed to?', 'Kepada siapa Dita memberikan satu benih?', '["Her teacher","Her neighbour Bayu","Her cat","Nobody"]', '["Gurunya","Tetangganya, Bayu","Kucingnya","Tidak ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_seven-seeds-for-grandmother_3', 'bok_seven-seeds-for-grandmother', 3, 'Why did Dita keep the very last seed?', 'Mengapa Dita menyimpan benih yang terakhir?', '["She forgot to plant it","To save a beginning for next year","She dropped it","She did not like it"]', '["Ia lupa menanamnya","Untuk menyimpan permulaan bagi tahun depan","Ia menjatuhkannya","Ia tidak menyukainya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-bus-that-was-always-late', 'the-bus-that-was-always-late', 'The Bus That Was Always Late', 'Bus yang Selalu Terlambat', 'Number 12 is the slowest bus in the city, and everybody complains — until the morning they find out why.', 'Bus Nomor 12 adalah bus paling lambat di kota, dan semua orang mengeluh — sampai suatu pagi mereka tahu alasannya.', 'cat_vehicles', 'aut_axto-creative-team', 'citrus', '🚌', 4, 8, 0, 'published', 9, 3939, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_1', 'bok_the-bus-that-was-always-late', 1, 'bus12-1', 'Every bus in the city had a number, and every number had a reputation. Number 3 was fast. Number 8 was clean. And Number 12 was always, always late.', 'Setiap bus di kota punya nomor, dan setiap nomor punya nama baik atau buruk. Nomor 3 cepat. Nomor 8 bersih. Dan Nomor 12 selalu, selalu terlambat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_2', 'bok_the-bus-that-was-always-late', 2, 'bus12-2', '"Four minutes behind," people muttered at the stop by the market. "Six minutes," they said at the school gates. Number 12 never argued. He just opened his doors and said good morning.', '"Terlambat empat menit," gerutu orang-orang di halte dekat pasar. "Enam menit," kata mereka di gerbang sekolah. Nomor 12 tidak pernah membantah. Ia hanya membuka pintunya dan mengucapkan selamat pagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_3', 'bok_the-bus-that-was-always-late', 3, 'bus12-3', 'One rainy Thursday, a girl named Sari decided to find out why. She got on at the very first stop, sat at the very front, and watched the whole route from beginning to end.', 'Pada suatu Kamis yang hujan, seorang gadis bernama Sari memutuskan mencari tahu sebabnya. Ia naik di halte paling pertama, duduk paling depan, dan mengamati seluruh rute dari awal sampai akhir.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_4', 'bok_the-bus-that-was-always-late', 4, 'bus12-4', 'At the third stop, Number 12 waited while old Pak Harun folded his umbrella and climbed the step, one hand on the rail. That took a while. Nobody hurried him.', 'Di halte ketiga, Nomor 12 menunggu sementara Pak Harun yang sudah tua melipat payungnya dan menaiki tangga, satu tangan memegang pegangan. Itu memakan waktu. Tidak ada yang menyuruhnya cepat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_5', 'bok_the-bus-that-was-always-late', 5, 'bus12-5', 'At the seventh stop, he waited for a mother with a stroller and a bag of shopping, and then he knelt down — the whole front of him tilting toward the kerb — so she would not have to lift anything.', 'Di halte ketujuh, ia menunggu seorang ibu dengan kereta bayi dan tas belanjaan, lalu ia merunduk — seluruh bagian depannya miring ke arah trotoar — supaya ibu itu tidak perlu mengangkat apa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_6', 'bok_the-bus-that-was-always-late', 6, 'bus12-6', 'At the eleventh stop, a boy came running down the hill, one shoe untied, waving. Number 12 had already closed his doors. He opened them again.', 'Di halte kesebelas, seorang anak lelaki berlari menuruni bukit, satu talinya lepas, sambil melambai. Nomor 12 sudah menutup pintunya. Ia membukanya lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_7', 'bok_the-bus-that-was-always-late', 7, 'bus12-7', 'Sari counted it all up in her notebook. Four minutes here, six there. Every single minute belonged to somebody. Not one of them had been wasted.', 'Sari menghitung semuanya di buku catatannya. Empat menit di sini, enam menit di sana. Setiap menit adalah milik seseorang. Tidak satu pun yang terbuang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_8', 'bok_the-bus-that-was-always-late', 8, 'bus12-8', 'The next morning, Sari pinned a paper to the shelter by the market. It said: THE NUMBER 12 IS LATE BECAUSE HE WAITS FOR US. And underneath, in smaller letters: THANK YOU.', 'Pagi berikutnya, Sari menempelkan selembar kertas di halte dekat pasar. Isinya: NOMOR 12 TERLAMBAT KARENA IA MENUNGGU KITA. Dan di bawahnya, dengan huruf lebih kecil: TERIMA KASIH.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-bus-that-was-always-late_9', 'bok_the-bus-that-was-always-late', 9, 'bus12-9', 'People still checked their watches at the stop by the market. But now, when the old blue bus came round the corner four minutes behind, somebody usually smiled.', 'Orang-orang masih melihat jam tangan mereka di halte dekat pasar. Tetapi kini, ketika bus biru tua itu membelok terlambat empat menit, biasanya ada yang tersenyum.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bus-that-was-always-late_1', 'bok_the-bus-that-was-always-late', 1, 'What was Number 12 known for?', 'Nomor 12 terkenal karena apa?', '["Being the fastest","Being always late","Being the cleanest","Being the newest"]', '["Paling cepat","Selalu terlambat","Paling bersih","Paling baru"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bus-that-was-always-late_2', 'bok_the-bus-that-was-always-late', 2, 'Why was the bus late?', 'Mengapa bus itu terlambat?', '["He was broken","He waited for people who needed time","He took the wrong road","He stopped for lunch"]', '["Ia rusak","Ia menunggu orang-orang yang butuh waktu","Ia salah jalan","Ia berhenti untuk makan siang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-bus-that-was-always-late_3', 'bok_the-bus-that-was-always-late', 3, 'What did Sari put up at the bus shelter?', 'Apa yang Sari tempelkan di halte?', '["A complaint","A note explaining and thanking him","A timetable","A drawing of herself"]', '["Surat keluhan","Catatan penjelasan dan ucapan terima kasih","Jadwal","Gambar dirinya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_pip-the-robot-who-could-not-hurry', 'pip-the-robot-who-could-not-hurry', 'Pip, the Robot Who Could Not Hurry', 'Pip, Robot yang Tak Bisa Terburu-buru', 'Every robot in the workshop is built for speed except Pip, who does one thing at a time — until the day speed is not what is needed.', 'Setiap robot di bengkel dirancang untuk cepat, kecuali Pip, yang mengerjakan satu hal pada satu waktu — sampai tiba hari ketika kecepatan bukanlah yang dibutuhkan.', 'cat_robots-tech', 'aut_axto-creative-team', 'twilight', '🤖', 5, 9, 0, 'published', 9, 2689, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_1', 'bok_pip-the-robot-who-could-not-hurry', 1, 'pip-1', 'In a workshop at the edge of the city, seven robots worked all day. Six of them were fast. Zeta could sort a thousand bolts in a minute. Orin could paint a whole wall before lunch.', 'Di sebuah bengkel di pinggir kota, tujuh robot bekerja sepanjang hari. Enam di antaranya cepat. Zeta bisa memilah seribu baut dalam semenit. Orin bisa mengecat seluruh dinding sebelum makan siang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_2', 'bok_pip-the-robot-who-could-not-hurry', 2, 'pip-2', 'And then there was Pip. Pip was small and round and moved as if he were thinking about each step. One bolt. Then the next bolt. Then the one after that.', 'Lalu ada Pip. Pip kecil dan bulat, dan bergerak seolah-olah memikirkan setiap langkahnya. Satu baut. Lalu baut berikutnya. Lalu yang setelah itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_3', 'bok_pip-the-robot-who-could-not-hurry', 3, 'pip-3', '"You are too slow," the other robots beeped, not unkindly. "We finish before you have started." Pip did not argue. He picked up the next bolt and turned it over in his little claw.', '"Kau terlalu lambat," bunyi robot-robot lain, tanpa maksud jahat. "Kami sudah selesai sebelum kau mulai." Pip tidak membantah. Ia mengambil baut berikutnya dan membolak-baliknya dengan capit kecilnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_4', 'bok_pip-the-robot-who-could-not-hurry', 4, 'pip-4', 'One winter morning, the workshop''s oldest machine stopped. It was the great weaving loom, the one that made the blankets for the whole town, and inside it something had come loose.', 'Pada suatu pagi musim dingin, mesin tertua di bengkel itu berhenti. Itu adalah alat tenun besar, yang membuat selimut untuk seluruh kota, dan di dalamnya ada sesuatu yang lepas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_5', 'bok_pip-the-robot-who-could-not-hurry', 5, 'pip-5', 'Zeta went in first and came out in four seconds. "Too many threads," she said. Orin tried and came out faster still. "Can''t see. Can''t reach. Can''t tell what''s broken."', 'Zeta masuk lebih dulu dan keluar dalam empat detik. "Terlalu banyak benang," katanya. Orin mencoba dan keluar lebih cepat lagi. "Tidak terlihat. Tidak terjangkau. Tidak jelas apa yang rusak."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_6', 'bok_pip-the-robot-who-could-not-hurry', 6, 'pip-6', 'Pip went in last. He did not rush. He followed one thread with his light, all the way from the top to the bottom. Then the second thread. Then the third.', 'Pip masuk paling akhir. Ia tidak tergesa. Ia menyusuri satu benang dengan lampunya, dari ujung atas sampai ujung bawah. Lalu benang kedua. Lalu ketiga.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_7', 'bok_pip-the-robot-who-could-not-hurry', 7, 'pip-7', 'It took him until the light outside went orange. But on the four hundred and sixth thread, he found it — a tiny cracked hook, no bigger than a grain of rice, holding everything still.', 'Waktunya sampai cahaya di luar berubah jingga. Namun pada benang keempat ratus enam, ia menemukannya — sebuah kait kecil yang retak, tak lebih besar dari sebutir beras, yang menahan semuanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_8', 'bok_pip-the-robot-who-could-not-hurry', 8, 'pip-8', 'Pip lifted the broken hook out and set a new one in. The loom shuddered, hummed, and began to weave. Outside, the six fast robots were quiet.', 'Pip mengangkat kait yang patah dan memasang yang baru. Alat tenun itu bergetar, berdengung, dan mulai menenun. Di luar, enam robot cepat itu terdiam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_pip-the-robot-who-could-not-hurry_9', 'bok_pip-the-robot-who-could-not-hurry', 9, 'pip-9', 'After that, nobody in the workshop said Pip was too slow. They said Pip was careful. And when something small and important went wrong, they knew exactly who to ask.', 'Sejak itu, tidak ada lagi yang mengatakan Pip terlalu lambat. Mereka mengatakan Pip teliti. Dan ketika ada sesuatu yang kecil namun penting rusak, mereka tahu persis siapa yang harus diminta bantuan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_pip-the-robot-who-could-not-hurry_1', 'bok_pip-the-robot-who-could-not-hurry', 1, 'What made Pip different from the other robots?', 'Apa yang membuat Pip berbeda dari robot lain?', '["He was the biggest","He worked slowly and carefully","He never worked","He was the newest"]', '["Ia paling besar","Ia bekerja lambat dan teliti","Ia tidak pernah bekerja","Ia paling baru"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_pip-the-robot-who-could-not-hurry_2', 'bok_pip-the-robot-who-could-not-hurry', 2, 'What was broken inside the loom?', 'Apa yang rusak di dalam alat tenun?', '["A large wheel","A tiny cracked hook","The roof","A whole engine"]', '["Roda besar","Kait kecil yang retak","Atapnya","Seluruh mesin"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_pip-the-robot-who-could-not-hurry_3', 'bok_pip-the-robot-who-could-not-hurry', 3, 'What did the other robots learn about Pip?', 'Apa yang dipelajari robot lain tentang Pip?', '["That he was too slow","That being careful is its own kind of skill","That he should work faster","That he was broken"]', '["Bahwa ia terlalu lambat","Bahwa teliti juga sebuah keahlian","Bahwa ia harus lebih cepat","Bahwa ia rusak"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-night-the-lights-stayed-on', 'the-night-the-lights-stayed-on', 'The Night the Lights Stayed On', 'Malam Ketika Lampu Tetap Menyala', 'A storm knocks out the power on the busiest street in town, and a small girl discovers how many people quietly keep a city running.', 'Badai memadamkan listrik di jalan tersibuk di kota, dan seorang gadis kecil menemukan betapa banyak orang yang diam-diam menjaga kota tetap berjalan.', 'cat_community-helpers', 'aut_axto-creative-team', 'twilight', '👩‍🚒', 5, 9, 0, 'published', 9, 1529, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_1', 'bok_the-night-the-lights-stayed-on', 1, 'lights-1', 'The storm came in fast, the way storms do. First the wind. Then the rain, sideways against the windows. And then, all at once, every light on Melati Street went out.', 'Badai datang cepat, seperti biasanya badai datang. Mula-mula angin. Lalu hujan, menyamping menerpa jendela. Dan kemudian, sekaligus, setiap lampu di Jalan Melati padam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_2', 'bok_the-night-the-lights-stayed-on', 2, 'lights-2', 'Nadia stood at the window with a candle. Below, the street was dark except for one thing: the hospital at the end of the road, still glowing, every window bright.', 'Nadia berdiri di jendela dengan sebatang lilin. Di bawah, jalanan gelap kecuali satu hal: rumah sakit di ujung jalan, masih bercahaya, setiap jendelanya terang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_3', 'bok_the-night-the-lights-stayed-on', 3, 'lights-3', '"How is it still on?" she asked. Her father pointed. "Look properly," he said. And Nadia saw a small figure in a yellow coat, standing in the rain beside a humming grey box.', '"Kenapa masih menyala?" tanyanya. Ayahnya menunjuk. "Lihat baik-baik," katanya. Dan Nadia melihat sesosok kecil bermantel kuning, berdiri di tengah hujan di samping kotak abu-abu yang berdengung.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_4', 'bok_the-night-the-lights-stayed-on', 4, 'lights-4', 'That was Bu Rina, the engineer. She had left her dinner on the table and driven out in the dark to start the backup generator, and she would stand there until the power came back.', 'Itu Bu Rina, sang teknisi. Ia meninggalkan makan malamnya di meja dan berkendara dalam gelap untuk menyalakan genset cadangan, dan ia akan berdiri di sana sampai listrik kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_5', 'bok_the-night-the-lights-stayed-on', 5, 'lights-5', 'Down at the corner, two firefighters were dragging a fallen branch off the road so the ambulances could pass. One of them was singing, very badly, to keep the other one laughing.', 'Di ujung jalan, dua petugas pemadam kebakaran menyeret dahan tumbang dari jalan supaya ambulans bisa lewat. Salah satunya bernyanyi, sangat sumbang, agar temannya tetap tertawa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_6', 'bok_the-night-the-lights-stayed-on', 6, 'lights-6', 'In the little shop below, Pak Umar had opened his door and set out a box of candles. "Take what you need," said the sign. "Pay me on Friday." People came and went all evening.', 'Di toko kecil di bawah, Pak Umar membuka pintunya dan meletakkan sekotak lilin. "Ambil seperlunya," tulis papannya. "Bayar hari Jumat." Orang-orang datang dan pergi sepanjang malam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_7', 'bok_the-night-the-lights-stayed-on', 7, 'lights-7', 'And on the third floor, Bu Sari the teacher went door to door with a torch, knocking gently, checking that everyone who lived alone had water, a light, and somebody who knew where they were.', 'Dan di lantai tiga, Bu Sari sang guru berkeliling dari pintu ke pintu dengan senter, mengetuk pelan, memastikan setiap orang yang tinggal sendirian punya air, penerangan, dan seseorang yang tahu keberadaannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_8', 'bok_the-night-the-lights-stayed-on', 8, 'lights-8', 'At half past two in the morning, the streetlights flickered and came back on all together. Nadia was still awake. She watched Bu Rina climb into her van, soaked through, and drive home.', 'Pukul setengah tiga dini hari, lampu jalan berkedip dan menyala kembali serentak. Nadia masih terjaga. Ia melihat Bu Rina naik ke mobilnya, basah kuyup, lalu pulang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-night-the-lights-stayed-on_9', 'bok_the-night-the-lights-stayed-on', 9, 'lights-9', 'The next day the street looked ordinary again. But Nadia knew something new about it now. A city does not run by itself. It runs because, in the dark, people go outside.', 'Keesokan harinya jalan itu tampak biasa lagi. Tetapi kini Nadia tahu sesuatu yang baru. Sebuah kota tidak berjalan dengan sendirinya. Ia berjalan karena, dalam kegelapan, ada orang-orang yang keluar rumah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-night-the-lights-stayed-on_1', 'bok_the-night-the-lights-stayed-on', 1, 'Why did the hospital still have lights?', 'Mengapa rumah sakit masih punya penerangan?', '["It had its own sun","An engineer started the backup generator","It was not in the storm","The lights never go out there"]', '["Ia punya matahari sendiri","Seorang teknisi menyalakan genset cadangan","Ia tidak terkena badai","Lampunya tidak pernah padam"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-night-the-lights-stayed-on_2', 'bok_the-night-the-lights-stayed-on', 2, 'What did Pak Umar do with his candles?', 'Apa yang Pak Umar lakukan dengan lilin-lilinnya?', '["Sold them at a high price","Let people take what they needed and pay later","Kept them for himself","Threw them away"]', '["Menjualnya dengan harga tinggi","Membiarkan orang mengambil seperlunya dan membayar nanti","Menyimpannya sendiri","Membuangnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-night-the-lights-stayed-on_3', 'bok_the-night-the-lights-stayed-on', 3, 'What did Nadia understand by the end?', 'Apa yang Nadia pahami di akhir cerita?', '["Storms are fun","A city keeps running because people go out and help","Lights fix themselves","She should stay awake every night"]', '["Badai itu menyenangkan","Kota tetap berjalan karena ada orang yang keluar dan menolong","Lampu memperbaiki dirinya sendiri","Ia harus begadang setiap malam"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_four-seasons-in-one-garden', 'four-seasons-in-one-garden', 'Four Seasons in One Garden', 'Empat Musim dalam Satu Kebun', 'An old apple tree tells a boy what she does all year — and why the empty months matter as much as the full ones.', 'Sebatang pohon apel tua bercerita kepada seorang anak tentang apa yang ia lakukan sepanjang tahun — dan mengapa bulan-bulan yang kosong sama pentingnya dengan yang penuh.', 'cat_weather-seasons', 'aut_axto-creative-team', 'meadow', '🌦️', 4, 8, 0, 'published', 9, 4243, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_1', 'bok_four-seasons-in-one-garden', 1, 'seasons-1', 'In the corner of the garden stood an apple tree so old that nobody remembered planting her. Arif liked to sit against her trunk and talk, and sometimes it seemed as though she answered.', 'Di sudut kebun berdiri sebatang pohon apel yang begitu tua sampai tidak ada yang ingat siapa menanamnya. Arif suka duduk bersandar di batangnya sambil berbicara, dan kadang seolah-olah pohon itu menjawab.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_2', 'bok_four-seasons-in-one-garden', 2, 'seasons-2', 'In spring she was covered in white blossom, so thick that the bees came from three gardens away. "This is the loud part," she said. "Everybody likes me in spring."', 'Di musim semi ia dipenuhi bunga putih, begitu lebat sampai lebah datang dari tiga kebun jauhnya. "Ini bagian yang ramai," katanya. "Semua orang menyukaiku di musim semi."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_3', 'bok_four-seasons-in-one-garden', 3, 'seasons-3', 'In summer the blossom fell and small hard green knots appeared where each flower had been. "Nothing to see," said Arif, disappointed. "Everything to do," said the tree.', 'Di musim panas bunga berguguran dan muncul bulatan hijau kecil dan keras di tempat setiap bunga tadi berada. "Tidak ada yang bisa dilihat," kata Arif, kecewa. "Justru banyak yang sedang dikerjakan," kata pohon itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_4', 'bok_four-seasons-in-one-garden', 4, 'seasons-4', 'All through the hot months she drank from deep down and pushed sweetness up into every green knot, slowly, without any fuss at all. Arif went to the sea and came back taller.', 'Sepanjang bulan-bulan panas ia minum dari kedalaman tanah dan mendorong rasa manis ke setiap bulatan hijau, perlahan, tanpa keributan sedikit pun. Arif pergi ke laut dan pulang dengan badan lebih tinggi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_5', 'bok_four-seasons-in-one-garden', 5, 'seasons-5', 'In autumn the apples came down. Red ones, yellow ones, some with a bruise on one side. The whole family carried baskets, and the kitchen smelled of them for weeks.', 'Di musim gugur apel-apel berjatuhan. Ada yang merah, ada yang kuning, ada yang memar di satu sisi. Seluruh keluarga membawa keranjang, dan dapur berbau apel selama berminggu-minggu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_6', 'bok_four-seasons-in-one-garden', 6, 'seasons-6', 'Then the leaves turned and let go, one at a time, until the tree stood dark and bare against a grey sky. Arif looked up at her and felt sad. "Are you finished?" he asked.', 'Lalu daun-daun berubah warna dan berlepasan, satu per satu, sampai pohon itu berdiri gelap dan gundul di bawah langit kelabu. Arif menengadah dan merasa sedih. "Apakah kau sudah selesai?" tanyanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_7', 'bok_four-seasons-in-one-garden', 7, 'seasons-7', '"I am resting," she said. "Under the ground I am still working, but slowly, in the dark, where nobody claps. If I did not have winter, I could not have spring."', '"Aku sedang beristirahat," katanya. "Di bawah tanah aku masih bekerja, tetapi perlahan, dalam gelap, tempat tak seorang pun bertepuk tangan. Jika aku tidak punya musim dingin, aku tidak akan punya musim semi."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_8', 'bok_four-seasons-in-one-garden', 8, 'seasons-8', 'Arif thought about that all winter. He thought about it on the days he was tired, and on the days when nothing he did seemed to show, and it made him feel a little better.', 'Arif memikirkan itu sepanjang musim dingin. Ia memikirkannya pada hari-hari ketika ia lelah, dan pada hari-hari ketika apa pun yang ia kerjakan tampak tidak membuahkan hasil, dan itu membuatnya sedikit lebih tenang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_four-seasons-in-one-garden_9', 'bok_four-seasons-in-one-garden', 9, 'seasons-9', 'In March, one morning, he found a single white bud on the lowest branch. He did not tell anybody for three days. He just came out each morning to look at it.', 'Pada bulan Maret, suatu pagi, ia menemukan satu kuncup putih di dahan terbawah. Ia tidak memberi tahu siapa pun selama tiga hari. Ia hanya keluar setiap pagi untuk memandanginya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_four-seasons-in-one-garden_1', 'bok_four-seasons-in-one-garden', 1, 'What did the tree say she was doing in summer?', 'Apa yang dikatakan pohon sedang ia lakukan di musim panas?', '["Nothing at all","Pushing sweetness into the small green apples","Sleeping","Growing new leaves only"]', '["Tidak melakukan apa-apa","Mendorong rasa manis ke apel hijau kecil","Tidur","Hanya menumbuhkan daun baru"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_four-seasons-in-one-garden_2', 'bok_four-seasons-in-one-garden', 2, 'Why does the tree need winter?', 'Mengapa pohon itu membutuhkan musim dingin?', '["To hide from people","Because resting is what makes spring possible","Because she dislikes apples","She does not need it"]', '["Untuk bersembunyi dari orang","Karena istirahat itulah yang memungkinkan musim semi","Karena ia tidak suka apel","Ia tidak membutuhkannya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_four-seasons-in-one-garden_3', 'bok_four-seasons-in-one-garden', 3, 'What did Arif find in March?', 'Apa yang Arif temukan pada bulan Maret?', '["A ripe apple","A single white bud","A bird''s nest","A fallen branch"]', '["Apel matang","Satu kuncup putih","Sarang burung","Dahan tumbang"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-boy-who-forgot-to-breathe', 'the-boy-who-forgot-to-breathe', 'The Boy Who Forgot to Breathe', 'Anak yang Lupa Bernapas', 'Before every race, Ravi''s chest goes tight and fast. His grandfather teaches him the oldest trick there is for getting it back.', 'Sebelum setiap lomba, dada Ravi terasa sesak dan berdebar. Kakeknya mengajarkan cara paling tua untuk menenangkannya kembali.', 'cat_health-body', 'aut_axto-creative-team', 'ocean', '🫁', 5, 9, 0, 'published', 9, 4067, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_1', 'bok_the-boy-who-forgot-to-breathe', 1, 'breathe-1', 'Ravi could run. Everybody said so. But on the morning of a race, something happened that he could not explain: his chest went tight, his hands went cold, and his breath came in small quick sips.', 'Ravi bisa berlari. Semua orang mengatakannya. Tetapi pada pagi hari lomba, ada sesuatu yang tidak bisa ia jelaskan: dadanya terasa sesak, tangannya dingin, dan napasnya datang pendek-pendek dan cepat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_2', 'bok_the-boy-who-forgot-to-breathe', 2, 'breathe-2', '"You are breathing like a rabbit," said his grandfather, watching him at the kitchen table. "Little sips at the top. Nothing reaching the bottom."', '"Kau bernapas seperti kelinci," kata kakeknya, memperhatikannya di meja dapur. "Tegukan kecil di bagian atas. Tidak ada yang sampai ke bawah."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_3', 'bok_the-boy-who-forgot-to-breathe', 3, 'breathe-3', 'Grandfather put one of Ravi''s hands on his own chest and one on his belly. "Now," he said. "Which hand is moving?" Ravi felt. Only the top one. The belly hand was still.', 'Kakek meletakkan satu tangan Ravi di dadanya sendiri dan satu di perutnya. "Sekarang," katanya. "Tangan mana yang bergerak?" Ravi merasakannya. Hanya yang atas. Tangan di perut diam saja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_4', 'bok_the-boy-who-forgot-to-breathe', 4, 'breathe-4', '"Your lungs go all the way down here," said Grandfather, tapping the low hand. "When you are frightened you forget the bottom half. So we are going to remember it."', '"Paru-parumu sampai ke bawah sini," kata Kakek sambil menepuk tangan yang bawah. "Saat kau takut, kau lupa separuh bagian bawahnya. Jadi kita akan mengingatnya kembali."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_5', 'bok_the-boy-who-forgot-to-breathe', 5, 'breathe-5', 'They practised on the step outside. In through the nose while counting to four. Hold, gently, for four. Out through the mouth, slowly, for six — longer going out than coming in.', 'Mereka berlatih di anak tangga depan rumah. Tarik lewat hidung sambil menghitung sampai empat. Tahan, pelan-pelan, empat hitungan. Buang lewat mulut, perlahan, enam hitungan — lebih lama keluar daripada masuk.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_6', 'bok_the-boy-who-forgot-to-breathe', 6, 'breathe-6', 'The first time, Ravi felt silly. The second time, he noticed his shoulders had come down. The fourth time, the belly hand moved, and something in his chest let go.', 'Pertama kali, Ravi merasa konyol. Kedua kali, ia menyadari bahunya sudah turun. Keempat kali, tangan di perut ikut bergerak, dan ada sesuatu di dadanya yang mengendur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_7', 'bok_the-boy-who-forgot-to-breathe', 7, 'breathe-7', '"It is not magic," Grandfather said. "A long breath out tells your body the danger has passed. Your body believes your breathing before it believes your thinking."', '"Ini bukan sihir," kata Kakek. "Napas panjang yang dikeluarkan memberi tahu tubuhmu bahwa bahaya sudah lewat. Tubuhmu lebih percaya napasmu daripada pikiranmu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_8', 'bok_the-boy-who-forgot-to-breathe', 8, 'breathe-8', 'On Saturday, at the line, Ravi''s hands went cold as usual. He put one on his belly where nobody could see. In for four. Hold. Out for six. And again.', 'Pada hari Sabtu, di garis start, tangan Ravi dingin seperti biasa. Ia meletakkan satu tangan di perutnya, tempat tak seorang pun melihat. Masuk empat hitungan. Tahan. Keluar enam hitungan. Dan sekali lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-forgot-to-breathe_9', 'bok_the-boy-who-forgot-to-breathe', 9, 'breathe-9', 'He came third. He was not sure whether the breathing made him faster. But he knew it made the waiting bearable, and that was the part he had been dreading all along.', 'Ia finis di urutan ketiga. Ia tidak yakin apakah latihan napas itu membuatnya lebih cepat. Tetapi ia tahu itu membuat masa menunggu jadi tertahankan, dan bagian itulah yang selama ini paling ia takuti.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-forgot-to-breathe_1', 'bok_the-boy-who-forgot-to-breathe', 1, 'What happened to Ravi before a race?', 'Apa yang terjadi pada Ravi sebelum lomba?', '["He felt sleepy","His chest went tight and his breath went short","He got hungry","He forgot the way"]', '["Ia mengantuk","Dadanya sesak dan napasnya pendek","Ia lapar","Ia lupa jalan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-forgot-to-breathe_2', 'bok_the-boy-who-forgot-to-breathe', 2, 'What did Grandfather teach him to do?', 'Apa yang Kakek ajarkan kepadanya?', '["Run faster","Breathe in for four and out for six","Skip the race","Hold his breath"]', '["Berlari lebih cepat","Menarik napas empat hitungan dan mengeluarkan enam hitungan","Membolos lomba","Menahan napas"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-forgot-to-breathe_3', 'bok_the-boy-who-forgot-to-breathe', 3, 'Why does a long breath out help?', 'Mengapa napas panjang yang dikeluarkan itu membantu?', '["It makes you taller","It tells the body the danger has passed","It makes noise","It uses less air"]', '["Membuat kita lebih tinggi","Memberi tahu tubuh bahwa bahaya sudah lewat","Menimbulkan suara","Menghemat udara"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-song-with-no-words', 'the-song-with-no-words', 'The Song With No Words', 'Lagu Tanpa Kata', 'A new girl at school speaks a language nobody else does — until somebody hands her a drum.', 'Seorang murid baru di sekolah berbicara dalam bahasa yang tak seorang pun mengerti — sampai seseorang memberinya sebuah gendang.', 'cat_music-rhymes', 'aut_axto-creative-team', 'citrus', '🥁', 5, 9, 0, 'published', 9, 741, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_1', 'bok_the-song-with-no-words', 1, 'song-1', 'Amara arrived at the school in the middle of term, which is the hardest time to arrive. She had a red bag, careful eyes, and not one word of the language everybody else was speaking.', 'Amara tiba di sekolah di tengah semester, waktu yang paling sulit untuk datang. Ia membawa tas merah, bermata hati-hati, dan tidak menguasai satu kata pun bahasa yang dipakai semua orang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_2', 'bok_the-song-with-no-words', 2, 'song-2', 'For two weeks she said almost nothing. She smiled when people smiled. She followed where people went. At break she sat by the wall and watched the games she did not know the rules of.', 'Selama dua minggu ia hampir tidak berbicara. Ia tersenyum ketika orang tersenyum. Ia mengikuti ke mana orang pergi. Saat istirahat ia duduk di dekat tembok dan menonton permainan yang aturannya tidak ia ketahui.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_3', 'bok_the-song-with-no-words', 3, 'song-3', 'On a Thursday, the music room door was open. Inside there were shakers, a xylophone, and an old drum with a cracked rim that nobody chose because it looked broken.', 'Pada suatu Kamis, pintu ruang musik terbuka. Di dalamnya ada marakas, xilofon, dan sebuah gendang tua dengan bibir retak yang tidak dipilih siapa pun karena terlihat rusak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_4', 'bok_the-song-with-no-words', 4, 'song-4', 'Amara picked up the drum. She turned it over once. Then she began to play — not loudly, but with a pattern underneath it, a rhythm that went somewhere and came back.', 'Amara mengambil gendang itu. Ia membaliknya sekali. Lalu ia mulai memainkannya — tidak keras, tetapi dengan pola di dalamnya, irama yang pergi ke suatu tempat lalu kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_5', 'bok_the-song-with-no-words', 5, 'song-5', 'One by one, children stopped what they were doing and came to the doorway. Nobody asked her anything. They just listened, because for once there was nothing to translate.', 'Satu per satu, anak-anak berhenti dari kegiatan mereka dan datang ke ambang pintu. Tidak ada yang bertanya apa pun. Mereka hanya mendengarkan, karena untuk sekali ini tidak ada yang perlu diterjemahkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_6', 'bok_the-song-with-no-words', 6, 'song-6', 'When she finished, a boy called Tomas picked up two shakers and tried to copy the pattern. He got it wrong. Amara laughed out loud — the first sound anyone had heard from her — and showed him again.', 'Ketika ia selesai, seorang anak bernama Tomas mengambil dua marakas dan mencoba menirukan polanya. Ia salah. Amara tertawa lepas — suara pertama yang pernah didengar orang darinya — lalu menunjukkannya lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_7', 'bok_the-song-with-no-words', 7, 'song-7', 'By the end of break there were nine of them, banging and shaking and counting under their breath, and the pattern was going all the way round the room and back to Amara.', 'Menjelang akhir istirahat, ada sembilan anak, memukul dan mengocok dan menghitung dalam hati, dan pola itu berkeliling seluruh ruangan lalu kembali kepada Amara.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_8', 'bok_the-song-with-no-words', 8, 'song-8', 'She still could not ask for a pencil. She still went quiet when the teacher asked a question. But at break she was never by the wall again, and by December she was correcting Tomas in two languages.', 'Ia masih belum bisa meminta pensil. Ia masih terdiam ketika guru bertanya. Tetapi saat istirahat ia tidak pernah lagi duduk di dekat tembok, dan pada bulan Desember ia sudah membetulkan Tomas dalam dua bahasa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-song-with-no-words_9', 'bok_the-song-with-no-words', 9, 'song-9', 'Years later, when somebody asked Tomas how they had become friends, he had to think about it. "She didn''t tell me anything," he said at last. "She just played, and I heard her."', 'Bertahun-tahun kemudian, ketika seseorang bertanya kepada Tomas bagaimana mereka bisa berteman, ia harus berpikir sejenak. "Ia tidak mengatakan apa-apa," katanya akhirnya. "Ia hanya bermain, dan aku mendengarnya."');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-with-no-words_1', 'bok_the-song-with-no-words', 1, 'Why was it hard for Amara at first?', 'Mengapa awalnya sulit bagi Amara?', '["She was not allowed outside","She did not speak the language","She had no bag","She did not like school"]', '["Ia tidak boleh keluar","Ia tidak bisa berbahasa itu","Ia tidak punya tas","Ia tidak suka sekolah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-with-no-words_2', 'bok_the-song-with-no-words', 2, 'What did Amara find in the music room?', 'Apa yang Amara temukan di ruang musik?', '["A piano","An old drum with a cracked rim","A guitar","A flute"]', '["Piano","Gendang tua dengan bibir retak","Gitar","Seruling"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-song-with-no-words_3', 'bok_the-song-with-no-words', 3, 'What helped the children get to know her?', 'Apa yang membuat anak-anak mulai mengenalnya?', '["A test","Playing rhythm together","A teacher''s instruction","A letter"]', '["Ujian","Bermain irama bersama","Perintah guru","Sepucuk surat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-slowest-runner-on-the-team', 'the-slowest-runner-on-the-team', 'The Slowest Runner on the Team', 'Pelari Paling Lambat di Tim', 'Lina is last in every race she enters. So why does the coach put her name down for the relay?', 'Lina selalu finis terakhir di setiap lomba. Lalu mengapa pelatih menuliskan namanya untuk lomba estafet?', 'cat_sports', 'aut_axto-creative-team', 'meadow', '🏃', 6, 10, 0, 'published', 9, 594, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_1', 'bok_the-slowest-runner-on-the-team', 1, 'relay-1', 'Lina was the slowest runner on the team. This was not an opinion; it was a fact with a stopwatch behind it. She had finished last in the sixty metres four times in a row.', 'Lina adalah pelari paling lambat di tim. Itu bukan pendapat; itu fakta dengan stopwatch sebagai buktinya. Ia sudah finis terakhir di lari enam puluh meter empat kali berturut-turut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_2', 'bok_the-slowest-runner-on-the-team', 2, 'relay-2', 'So when the relay list went up on the board and her name was on it, she assumed it was a mistake. She stood in front of it for a long time, waiting for somebody to notice.', 'Maka ketika daftar estafet dipasang di papan dan namanya ada di sana, ia mengira itu keliru. Ia berdiri lama di depannya, menunggu ada yang menyadarinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_3', 'bok_the-slowest-runner-on-the-team', 3, 'relay-3', '"It is not a mistake," said Coach Devi, without looking up. "You are running second leg." Lina said, "But I am the slowest." Coach Devi said, "Yes. And you are the best at the handover."', '"Itu bukan keliru," kata Pelatih Devi tanpa mendongak. "Kau lari di kaki kedua." Lina berkata, "Tapi saya paling lambat." Pelatih Devi berkata, "Ya. Dan kau paling baik dalam serah terima tongkat."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_4', 'bok_the-slowest-runner-on-the-team', 4, 'relay-4', 'It was true, though Lina had never thought of it as a skill. She had spent weeks practising while the others raced: the reach, the flat palm, the not-looking-back, the timing of the first step.', 'Itu benar, meskipun Lina tidak pernah menganggapnya keahlian. Ia menghabiskan berminggu-minggu berlatih sementara yang lain berlomba: menjulurkan tangan, telapak yang rata, tidak menoleh ke belakang, dan waktu langkah pertama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_5', 'bok_the-slowest-runner-on-the-team', 5, 'relay-5', '"A relay is not four races," Coach Devi said. "It is three exchanges with running in between. You can gain more in a clean handover than a fast runner gains in ten metres."', '"Estafet bukan empat lomba," kata Pelatih Devi. "Itu tiga pergantian dengan lari di antaranya. Kau bisa mendapat lebih banyak dari serah terima yang bersih dibanding pelari cepat yang berlari sepuluh meter."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_6', 'bok_the-slowest-runner-on-the-team', 6, 'relay-6', 'On the day, the first leg went out and came back level with two other teams. Lina heard the footsteps behind her, put her hand back without turning, and felt the baton land exactly in her palm.', 'Pada hari lomba, pelari pertama berangkat dan kembali sejajar dengan dua tim lain. Lina mendengar langkah kaki di belakangnya, menjulurkan tangan ke belakang tanpa menoleh, dan merasakan tongkat mendarat tepat di telapaknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_7', 'bok_the-slowest-runner-on-the-team', 7, 'relay-7', 'She ran her leg slowly — everybody knew she would. Two teams passed her. But at the far end she put the baton into the third runner''s hand without either of them breaking stride, and the third runner was gone.', 'Ia berlari di bagiannya dengan lambat — semua orang tahu itu akan terjadi. Dua tim melewatinya. Tetapi di ujung sana ia memindahkan tongkat ke tangan pelari ketiga tanpa keduanya kehilangan langkah, dan pelari ketiga melesat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_8', 'bok_the-slowest-runner-on-the-team', 8, 'relay-8', 'The other two teams fumbled. One dropped the baton entirely; the other stopped, turned, and lost four seconds. Lina''s team came second, and the four of them stood together not quite believing it.', 'Dua tim lain kacau. Satu menjatuhkan tongkat sama sekali; yang lain berhenti, menoleh, dan kehilangan empat detik. Tim Lina finis kedua, dan mereka berempat berdiri bersama, hampir tidak percaya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-slowest-runner-on-the-team_9', 'bok_the-slowest-runner-on-the-team', 9, 'relay-9', 'Lina was still the slowest runner on the team. She was also, from that day, the one nobody wanted to run without. Both of those things were true, and only one of them had a stopwatch.', 'Lina tetap pelari paling lambat di tim. Ia juga, sejak hari itu, orang yang tak seorang pun mau berlari tanpanya. Kedua hal itu benar, dan hanya satu yang bisa diukur dengan stopwatch.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-slowest-runner-on-the-team_1', 'bok_the-slowest-runner-on-the-team', 1, 'Why did the coach pick Lina for the relay?', 'Mengapa pelatih memilih Lina untuk estafet?', '["By mistake","Because she was best at the baton handover","Because she was fastest","Because nobody else wanted to"]', '["Karena keliru","Karena ia paling baik dalam serah terima tongkat","Karena ia paling cepat","Karena tidak ada yang mau"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-slowest-runner-on-the-team_2', 'bok_the-slowest-runner-on-the-team', 2, 'What did the other teams do wrong?', 'Apa kesalahan tim-tim lain?', '["They ran too slowly","They fumbled and dropped the baton","They started early","They ran the wrong way"]', '["Mereka berlari terlalu lambat","Mereka gugup dan menjatuhkan tongkat","Mereka start terlalu awal","Mereka salah arah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-slowest-runner-on-the-team_3', 'bok_the-slowest-runner-on-the-team', 3, 'What is the lesson of the story?', 'Apa pelajaran dari cerita ini?', '["Only speed matters","A team needs different skills, not just the fastest one","Never run relays","Stopwatches measure everything"]', '["Hanya kecepatan yang penting","Tim butuh keahlian berbeda-beda, bukan hanya yang tercepat","Jangan pernah ikut estafet","Stopwatch mengukur segalanya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-dog-who-chose-us', 'the-dog-who-chose-us', 'The Dog Who Chose Us', 'Anjing yang Memilih Kami', 'The family went to the shelter to pick a puppy. A grey old dog with one ear had other ideas.', 'Keluarga itu datang ke penampungan untuk memilih anak anjing. Seekor anjing tua berbulu kelabu dengan satu telinga punya rencana lain.', 'cat_pets', 'aut_axto-creative-team', 'sunrise', '🐕', 4, 9, 0, 'published', 9, 5166, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_1', 'bok_the-dog-who-chose-us', 1, 'shelter-1', 'We went to the shelter on a Saturday to choose a puppy. That was the plan. A puppy: small, golden, bouncing, the sort of dog that is on the front of a calendar.', 'Kami pergi ke penampungan pada hari Sabtu untuk memilih anak anjing. Itu rencananya. Anak anjing: kecil, keemasan, lincah, jenis anjing yang ada di sampul kalender.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_2', 'bok_the-dog-who-chose-us', 2, 'shelter-2', 'There were six puppies, and they were exactly as advertised. They tumbled. They chewed shoelaces. My little brother lay on the floor and let them walk over his back.', 'Ada enam anak anjing, dan mereka persis seperti dijanjikan. Mereka berguling-guling. Mereka menggigit tali sepatu. Adikku berbaring di lantai dan membiarkan mereka berjalan di punggungnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_3', 'bok_the-dog-who-chose-us', 3, 'shelter-3', 'In the last pen, on his own, there was a grey dog with a white face and one ear that stood up while the other did not. The card on his gate said: BUDI. AGE 9. HERE 14 MONTHS.', 'Di kandang terakhir, seorang diri, ada seekor anjing kelabu berwajah putih dengan satu telinga berdiri sementara yang lain tidak. Kartu di gerbangnya bertuliskan: BUDI. UMUR 9. DI SINI 14 BULAN.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_4', 'bok_the-dog-who-chose-us', 4, 'shelter-4', '"Fourteen months," my mother said quietly. Budi did not jump up. He did not bark. He walked to the front of the pen, sat down, and looked at us the way you look at a bus you have missed before.', '"Empat belas bulan," kata ibuku pelan. Budi tidak melompat. Ia tidak menggonggong. Ia berjalan ke depan kandang, duduk, dan memandangi kami seperti orang memandangi bus yang pernah ia lewatkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_5', 'bok_the-dog-who-chose-us', 5, 'shelter-5', 'We went back to the puppies. We came back to Budi. We went back to the puppies again. And each time we returned, he was already sitting at the front, waiting, as if he had known.', 'Kami kembali ke anak-anak anjing. Kami kembali ke Budi. Kami kembali lagi ke anak-anak anjing. Dan setiap kali kami kembali, ia sudah duduk di depan, menunggu, seolah-olah ia sudah tahu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_6', 'bok_the-dog-who-chose-us', 6, 'shelter-6', '"He is nine," the man at the desk said, being honest. "He sleeps a great deal. He cannot do stairs quickly. He will not be with you as long as a puppy would."', '"Umurnya sembilan tahun," kata petugas di meja, dengan jujur. "Ia banyak tidur. Ia tidak bisa cepat menaiki tangga. Ia tidak akan bersama kalian selama anak anjing bisa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_7', 'bok_the-dog-who-chose-us', 7, 'shelter-7', 'My father was quiet for a moment. Then he said, "How long has anybody asked about him?" And the man at the desk looked down at his hands and said, "Not this year."', 'Ayahku terdiam sejenak. Lalu ia berkata, "Sudah berapa lama tidak ada yang menanyakannya?" Dan petugas itu menunduk menatap tangannya dan berkata, "Tahun ini belum ada."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_8', 'bok_the-dog-who-chose-us', 8, 'shelter-8', 'Budi came home in the back of the car with his chin on my knee. He slept for most of the first week. On the eighth day he brought a shoe to the kitchen and put it down, very seriously, as a gift.', 'Budi pulang di bagian belakang mobil dengan dagunya di lututku. Ia tidur hampir sepanjang minggu pertama. Pada hari kedelapan ia membawa sepatu ke dapur dan meletakkannya, dengan sangat serius, sebagai hadiah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-dog-who-chose-us_9', 'bok_the-dog-who-chose-us', 9, 'shelter-9', 'We had gone to choose a dog. We came back understanding that it had gone the other way round. Budi had sat down at the front of his pen and chosen us, and he had been right.', 'Kami datang untuk memilih anjing. Kami pulang dengan pemahaman bahwa yang terjadi justru sebaliknya. Budi duduk di depan kandangnya dan memilih kami, dan ternyata ia benar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-dog-who-chose-us_1', 'bok_the-dog-who-chose-us', 1, 'What had the family planned to get?', 'Apa yang keluarga itu rencanakan untuk dibawa pulang?', '["An old dog","A puppy","A cat","A bird"]', '["Anjing tua","Anak anjing","Kucing","Burung"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-dog-who-chose-us_2', 'bok_the-dog-who-chose-us', 2, 'How long had Budi been at the shelter?', 'Berapa lama Budi berada di penampungan?', '["Two weeks","Fourteen months","One day","Nine years"]', '["Dua minggu","Empat belas bulan","Satu hari","Sembilan tahun"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-dog-who-chose-us_3', 'bok_the-dog-who-chose-us', 3, 'What did the family realise at the end?', 'Apa yang keluarga itu sadari di akhir cerita?', '["They should have taken a puppy","That Budi had chosen them","That dogs are difficult","That they were too late"]', '["Mereka seharusnya mengambil anak anjing","Bahwa Budi yang memilih mereka","Bahwa anjing itu merepotkan","Bahwa mereka terlambat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-astronaut-who-was-afraid-of-the-dark', 'the-astronaut-who-was-afraid-of-the-dark', 'The Astronaut Who Was Afraid of the Dark', 'Astronaut yang Takut Gelap', 'Commander Zahra has flown further than anyone alive. She has also slept with a light on since she was six.', 'Komandan Zahra telah terbang lebih jauh dari siapa pun yang masih hidup. Ia juga selalu tidur dengan lampu menyala sejak usia enam tahun.', 'cat_space', 'aut_axto-creative-team', 'twilight', '🚀', 5, 9, 0, 'published', 9, 875, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_1', 'bok_the-astronaut-who-was-afraid-of-the-dark', 1, 'dark-1', 'Commander Zahra had flown three missions. She had repaired a satellite with her own hands and once spent eleven hours outside the station with nothing between her and everything but a suit.', 'Komandan Zahra telah menjalani tiga misi. Ia pernah memperbaiki satelit dengan tangannya sendiri dan pernah menghabiskan sebelas jam di luar stasiun tanpa apa pun di antara dirinya dan kehampaan kecuali sebuah baju antariksa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_2', 'bok_the-astronaut-who-was-afraid-of-the-dark', 2, 'dark-2', 'She had also, since she was six years old, been afraid of the dark. Not a little afraid. Properly afraid, the kind that makes your ears listen too hard.', 'Ia juga, sejak berusia enam tahun, takut gelap. Bukan sedikit takut. Benar-benar takut, jenis rasa takut yang membuat telinga mendengar terlalu tajam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_3', 'bok_the-astronaut-who-was-afraid-of-the-dark', 3, 'dark-3', 'Nobody knew. On Earth she left a small lamp on. On the station there was always something glowing — a screen, a switch, the blue line of the planet turning below the window.', 'Tidak ada yang tahu. Di Bumi ia menyalakan lampu kecil. Di stasiun selalu ada sesuatu yang bercahaya — layar, sakelar, atau garis biru planet yang berputar di bawah jendela.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_4', 'bok_the-astronaut-who-was-afraid-of-the-dark', 4, 'dark-4', 'Then came the fault. A quiet click, and the whole module went black — no screens, no switches, and the window facing away from Earth into nothing at all.', 'Lalu terjadilah kerusakan. Bunyi klik pelan, dan seluruh modul menjadi gelap — tanpa layar, tanpa sakelar, dan jendela menghadap menjauhi Bumi, ke arah kehampaan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_5', 'bok_the-astronaut-who-was-afraid-of-the-dark', 5, 'dark-5', 'Zahra''s hands went cold on the rail. She was thirty-eight years old, four hundred kilometres above her own house, and for a moment she was six again in a bedroom with the door shut.', 'Tangan Zahra mendingin di pegangan. Usianya tiga puluh delapan tahun, empat ratus kilometer di atas rumahnya sendiri, dan sesaat ia kembali menjadi anak enam tahun di kamar dengan pintu tertutup.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_6', 'bok_the-astronaut-who-was-afraid-of-the-dark', 6, 'dark-6', 'So she did what her grandmother had taught her long ago. She said out loud, into the dark, exactly what was there. "A rail. My left hand. The hatch, two metres behind me. Tomo, asleep in the next module."', 'Maka ia melakukan apa yang diajarkan neneknya dahulu. Ia berkata lantang, ke dalam kegelapan, tentang apa saja yang ada di sana. "Sebuah pegangan. Tangan kiriku. Palka, dua meter di belakangku. Tomo, sedang tidur di modul sebelah."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_7', 'bok_the-astronaut-who-was-afraid-of-the-dark', 7, 'dark-7', 'Naming them did not switch the lights on. But it made the dark into a room again instead of a nowhere, and a room can be crossed. She moved hand over hand toward the panel.', 'Menyebut nama-nama itu tidak menyalakan lampu. Tetapi itu mengubah kegelapan menjadi sebuah ruangan lagi, bukan ketiadaan, dan ruangan bisa diseberangi. Ia bergerak tangan demi tangan menuju panel.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_8', 'bok_the-astronaut-who-was-afraid-of-the-dark', 8, 'dark-8', 'It took her nine minutes to find the tripped breaker by touch. When the lights came back, Tomo floated in rubbing his eyes and said, "Everything all right?" Zahra said, "Yes." Then she thought about it. "No. But it is now."', 'Ia butuh sembilan menit untuk menemukan sakelar yang jatuh, hanya dengan sentuhan. Ketika lampu menyala kembali, Tomo melayang masuk sambil mengucek mata dan bertanya, "Semua baik-baik saja?" Zahra menjawab, "Ya." Lalu ia berpikir lagi. "Tidak. Tapi sekarang iya."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-astronaut-who-was-afraid-of-the-dark_9', 'bok_the-astronaut-who-was-afraid-of-the-dark', 9, 'dark-9', 'She still sleeps with a light on. She has decided that is allowed. Being brave, it turns out, is not the same as not being frightened — it is knowing what to do while you are.', 'Ia masih tidur dengan lampu menyala. Ia memutuskan itu boleh saja. Ternyata, menjadi berani bukan berarti tidak takut — melainkan tahu apa yang harus dilakukan saat sedang takut.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-astronaut-who-was-afraid-of-the-dark_1', 'bok_the-astronaut-who-was-afraid-of-the-dark', 1, 'What was Zahra secretly afraid of?', 'Apa yang diam-diam Zahra takuti?', '["Heights","The dark","Water","Loud noises"]', '["Ketinggian","Kegelapan","Air","Suara keras"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-astronaut-who-was-afraid-of-the-dark_2', 'bok_the-astronaut-who-was-afraid-of-the-dark', 2, 'What did she do when the lights went out?', 'Apa yang ia lakukan saat lampu padam?', '["Shouted for help","Named out loud everything that was there","Went back to sleep","Closed her eyes"]', '["Berteriak minta tolong","Menyebut lantang segala sesuatu yang ada di sana","Kembali tidur","Memejamkan mata"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-astronaut-who-was-afraid-of-the-dark_3', 'bok_the-astronaut-who-was-afraid-of-the-dark', 3, 'What does the story say bravery is?', 'Menurut cerita ini, apa itu keberanian?', '["Never being frightened","Knowing what to do while you are frightened","Being the strongest","Working alone"]', '["Tidak pernah merasa takut","Tahu apa yang harus dilakukan saat sedang takut","Menjadi yang terkuat","Bekerja sendirian"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-smallest-dinosaur-in-the-valley', 'the-smallest-dinosaur-in-the-valley', 'The Smallest Dinosaur in the Valley', 'Dinosaurus Terkecil di Lembah', 'Everyone in the valley is enormous except Rui, who is the size of a chicken — and the only one who can hear the river changing.', 'Semua penghuni lembah bertubuh raksasa kecuali Rui, yang sebesar ayam — dan satu-satunya yang bisa mendengar sungai berubah.', 'cat_dinosaur', 'aut_axto-creative-team', 'forest', '🦕', 4, 8, 0, 'published', 9, 3765, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_1', 'bok_the-smallest-dinosaur-in-the-valley', 1, 'rui-1', 'In the green valley between two ridges lived some of the largest creatures that have ever walked. There were long-necks who ate from the tops of trees and heavy-tails who shook the ground.', 'Di lembah hijau di antara dua punggung bukit hiduplah beberapa makhluk terbesar yang pernah berjalan di bumi. Ada si leher panjang yang makan dari pucuk pohon dan si ekor berat yang mengguncang tanah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_2', 'bok_the-smallest-dinosaur-in-the-valley', 2, 'rui-2', 'And there was Rui. Rui was a dinosaur too, but he was the size of a chicken, with feathers on his arms and very quick eyes.', 'Dan ada Rui. Rui juga seekor dinosaurus, tetapi ukurannya sebesar ayam, dengan bulu di lengannya dan mata yang sangat gesit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_3', 'bok_the-smallest-dinosaur-in-the-valley', 3, 'rui-3', 'The big ones were kind to him in the way big things often are: they did not notice him much. When they talked about the valley, they talked over his head, because his head was near their feet.', 'Para raksasa bersikap baik kepadanya seperti umumnya makhluk besar: mereka tidak terlalu memperhatikannya. Ketika membicarakan lembah, mereka bicara di atas kepalanya, karena kepalanya ada di dekat kaki mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_4', 'bok_the-smallest-dinosaur-in-the-valley', 4, 'rui-4', 'But being close to the ground meant Rui heard things nobody else did. He heard beetles under bark. He heard rain three valleys away. And one afternoon, he heard the river change its voice.', 'Namun berada dekat tanah membuat Rui mendengar hal-hal yang tak didengar siapa pun. Ia mendengar kumbang di balik kulit kayu. Ia mendengar hujan dari tiga lembah jauhnya. Dan suatu sore, ia mendengar sungai berubah suaranya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_5', 'bok_the-smallest-dinosaur-in-the-valley', 5, 'rui-5', 'It had been a wide, slow, chuckling sound for as long as he had lived. Now it was tighter and higher, the way a voice goes when something is squeezing it.', 'Selama ia hidup, suaranya selalu lebar, lambat, dan seperti tertawa kecil. Kini suaranya lebih rapat dan lebih tinggi, seperti suara orang yang sedang tertekan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_6', 'bok_the-smallest-dinosaur-in-the-valley', 6, 'rui-6', 'Rui ran upstream on his quick feet and found it: a landslide of rock and mud from the ridge, damming the water into a swelling grey pool that was rising toward the low meadow where everyone slept.', 'Rui berlari ke hulu dengan kakinya yang gesit dan menemukannya: longsoran batu dan lumpur dari punggung bukit, membendung air menjadi kolam kelabu yang membengkak dan naik ke arah padang rendah tempat semua tidur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_7', 'bok_the-smallest-dinosaur-in-the-valley', 7, 'rui-7', 'He ran back and shouted. Nobody heard him — his voice was small and they were high up. So Rui did the only thing left: he climbed the tail of the biggest long-neck and shrieked directly into her ear.', 'Ia berlari kembali dan berteriak. Tidak ada yang mendengarnya — suaranya kecil dan mereka berada jauh di atas. Maka Rui melakukan satu-satunya hal yang tersisa: ia memanjat ekor si leher panjang terbesar dan memekik tepat di telinganya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_8', 'bok_the-smallest-dinosaur-in-the-valley', 8, 'rui-8', 'She listened. Then she bellowed, and the whole valley moved. All night the big ones pushed and rolled the fallen rock aside while Rui stood on a stump and told them where to shove.', 'Ia mendengarkan. Lalu ia mengaum, dan seluruh lembah bergerak. Sepanjang malam para raksasa mendorong dan menggulingkan batu-batu yang jatuh sementara Rui berdiri di atas tunggul dan menunjukkan ke mana harus mendorong.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-smallest-dinosaur-in-the-valley_9', 'bok_the-smallest-dinosaur-in-the-valley', 9, 'rui-9', 'By morning the river ran wide and slow and chuckling again. And after that, when the big ones talked about the valley, somebody always thought to look down first and ask Rui what he could hear.', 'Menjelang pagi sungai kembali mengalir lebar, lambat, dan seperti tertawa kecil. Dan setelah itu, ketika para raksasa membicarakan lembah, selalu ada yang ingat untuk menunduk lebih dulu dan bertanya kepada Rui apa yang ia dengar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-smallest-dinosaur-in-the-valley_1', 'bok_the-smallest-dinosaur-in-the-valley', 1, 'What made Rui different from the others?', 'Apa yang membuat Rui berbeda dari yang lain?', '["He could fly","He was very small and close to the ground","He was the oldest","He could swim"]', '["Ia bisa terbang","Ia sangat kecil dan dekat dengan tanah","Ia paling tua","Ia bisa berenang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-smallest-dinosaur-in-the-valley_2', 'bok_the-smallest-dinosaur-in-the-valley', 2, 'What had happened to the river?', 'Apa yang terjadi pada sungai?', '["It dried up","A landslide had dammed it","It froze","It changed colour"]', '["Sungainya kering","Longsoran membendungnya","Sungainya membeku","Warnanya berubah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-smallest-dinosaur-in-the-valley_3', 'bok_the-smallest-dinosaur-in-the-valley', 3, 'How did Rui finally get the big ones to listen?', 'Bagaimana akhirnya Rui membuat para raksasa mendengarkan?', '["He wrote a note","He climbed up and shrieked into an ear","He waited a week","He gave up"]', '["Ia menulis pesan","Ia memanjat dan memekik di telinga","Ia menunggu seminggu","Ia menyerah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_one-hundred-sheep-and-one-that-wandered', 'one-hundred-sheep-and-one-that-wandered', 'One Hundred Sheep and One That Wandered', 'Seratus Domba dan Satu yang Berkelana', 'A very quiet bedtime story for counting down, in which everybody eventually gets where they are going.', 'Cerita pengantar tidur yang sangat tenang untuk menghitung mundur, di mana semua akhirnya sampai di tujuan.', 'cat_bedtime', 'aut_axto-creative-team', 'twilight', '🌙', 2, 6, 0, 'published', 9, 2643, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_1', 'bok_one-hundred-sheep-and-one-that-wandered', 1, 'sheep-1', 'On a hill above a sleeping village there were one hundred sheep, and one shepherd, and one very old dog whose name was Pillow because that is where he slept.', 'Di sebuah bukit di atas desa yang tertidur ada seratus domba, seorang gembala, dan seekor anjing yang sangat tua bernama Bantal, karena di situlah ia tidur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_2', 'bok_one-hundred-sheep-and-one-that-wandered', 2, 'sheep-2', 'When the sun went down, the sheep began to walk home. They walked slowly, because sheep never hurry, and one by one they went in through the gate.', 'Ketika matahari terbenam, domba-domba mulai berjalan pulang. Mereka berjalan perlahan, karena domba tidak pernah terburu-buru, dan satu per satu mereka masuk lewat gerbang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_3', 'bok_one-hundred-sheep-and-one-that-wandered', 3, 'sheep-3', 'Ninety went in without stopping. Then five stopped to look at the moon, which was the colour of milk, and then they went in too. That left five outside, and then four.', 'Sembilan puluh masuk tanpa berhenti. Lalu lima berhenti memandang bulan, yang berwarna susu, dan kemudian mereka pun masuk. Tinggal lima di luar, lalu empat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_4', 'bok_one-hundred-sheep-and-one-that-wandered', 4, 'sheep-4', 'Number four had wool over her eyes and went in sideways. Number three followed her friend. Number two was already half asleep and simply leaned in the right direction until she arrived.', 'Domba nomor empat matanya tertutup bulu dan masuk dengan menyamping. Nomor tiga mengikuti temannya. Nomor dua sudah setengah tertidur dan hanya bersandar ke arah yang benar sampai ia tiba.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_5', 'bok_one-hundred-sheep-and-one-that-wandered', 5, 'sheep-5', 'That left one. And number one was not by the gate at all. She was far up the hill, at the very top, standing quite still in the long blue grass.', 'Tinggal satu. Dan nomor satu sama sekali tidak ada di dekat gerbang. Ia jauh di atas bukit, di puncaknya, berdiri diam sekali di rumput biru yang panjang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_6', 'bok_one-hundred-sheep-and-one-that-wandered', 6, 'sheep-6', 'The shepherd did not shout. He walked up, all the way, with Pillow padding beside him, and when he got there he did not say anything either. He just looked at what she was looking at.', 'Sang gembala tidak berteriak. Ia berjalan naik, sampai ke puncak, dengan Bantal melangkah di sisinya, dan ketika sampai ia juga tidak berkata apa-apa. Ia hanya menatap apa yang sedang domba itu tatap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_7', 'bok_one-hundred-sheep-and-one-that-wandered', 7, 'sheep-7', 'Below them the whole valley lay folded in the dark, with three small lights in it, and above them there were more stars than anybody has ever counted, even the people who try.', 'Di bawah mereka seluruh lembah terlipat dalam gelap, dengan tiga titik cahaya kecil di dalamnya, dan di atas mereka ada lebih banyak bintang daripada yang pernah dihitung siapa pun, bahkan oleh mereka yang mencoba.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_8', 'bok_one-hundred-sheep-and-one-that-wandered', 8, 'sheep-8', 'After a while the sheep turned round on her own and started down. The shepherd walked behind her. Pillow walked behind them both, stopping twice to sniff something and then forgetting what it was.', 'Setelah beberapa lama domba itu berbalik sendiri dan mulai menuruni bukit. Sang gembala berjalan di belakangnya. Bantal berjalan di belakang keduanya, berhenti dua kali untuk mengendus sesuatu lalu lupa apa itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_one-hundred-sheep-and-one-that-wandered_9', 'bok_one-hundred-sheep-and-one-that-wandered', 9, 'sheep-9', 'One hundred sheep. One gate. One old dog already snoring. And on the hill, the long blue grass moving very slowly, as if it too were finally going to sleep.', 'Seratus domba. Satu gerbang. Satu anjing tua yang sudah mendengkur. Dan di bukit, rumput biru panjang bergerak sangat perlahan, seolah-olah ia pun akhirnya hendak tidur.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_one-hundred-sheep-and-one-that-wandered_1', 'bok_one-hundred-sheep-and-one-that-wandered', 1, 'How many sheep were on the hill?', 'Berapa jumlah domba di bukit itu?', '["Ten","Fifty","One hundred","One"]', '["Sepuluh","Lima puluh","Seratus","Satu"]', 2, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_one-hundred-sheep-and-one-that-wandered_2', 'bok_one-hundred-sheep-and-one-that-wandered', 2, 'Why was the dog called Pillow?', 'Mengapa anjing itu dinamai Bantal?', '["He was soft","That is where he slept","He was white","He was noisy"]', '["Karena lembut","Karena di situlah ia tidur","Karena putih","Karena berisik"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_one-hundred-sheep-and-one-that-wandered_3', 'bok_one-hundred-sheep-and-one-that-wandered', 3, 'What did the shepherd do about the last sheep?', 'Apa yang gembala lakukan pada domba terakhir?', '["Shouted at her","Walked up and waited quietly with her","Left her there","Carried her down"]', '["Membentaknya","Naik dan menunggu dengan tenang bersamanya","Meninggalkannya di sana","Menggendongnya turun"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-question-that-would-not-sit-down', 'the-question-that-would-not-sit-down', 'The Question That Would Not Sit Down', 'Pertanyaan yang Tak Mau Duduk Diam', 'Ilham asks why the sky is blue. Nobody can answer properly — so he spends a whole year finding out.', 'Ilham bertanya mengapa langit berwarna biru. Tak seorang pun bisa menjawab dengan benar — maka ia menghabiskan setahun penuh untuk mencari tahu.', 'cat_learning', 'aut_axto-creative-team', 'ocean', '📚', 6, 10, 0, 'published', 9, 3074, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_1', 'bok_the-question-that-would-not-sit-down', 1, 'why-1', 'Ilham asked his question on a Tuesday, lying on his back in the yard. "Why is the sky blue?" His sister said, "Because it is." That is not an answer, and Ilham knew it.', 'Ilham mengajukan pertanyaannya pada hari Selasa, sambil telentang di halaman. "Mengapa langit berwarna biru?" Kakaknya menjawab, "Ya karena memang begitu." Itu bukan jawaban, dan Ilham tahu itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_2', 'bok_the-question-that-would-not-sit-down', 2, 'why-2', 'He asked his father, who said it was something to do with the sea reflecting. He asked his uncle, who said it was the air. Both answers sounded confident. Only one of them could be right, and in fact neither was.', 'Ia bertanya kepada ayahnya, yang menjawab bahwa itu ada hubungannya dengan pantulan laut. Ia bertanya kepada pamannya, yang menjawab bahwa itu karena udara. Keduanya terdengar yakin. Hanya satu yang bisa benar, dan ternyata tidak satu pun benar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_3', 'bok_the-question-that-would-not-sit-down', 3, 'why-3', 'At school, his teacher Bu Ratna did something better than answering. She said, "I am not certain. Shall we find out properly?" And she wrote the question on a card and pinned it to the wall.', 'Di sekolah, gurunya Bu Ratna melakukan hal yang lebih baik daripada menjawab. Ia berkata, "Saya kurang yakin. Mau kita cari tahu bersama?" Lalu ia menulis pertanyaan itu di sebuah kartu dan menempelkannya di dinding.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_4', 'bok_the-question-that-would-not-sit-down', 4, 'why-4', 'First they discovered that white light is not white at all. Bu Ratna held a prism in the window and there it was on the floor — red, orange, yellow, green, blue, indigo, violet, all hiding inside the sunlight.', 'Pertama mereka menemukan bahwa cahaya putih sebenarnya sama sekali tidak putih. Bu Ratna memegang prisma di jendela dan warnanya muncul di lantai — merah, jingga, kuning, hijau, biru, nila, ungu, semuanya bersembunyi di dalam sinar matahari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_5', 'bok_the-question-that-would-not-sit-down', 5, 'why-5', 'Then they learned that light travels in waves, and that blue waves are short and bunched-up while red waves are long and stretched out, like ripples of different sizes crossing a pond.', 'Lalu mereka belajar bahwa cahaya merambat sebagai gelombang, dan bahwa gelombang biru itu pendek dan rapat sementara gelombang merah panjang dan renggang, seperti riak berbeda ukuran yang menyeberangi kolam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_6', 'bok_the-question-that-would-not-sit-down', 6, 'why-6', 'And then the piece that made it click. The air is full of tiny specks — bits of gas far too small to see. Short bunched-up waves bump into them and scatter everywhere. Long stretched-out waves mostly sail straight past.', 'Lalu tibalah bagian yang membuat semuanya masuk akal. Udara penuh dengan bintik-bintik amat kecil — partikel gas yang jauh terlalu kecil untuk dilihat. Gelombang pendek yang rapat menabraknya dan terhambur ke mana-mana. Gelombang panjang yang renggang umumnya lewat begitu saja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_7', 'bok_the-question-that-would-not-sit-down', 7, 'why-7', '"So," said Ilham slowly, working it out, "the blue is bouncing all over the sky. That is why it comes at me from everywhere at once — not from one place, like the sun does." Bu Ratna smiled and said nothing, which meant yes.', '"Jadi," kata Ilham perlahan, sambil menalar, "warna birunya terpantul ke seluruh langit. Itu sebabnya biru datang kepadaku dari segala arah sekaligus — bukan dari satu titik, seperti matahari." Bu Ratna tersenyum dan tidak berkata apa-apa, yang berarti benar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_8', 'bok_the-question-that-would-not-sit-down', 8, 'why-8', '"Then why is sunset red?" he asked immediately. And Bu Ratna laughed and wrote that on a second card, and pinned it up beside the first.', '"Lalu mengapa matahari terbenam berwarna merah?" tanyanya seketika. Bu Ratna tertawa dan menuliskannya di kartu kedua, lalu menempelkannya di samping yang pertama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-question-that-would-not-sit-down_9', 'bok_the-question-that-would-not-sit-down', 9, 'why-9', 'By the end of the year the wall was covered in cards. Some had answers under them. Some did not, and Bu Ratna left those up too, because a question nobody has answered yet is the most interesting thing in any room.', 'Menjelang akhir tahun, dinding itu penuh dengan kartu. Beberapa sudah ada jawabannya di bawahnya. Beberapa belum, dan Bu Ratna membiarkannya tetap terpasang, karena pertanyaan yang belum terjawab adalah hal paling menarik di ruangan mana pun.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-question-that-would-not-sit-down_1', 'bok_the-question-that-would-not-sit-down', 1, 'What did Bu Ratna do when she did not know the answer?', 'Apa yang Bu Ratna lakukan ketika ia tidak tahu jawabannya?', '["Made one up","Said so and offered to find out together","Changed the subject","Told him to stop asking"]', '["Mengarang jawaban","Mengakuinya dan mengajak mencari tahu bersama","Mengalihkan pembicaraan","Menyuruhnya berhenti bertanya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-question-that-would-not-sit-down_2', 'bok_the-question-that-would-not-sit-down', 2, 'Why does the sky look blue?', 'Mengapa langit tampak biru?', '["It reflects the sea","Short blue waves scatter off tiny specks in the air","The sun is blue","The air is painted"]', '["Memantulkan laut","Gelombang biru yang pendek terhambur oleh partikel kecil di udara","Mataharinya biru","Udaranya dicat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-question-that-would-not-sit-down_3', 'bok_the-question-that-would-not-sit-down', 3, 'Why did Bu Ratna leave unanswered cards on the wall?', 'Mengapa Bu Ratna membiarkan kartu yang belum terjawab tetap di dinding?', '["She forgot them","Because unanswered questions are interesting","To punish the class","There was no space elsewhere"]', '["Ia lupa","Karena pertanyaan yang belum terjawab itu menarik","Untuk menghukum kelas","Tidak ada tempat lain"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-superhero-with-no-powers', 'the-superhero-with-no-powers', 'The Superhero With No Powers', 'Pahlawan Super Tanpa Kekuatan', 'The city has four heroes who can fly, freeze and lift buses. It also has Dewi, who notices things.', 'Kota itu punya empat pahlawan yang bisa terbang, membekukan, dan mengangkat bus. Kota itu juga punya Dewi, yang pandai memperhatikan.', 'cat_superheroes', 'aut_axto-creative-team', 'citrus', '🦸', 6, 10, 0, 'published', 9, 2078, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_1', 'bok_the-superhero-with-no-powers', 1, 'dewi-1', 'The city of Kertasari was protected by four heroes. Blaze could throw fire. Tide could stop a river. Iron Anna could lift a bus, and Wisp could be in two places at once, which was confusing for everybody including Wisp.', 'Kota Kertasari dilindungi oleh empat pahlawan. Blaze bisa melemparkan api. Tide bisa menghentikan sungai. Iron Anna bisa mengangkat bus, dan Wisp bisa berada di dua tempat sekaligus, yang membingungkan semua orang termasuk Wisp sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_2', 'bok_the-superhero-with-no-powers', 2, 'dewi-2', 'Dewi could not do any of those things. Dewi was eleven, wore glasses that slid down her nose, and had exactly one talent: she noticed things, and she remembered them.', 'Dewi tidak bisa melakukan satu pun dari itu. Dewi berusia sebelas tahun, memakai kacamata yang melorot di hidungnya, dan punya tepat satu bakat: ia pandai memperhatikan, dan ia mengingatnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_3', 'bok_the-superhero-with-no-powers', 3, 'dewi-3', 'When the museum was robbed, the four heroes searched the whole city. They flew over rooftops and froze the harbour and lifted three buses looking underneath, and they found nothing at all.', 'Ketika museum dirampok, keempat pahlawan menyisir seluruh kota. Mereka terbang di atas atap, membekukan pelabuhan, dan mengangkat tiga bus untuk melihat ke bawahnya, dan mereka sama sekali tidak menemukan apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_4', 'bok_the-superhero-with-no-powers', 4, 'dewi-4', 'Dewi did not search anywhere. She sat on the museum steps with a notebook and thought about what she had seen there on Tuesday, and Wednesday, and every day for a month on her way to school.', 'Dewi tidak menyisir ke mana pun. Ia duduk di anak tangga museum dengan buku catatan dan memikirkan apa yang ia lihat di sana pada hari Selasa, Rabu, dan setiap hari selama sebulan dalam perjalanan ke sekolah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_5', 'bok_the-superhero-with-no-powers', 5, 'dewi-5', 'The bins had been emptied on a Thursday for three weeks, she wrote. But this week the lorry came on Monday, and it was a different lorry, and the driver did not have the little blue sticker on his window.', 'Tempat sampah dikosongkan setiap Kamis selama tiga minggu, tulisnya. Tetapi minggu ini truknya datang hari Senin, dan itu truk yang berbeda, dan sopirnya tidak punya stiker biru kecil di jendelanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_6', 'bok_the-superhero-with-no-powers', 6, 'dewi-6', 'She showed the page to Iron Anna, who read it twice and went very quiet. Then Anna said a word she was not supposed to say in front of children, and went to find the bin lorry.', 'Ia menunjukkan halaman itu kepada Iron Anna, yang membacanya dua kali dan terdiam. Lalu Anna mengucapkan sebuah kata yang seharusnya tidak diucapkan di depan anak-anak, dan pergi mencari truk sampah itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_7', 'bok_the-superhero-with-no-powers', 7, 'dewi-7', 'The paintings were inside it, wrapped in plastic under the rubbish, exactly where nobody who could fly would ever think to look.', 'Lukisan-lukisan itu ada di dalamnya, terbungkus plastik di bawah sampah, persis di tempat yang tak akan pernah terpikirkan oleh siapa pun yang bisa terbang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_8', 'bok_the-superhero-with-no-powers', 8, 'dewi-8', 'At the ceremony, the mayor asked Dewi what her power was. Dewi thought about it seriously, the way she thought about everything. "I pay attention," she said. "For a long time. Even when nothing is happening."', 'Pada upacara penghargaan, wali kota bertanya kepada Dewi apa kekuatannya. Dewi memikirkannya dengan serius, seperti ia memikirkan segalanya. "Saya memperhatikan," katanya. "Dalam waktu lama. Bahkan ketika tidak sedang terjadi apa-apa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-superhero-with-no-powers_9', 'bok_the-superhero-with-no-powers', 9, 'dewi-9', 'Blaze still throws fire and Iron Anna still lifts buses. But now, before they start, one of them always goes and knocks on a certain window and asks a girl in glasses what she has noticed lately.', 'Blaze masih melemparkan api dan Iron Anna masih mengangkat bus. Tetapi kini, sebelum mulai, salah satu dari mereka selalu pergi mengetuk sebuah jendela dan bertanya kepada seorang gadis berkacamata apa yang belakangan ini ia perhatikan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-superhero-with-no-powers_1', 'bok_the-superhero-with-no-powers', 1, 'What was Dewi''s only talent?', 'Apa satu-satunya bakat Dewi?', '["Flying","Noticing and remembering things","Lifting heavy objects","Running fast"]', '["Terbang","Memperhatikan dan mengingat","Mengangkat benda berat","Berlari cepat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-superhero-with-no-powers_2', 'bok_the-superhero-with-no-powers', 2, 'Where were the stolen paintings?', 'Di mana lukisan-lukisan yang dicuri itu?', '["In the harbour","Inside a bin lorry","On a rooftop","Under a bus"]', '["Di pelabuhan","Di dalam truk sampah","Di atas atap","Di bawah bus"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-superhero-with-no-powers_3', 'bok_the-superhero-with-no-powers', 3, 'Why did the four heroes not find them?', 'Mengapa keempat pahlawan tidak menemukannya?', '["They were not trying","They looked in dramatic places, not ordinary ones","They were too slow","The thief was invisible"]', '["Mereka tidak berusaha","Mereka mencari di tempat dramatis, bukan tempat biasa","Mereka terlalu lambat","Pencurinya tak terlihat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-day-everything-was-upside-down', 'the-day-everything-was-upside-down', 'The Day Everything Was Upside Down', 'Hari Ketika Semuanya Terbalik', 'Grandpa Wira insists that on Wednesdays the rules are different. A gloriously silly story about a very serious old man.', 'Kakek Wira bersikeras bahwa pada hari Rabu aturannya berbeda. Cerita konyol yang meriah tentang seorang kakek yang sangat serius.', 'cat_humor', 'aut_axto-creative-team', 'citrus', '🙃', 4, 8, 0, 'published', 9, 1053, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_1', 'bok_the-day-everything-was-upside-down', 1, 'upside-1', 'Grandpa Wira was a serious man. He wore a pressed shirt every day of his life and folded his newspaper into exact quarters. This is important to know, because of what happened on Wednesdays.', 'Kakek Wira adalah orang yang serius. Ia mengenakan kemeja licin setiap hari dalam hidupnya dan melipat korannya menjadi seperempat yang presisi. Ini penting diketahui, mengingat apa yang terjadi setiap hari Rabu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_2', 'bok_the-day-everything-was-upside-down', 2, 'upside-2', 'On Wednesdays, Grandpa Wira announced that the rules were different, and then behaved as though this were the most ordinary fact in the world.', 'Pada hari Rabu, Kakek Wira mengumumkan bahwa aturannya berbeda, lalu bersikap seolah-olah itu fakta paling biasa di dunia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_3', 'bok_the-day-everything-was-upside-down', 3, 'upside-3', 'Breakfast was at night. Dinner was at seven in the morning, and it was soup, and he ate it looking out of the window at people going to work, and he waved at them with his spoon.', 'Sarapan disantap malam hari. Makan malam pukul tujuh pagi, berupa sup, dan ia menyantapnya sambil memandang keluar jendela ke arah orang-orang yang berangkat kerja, dan ia melambai kepada mereka dengan sendok.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_4', 'bok_the-day-everything-was-upside-down', 4, 'upside-4', 'He walked backwards to the shop. He said goodbye when he arrived and hello when he left. The shopkeeper had long ago stopped commenting and simply said the opposite thing back.', 'Ia berjalan mundur ke toko. Ia mengucapkan selamat tinggal saat tiba dan halo saat pergi. Pemilik toko sudah lama berhenti berkomentar dan hanya membalas dengan kata yang sebaliknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_5', 'bok_the-day-everything-was-upside-down', 5, 'upside-5', 'His grandson Adi thought this was the funniest thing that had ever happened to anybody. He also thought, secretly, that it was a bit embarrassing when his friends were watching.', 'Cucunya, Adi, menganggap ini hal paling lucu yang pernah terjadi pada siapa pun. Ia juga diam-diam merasa agak malu ketika teman-temannya menonton.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_6', 'bok_the-day-everything-was-upside-down', 6, 'upside-6', 'One Wednesday, Adi asked him to stop. Just for one week. Just while his class walked past. Grandpa Wira put down his newspaper, which he had folded into exact quarters, and thought about it.', 'Suatu Rabu, Adi memintanya berhenti. Cukup satu minggu saja. Hanya selama kelasnya lewat. Kakek Wira meletakkan korannya, yang telah dilipat menjadi seperempat yang presisi, lalu berpikir.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_7', 'bok_the-day-everything-was-upside-down', 7, 'upside-7', '"When I was young," he said, "I did everything correctly for forty years. Correct shirt. Correct hours. Correct opinions at correct volumes. It was not a bad life. But it was very quiet in here." He tapped his chest.', '"Ketika saya muda," katanya, "saya melakukan semuanya dengan benar selama empat puluh tahun. Kemeja yang benar. Jam yang benar. Pendapat yang benar dengan volume yang benar. Itu bukan hidup yang buruk. Tetapi di dalam sini sangat sepi." Ia menepuk dadanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_8', 'bok_the-day-everything-was-upside-down', 8, 'upside-8', '"So now I have Wednesday," he said. "One day out of seven where nothing has to be the right way round. You may join me or not. But I am not giving it back."', '"Maka sekarang saya punya hari Rabu," katanya. "Satu hari dari tujuh, ketika tidak ada yang harus berada pada posisi yang benar. Kau boleh ikut atau tidak. Tetapi hari itu tidak akan saya kembalikan."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-everything-was-upside-down_9', 'bok_the-day-everything-was-upside-down', 9, 'upside-9', 'The following Wednesday, Adi''s whole class walked past. Grandpa Wira was outside, walking backwards, waving with a spoon. And Adi, after a moment, waved back with both hands and shouted, "Goodbye, Grandpa!"', 'Rabu berikutnya, seluruh kelas Adi lewat. Kakek Wira ada di luar, berjalan mundur, melambai dengan sendok. Dan Adi, setelah sejenak, membalas melambai dengan kedua tangan sambil berteriak, "Selamat tinggal, Kek!"');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-everything-was-upside-down_1', 'bok_the-day-everything-was-upside-down', 1, 'What happened on Wednesdays?', 'Apa yang terjadi pada hari Rabu?', '["Grandpa stayed in bed","Grandpa did everything the opposite way round","Nothing","It always rained"]', '["Kakek tetap di tempat tidur","Kakek melakukan segalanya secara terbalik","Tidak terjadi apa-apa","Selalu hujan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-everything-was-upside-down_2', 'bok_the-day-everything-was-upside-down', 2, 'Why did Grandpa Wira invent Wednesday?', 'Mengapa Kakek Wira menciptakan hari Rabu?', '["To annoy people","Because he had spent forty years doing everything correctly","He lost a bet","He was confused"]', '["Untuk mengganggu orang","Karena empat puluh tahun ia melakukan semuanya dengan benar","Ia kalah taruhan","Ia bingung"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-everything-was-upside-down_3', 'bok_the-day-everything-was-upside-down', 3, 'What did Adi do at the end?', 'Apa yang Adi lakukan di akhir cerita?', '["Hid from his class","Waved back and joined in","Asked him to stop again","Walked away"]', '["Bersembunyi dari kelasnya","Membalas lambaian dan ikut serta","Memintanya berhenti lagi","Pergi menjauh"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-library-with-one-locked-door', 'the-library-with-one-locked-door', 'The Library With One Locked Door', 'Perpustakaan dengan Satu Pintu Terkunci', 'Every door in the old library is open except one. Maya has three weeks of summer and a very good reason to be curious.', 'Setiap pintu di perpustakaan tua itu terbuka kecuali satu. Maya punya tiga minggu liburan dan alasan yang sangat kuat untuk penasaran.', 'cat_mystery', 'aut_axto-creative-team', 'twilight', '🔍', 7, 11, 0, 'published', 9, 2882, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_1', 'bok_the-library-with-one-locked-door', 1, 'locked-1', 'The library on Kenanga Street had eleven doors. Ten of them were propped open all summer to let the air through. The eleventh, at the end of the north corridor, was locked, and had been for as long as anybody could remember.', 'Perpustakaan di Jalan Kenanga punya sebelas pintu. Sepuluh di antaranya diganjal terbuka sepanjang musim panas agar udara mengalir. Yang kesebelas, di ujung koridor utara, terkunci, dan sudah terkunci selama yang bisa diingat siapa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_2', 'bok_the-library-with-one-locked-door', 2, 'locked-2', 'Maya asked the librarian, Pak Yusuf, what was behind it. He said, "Nothing interesting." Which is, of course, exactly the wrong thing to say to somebody like Maya.', 'Maya bertanya kepada pustakawan, Pak Yusuf, apa yang ada di baliknya. Ia menjawab, "Tidak ada yang menarik." Yang tentu saja merupakan hal paling keliru untuk dikatakan kepada orang seperti Maya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_3', 'bok_the-library-with-one-locked-door', 3, 'locked-3', 'She began collecting facts, which is what you do when you cannot get in. Fact one: the door had a keyhole, so there was a key. Fact two: there was no dust on the handle.', 'Ia mulai mengumpulkan fakta, yang memang harus dilakukan ketika tidak bisa masuk. Fakta satu: pintu itu punya lubang kunci, jadi ada kuncinya. Fakta dua: tidak ada debu di gagangnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_4', 'bok_the-library-with-one-locked-door', 4, 'locked-4', 'Fact three, and the best one: on the outside wall of the library, the north side had a window that did not match any room she had ever been in. She counted the windows twice from the street to be sure.', 'Fakta tiga, dan yang terbaik: di dinding luar perpustakaan, sisi utara punya sebuah jendela yang tidak cocok dengan ruangan mana pun yang pernah ia masuki. Ia menghitung jendela dua kali dari jalan untuk memastikan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_5', 'bok_the-library-with-one-locked-door', 5, 'locked-5', 'For eight days she watched from the reading table. On the ninth day, at four in the afternoon, Pak Yusuf took a small brass key from his pocket, went down the north corridor, and did not come back for an hour.', 'Selama delapan hari ia mengamati dari meja baca. Pada hari kesembilan, pukul empat sore, Pak Yusuf mengeluarkan kunci kuningan kecil dari sakunya, menyusuri koridor utara, dan tidak kembali selama satu jam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_6', 'bok_the-library-with-one-locked-door', 6, 'locked-6', 'Maya could have followed him. She thought about it for a long time. In the end she did something braver and much harder: on the tenth day, she waited until four, walked up to him, and asked.', 'Maya bisa saja mengikutinya. Ia memikirkannya lama. Pada akhirnya ia melakukan sesuatu yang lebih berani dan jauh lebih sulit: pada hari kesepuluh, ia menunggu sampai pukul empat, menghampirinya, dan bertanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_7', 'bok_the-library-with-one-locked-door', 7, 'locked-7', 'Pak Yusuf looked at her for a while. Then he said, "You counted the windows, didn''t you." And he took out the brass key and opened the door.', 'Pak Yusuf memandanginya sejenak. Lalu ia berkata, "Kau menghitung jendelanya, bukan?" Dan ia mengeluarkan kunci kuningan itu lalu membuka pintunya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_8', 'bok_the-library-with-one-locked-door', 8, 'locked-8', 'Inside was a small room full of books that were falling apart. Loose spines. Torn pages. A long table with glue, thread, thin brushes and weights. Pak Yusuf had been repairing them, one at a time, for nineteen years.', 'Di dalamnya ada ruangan kecil penuh buku yang hampir hancur. Punggung buku lepas. Halaman robek. Sebuah meja panjang dengan lem, benang, kuas halus, dan pemberat. Pak Yusuf telah memperbaikinya, satu per satu, selama sembilan belas tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-library-with-one-locked-door_9', 'bok_the-library-with-one-locked-door', 9, 'locked-9', '"It is not a secret," he said. "It is just quiet work, and quiet work needs a door." Maya spent the rest of the summer in that room, learning to sew a spine, and she never once told anybody where she went at four o''clock.', '"Ini bukan rahasia," katanya. "Ini hanya pekerjaan yang tenang, dan pekerjaan yang tenang butuh pintu." Maya menghabiskan sisa liburannya di ruangan itu, belajar menjahit punggung buku, dan ia tidak pernah sekali pun memberi tahu siapa pun ke mana ia pergi pukul empat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-library-with-one-locked-door_1', 'bok_the-library-with-one-locked-door', 1, 'What clue told Maya there was a hidden room?', 'Petunjuk apa yang membuat Maya tahu ada ruangan tersembunyi?', '["A map","A window that matched no room she knew","A note","A sound"]', '["Sebuah peta","Jendela yang tidak cocok dengan ruangan mana pun","Sebuah catatan","Sebuah suara"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-library-with-one-locked-door_2', 'bok_the-library-with-one-locked-door', 2, 'What did Maya finally decide to do?', 'Apa yang akhirnya Maya putuskan untuk dilakukan?', '["Sneak in","Simply ask Pak Yusuf","Take the key","Tell everyone"]', '["Menyelinap masuk","Bertanya langsung kepada Pak Yusuf","Mengambil kuncinya","Memberi tahu semua orang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-library-with-one-locked-door_3', 'bok_the-library-with-one-locked-door', 3, 'What was behind the locked door?', 'Apa yang ada di balik pintu terkunci itu?', '["Treasure","A workshop for repairing damaged books","An empty room","A staircase"]', '["Harta karun","Bengkel untuk memperbaiki buku rusak","Ruangan kosong","Sebuah tangga"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-pirate-who-kept-every-promise', 'the-pirate-who-kept-every-promise', 'The Pirate Who Kept Every Promise', 'Bajak Laut yang Menepati Setiap Janji', 'Captain Rahma is the most feared pirate in the southern sea, entirely because of one strange habit.', 'Kapten Rahma adalah bajak laut paling ditakuti di laut selatan, sepenuhnya karena satu kebiasaan yang aneh.', 'cat_pirates', 'aut_axto-creative-team', 'ocean', '🏴‍☠️', 6, 10, 0, 'published', 9, 2597, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_1', 'bok_the-pirate-who-kept-every-promise', 1, 'rahma-1', 'Captain Rahma was the most feared pirate in the southern sea, and not one person could tell you why. She had no cannon. Her ship was small. She had never once taken anything by force.', 'Kapten Rahma adalah bajak laut paling ditakuti di laut selatan, dan tak seorang pun bisa menjelaskan alasannya. Ia tidak punya meriam. Kapalnya kecil. Ia tidak pernah sekali pun merampas apa pun dengan kekerasan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_2', 'bok_the-pirate-who-kept-every-promise', 2, 'rahma-2', 'What she had was a habit. When Captain Rahma said a thing would happen, it happened. When she said it would not, it did not. In twenty years at sea she had never broken her word once.', 'Yang ia punya adalah sebuah kebiasaan. Ketika Kapten Rahma mengatakan sesuatu akan terjadi, hal itu terjadi. Ketika ia mengatakan tidak, maka tidak. Dalam dua puluh tahun di laut, ia tidak pernah sekali pun mengingkari ucapannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_3', 'bok_the-pirate-who-kept-every-promise', 3, 'rahma-3', 'This turns out to be terrifying. When she pulled alongside a merchant ship and said, "Give me the cargo and every one of you goes home," they believed her, because she had never lied — and so they gave it.', 'Ternyata itu menakutkan. Ketika ia merapat ke kapal dagang dan berkata, "Serahkan muatannya dan kalian semua pulang dengan selamat," mereka percaya, karena ia tidak pernah berbohong — maka mereka menyerahkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_4', 'bok_the-pirate-who-kept-every-promise', 4, 'rahma-4', 'The other pirates thought she was soft. Captain Bram of the Iron Gull told everyone that promises were for children. He also told a crew he would spare them, and then did not, and word travelled.', 'Bajak laut lain menganggapnya lembek. Kapten Bram dari kapal Iron Gull memberi tahu semua orang bahwa janji itu untuk anak-anak. Ia juga berjanji akan mengampuni satu awak kapal, lalu ingkar, dan kabar itu menyebar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_5', 'bok_the-pirate-who-kept-every-promise', 5, 'rahma-5', 'After that, every ship Bram approached fought him to the last plank, because they had nothing to gain by surrendering. He lost two ships and eleven men in a single season and never understood why.', 'Setelah itu, setiap kapal yang Bram dekati melawan sampai papan terakhir, karena mereka tidak punya apa pun untuk diperoleh dengan menyerah. Ia kehilangan dua kapal dan sebelas anak buah dalam satu musim dan tidak pernah paham mengapa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_6', 'bok_the-pirate-who-kept-every-promise', 6, 'rahma-6', 'One winter, Rahma made a promise she regretted. She told a fisherman''s widow she would bring her son home from the prison island by the first day of spring, before she knew how hard it would be.', 'Suatu musim dingin, Rahma membuat janji yang ia sesali. Ia berkata kepada janda seorang nelayan bahwa ia akan membawa pulang putranya dari pulau penjara sebelum hari pertama musim semi, sebelum ia tahu betapa sulitnya itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_7', 'bok_the-pirate-who-kept-every-promise', 7, 'rahma-7', 'Her crew told her to let it go. It was one promise. Nobody would blame her. Rahma said, "They would not blame me. They would simply stop believing me. And then I would have nothing at all."', 'Awak kapalnya menyuruhnya melupakan saja. Itu hanya satu janji. Tidak ada yang akan menyalahkannya. Rahma berkata, "Mereka memang tidak akan menyalahkanku. Mereka hanya akan berhenti mempercayaiku. Dan saat itu aku tidak punya apa-apa lagi."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_8', 'bok_the-pirate-who-kept-every-promise', 8, 'rahma-8', 'It took her nine weeks, three bribes, one storm and a rope ladder she made herself. She delivered the boy to his mother''s door on the last night of winter, one day early, because she had said the first day of spring.', 'Butuh sembilan minggu, tiga kali menyuap, satu badai, dan tangga tali yang ia buat sendiri. Ia mengantar anak itu ke depan pintu ibunya pada malam terakhir musim dingin, sehari lebih awal, karena ia berjanji sebelum hari pertama musim semi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-pirate-who-kept-every-promise_9', 'bok_the-pirate-who-kept-every-promise', 9, 'rahma-9', 'They still tell the story in the southern ports. Not because of the rescue. Because of what it proved: that the most valuable thing a person can own is that when they say something, everybody knows it is true.', 'Kisah itu masih diceritakan di pelabuhan-pelabuhan selatan. Bukan karena penyelamatannya. Melainkan karena apa yang dibuktikannya: bahwa hal paling berharga yang bisa dimiliki seseorang adalah bahwa ketika ia berkata sesuatu, semua orang tahu itu benar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-pirate-who-kept-every-promise_1', 'bok_the-pirate-who-kept-every-promise', 1, 'Why was Captain Rahma feared?', 'Mengapa Kapten Rahma ditakuti?', '["She had the biggest cannon","She always kept her word","She had the fastest ship","She had the largest crew"]', '["Ia punya meriam terbesar","Ia selalu menepati ucapannya","Kapalnya tercepat","Awaknya terbanyak"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-pirate-who-kept-every-promise_2', 'bok_the-pirate-who-kept-every-promise', 2, 'What happened to Captain Bram after he broke a promise?', 'Apa yang terjadi pada Kapten Bram setelah ia ingkar janji?', '["He became rich","Every ship fought him to the end","Nothing changed","He was made a hero"]', '["Ia menjadi kaya","Setiap kapal melawannya sampai akhir","Tidak ada yang berubah","Ia dijadikan pahlawan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-pirate-who-kept-every-promise_3', 'bok_the-pirate-who-kept-every-promise', 3, 'Why did Rahma keep the difficult promise?', 'Mengapa Rahma menepati janji yang sulit itu?', '["For the money","Because being believed was everything she had","Because she was ordered to","By accident"]', '["Demi uang","Karena dipercaya adalah segalanya yang ia miliki","Karena diperintah","Secara kebetulan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-knight-who-would-not-fight', 'the-knight-who-would-not-fight', 'The Knight Who Would Not Fight', 'Ksatria yang Menolak Bertarung', 'Sir Anindita is the finest swordsman in the kingdom. She has also not drawn her sword in six years, and there is a reason.', 'Sir Anindita adalah pemain pedang terbaik di kerajaan. Ia juga tidak menghunus pedangnya selama enam tahun, dan ada alasannya.', 'cat_princess-knights', 'aut_axto-creative-team', 'forest', '👑', 7, 11, 0, 'published', 9, 2903, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_1', 'bok_the-knight-who-would-not-fight', 1, 'anin-1', 'Sir Anindita had won every tournament she entered before she was twenty. She was the finest swordsman the kingdom had produced in a hundred years, and everybody said so, including the people she had beaten.', 'Sir Anindita telah memenangi setiap turnamen yang ia ikuti sebelum berusia dua puluh tahun. Ia pemain pedang terbaik yang dihasilkan kerajaan dalam seratus tahun, dan semua orang mengatakannya, termasuk mereka yang ia kalahkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_2', 'bok_the-knight-who-would-not-fight', 2, 'anin-2', 'Then, one autumn, she stopped. She did not resign. She did not explain. She simply stopped drawing her sword, and for six years nobody could persuade her to say why.', 'Lalu, pada suatu musim gugur, ia berhenti. Ia tidak mengundurkan diri. Ia tidak menjelaskan. Ia hanya berhenti menghunus pedangnya, dan selama enam tahun tak seorang pun bisa membujuknya menjelaskan alasannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_3', 'bok_the-knight-who-would-not-fight', 3, 'anin-3', 'The young knights whispered that she had lost her nerve. The old ones said nothing, because they had been at the border that autumn too and they remembered what a battle actually looks like afterwards.', 'Para ksatria muda berbisik bahwa ia sudah kehilangan nyali. Para ksatria tua tidak berkata apa-apa, karena mereka juga berada di perbatasan pada musim gugur itu dan mereka ingat seperti apa sebenarnya rupa medan perang sesudahnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_4', 'bok_the-knight-who-would-not-fight', 4, 'anin-4', 'When the dispute with the river villages began, the council wanted Anindita to lead. She said she would go, but not to fight. "Then what use are you?" asked a young lord. She said, "We shall see."', 'Ketika perselisihan dengan desa-desa tepi sungai dimulai, dewan ingin Anindita memimpin. Ia berkata ia akan pergi, tetapi bukan untuk bertarung. "Lalu apa gunanya kau?" tanya seorang bangsawan muda. Ia menjawab, "Kita lihat nanti."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_5', 'bok_the-knight-who-would-not-fight', 5, 'anin-5', 'She rode to the river alone, without armour, and sat down on the bank in full view of both sides. She stayed there three days. On the first day people shouted at her. On the second, they came to look.', 'Ia berkuda ke sungai seorang diri, tanpa baju zirah, lalu duduk di tepian dalam pandangan kedua pihak. Ia bertahan di sana tiga hari. Hari pertama orang-orang meneriakinya. Hari kedua, mereka datang untuk melihat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_6', 'bok_the-knight-who-would-not-fight', 6, 'anin-6', 'On the third day the headman of the river villages sat down beside her, because it is very difficult to keep shouting at somebody who will not shout back and has clearly brought her own lunch.', 'Hari ketiga kepala desa dari desa tepi sungai duduk di sampingnya, karena sangat sulit terus berteriak kepada orang yang tidak membalas berteriak dan jelas-jelas membawa bekal makan siangnya sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_7', 'bok_the-knight-who-would-not-fight', 7, 'anin-7', 'What they were arguing about, it turned out, was a weir built forty years earlier that flooded one village every spring and dried another every summer. Nobody had asked. Everybody had assumed.', 'Ternyata yang mereka perselisihkan adalah sebuah bendungan yang dibangun empat puluh tahun sebelumnya, yang membanjiri satu desa setiap musim semi dan mengeringkan desa lain setiap musim panas. Tidak ada yang pernah bertanya. Semua hanya berasumsi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_8', 'bok_the-knight-who-would-not-fight', 8, 'anin-8', 'It took eleven days and two arguments and one afternoon when everything nearly collapsed. But at the end of it there was a plan for the weir, signed by both sides, and not one person had been hurt.', 'Butuh sebelas hari, dua kali pertengkaran, dan satu sore ketika semuanya nyaris gagal. Tetapi di akhirnya ada rencana untuk bendungan itu, ditandatangani kedua pihak, dan tidak seorang pun terluka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-knight-who-would-not-fight_9', 'bok_the-knight-who-would-not-fight', 9, 'anin-9', 'Back at the castle the young lord asked her again what use a knight was who would not fight. Anindita said, "The sword was always the easy part. Anyone can end a thing. Try beginning one."', 'Kembali di kastel, bangsawan muda itu bertanya lagi apa gunanya ksatria yang menolak bertarung. Anindita menjawab, "Pedang selalu bagian yang mudah. Siapa pun bisa mengakhiri sesuatu. Cobalah memulai sesuatu."');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-knight-who-would-not-fight_1', 'bok_the-knight-who-would-not-fight', 1, 'What had Sir Anindita stopped doing?', 'Apa yang berhenti dilakukan Sir Anindita?', '["Riding horses","Drawing her sword","Speaking","Wearing armour to feasts"]', '["Menunggang kuda","Menghunus pedangnya","Berbicara","Memakai zirah ke perjamuan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-knight-who-would-not-fight_2', 'bok_the-knight-who-would-not-fight', 2, 'What did she do at the river?', 'Apa yang ia lakukan di sungai?', '["Attacked at dawn","Sat down in view of both sides for three days","Built a wall","Burned the weir"]', '["Menyerang saat fajar","Duduk dalam pandangan kedua pihak selama tiga hari","Membangun tembok","Membakar bendungan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-knight-who-would-not-fight_3', 'bok_the-knight-who-would-not-fight', 3, 'What was the argument really about?', 'Sebenarnya apa yang mereka perselisihkan?', '["An old insult","A weir that flooded one village and dried another","A stolen horse","A border stone"]', '["Hinaan lama","Bendungan yang membanjiri satu desa dan mengeringkan desa lain","Kuda yang dicuri","Batu perbatasan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-shop-that-sold-nothing', 'the-shop-that-sold-nothing', 'The Shop That Sold Nothing', 'Toko yang Tidak Menjual Apa-apa', 'A strange little shop appears between the baker and the barber, and the sign in the window says exactly what it has in stock.', 'Sebuah toko kecil yang aneh muncul di antara toko roti dan tukang cukur, dan papan di jendelanya menyebutkan persis apa yang tersedia.', 'cat_fantasy', 'aut_axto-creative-team', 'twilight', '🪄', 6, 10, 0, 'published', 9, 851, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_1', 'bok_the-shop-that-sold-nothing', 1, 'nothing-1', 'The shop appeared on a Tuesday, in a gap between the baker and the barber where there had never been a gap before. It was narrow, painted green, and the sign in the window said: WE SELL NOTHING.', 'Toko itu muncul pada hari Selasa, di sebuah celah antara toko roti dan tukang cukur, tempat yang sebelumnya tidak pernah ada celah. Toko itu sempit, dicat hijau, dan papan di jendelanya bertuliskan: KAMI MENJUAL KETIADAAN.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_2', 'bok_the-shop-that-sold-nothing', 2, 'nothing-2', 'Inside there were shelves, and on the shelves there were jars, and in the jars there was — as advertised — nothing at all. Each jar had a small handwritten label.', 'Di dalamnya ada rak-rak, dan di rak-rak itu ada toples, dan di dalam toples itu ada — persis seperti diiklankan — ketiadaan. Setiap toples punya label kecil yang ditulis tangan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_3', 'bok_the-shop-that-sold-nothing', 3, 'nothing-3', 'A NIGHT WITH NOTHING TO WORRY ABOUT, said one. A MORNING WITH NOTHING TO RUSH FOR, said another. Bening read them all and said, "But the jars are empty." The shopkeeper said, "Yes. That is what you are buying."', 'SATU MALAM TANPA HAL YANG DICEMASKAN, tulis salah satunya. SATU PAGI TANPA HAL YANG DIKEJAR, tulis yang lain. Bening membaca semuanya lalu berkata, "Tapi toplesnya kosong." Penjaga toko menjawab, "Ya. Itulah yang kau beli."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_4', 'bok_the-shop-that-sold-nothing', 4, 'nothing-4', 'The prices were strange. A NIGHT WITH NOTHING TO WORRY ABOUT cost one worry, handed over. A MORNING WITH NOTHING TO RUSH FOR cost one appointment, cancelled. Everything was paid for in the thing it removed.', 'Harganya aneh. SATU MALAM TANPA HAL YANG DICEMASKAN berharga satu kecemasan, yang diserahkan. SATU PAGI TANPA HAL YANG DIKEJAR berharga satu janji temu, yang dibatalkan. Semuanya dibayar dengan hal yang dihilangkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_5', 'bok_the-shop-that-sold-nothing', 5, 'nothing-5', 'Bening''s mother came in the next day. She was carrying so many things that she had to put three of them down to open the door, and she stood in front of the shelves for a long time without speaking.', 'Ibu Bening datang keesokan harinya. Ia membawa begitu banyak barang sampai harus meletakkan tiga di antaranya untuk membuka pintu, dan ia berdiri lama di depan rak-rak itu tanpa berkata apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_6', 'bok_the-shop-that-sold-nothing', 6, 'nothing-6', 'She bought AN AFTERNOON WITH NOTHING IN IT. The price was one afternoon of things she had agreed to do for people who had not thanked her. She paid it, and the shopkeeper wrapped the empty jar in brown paper.', 'Ia membeli SATU SORE YANG KOSONG. Harganya adalah satu sore penuh urusan yang ia sanggupi untuk orang-orang yang tidak berterima kasih. Ia membayarnya, dan penjaga toko membungkus toples kosong itu dengan kertas cokelat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_7', 'bok_the-shop-that-sold-nothing', 7, 'nothing-7', 'That Sunday, Bening''s mother did not do anything. She sat on the back step with a cup of tea going cold beside her and watched a bird on the fence for about forty minutes. It was the best afternoon of her year.', 'Minggu itu, ibu Bening tidak melakukan apa-apa. Ia duduk di anak tangga belakang dengan secangkir teh yang mendingin di sampingnya dan mengamati seekor burung di pagar selama sekitar empat puluh menit. Itu sore terbaik sepanjang tahunnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_8', 'bok_the-shop-that-sold-nothing', 8, 'nothing-8', 'On Monday the shop was gone. The gap between the baker and the barber had closed as if it had never been there, and the wall was old brick with moss on it, the way it had always been.', 'Pada hari Senin toko itu lenyap. Celah antara toko roti dan tukang cukur telah menutup seolah-olah tidak pernah ada, dan dindingnya adalah bata tua berlumut, seperti sedia kala.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shop-that-sold-nothing_9', 'bok_the-shop-that-sold-nothing', 9, 'nothing-9', 'Bening still has the brown paper. And every few weeks her mother says, "I think I shall have an afternoon with nothing in it," and goes and sits on the step. It turns out you do not actually need the shop.', 'Bening masih menyimpan kertas cokelat itu. Dan setiap beberapa minggu ibunya berkata, "Sepertinya aku mau satu sore yang kosong," lalu pergi duduk di anak tangga. Ternyata kita tidak benar-benar membutuhkan toko itu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shop-that-sold-nothing_1', 'bok_the-shop-that-sold-nothing', 1, 'What did the shop sell?', 'Apa yang dijual toko itu?', '["Magic potions","Jars of nothing","Bread","Old books"]', '["Ramuan sihir","Toples berisi ketiadaan","Roti","Buku tua"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shop-that-sold-nothing_2', 'bok_the-shop-that-sold-nothing', 2, 'How did people pay?', 'Bagaimana orang membayarnya?', '["With gold","With the very thing being removed","With songs","It was free"]', '["Dengan emas","Dengan hal yang justru dihilangkan itu","Dengan lagu","Gratis"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shop-that-sold-nothing_3', 'bok_the-shop-that-sold-nothing', 3, 'What did Bening''s mother learn?', 'Apa yang dipelajari ibu Bening?', '["To buy more jars","That she can give herself an empty afternoon without the shop","That the shop was a trick","To work harder"]', '["Membeli lebih banyak toples","Bahwa ia bisa memberi dirinya sore yang kosong tanpa toko itu","Bahwa toko itu tipuan","Bekerja lebih keras"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-crow-who-collected-buttons', 'the-crow-who-collected-buttons', 'The Crow Who Collected Buttons', 'Gagak yang Mengumpulkan Kancing', 'A crow takes small shiny things from the whole village. Nobody minds until she takes the wrong one — and then something unexpected happens.', 'Seekor gagak mengambil benda-benda kecil berkilau dari seluruh desa. Tak ada yang keberatan sampai ia mengambil benda yang salah — lalu terjadilah sesuatu yang tak terduga.', 'cat_animals', 'aut_axto-creative-team', 'twilight', '🐦‍⬛', 5, 9, 0, 'published', 9, 3500, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_1', 'bok_the-crow-who-collected-buttons', 1, 'crow-1', 'There was a crow in the village of Sumberan who collected things. Not food — she found her own food. She collected small bright objects and kept them in a hollow at the top of the tallest pine.', 'Ada seekor gagak di desa Sumberan yang suka mengumpulkan benda. Bukan makanan — ia mencari makanannya sendiri. Ia mengumpulkan benda-benda kecil berkilau dan menyimpannya di lubang pohon pinus tertinggi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_2', 'bok_the-crow-who-collected-buttons', 2, 'crow-2', 'Buttons, mostly. Also a bottle cap, two coins, a hairpin, a key that opened nothing anyone knew of, and one very small spoon. The village had grown used to it. Things went missing. That was simply the crow.', 'Kebanyakan kancing. Juga tutup botol, dua keping uang logam, jepit rambut, sebuah kunci yang tak diketahui membuka apa, dan satu sendok yang sangat kecil. Desa itu sudah terbiasa. Barang-barang hilang. Itu memang ulah si gagak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_3', 'bok_the-crow-who-collected-buttons', 3, 'crow-3', 'Then one afternoon she took Bu Tini''s wedding ring from the window ledge where it had been left while Bu Tini washed the rice. And that was different, because Bu Tini''s husband had died four years earlier.', 'Lalu suatu sore ia mengambil cincin kawin Bu Tini dari tepi jendela, tempat cincin itu ditaruh saat Bu Tini mencuci beras. Dan itu berbeda, karena suami Bu Tini telah meninggal empat tahun sebelumnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_4', 'bok_the-crow-who-collected-buttons', 4, 'crow-4', 'The whole village came out. Some brought ladders. One man brought a slingshot and was told very firmly to put it away. Nobody could climb high enough, and the crow sat at the top and watched them all.', 'Seluruh desa keluar. Ada yang membawa tangga. Seorang lelaki membawa ketapel dan dengan tegas disuruh menyimpannya kembali. Tak seorang pun bisa memanjat cukup tinggi, dan si gagak duduk di puncak sambil memandangi mereka semua.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_5', 'bok_the-crow-who-collected-buttons', 5, 'crow-5', 'A boy named Eko had a different idea. He had watched the crow all summer, and he had noticed something: she never took a thing. She traded. Wherever something vanished, a small stone or a feather was left behind.', 'Seorang anak bernama Eko punya gagasan lain. Ia mengamati si gagak sepanjang musim panas, dan ia menyadari sesuatu: gagak itu tidak pernah sekadar mengambil. Ia menukar. Di mana pun sesuatu lenyap, tertinggal sebutir kerikil atau sehelai bulu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_6', 'bok_the-crow-who-collected-buttons', 6, 'crow-6', 'So Eko put a saucer on the wall by the pine tree. In it he placed the shiniest thing he owned: a broken watch face, silver, catching the light. And then he sat down on the grass and waited, and did not look up.', 'Maka Eko meletakkan sebuah lepek di tembok dekat pohon pinus. Di atasnya ia taruh benda paling berkilau miliknya: pecahan kaca jam tangan, keperakan, memantulkan cahaya. Lalu ia duduk di rumput dan menunggu, tanpa menengadah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_7', 'bok_the-crow-who-collected-buttons', 7, 'crow-7', 'It took two days. On the second evening there was a small sound, and when Eko looked, the watch face was gone and the saucer held a hairpin, a bottle cap, and a thin gold ring.', 'Butuh dua hari. Pada malam kedua terdengar bunyi kecil, dan ketika Eko melihat, pecahan kaca jam itu sudah lenyap dan di lepek tergeletak sebuah jepit rambut, tutup botol, dan sebentuk cincin emas tipis.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_8', 'bok_the-crow-who-collected-buttons', 8, 'crow-8', 'Bu Tini held the ring in her hand for a long moment without saying anything at all. Then she asked Eko how he had known, and Eko said, "I watched her. She was never stealing. She was swapping."', 'Bu Tini menggenggam cincin itu lama sekali tanpa berkata apa pun. Lalu ia bertanya kepada Eko bagaimana ia bisa tahu, dan Eko menjawab, "Saya mengamatinya. Ia tidak pernah mencuri. Ia menukar."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-crow-who-collected-buttons_9', 'bok_the-crow-who-collected-buttons', 9, 'crow-9', 'The saucer is still on the wall. People put things in it now — a marble, a foil sweet wrapper, a bead. And most mornings there is something else there instead, left by a crow who has always, all along, been trading fairly.', 'Lepek itu masih ada di tembok. Kini orang-orang meletakkan sesuatu di sana — kelereng, bungkus permen berkilau, manik-manik. Dan hampir setiap pagi ada benda lain sebagai gantinya, ditinggalkan seekor gagak yang sejak dulu selalu menukar dengan adil.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-who-collected-buttons_1', 'bok_the-crow-who-collected-buttons', 1, 'What did the crow collect?', 'Apa yang dikumpulkan si gagak?', '["Food","Small shiny objects","Leaves","Sticks"]', '["Makanan","Benda-benda kecil berkilau","Daun","Ranting"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-who-collected-buttons_2', 'bok_the-crow-who-collected-buttons', 2, 'What had Eko noticed about her?', 'Apa yang Eko sadari tentang si gagak?', '["She was hungry","She always left something behind in trade","She was afraid of people","She could speak"]', '["Ia lapar","Ia selalu meninggalkan sesuatu sebagai tukaran","Ia takut manusia","Ia bisa bicara"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-crow-who-collected-buttons_3', 'bok_the-crow-who-collected-buttons', 3, 'How did Eko get the ring back?', 'Bagaimana Eko mendapatkan cincin itu kembali?', '["He climbed the tree","He offered something shinier in a saucer","He frightened the crow","He asked the village"]', '["Ia memanjat pohon","Ia menawarkan benda yang lebih berkilau di sebuah lepek","Ia menakuti si gagak","Ia meminta bantuan desa"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-octopus-who-redecorated', 'the-octopus-who-redecorated', 'The Octopus Who Redecorated', 'Gurita yang Menata Ulang Rumahnya', 'Nita the octopus rearranges her doorstep every single day, and a passing turtle wants to know why she bothers.', 'Nita si gurita menata ulang halaman rumahnya setiap hari, dan seekor penyu yang lewat ingin tahu mengapa ia repot-repot.', 'cat_ocean-life', 'aut_axto-creative-team', 'ocean', '🐙', 4, 8, 0, 'published', 9, 4655, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_1', 'bok_the-octopus-who-redecorated', 1, 'octo-1', 'Nita lived under a ledge of rock where the cold water met the warm. She had eight arms, three hearts, and blue blood, all of which were normal, and one habit that was not.', 'Nita tinggal di bawah tonjolan batu tempat air dingin bertemu air hangat. Ia punya delapan lengan, tiga jantung, dan darah biru, yang semuanya normal, serta satu kebiasaan yang tidak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_2', 'bok_the-octopus-who-redecorated', 2, 'octo-2', 'Every morning she rearranged her doorstep. Shells here. Flat stones there. A curve of coral moved half a body-length to the left, considered, and moved back again.', 'Setiap pagi ia menata ulang halaman rumahnya. Kerang di sini. Batu pipih di sana. Sepotong karang melengkung digeser setengah badan ke kiri, dipertimbangkan, lalu dikembalikan lagi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_3', 'bok_the-octopus-who-redecorated', 3, 'octo-3', 'A turtle called Sabar drifted past most weeks, because turtles drift and are in no hurry. "You did that yesterday," he observed. "And the day before. It looked perfectly fine both times."', 'Seekor penyu bernama Sabar hanyut lewat hampir setiap minggu, karena penyu memang hanyut dan tidak pernah terburu-buru. "Kau melakukan itu kemarin," katanya. "Dan kemarinnya lagi. Padahal keduanya sudah tampak bagus."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_4', 'bok_the-octopus-who-redecorated', 4, 'octo-4', '"It was fine," Nita agreed. "But the light has changed. In summer it comes over the ledge. In autumn it comes under it. A doorstep for summer light is the wrong doorstep in autumn."', '"Memang bagus," Nita setuju. "Tetapi cahayanya berubah. Di musim panas cahaya datang dari atas tonjolan. Di musim gugur dari bawahnya. Halaman untuk cahaya musim panas adalah halaman yang keliru di musim gugur."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_5', 'bok_the-octopus-who-redecorated', 5, 'octo-5', 'Sabar thought about this for a while, as turtles do. "I have had the same shell my whole life," he said eventually. "I have never once rearranged it." "No," said Nita kindly. "You carry your house. I have to build mine."', 'Sabar memikirkannya sejenak, sebagaimana penyu biasanya. "Aku punya cangkang yang sama seumur hidupku," katanya akhirnya. "Aku tidak pernah sekali pun menatanya ulang." "Memang tidak," kata Nita dengan ramah. "Kau membawa rumahmu. Aku harus membangun rumahku."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_6', 'bok_the-octopus-who-redecorated', 6, 'octo-6', 'Then the storm came. It came from the north and it moved the sand and it broke coral that had stood for forty years. Sabar pulled his head in and let it pass over him.', 'Lalu datanglah badai. Ia datang dari utara, memindahkan pasir, dan mematahkan karang yang telah berdiri empat puluh tahun. Sabar menarik kepalanya masuk dan membiarkan badai lewat di atasnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_7', 'bok_the-octopus-who-redecorated', 7, 'octo-7', 'When it was over he swam back to the ledge, and he expected to find nothing. Instead he found Nita already outside, moving a shell, because her doorstep had held. All that rearranging had taught her exactly which stones did not shift.', 'Ketika badai berlalu ia berenang kembali ke tonjolan batu, dan ia mengira tidak akan menemukan apa-apa. Sebaliknya, ia menemukan Nita sudah di luar, memindahkan sebuah kerang, karena halaman rumahnya bertahan. Semua penataan ulang itu telah mengajarinya persis batu mana yang tidak bergeser.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_8', 'bok_the-octopus-who-redecorated', 8, 'octo-8', '"You were not fussing," said Sabar slowly. "You were learning your own front door." Nita moved the coral half a body-length to the left, considered it, and left it there this time.', '"Kau bukan sedang cerewet," kata Sabar perlahan. "Kau sedang mempelajari pintu depanmu sendiri." Nita menggeser karang itu setengah badan ke kiri, mempertimbangkannya, dan kali ini membiarkannya di sana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-octopus-who-redecorated_9', 'bok_the-octopus-who-redecorated', 9, 'octo-9', 'Sabar still drifts past most weeks. He no longer asks why she bothers. Sometimes he brings her a good flat stone he has found, and she takes it seriously, and puts it somewhere exact.', 'Sabar masih hanyut lewat hampir setiap minggu. Ia tidak lagi bertanya mengapa Nita repot-repot. Kadang ia membawakan batu pipih bagus yang ia temukan, dan Nita menerimanya dengan serius, lalu meletakkannya di tempat yang tepat.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-octopus-who-redecorated_1', 'bok_the-octopus-who-redecorated', 1, 'Why did Nita rearrange her doorstep?', 'Mengapa Nita menata ulang halaman rumahnya?', '["She was bored","Because the light changed with the seasons","To hide from turtles","She had lost something"]', '["Ia bosan","Karena cahaya berubah seiring musim","Untuk bersembunyi dari penyu","Ia kehilangan sesuatu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-octopus-who-redecorated_2', 'bok_the-octopus-who-redecorated', 2, 'What happened to Nita''s doorstep in the storm?', 'Apa yang terjadi pada halaman Nita saat badai?', '["It was destroyed","It held","It floated away","It turned to sand"]', '["Hancur","Bertahan","Hanyut","Menjadi pasir"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-octopus-who-redecorated_3', 'bok_the-octopus-who-redecorated', 3, 'What did Sabar finally understand?', 'Apa yang akhirnya Sabar pahami?', '["That Nita was fussy","That all her practice had taught her which stones held","That storms are harmless","That turtles are better"]', '["Bahwa Nita cerewet","Bahwa latihannya mengajarinya batu mana yang kuat","Bahwa badai tidak berbahaya","Bahwa penyu lebih baik"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-stream-that-came-back', 'the-stream-that-came-back', 'The Stream That Came Back', 'Sungai Kecil yang Kembali', 'There used to be a stream behind the school. The oldest people remember it. A class of nine-year-olds decides to find out where it went.', 'Dulu ada sungai kecil di belakang sekolah. Orang-orang tertua mengingatnya. Sekelas anak berusia sembilan tahun memutuskan mencari tahu ke mana perginya.', 'cat_nature-environment', 'aut_axto-creative-team', 'meadow', '🌳', 7, 11, 0, 'published', 9, 5057, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_1', 'bok_the-stream-that-came-back', 1, 'stream-1', 'Behind the school at Cempaka there was a long strip of dry ground where nothing much grew: hard packed earth, a few thistles, and a shallow dip running along it that nobody thought about.', 'Di belakang sekolah Cempaka ada sebidang tanah kering memanjang yang hampir tidak ditumbuhi apa-apa: tanah keras memadat, beberapa rumput berduri, dan cekungan dangkal memanjang yang tak seorang pun pikirkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_2', 'bok_the-stream-that-came-back', 2, 'stream-2', 'Then Pak Bakri, who was ninety-one and came to every school concert, said something at the end of one. He said, "We used to catch fish there. Behind the fence. When I was your size."', 'Lalu Pak Bakri, yang berusia sembilan puluh satu tahun dan datang ke setiap pentas sekolah, mengucapkan sesuatu di akhir acara. Ia berkata, "Dulu kami memancing di sana. Di balik pagar. Waktu saya sebesar kalian."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_3', 'bok_the-stream-that-came-back', 3, 'stream-3', 'Class 4B did not let this go. They found an old map in the district office, badly folded, from before any of their parents were born. And on it, running exactly along the dry dip, was a thin blue line.', 'Kelas 4B tidak melepaskan begitu saja. Mereka menemukan peta tua di kantor kecamatan, terlipat berantakan, dari masa sebelum orang tua mereka lahir. Dan di peta itu, membentang persis di sepanjang cekungan kering, ada garis biru tipis.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_4', 'bok_the-stream-that-came-back', 4, 'stream-4', 'It had not dried up. It had been buried. Somewhere upstream it had been put into a concrete pipe and sent underground, and everything downstream of that had simply stopped being a stream at all.', 'Sungai itu tidak mengering. Ia dikubur. Di suatu tempat di hulu, ia dimasukkan ke dalam pipa beton dan dialirkan ke bawah tanah, dan segala yang ada di hilirnya berhenti menjadi sungai sama sekali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_5', 'bok_the-stream-that-came-back', 5, 'stream-5', 'The children wrote letters. Eleven of them, to the district office, the water authority, and a newspaper. Nine got no reply. One got a polite refusal. One got a phone call from an engineer named Bu Hesti who asked to visit.', 'Anak-anak menulis surat. Sebelas pucuk, kepada kantor kecamatan, dinas pengairan, dan sebuah surat kabar. Sembilan tidak dibalas. Satu dibalas penolakan sopan. Satu berbuah telepon dari seorang insinyur bernama Bu Hesti yang minta berkunjung.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_6', 'bok_the-stream-that-came-back', 6, 'stream-6', 'Bu Hesti walked the dry dip with a class of nine-year-olds explaining it to her, which she said afterwards was the best site visit of her career. Then she said the difficult part: it would cost money, and take years.', 'Bu Hesti menyusuri cekungan kering itu sementara sekelas anak sembilan tahun menjelaskannya kepadanya, yang kemudian ia sebut kunjungan lapangan terbaik dalam kariernya. Lalu ia mengatakan bagian yang sulit: itu akan makan biaya, dan butuh bertahun-tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_7', 'bok_the-stream-that-came-back', 7, 'stream-7', 'It took six. The children who wrote the letters were fifteen by the time the machines came, and some had moved away. Three came back for the day the pipe was opened.', 'Butuh enam tahun. Anak-anak yang menulis surat sudah berusia lima belas ketika alat berat datang, dan sebagian sudah pindah. Tiga di antaranya datang kembali pada hari pipa itu dibuka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_8', 'bok_the-stream-that-came-back', 8, 'stream-8', 'The water came out slowly at first, brown and unsure, feeling its way along a bed it had not used in sixty years. By the second week it ran clear. By the second spring there were reeds, and then frogs, and then, one morning, a heron.', 'Airnya keluar perlahan mula-mula, cokelat dan ragu, meraba-raba dasar yang tak ia lalui selama enam puluh tahun. Pada minggu kedua airnya jernih. Pada musim semi kedua tumbuh alang-alang, lalu katak, dan kemudian, suatu pagi, seekor bangau.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stream-that-came-back_9', 'bok_the-stream-that-came-back', 9, 'stream-9', 'Pak Bakri was ninety-seven. They wheeled him down to the bank and he sat and looked at it for a long time. Then he said, "There," and pointed at a bend, "that is where the fish were." And there were fish there.', 'Pak Bakri berusia sembilan puluh tujuh. Mereka mendorong kursi rodanya ke tepi sungai dan ia duduk memandanginya lama sekali. Lalu ia berkata, "Di sana," sambil menunjuk sebuah tikungan, "di situlah ikannya dulu." Dan memang ada ikan di sana.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stream-that-came-back_1', 'bok_the-stream-that-came-back', 1, 'What had happened to the stream?', 'Apa yang terjadi pada sungai kecil itu?', '["It dried up","It had been buried in a pipe underground","It changed direction","It froze"]', '["Mengering","Dikubur dalam pipa di bawah tanah","Berubah arah","Membeku"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stream-that-came-back_2', 'bok_the-stream-that-came-back', 2, 'How did the children find out?', 'Bagaimana anak-anak mengetahuinya?', '["They dug a hole","An old man remembered it and an old map showed it","A teacher told them","They guessed"]', '["Mereka menggali lubang","Seorang kakek mengingatnya dan peta tua menunjukkannya","Guru memberi tahu","Mereka menebak"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stream-that-came-back_3', 'bok_the-stream-that-came-back', 3, 'How long did the work take?', 'Berapa lama pengerjaannya?', '["Six weeks","Six months","Six years","Sixty years"]', '["Enam minggu","Enam bulan","Enam tahun","Enam puluh tahun"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-lantern-i-was-not-allowed-to-carry', 'the-lantern-i-was-not-allowed-to-carry', 'The Lantern I Was Not Allowed to Carry', 'Lampion yang Tak Boleh Kubawa', 'At the festival every child carries a lantern. Ari is six, and this year he is told he is still too small — which is not the end of the story.', 'Di festival itu setiap anak membawa lampion. Ari berumur enam tahun, dan tahun ini ia dibilang masih terlalu kecil — dan itu belum akhir ceritanya.', 'cat_holidays-culture', 'aut_axto-creative-team', 'sunrise', '🏮', 4, 8, 0, 'published', 9, 2635, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_1', 'bok_the-lantern-i-was-not-allowed-to-carry', 1, 'lantern-1', 'On the last night of the festival, everybody walks from the square to the river carrying a lantern. The small children carry small ones. The older ones carry the tall paper lanterns with a real candle inside.', 'Pada malam terakhir festival, semua orang berjalan dari alun-alun ke sungai sambil membawa lampion. Anak-anak kecil membawa yang kecil. Yang lebih besar membawa lampion kertas tinggi dengan lilin sungguhan di dalamnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_2', 'bok_the-lantern-i-was-not-allowed-to-carry', 2, 'lantern-2', 'Ari was six. He had wanted a tall one for two years. This year he asked, and his mother looked at the candle, and looked at Ari, and said, "Next year."', 'Ari berumur enam tahun. Ia sudah mengingini lampion tinggi selama dua tahun. Tahun ini ia meminta, dan ibunya menatap lilinnya, lalu menatap Ari, lalu berkata, "Tahun depan."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_3', 'bok_the-lantern-i-was-not-allowed-to-carry', 3, 'lantern-3', 'Ari was not fine about this. He said several things he did not entirely mean, and then he sat on the step at the back of the house while the drums started in the square without him.', 'Ari tidak terima. Ia mengucapkan beberapa hal yang sebenarnya tidak sepenuhnya ia maksudkan, lalu duduk di anak tangga belakang rumah sementara tabuhan gendang mulai bergema di alun-alun tanpa dirinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_4', 'bok_the-lantern-i-was-not-allowed-to-carry', 4, 'lantern-4', 'His grandmother came and sat beside him, which took her a while, and did not tell him he was being silly. She said, "Do you know what my job was, the year I was six?"', 'Neneknya datang dan duduk di sampingnya, yang memakan waktu cukup lama baginya, dan tidak mengatakan bahwa Ari sedang bersikap konyol. Ia berkata, "Tahukah kau apa tugasku, ketika aku berumur enam tahun?"');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_5', 'bok_the-lantern-i-was-not-allowed-to-carry', 5, 'lantern-5', '"I carried the matches," she said. "In a tin. All the way to the river. Because the wind comes off the water and lanterns go out, and somebody has to be able to light them again."', '"Aku membawa korek api," katanya. "Dalam kaleng. Sepanjang jalan sampai ke sungai. Karena angin bertiup dari air dan lampion bisa padam, dan harus ada yang bisa menyalakannya kembali."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_6', 'bok_the-lantern-i-was-not-allowed-to-carry', 6, 'lantern-6', 'She took a small tin out of her pocket. It was old, dented, and had a fish painted on the lid. She put it in Ari''s hand and closed his fingers over it and said, "Now it is yours. Do not lose it. Do not open it while we walk."', 'Ia mengeluarkan kaleng kecil dari sakunya. Kaleng itu tua, penyok, dan bergambar ikan di tutupnya. Ia meletakkannya di tangan Ari, mengatupkan jemarinya, dan berkata, "Sekarang ini milikmu. Jangan hilang. Jangan dibuka selama kita berjalan."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_7', 'bok_the-lantern-i-was-not-allowed-to-carry', 7, 'lantern-7', 'They walked. Ari carried the smallest lantern in the whole procession and the tin in his other hand, and he did not once look at the tall lanterns, because he was too busy watching for a light going out.', 'Mereka berjalan. Ari membawa lampion terkecil di seluruh arak-arakan dan kaleng itu di tangan satunya, dan ia sama sekali tidak melirik lampion-lampion tinggi, karena ia terlalu sibuk mengawasi kalau-kalau ada cahaya yang padam.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_8', 'bok_the-lantern-i-was-not-allowed-to-carry', 8, 'lantern-8', 'Near the bridge the wind came off the water exactly as his grandmother had said, and four lanterns went dark at once. Ari was there in nine seconds. His hands shook. He got all four.', 'Di dekat jembatan angin bertiup dari air persis seperti kata neneknya, dan empat lampion padam sekaligus. Ari sampai di sana dalam sembilan detik. Tangannya gemetar. Ia berhasil menyalakan keempatnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-lantern-i-was-not-allowed-to-carry_9', 'bok_the-lantern-i-was-not-allowed-to-carry', 9, 'lantern-9', 'He is nine now and carries a tall one. But he keeps the tin in his pocket every year, and every year he gives it to somebody smaller on the steps at the back of the house, and tells them what it is for.', 'Kini ia berumur sembilan tahun dan membawa lampion tinggi. Tetapi ia menyimpan kaleng itu di sakunya setiap tahun, dan setiap tahun ia memberikannya kepada anak yang lebih kecil di anak tangga belakang rumah, sambil menjelaskan untuk apa kaleng itu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lantern-i-was-not-allowed-to-carry_1', 'bok_the-lantern-i-was-not-allowed-to-carry', 1, 'Why could Ari not carry a tall lantern?', 'Mengapa Ari belum boleh membawa lampion tinggi?', '["He had lost his","He was still too small for the real candle","He was unwell","He did not want one"]', '["Miliknya hilang","Ia masih terlalu kecil untuk lilin sungguhan","Ia sakit","Ia tidak menginginkannya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lantern-i-was-not-allowed-to-carry_2', 'bok_the-lantern-i-was-not-allowed-to-carry', 2, 'What did his grandmother give him?', 'Apa yang neneknya berikan kepadanya?', '["A bigger lantern","A tin of matches and a job","Some money","A drum"]', '["Lampion yang lebih besar","Sekaleng korek api dan sebuah tugas","Sejumlah uang","Sebuah gendang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-lantern-i-was-not-allowed-to-carry_3', 'bok_the-lantern-i-was-not-allowed-to-carry', 3, 'What does Ari do now that he is older?', 'Apa yang Ari lakukan sekarang setelah lebih besar?', '["Keeps the tin to himself","Passes the tin to somebody smaller each year","Stopped going to the festival","Sold the tin"]', '["Menyimpan kaleng itu untuk dirinya","Memberikan kaleng itu kepada anak yang lebih kecil setiap tahun","Berhenti ikut festival","Menjual kaleng itu"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-woman-who-mapped-the-sea-floor', 'the-woman-who-mapped-the-sea-floor', 'The Woman Who Mapped the Sea Floor', 'Perempuan yang Memetakan Dasar Laut', 'She was not allowed on the ship. So she drew the bottom of the ocean from a desk, and found something that changed what we know about the Earth.', 'Ia tidak diizinkan naik kapal. Maka ia menggambar dasar samudra dari balik meja, dan menemukan sesuatu yang mengubah pemahaman kita tentang Bumi.', 'cat_true-stories', 'aut_axto-creative-team', 'ocean', '🗺️', 8, 12, 0, 'published', 9, 4164, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_1', 'bok_the-woman-who-mapped-the-sea-floor', 1, 'seafloor-1', 'For most of human history, nobody knew what the bottom of the ocean looked like. Sailors knew it was deep. That was roughly the extent of it. Maps of the sea were blank, or decorated with guesses.', 'Sepanjang sebagian besar sejarah manusia, tak seorang pun tahu seperti apa rupa dasar samudra. Para pelaut tahu bahwa laut itu dalam. Kira-kira sebatas itu. Peta laut kosong, atau dihias dengan tebakan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_2', 'bok_the-woman-who-mapped-the-sea-floor', 2, 'seafloor-2', 'In the middle of the twentieth century, ships began dragging sound equipment across the Atlantic, sending a ping down and timing how long it took to come back. Long time: deep. Short time: shallow. It produced pages and pages of numbers.', 'Pada pertengahan abad kedua puluh, kapal-kapal mulai menyeret alat pengukur bunyi melintasi Atlantik, mengirim pantulan ke bawah dan menghitung berapa lama ia kembali. Lama: dalam. Sebentar: dangkal. Hasilnya berlembar-lembar angka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_3', 'bok_the-woman-who-mapped-the-sea-floor', 3, 'seafloor-3', 'There was a geologist called Marie Tharp who was extremely good at turning numbers into pictures. She was not permitted on the research ships — at that time women were kept off them — so she worked from a desk on land.', 'Ada seorang ahli geologi bernama Marie Tharp yang sangat mahir mengubah angka menjadi gambar. Ia tidak diizinkan naik kapal riset — pada masa itu perempuan dilarang ikut — maka ia bekerja dari meja di darat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_4', 'bok_the-woman-who-mapped-the-sea-floor', 4, 'seafloor-4', 'The data came back to her in notebooks. She turned each line of soundings into a profile, and each profile into a strip of drawn sea floor, and then she laid the strips side by side to build a picture of a place no human had ever seen.', 'Data itu kembali kepadanya dalam buku catatan. Ia mengubah setiap baris pengukuran menjadi profil, dan setiap profil menjadi lajur gambar dasar laut, lalu ia menjajarkan lajur-lajur itu untuk menyusun gambaran tempat yang belum pernah dilihat manusia.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_5', 'bok_the-woman-who-mapped-the-sea-floor', 5, 'seafloor-5', 'And running down the middle of the Atlantic, in profile after profile, there was a mountain range. That was already suspected. But Tharp saw something else: a deep V-shaped valley running along the very top of it, like a split.', 'Dan membentang di tengah Atlantik, dalam profil demi profil, ada barisan pegunungan. Itu sudah diduga sebelumnya. Tetapi Tharp melihat hal lain: lembah dalam berbentuk V yang membentang tepat di puncaknya, seperti sebuah belahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_6', 'bok_the-woman-who-mapped-the-sea-floor', 6, 'seafloor-6', 'She said what she thought it meant: that the sea floor was splitting apart, and that the continents were therefore moving. Her colleague looked at her work and used a word that has followed the story ever since. He called it girl talk.', 'Ia menyampaikan apa yang menurutnya berarti: bahwa dasar laut sedang terbelah, dan karenanya benua-benua bergerak. Rekannya melihat hasil kerjanya dan memakai sebuah kata yang terus melekat pada kisah ini. Ia menyebutnya omongan perempuan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_7', 'bok_the-woman-who-mapped-the-sea-floor', 7, 'seafloor-7', 'Tharp did not argue. She did something better. She got the map of earthquake locations — where the ground shakes hardest — and laid it over her drawing of the valley. Every earthquake fell inside her line.', 'Tharp tidak berdebat. Ia melakukan sesuatu yang lebih baik. Ia mengambil peta lokasi gempa — tempat tanah paling keras berguncang — dan menumpangkannya di atas gambar lembahnya. Setiap gempa jatuh persis di dalam garisnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_8', 'bok_the-woman-who-mapped-the-sea-floor', 8, 'seafloor-8', 'You cannot argue with that. The two maps agreed, and they agreed because both were describing the same thing: a seam where the Earth is pulling itself apart, all the way down the middle of an ocean.', 'Itu tidak bisa dibantah. Kedua peta itu sepakat, dan mereka sepakat karena keduanya menggambarkan hal yang sama: sebuah jahitan tempat Bumi menarik dirinya terbelah, sepanjang tengah samudra.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-woman-who-mapped-the-sea-floor_9', 'bok_the-woman-who-mapped-the-sea-floor', 9, 'seafloor-9', 'It took years for people to accept it. Tharp kept drawing, and eventually published a map of the whole world''s ocean floor. She finally went to sea in 1968, aged forty-eight, on a ship crossing the ridge she had already drawn from a desk.', 'Butuh bertahun-tahun sampai orang menerimanya. Tharp terus menggambar, dan akhirnya menerbitkan peta dasar samudra seluruh dunia. Ia baru berlayar pada tahun 1968, pada usia empat puluh delapan, di atas kapal yang melintasi punggungan yang telah ia gambar dari balik meja.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-woman-who-mapped-the-sea-floor_1', 'bok_the-woman-who-mapped-the-sea-floor', 1, 'Why did Marie Tharp work from a desk?', 'Mengapa Marie Tharp bekerja dari balik meja?', '["She preferred it","Women were not allowed on the research ships then","She was afraid of water","There were no ships"]', '["Ia lebih suka begitu","Saat itu perempuan tidak diizinkan naik kapal riset","Ia takut air","Tidak ada kapal"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-woman-who-mapped-the-sea-floor_2', 'bok_the-woman-who-mapped-the-sea-floor', 2, 'What did she notice in the middle of the Atlantic?', 'Apa yang ia perhatikan di tengah Atlantik?', '["A flat plain","A deep valley along the top of a mountain range","An island","A whirlpool"]', '["Dataran rata","Lembah dalam di sepanjang puncak barisan pegunungan","Sebuah pulau","Pusaran air"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-woman-who-mapped-the-sea-floor_3', 'bok_the-woman-who-mapped-the-sea-floor', 3, 'How did she prove her idea?', 'Bagaimana ia membuktikan gagasannya?', '["She argued louder","She overlaid the earthquake map and they matched","She went to sea","She waited"]', '["Ia berdebat lebih keras","Ia menumpangkan peta gempa dan keduanya cocok","Ia berlayar","Ia menunggu"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_why-does-bread-rise', 'why-does-bread-rise', 'Why Does Bread Rise?', 'Mengapa Roti Mengembang?', 'Fira wants to know what is actually happening inside the dough. Her father hands her two bowls and says: find out.', 'Fira ingin tahu apa sebenarnya yang terjadi di dalam adonan. Ayahnya menyerahkan dua mangkuk dan berkata: cari tahu sendiri.', 'cat_science', 'aut_axto-creative-team', 'sunrise', '🍞', 6, 10, 0, 'published', 9, 4020, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_1', 'bok_why-does-bread-rise', 1, 'bread-1', 'Fira''s father made bread every Saturday. Fira had watched him a hundred times: flour, water, salt, a spoonful of grey-brown powder, mixing, waiting, and then the dough was twice the size it had been.', 'Ayah Fira membuat roti setiap Sabtu. Fira sudah menontonnya seratus kali: tepung, air, garam, sesendok bubuk cokelat keabu-abuan, diaduk, ditunggu, lalu adonan itu menjadi dua kali lipat besarnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_2', 'bok_why-does-bread-rise', 2, 'bread-2', '"But where does the extra come from?" Fira asked. "You did not add anything." Her father said, "Good question," and got out two bowls instead of answering it.', '"Tapi tambahannya dari mana?" tanya Fira. "Ayah tidak menambahkan apa-apa." Ayahnya berkata, "Pertanyaan bagus," lalu mengeluarkan dua mangkuk alih-alih menjawabnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_3', 'bok_why-does-bread-rise', 3, 'bread-3', 'In both bowls: the same flour, the same water, the same salt. In bowl one he added the grey-brown powder. In bowl two he added nothing. "Now we wait," he said, "and you write down what you see."', 'Di kedua mangkuk: tepung yang sama, air yang sama, garam yang sama. Di mangkuk satu ia menambahkan bubuk cokelat keabu-abuan itu. Di mangkuk dua ia tidak menambahkan apa pun. "Sekarang kita tunggu," katanya, "dan kau catat apa yang kau lihat."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_4', 'bok_why-does-bread-rise', 4, 'bread-4', 'After one hour, bowl two looked exactly the same. Bowl one had risen to the rim and had small holes in the surface, and when Fira put her face close to it, it smelled faintly sour and warm.', 'Setelah satu jam, mangkuk dua tampak persis sama. Mangkuk satu sudah mengembang sampai bibir mangkuk dan permukaannya berlubang-lubang kecil, dan ketika Fira mendekatkan wajahnya, tercium bau asam samar dan hangat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_5', 'bok_why-does-bread-rise', 5, 'bread-5', '"The powder is alive," her father said. "It is called yeast. It is a fungus, and there are billions of them in that spoonful, and every one of them is very small and very hungry."', '"Bubuk itu hidup," kata ayahnya. "Namanya ragi. Ia sejenis jamur, dan ada miliaran di dalam sesendok itu, dan setiap satunya sangat kecil dan sangat lapar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_6', 'bok_why-does-bread-rise', 6, 'bread-6', '"They eat the sugars in the flour. And like everything that eats, they let something out afterwards. What they let out is a gas — carbon dioxide — and it has nowhere to go, so it makes bubbles, and the bubbles push the dough up."', '"Mereka memakan gula dalam tepung. Dan seperti semua makhluk yang makan, mereka mengeluarkan sesuatu sesudahnya. Yang mereka keluarkan adalah gas — karbon dioksida — dan gas itu tidak punya jalan keluar, jadi ia membentuk gelembung, dan gelembung itu mendorong adonan naik."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_7', 'bok_why-does-bread-rise', 7, 'bread-7', 'Fira ran two more tests, because one is never enough. One bowl in the fridge, one on the warm windowsill. The cold one barely moved. The warm one climbed over the edge and onto the sill.', 'Fira melakukan dua percobaan lagi, karena satu tidak pernah cukup. Satu mangkuk di kulkas, satu di ambang jendela yang hangat. Yang dingin nyaris tidak bergerak. Yang hangat memanjat melewati bibir mangkuk dan tumpah ke ambang jendela.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_8', 'bok_why-does-bread-rise', 8, 'bread-8', '"So they are slow when they are cold and fast when they are warm," she said, writing it down, "like everything else alive." And then, after a moment: "So the holes in bread are where they breathed."', '"Jadi mereka lambat saat dingin dan cepat saat hangat," katanya sambil mencatat, "seperti semua makhluk hidup lainnya." Lalu, setelah sesaat: "Berarti lubang-lubang di roti itu bekas mereka bernapas."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_why-does-bread-rise_9', 'bok_why-does-bread-rise', 9, 'bread-9', 'Her father put the loaf in the oven, where the heat kills the yeast and sets the bubbles in place forever. Fira ate two slices and looked very carefully at every hole in them, which is a thing you can only do once you know.', 'Ayahnya memasukkan adonan ke dalam oven, tempat panas mematikan ragi dan mengunci gelembungnya selamanya. Fira memakan dua iris dan mengamati dengan cermat setiap lubang di dalamnya, hal yang hanya bisa kau lakukan setelah kau tahu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-does-bread-rise_1', 'bok_why-does-bread-rise', 1, 'What is yeast?', 'Apa itu ragi?', '["A kind of flour","A living fungus","A salt","A type of water"]', '["Sejenis tepung","Jamur yang hidup","Sejenis garam","Sejenis air"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-does-bread-rise_2', 'bok_why-does-bread-rise', 2, 'What makes the dough rise?', 'Apa yang membuat adonan mengembang?', '["Stirring","Bubbles of gas the yeast lets out","The salt","The bowl"]', '["Pengadukan","Gelembung gas yang dikeluarkan ragi","Garamnya","Mangkuknya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_why-does-bread-rise_3', 'bok_why-does-bread-rise', 3, 'What did the fridge experiment show?', 'Apa yang ditunjukkan percobaan kulkas?', '["Cold makes yeast faster","Yeast is slow when cold and fast when warm","Yeast dies in bowls","Nothing at all"]', '["Dingin membuat ragi lebih cepat","Ragi lambat saat dingin dan cepat saat hangat","Ragi mati di dalam mangkuk","Tidak menunjukkan apa-apa"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_my-brother-does-not-talk', 'my-brother-does-not-talk', 'My Brother Does Not Talk', 'Adikku Tidak Bicara', 'Ines is eight. Her little brother Rio is four and has never said a word. This is a story about the year she stopped waiting for one.', 'Ines berumur delapan tahun. Adiknya, Rio, berumur empat tahun dan belum pernah mengucapkan satu kata pun. Ini kisah tentang tahun ketika Ines berhenti menunggu kata itu.', 'cat_family', 'aut_axto-creative-team', 'sunrise', '👨‍👩‍👧‍👦', 6, 10, 0, 'published', 9, 917, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_1', 'bok_my-brother-does-not-talk', 1, 'rio-1', 'My brother Rio is four and he does not talk. Not shy-does-not-talk. He has never said a word, not once, and the doctors have a name for it and it does not really help to say the name.', 'Adikku Rio berumur empat tahun dan ia tidak bicara. Bukan tidak bicara karena malu. Ia belum pernah mengucapkan satu kata pun, sekali pun, dan para dokter punya sebutan untuk itu, dan menyebutkan namanya tidak terlalu membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_2', 'bok_my-brother-does-not-talk', 2, 'rio-2', 'For a long time I waited. Everybody waited. Every family dinner had a moment where somebody looked at him hopefully, and then the moment passed, and we all ate our rice.', 'Lama sekali aku menunggu. Semua orang menunggu. Setiap makan malam keluarga selalu ada saat ketika seseorang menatapnya penuh harap, lalu saat itu berlalu, dan kami semua melanjutkan makan nasi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_3', 'bok_my-brother-does-not-talk', 3, 'rio-3', 'Then, one Tuesday, I stopped waiting. Not because I gave up. Because I noticed that Rio had been telling me things for years and I had been too busy listening for words to hear any of them.', 'Lalu, pada suatu Selasa, aku berhenti menunggu. Bukan karena menyerah. Melainkan karena aku sadar Rio sudah bertahun-tahun mengatakan banyak hal kepadaku, dan aku terlalu sibuk mendengarkan kata-kata sampai tidak mendengar satu pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_4', 'bok_my-brother-does-not-talk', 4, 'rio-4', 'When Rio is happy he taps twice on whatever is nearest — a table, a wall, my arm. Two taps. Always two. He has done it since he could reach the table, and I had never once counted them.', 'Ketika Rio senang ia mengetuk dua kali pada apa pun yang terdekat — meja, dinding, lenganku. Dua ketukan. Selalu dua. Ia melakukannya sejak bisa menggapai meja, dan aku tidak pernah sekali pun menghitungnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_5', 'bok_my-brother-does-not-talk', 5, 'rio-5', 'When he wants something he does not point at it. He looks at it, then at you, then back at it. That is a whole sentence. It means: that one, please, and I am asking you specifically.', 'Ketika ia menginginkan sesuatu ia tidak menunjuk. Ia menatap benda itu, lalu menatapmu, lalu menatapnya lagi. Itu satu kalimat utuh. Artinya: yang itu, tolong, dan aku memintanya kepadamu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_6', 'bok_my-brother-does-not-talk', 6, 'rio-6', 'When something is too much — too loud, too bright, too many people — he presses the back of his hand against his cheek. That means stop. It has always meant stop. Nobody in our family knew that until I wrote it down.', 'Ketika sesuatu terasa berlebihan — terlalu berisik, terlalu terang, terlalu banyak orang — ia menekankan punggung tangannya ke pipi. Itu artinya berhenti. Selalu berarti berhenti. Tidak ada di keluarga kami yang tahu itu sampai aku menuliskannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_7', 'bok_my-brother-does-not-talk', 7, 'rio-7', 'I made a book. Nine pages, one thing per page, drawn badly with a photograph taped next to it. I gave it to my mother, my father, my grandmother, and Rio''s teacher. Then something changed quite fast.', 'Aku membuat sebuah buku. Sembilan halaman, satu hal per halaman, digambar dengan buruk dengan foto ditempel di sebelahnya. Aku berikan kepada ibuku, ayahku, nenekku, dan guru Rio. Lalu sesuatu berubah cukup cepat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_8', 'bok_my-brother-does-not-talk', 8, 'rio-8', 'Because when people understood him, Rio stopped having as many bad afternoons. It turns out a lot of what we had thought was Rio being difficult was Rio saying something clearly to a room that did not know his language.', 'Karena ketika orang-orang memahaminya, Rio tidak lagi sering mengalami sore yang buruk. Ternyata banyak dari apa yang kami kira Rio sedang sulit sebenarnya adalah Rio berbicara dengan jelas kepada ruangan yang tidak mengerti bahasanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_my-brother-does-not-talk_9', 'bok_my-brother-does-not-talk', 9, 'rio-9', 'He still does not talk. He might one day and he might not. But last week he came and found me, on purpose, from another room, and tapped twice on my arm, and I know exactly what that means.', 'Ia masih tidak bicara. Mungkin suatu hari nanti, mungkin juga tidak. Tetapi minggu lalu ia datang mencariku, dengan sengaja, dari ruangan lain, lalu mengetuk dua kali di lenganku, dan aku tahu persis apa artinya itu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_my-brother-does-not-talk_1', 'bok_my-brother-does-not-talk', 1, 'What does Rio do when he is happy?', 'Apa yang Rio lakukan ketika ia senang?', '["He sings","He taps twice on the nearest thing","He runs","He claps"]', '["Ia bernyanyi","Ia mengetuk dua kali pada benda terdekat","Ia berlari","Ia bertepuk tangan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_my-brother-does-not-talk_2', 'bok_my-brother-does-not-talk', 2, 'What did Ines make?', 'Apa yang Ines buat?', '["A toy","A book explaining what Rio''s signs mean","A song","A drawing of herself"]', '["Sebuah mainan","Buku yang menjelaskan arti isyarat Rio","Sebuah lagu","Gambar dirinya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_my-brother-does-not-talk_3', 'bok_my-brother-does-not-talk', 3, 'What changed once people understood him?', 'Apa yang berubah setelah orang-orang memahaminya?', '["Rio started talking","Rio had far fewer bad afternoons","Rio moved away","Nothing changed"]', '["Rio mulai bicara","Sore-sore buruk Rio jauh berkurang","Rio pindah","Tidak ada yang berubah"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-jar-of-difficult-feelings', 'the-jar-of-difficult-feelings', 'The Jar of Difficult Feelings', 'Toples Perasaan Sulit', 'Ken is angry a lot and does not know why. His teacher gives him a jar, some paper, and one rule.', 'Ken sering marah dan tidak tahu sebabnya. Gurunya memberinya sebuah toples, beberapa lembar kertas, dan satu aturan.', 'cat_emotions', 'aut_axto-creative-team', 'twilight', '🫙', 5, 9, 0, 'published', 9, 3316, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_1', 'bok_the-jar-of-difficult-feelings', 1, 'jar-1', 'Ken was angry a lot that year. It arrived without warning, like weather. One minute he was fine and the next his chest was hot and his hands wanted to push something over.', 'Ken sering marah tahun itu. Kemarahan datang tanpa peringatan, seperti cuaca. Sesaat ia baik-baik saja dan sesaat kemudian dadanya panas dan tangannya ingin mendorong sesuatu sampai jatuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_2', 'bok_the-jar-of-difficult-feelings', 2, 'jar-2', 'Adults kept asking him why. Ken did not know why. That was the worst part — being asked a question about yourself that you genuinely cannot answer, over and over, by people who think you are hiding it.', 'Orang dewasa terus bertanya mengapa. Ken tidak tahu mengapa. Itulah bagian terburuknya — ditanya tentang dirimu sendiri padahal kau sungguh tidak bisa menjawabnya, berulang kali, oleh orang yang mengira kau menyembunyikannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_3', 'bok_the-jar-of-difficult-feelings', 3, 'jar-3', 'Bu Lestari did not ask why. She gave him a glass jar with a screw lid, a stack of small paper squares and a pencil, and one rule: when it happens, write one word. Not a reason. Just what it felt like.', 'Bu Lestari tidak bertanya mengapa. Ia memberinya toples kaca bertutup ulir, setumpuk kertas kecil persegi dan sebatang pensil, serta satu aturan: ketika itu datang, tulis satu kata. Bukan alasannya. Cukup rasanya seperti apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_4', 'bok_the-jar-of-difficult-feelings', 4, 'jar-4', 'The first week the jar filled with the same word over and over. ANGRY. ANGRY. ANGRY. Ken thought this proved the whole thing was pointless and said so, fairly loudly.', 'Minggu pertama toples itu terisi kata yang sama berulang-ulang. MARAH. MARAH. MARAH. Ken mengira ini membuktikan seluruh caranya sia-sia dan mengatakannya, cukup keras.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_5', 'bok_the-jar-of-difficult-feelings', 5, 'jar-5', '"Keep going," said Bu Lestari. In the third week the words started changing. EMBARRASSED, said one. LEFT OUT, said another. One just said TIRED, which surprised him when he read it back.', '"Lanjutkan saja," kata Bu Lestari. Pada minggu ketiga kata-katanya mulai berubah. MALU, tulis salah satunya. TERSISIH, tulis yang lain. Satu hanya bertuliskan LELAH, yang mengejutkannya saat ia membacanya kembali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_6', 'bok_the-jar-of-difficult-feelings', 6, 'jar-6', 'At the end of the month they tipped the jar out on the desk and sorted the papers into piles. The ANGRY pile was big. But next to it there were four other piles, and none of them was anger at all.', 'Di akhir bulan mereka menumpahkan isi toples ke atas meja dan memilah kertas-kertas itu menjadi beberapa tumpukan. Tumpukan MARAH memang besar. Tetapi di sebelahnya ada empat tumpukan lain, dan tak satu pun dari itu kemarahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_7', 'bok_the-jar-of-difficult-feelings', 7, 'jar-7', '"Anger is loud," Bu Lestari said. "It arrives first and shouts over everything else. Most of the time it is standing in front of something quieter." She pointed at the LEFT OUT pile, which was the second biggest.', '"Kemarahan itu berisik," kata Bu Lestari. "Ia datang lebih dulu dan berteriak menutupi yang lain. Sebagian besar waktu ia sedang berdiri menutupi sesuatu yang lebih pelan." Ia menunjuk tumpukan TERSISIH, yang kedua terbesar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_8', 'bok_the-jar-of-difficult-feelings', 8, 'jar-8', 'It did not fix everything. Ken still got angry, and twice more that year he pushed something over. But now, sometimes, in the middle of the hot feeling, he could think: this is the left-out one. And that changed what he did next.', 'Itu tidak menyelesaikan segalanya. Ken masih marah, dan dua kali lagi tahun itu ia mendorong sesuatu sampai jatuh. Tetapi kini, kadang, di tengah rasa panas itu, ia bisa berpikir: ini yang tersisih. Dan itu mengubah apa yang ia lakukan setelahnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-jar-of-difficult-feelings_9', 'bok_the-jar-of-difficult-feelings', 9, 'jar-9', 'He kept the jar. It is on his shelf at home with about sixty papers in it. He does not write in it much any more, but he has never thrown it away, because it is the only place he has ever seen his own feelings from the outside.', 'Ia menyimpan toples itu. Toples itu ada di raknya di rumah dengan sekitar enam puluh lembar kertas di dalamnya. Ia sudah jarang menulis lagi, tetapi ia tidak pernah membuangnya, karena hanya di sanalah ia pernah melihat perasaannya sendiri dari luar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-jar-of-difficult-feelings_1', 'bok_the-jar-of-difficult-feelings', 1, 'What was Bu Lestari''s one rule?', 'Apa satu aturan dari Bu Lestari?', '["Explain why you are angry","Write one word for what it felt like","Count to ten","Say sorry"]', '["Jelaskan mengapa kau marah","Tulis satu kata tentang rasanya","Hitung sampai sepuluh","Minta maaf"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-jar-of-difficult-feelings_2', 'bok_the-jar-of-difficult-feelings', 2, 'What did the piles of paper show?', 'Apa yang ditunjukkan tumpukan kertas itu?', '["Only anger","That other feelings were hiding behind the anger","That the jar was too small","Nothing useful"]', '["Hanya kemarahan","Bahwa ada perasaan lain yang bersembunyi di balik kemarahan","Bahwa toplesnya terlalu kecil","Tidak ada yang berguna"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-jar-of-difficult-feelings_3', 'bok_the-jar-of-difficult-feelings', 3, 'What did Bu Lestari say about anger?', 'Apa kata Bu Lestari tentang kemarahan?', '["It is always bad","It is loud and often stands in front of something quieter","It never changes","It should be hidden"]', '["Selalu buruk","Ia berisik dan sering menutupi sesuatu yang lebih pelan","Tidak pernah berubah","Harus disembunyikan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-elephant-who-remembered-the-water', 'the-elephant-who-remembered-the-water', 'The Elephant Who Remembered the Water', 'Gajah yang Mengingat Letak Air', 'In the worst dry season anyone can recall, the herd follows an old matriarch who has not been that way in thirty years.', 'Pada musim kemarau terburuk yang bisa diingat siapa pun, kawanan itu mengikuti seekor induk tua yang tidak melewati jalan itu selama tiga puluh tahun.', 'cat_jungle-safari', 'aut_axto-creative-team', 'citrus', '🐘', 5, 10, 0, 'published', 9, 4986, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_1', 'bok_the-elephant-who-remembered-the-water', 1, 'eleph-1', 'The dry season came early and stayed. The grass went from green to yellow to grey. The waterhole at the acacia went down and down until it was a ring of cracked mud with a shine in the middle, and then no shine at all.', 'Musim kemarau datang lebih awal dan bertahan lama. Rumput berubah dari hijau ke kuning ke kelabu. Kubangan air di dekat pohon akasia menyusut terus sampai tinggal lingkaran lumpur retak dengan kilauan di tengahnya, lalu tak ada kilauan sama sekali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_2', 'bok_the-elephant-who-remembered-the-water', 2, 'eleph-2', 'The herd waited. Elephants are patient. But the youngest calf had stopped playing, which is the sign every mother in the herd understands without anybody having to say it.', 'Kawanan itu menunggu. Gajah itu sabar. Tetapi anak gajah termuda sudah berhenti bermain, dan itulah tanda yang dipahami setiap induk dalam kawanan tanpa perlu diucapkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_3', 'bok_the-elephant-who-remembered-the-water', 3, 'eleph-3', 'The matriarch was called Old Ma by everyone, though of course elephants do not have names, only the particular sound the herd makes when they mean her. She was sixty-two years old. She stood for a whole afternoon facing north-west.', 'Induk pemimpin itu dipanggil Bunda Tua oleh semua, meskipun tentu saja gajah tidak punya nama, hanya bunyi khas yang dibuat kawanan ketika memaksudkan dirinya. Usianya enam puluh dua tahun. Ia berdiri sepanjang sore menghadap barat laut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_4', 'bok_the-elephant-who-remembered-the-water', 4, 'eleph-4', 'Then she walked, and the herd walked behind her, because that is what a herd does. They walked away from the river they knew, away from the trees they knew, into flat country with nothing in it.', 'Lalu ia berjalan, dan kawanan berjalan di belakangnya, karena itulah yang dilakukan sebuah kawanan. Mereka berjalan menjauhi sungai yang mereka kenal, menjauhi pepohonan yang mereka kenal, menuju dataran kosong tanpa apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_5', 'bok_the-elephant-who-remembered-the-water', 5, 'eleph-5', 'The younger mothers were frightened. There was nothing out there. There had never been anything out there in their whole lives, and their whole lives were the only evidence they had.', 'Para induk yang lebih muda ketakutan. Tidak ada apa-apa di sana. Sepanjang hidup mereka tidak pernah ada apa pun di sana, dan sepanjang hidup mereka adalah satu-satunya bukti yang mereka punya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_6', 'bok_the-elephant-who-remembered-the-water', 6, 'eleph-6', 'They walked for three days. Old Ma did not stop to consider or look around. She walked like somebody crossing their own kitchen in the dark, which is what she was doing, except that the kitchen was ninety kilometres wide.', 'Mereka berjalan tiga hari. Bunda Tua tidak berhenti untuk menimbang atau melihat sekeliling. Ia berjalan seperti orang menyeberangi dapurnya sendiri dalam gelap, dan memang itulah yang ia lakukan, hanya saja dapurnya selebar sembilan puluh kilometer.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_7', 'bok_the-elephant-who-remembered-the-water', 7, 'eleph-7', 'On the fourth morning the ground changed under their feet, and then there was a line of green, and then there was a spring coming out of rock in a shallow gorge that none of the young ones had ever seen.', 'Pada pagi keempat tanah di bawah kaki mereka berubah, lalu muncul garis hijau, lalu ada mata air yang keluar dari batu di sebuah ngarai dangkal yang belum pernah dilihat satu pun gajah muda.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_8', 'bok_the-elephant-who-remembered-the-water', 8, 'eleph-8', 'Old Ma had been there once. She had been a calf herself, in a dry year, following her own mother. That was fifty-four years earlier. She had not been back since, and she had not needed to be.', 'Bunda Tua pernah ke sana sekali. Waktu itu ia sendiri masih anak gajah, di tahun yang kering, mengikuti induknya sendiri. Itu lima puluh empat tahun sebelumnya. Ia tidak pernah kembali sejak itu, dan memang tidak perlu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-elephant-who-remembered-the-water_9', 'bok_the-elephant-who-remembered-the-water', 9, 'eleph-9', 'The calf drank and drank and then, that evening, started playing again. And the young mothers stood around Old Ma and touched her with their trunks, which is how elephants say the thing there is no sound for.', 'Anak gajah itu minum dan terus minum, lalu petang itu mulai bermain lagi. Dan para induk muda berdiri mengelilingi Bunda Tua dan menyentuhnya dengan belalai, yang merupakan cara gajah mengucapkan sesuatu yang tak ada bunyinya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elephant-who-remembered-the-water_1', 'bok_the-elephant-who-remembered-the-water', 1, 'What was the sign that things had become serious?', 'Apa tanda bahwa keadaan sudah gawat?', '["The grass turned yellow","The youngest calf stopped playing","The sun was hot","The birds left"]', '["Rumput menguning","Anak gajah termuda berhenti bermain","Matahari terik","Burung-burung pergi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elephant-who-remembered-the-water_2', 'bok_the-elephant-who-remembered-the-water', 2, 'How did Old Ma know where to go?', 'Bagaimana Bunda Tua tahu ke mana harus pergi?', '["She guessed","She remembered it from when she was a calf","She followed birds","She smelled it"]', '["Ia menebak","Ia mengingatnya sejak masih anak gajah","Ia mengikuti burung","Ia menciumnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-elephant-who-remembered-the-water_3', 'bok_the-elephant-who-remembered-the-water', 3, 'How long had it been since she was there?', 'Berapa lama sejak ia terakhir ke sana?', '["Five years","Fifty-four years","One year","She had never been"]', '["Lima tahun","Lima puluh empat tahun","Satu tahun","Ia belum pernah ke sana"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-hen-who-would-not-be-hurried', 'the-hen-who-would-not-be-hurried', 'The Hen Who Would Not Be Hurried', 'Ayam Betina yang Tak Mau Diburu-buru', 'Every hen on the farm lays in the morning. Kembang lays whenever she likes, and a boy learns something about patience the hard way.', 'Setiap ayam betina di peternakan bertelur pagi hari. Kembang bertelur kapan pun ia suka, dan seorang anak belajar tentang kesabaran dengan cara yang sulit.', 'cat_farm', 'aut_axto-creative-team', 'meadow', '🐔', 4, 8, 0, 'published', 9, 1943, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_1', 'bok_the-hen-who-would-not-be-hurried', 1, 'hen-1', 'On his grandmother''s farm there were fourteen hens, and thirteen of them laid in the morning. You could collect the eggs before breakfast and be done. Then there was Kembang.', 'Di peternakan neneknya ada empat belas ayam betina, dan tiga belas di antaranya bertelur pagi hari. Kau bisa mengumpulkan telur sebelum sarapan dan selesai. Lalu ada Kembang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_2', 'bok_the-hen-who-would-not-be-hurried', 2, 'hen-2', 'Kembang laid at eleven. Or at two. Once, memorably, at dusk, in a flowerpot. She was a perfectly good hen in every other respect and she simply would not be organised.', 'Kembang bertelur pukul sebelas. Atau pukul dua. Pernah sekali, yang tak terlupakan, saat senja, di dalam pot bunga. Dalam hal lain ia ayam yang sangat baik dan ia sekadar tidak mau diatur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_3', 'bok_the-hen-who-would-not-be-hurried', 3, 'hen-3', 'Bayu was staying for the summer and had been given the eggs as his job. He liked jobs that finished. Kembang meant the job never finished; it just moved around the day like a wasp.', 'Bayu menginap sepanjang musim liburan dan diberi tugas mengurus telur. Ia suka pekerjaan yang ada selesainya. Kembang membuat pekerjaan itu tidak pernah selesai; ia hanya berpindah-pindah sepanjang hari seperti tawon.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_4', 'bok_the-hen-who-would-not-be-hurried', 4, 'hen-4', 'So Bayu tried to make her hurry. He moved her to the nesting box and shut the door. He stood outside and waited. He came back six times. Kembang did not lay at all that day, or the next.', 'Maka Bayu berusaha memburu-burunya. Ia memindahkannya ke kotak bertelur dan menutup pintunya. Ia berdiri di luar dan menunggu. Ia kembali enam kali. Kembang sama sekali tidak bertelur hari itu, atau esoknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_5', 'bok_the-hen-who-would-not-be-hurried', 5, 'hen-5', 'His grandmother watched all this without saying anything for two days, which is a skill. On the third day she said, "You have made her frightened. A frightened hen holds on. You will get fewer eggs, not more."', 'Neneknya mengamati semua itu tanpa berkata apa-apa selama dua hari, yang merupakan sebuah keahlian. Pada hari ketiga ia berkata, "Kau membuatnya takut. Ayam yang takut menahan telurnya. Kau akan dapat lebih sedikit, bukan lebih banyak."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_6', 'bok_the-hen-who-would-not-be-hurried', 6, 'hen-6', '"Then what am I supposed to do?" said Bayu, who was hot and cross. His grandmother said, "Go twice. Once before breakfast for the thirteen. Once before dinner for Kembang. Stop trying to make her be a different hen."', '"Lalu aku harus bagaimana?" kata Bayu, yang kepanasan dan kesal. Neneknya berkata, "Pergilah dua kali. Sekali sebelum sarapan untuk yang tiga belas. Sekali sebelum makan malam untuk Kembang. Berhentilah memaksanya menjadi ayam yang lain."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_7', 'bok_the-hen-who-would-not-be-hurried', 7, 'hen-7', 'It took a week for Kembang to start laying again. When she did, she went back to her old habits entirely: eleven, or two, or once in the flowerpot. Bayu collected them in the evening and stopped counting when they arrived.', 'Butuh seminggu sampai Kembang mulai bertelur lagi. Ketika ia mulai, ia kembali sepenuhnya ke kebiasaan lamanya: pukul sebelas, atau pukul dua, atau sekali di pot bunga. Bayu mengumpulkannya petang hari dan berhenti mempersoalkan kapan telur itu datang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_8', 'bok_the-hen-who-would-not-be-hurried', 8, 'hen-8', 'At the end of the summer his grandmother added it up. Kembang had laid more eggs than any other hen on the farm. Not on time. Not conveniently. But more.', 'Di akhir musim liburan neneknya menghitung semuanya. Kembang bertelur lebih banyak daripada ayam mana pun di peternakan itu. Tidak tepat waktu. Tidak praktis. Tetapi lebih banyak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-hen-who-would-not-be-hurried_9', 'bok_the-hen-who-would-not-be-hurried', 9, 'hen-9', '"Some things go faster if you push them," his grandmother said, packing his bag. "Hens are not one of them. Neither are most of the things worth having." Bayu has thought about that sentence quite a lot since.', '"Ada hal-hal yang jadi lebih cepat kalau didorong," kata neneknya sambil mengemasi tasnya. "Ayam bukan salah satunya. Begitu pula kebanyakan hal yang layak dimiliki." Bayu cukup sering memikirkan kalimat itu sejak saat itu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-hen-who-would-not-be-hurried_1', 'bok_the-hen-who-would-not-be-hurried', 1, 'What was unusual about Kembang?', 'Apa yang tidak biasa dari Kembang?', '["She was very large","She laid at unpredictable times","She could not lay eggs","She lived indoors"]', '["Ia sangat besar","Ia bertelur pada waktu yang tak terduga","Ia tidak bisa bertelur","Ia tinggal di dalam rumah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-hen-who-would-not-be-hurried_2', 'bok_the-hen-who-would-not-be-hurried', 2, 'What happened when Bayu tried to hurry her?', 'Apa yang terjadi ketika Bayu memburu-burunya?', '["She laid more","She stopped laying altogether","She ran away","Nothing changed"]', '["Ia bertelur lebih banyak","Ia berhenti bertelur sama sekali","Ia kabur","Tidak ada yang berubah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-hen-who-would-not-be-hurried_3', 'bok_the-hen-who-would-not-be-hurried', 3, 'How many eggs did Kembang lay over the summer?', 'Berapa banyak telur Kembang sepanjang musim liburan?', '["The fewest","More than any other hen","Exactly average","None"]', '["Paling sedikit","Lebih banyak daripada ayam mana pun","Tepat rata-rata","Tidak ada"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-map-with-one-mistake', 'the-map-with-one-mistake', 'The Map With One Mistake', 'Peta dengan Satu Kekeliruan', 'Two children set out to cross the ridge with a map their grandfather drew. It is accurate everywhere except one place.', 'Dua anak berangkat menyeberangi punggung bukit dengan peta buatan kakek mereka. Peta itu tepat di mana-mana kecuali satu tempat.', 'cat_adventure', 'aut_axto-creative-team', 'forest', '🧭', 7, 11, 0, 'published', 9, 3383, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_1', 'bok_the-map-with-one-mistake', 1, 'map-1', 'Their grandfather had walked the ridge every summer for fifty years, and he had drawn a map of it on the back of a calendar. It showed every stream, every fallen tree, and the four hours it took to cross.', 'Kakek mereka telah menyusuri punggung bukit itu setiap musim panas selama lima puluh tahun, dan ia menggambar petanya di balik sebuah kalender. Peta itu menunjukkan setiap anak sungai, setiap pohon tumbang, dan empat jam waktu tempuhnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_2', 'bok_the-map-with-one-mistake', 2, 'map-2', 'Wira was twelve and Nala was ten, and they had permission, water, and a whistle each. They also had the map, folded into eight, in Wira''s shirt pocket.', 'Wira berumur dua belas tahun dan Nala sepuluh, dan mereka sudah mendapat izin, membawa air, dan masing-masing sebuah peluit. Mereka juga membawa peta itu, terlipat delapan, di saku kemeja Wira.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_3', 'bok_the-map-with-one-mistake', 3, 'map-3', 'For three hours the map was perfect. The stream was where it said. The split rock was where it said. Nala started calling it the magic paper and Wira stopped checking it as often as he should have.', 'Selama tiga jam peta itu sempurna. Anak sungai ada persis di tempatnya. Batu belah ada persis di tempatnya. Nala mulai menyebutnya kertas ajaib dan Wira berhenti memeriksanya sesering seharusnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_4', 'bok_the-map-with-one-mistake', 4, 'map-4', 'Then they came to the fork. The map showed the path going left around a stand of pines. They went left. And after twenty minutes the path simply stopped, at a wall of young trees too thick to push through.', 'Lalu mereka tiba di persimpangan. Peta menunjukkan jalan setapak membelok kiri mengitari rumpun pinus. Mereka ke kiri. Dan setelah dua puluh menit jalan itu begitu saja berhenti, di dinding pohon muda yang terlalu rapat untuk ditembus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_5', 'bok_the-map-with-one-mistake', 5, 'map-5', 'Nala wanted to force through. Wira wanted to go back. They argued about it for a while, which is what people do when they are frightened and would rather be angry than frightened.', 'Nala ingin menerobos. Wira ingin kembali. Mereka berdebat cukup lama, seperti yang biasa dilakukan orang ketika takut dan lebih memilih marah daripada mengakui takut.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_6', 'bok_the-map-with-one-mistake', 6, 'map-6', 'Then Wira looked at the map properly. The pines were drawn small. Their grandfather had drawn them fifty summers ago, when they were small. Fifty years is a long time for a pine.', 'Lalu Wira mengamati petanya baik-baik. Pohon-pohon pinus itu digambar kecil. Kakek mereka menggambarnya lima puluh musim panas lalu, ketika pohon-pohon itu memang masih kecil. Lima puluh tahun adalah waktu yang panjang bagi sebatang pinus.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_7', 'bok_the-map-with-one-mistake', 7, 'map-7', '"The map is not wrong," he said slowly. "It is old. The trees grew." And once he had said it out loud, the answer was obvious: the path did not go left any more, because there was no longer a way round on that side.', '"Petanya tidak salah," katanya perlahan. "Petanya sudah tua. Pohonnya tumbuh." Dan begitu ia mengucapkannya lantang, jawabannya menjadi jelas: jalan itu tidak lagi ke kiri, karena di sisi itu sudah tidak ada jalan memutar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_8', 'bok_the-map-with-one-mistake', 8, 'map-8', 'They went back to the fork and took the right-hand path, and it curved wide around the pines and rejoined the map exactly where the map said it would, forty minutes later, at a gate with a rusted hinge.', 'Mereka kembali ke persimpangan dan mengambil jalan kanan, dan jalan itu melengkung lebar mengitari rumpun pinus lalu bertemu kembali dengan peta persis di tempat yang ditunjukkan peta, empat puluh menit kemudian, di sebuah gerbang berengsel karat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-map-with-one-mistake_9', 'bok_the-map-with-one-mistake', 9, 'map-9', 'That evening their grandfather listened to the whole story. Then he took a pencil, drew the pines much bigger, drew the new path, wrote the year beside it, and handed the map back to Wira. "Yours now," he said. "Keep it up to date."', 'Petang itu kakek mereka mendengarkan seluruh cerita. Lalu ia mengambil pensil, menggambar pinus jauh lebih besar, menggambar jalan baru, menuliskan tahunnya di sebelahnya, dan menyerahkan peta itu kembali kepada Wira. "Sekarang milikmu," katanya. "Jaga supaya tetap mutakhir."');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-map-with-one-mistake_1', 'bok_the-map-with-one-mistake', 1, 'Why did the path not go left any more?', 'Mengapa jalannya tidak lagi ke kiri?', '["Somebody blocked it","The pines had grown over fifty years","It flooded","The map was drawn wrongly"]', '["Ada yang menutupnya","Pohon pinus tumbuh selama lima puluh tahun","Kebanjiran","Petanya salah gambar"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-map-with-one-mistake_2', 'bok_the-map-with-one-mistake', 2, 'What did Wira work out?', 'Apa yang Wira simpulkan?', '["The map was a fake","The map was old, not wrong","They were lost forever","Nala had misread it"]', '["Petanya palsu","Petanya tua, bukan salah","Mereka tersesat selamanya","Nala salah membaca"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-map-with-one-mistake_3', 'bok_the-map-with-one-mistake', 3, 'What did their grandfather do at the end?', 'Apa yang kakek mereka lakukan di akhir cerita?', '["Threw the map away","Updated it and gave it to Wira","Told them off","Drew a new map alone"]', '["Membuang petanya","Memperbaruinya dan memberikannya kepada Wira","Memarahi mereka","Menggambar peta baru sendiri"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-friend-who-moved-away', 'the-friend-who-moved-away', 'The Friend Who Moved Away', 'Sahabat yang Pindah', 'Sena and Tio were best friends for six years. Then one of them moved four hundred kilometres, and both of them had to learn something difficult.', 'Sena dan Tio bersahabat selama enam tahun. Lalu salah satunya pindah empat ratus kilometer, dan keduanya harus belajar sesuatu yang sulit.', 'cat_friendship', 'aut_axto-creative-team', 'sunrise', '🤝', 6, 10, 0, 'published', 9, 4527, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_1', 'bok_the-friend-who-moved-away', 1, 'moved-1', 'Sena and Tio had been in the same class since they were five. They had a handshake that took eleven seconds and a rule that whoever got to the gate first waited, no matter how long.', 'Sena dan Tio sekelas sejak umur lima tahun. Mereka punya salaman khas yang memakan waktu sebelas detik dan sebuah aturan bahwa siapa pun yang lebih dulu sampai gerbang harus menunggu, berapa lama pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_2', 'bok_the-friend-who-moved-away', 2, 'moved-2', 'In March, Tio''s father got work in another province. Four hundred kilometres. Tio told Sena on a Wednesday, at the gate, and neither of them said very much afterwards.', 'Pada bulan Maret, ayah Tio mendapat pekerjaan di provinsi lain. Empat ratus kilometer. Tio memberi tahu Sena pada hari Rabu, di gerbang, dan setelah itu keduanya nyaris tidak berkata apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_3', 'bok_the-friend-who-moved-away', 3, 'moved-3', 'For the first month they spoke every single day. Then it was every second day. Then Sena sent a message on a Tuesday and Tio replied on the Thursday, and Sena noticed, and it hurt more than he expected.', 'Bulan pertama mereka bicara setiap hari. Lalu jadi dua hari sekali. Lalu Sena mengirim pesan pada Selasa dan Tio membalas hari Kamis, dan Sena menyadarinya, dan itu lebih menyakitkan daripada yang ia kira.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_4', 'bok_the-friend-who-moved-away', 4, 'moved-4', 'What Sena did not know was that Tio was having a bad time. He had nobody to wait for at the gate. He had eaten lunch alone for six weeks. And every time he messaged Sena he felt further away rather than closer.', 'Yang Sena tidak tahu adalah bahwa Tio sedang mengalami masa sulit. Ia tidak punya siapa pun untuk ditunggu di gerbang. Ia makan siang sendirian selama enam minggu. Dan setiap kali ia mengirim pesan kepada Sena, ia justru merasa makin jauh, bukan makin dekat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_5', 'bok_the-friend-who-moved-away', 5, 'moved-5', 'So they both did the thing people do, which is nothing. Weeks went by. Sena decided Tio had found better friends. Tio decided Sena had stopped caring. Both were wrong, and neither asked.', 'Maka keduanya melakukan hal yang biasa dilakukan orang, yaitu tidak melakukan apa-apa. Berminggu-minggu berlalu. Sena menyimpulkan Tio sudah punya teman yang lebih baik. Tio menyimpulkan Sena sudah tidak peduli. Keduanya keliru, dan tidak ada yang bertanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_6', 'bok_the-friend-who-moved-away', 6, 'moved-6', 'In August, Sena''s mother made him write a letter. A real one, on paper, because she is from a generation that believes in this. Sena wrote four lines and thought they were stupid and sent it anyway.', 'Pada bulan Agustus, ibu Sena menyuruhnya menulis surat. Surat sungguhan, di atas kertas, karena ia dari generasi yang memercayai hal itu. Sena menulis empat baris, merasa isinya konyol, dan tetap mengirimkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_7', 'bok_the-friend-who-moved-away', 7, 'moved-7', 'The four lines were: I thought you had better friends now. I did not want to be the one always messaging first. I miss the gate thing. Write back or do not, but I wanted you to know that.', 'Empat baris itu berbunyi: Aku kira sekarang kau punya teman yang lebih baik. Aku tidak mau jadi yang selalu mengirim pesan duluan. Aku rindu kebiasaan menunggu di gerbang. Balas atau tidak, aku hanya ingin kau tahu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_8', 'bok_the-friend-who-moved-away', 8, 'moved-8', 'Tio phoned the day it arrived. They talked for an hour and a half, most of which was arguing about who had stopped first, and then laughing about arguing about it.', 'Tio menelepon di hari surat itu tiba. Mereka bicara satu setengah jam, sebagian besar berisi perdebatan tentang siapa yang lebih dulu berhenti, lalu tertawa karena memperdebatkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-friend-who-moved-away_9', 'bok_the-friend-who-moved-away', 9, 'moved-9', 'They are still friends. Not the same as before — you cannot wait at a gate for somebody four hundred kilometres away. But they talk on Sundays, and they both know now that the silence had never meant what either of them thought.', 'Mereka masih bersahabat. Tidak sama seperti dulu — kau tidak bisa menunggu di gerbang untuk seseorang yang berjarak empat ratus kilometer. Tetapi mereka bicara setiap Minggu, dan kini keduanya tahu bahwa keheningan itu tidak pernah berarti seperti yang mereka kira.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-friend-who-moved-away_1', 'bok_the-friend-who-moved-away', 1, 'Why did Sena stop messaging?', 'Mengapa Sena berhenti mengirim pesan?', '["He was busy","He thought Tio had better friends now","He lost his phone","He was angry"]', '["Ia sibuk","Ia mengira Tio sudah punya teman yang lebih baik","Ponselnya hilang","Ia marah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-friend-who-moved-away_2', 'bok_the-friend-who-moved-away', 2, 'What was actually happening to Tio?', 'Apa yang sebenarnya dialami Tio?', '["He was very happy","He was lonely and eating lunch alone","He had forgotten Sena","He had moved again"]', '["Ia sangat bahagia","Ia kesepian dan makan siang sendirian","Ia melupakan Sena","Ia pindah lagi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-friend-who-moved-away_3', 'bok_the-friend-who-moved-away', 3, 'What fixed it?', 'Apa yang memperbaikinya?', '["Time","Sena writing honestly about what he had assumed","Tio moving back","A teacher"]', '["Waktu","Sena menulis jujur tentang apa yang ia asumsikan","Tio pindah kembali","Seorang guru"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-borrowed-bicycle', 'the-borrowed-bicycle', 'The Borrowed Bicycle', 'Sepeda Pinjaman', 'Fajar borrows a bicycle without asking, and breaks it. What he does next takes three weeks and costs him more than the repair.', 'Fajar meminjam sepeda tanpa izin, lalu merusaknya. Apa yang ia lakukan setelahnya memakan tiga minggu dan biayanya lebih dari sekadar perbaikan.', 'cat_moral-stories', 'aut_axto-creative-team', 'citrus', '🚲', 6, 10, 0, 'published', 9, 4509, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_1', 'bok_the-borrowed-bicycle', 1, 'bike-1', 'The bicycle belonged to Pak Sardi, who was seventy and rode it to the mosque and back and nowhere else. It leaned against his wall all day, blue, upright, and completely unlocked.', 'Sepeda itu milik Pak Sardi, yang berumur tujuh puluh tahun dan mengayuhnya ke masjid pulang pergi dan tidak ke mana-mana lagi. Sepeda itu bersandar di temboknya sepanjang hari, biru, tegak, dan sama sekali tidak dikunci.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_2', 'bok_the-borrowed-bicycle', 2, 'bike-2', 'Fajar took it on a Thursday. He told himself it was borrowing, because he intended to bring it back, and because Pak Sardi was asleep and could not be asked, and because he really wanted to ride down the hill road.', 'Fajar mengambilnya pada hari Kamis. Ia berkata pada dirinya sendiri bahwa itu meminjam, karena ia berniat mengembalikannya, karena Pak Sardi sedang tidur dan tidak bisa dimintai izin, dan karena ia sangat ingin meluncur di jalan menurun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_3', 'bok_the-borrowed-bicycle', 3, 'bike-3', 'The hill road was wonderful for about ninety seconds. Then the front wheel found a drain cover, and the bicycle went one way, and Fajar went the other, and when he got up the front wheel was bent like a plate.', 'Jalan menurun itu luar biasa selama kira-kira sembilan puluh detik. Lalu roda depan menghantam tutup selokan, sepeda melaju ke satu arah, Fajar ke arah lain, dan ketika ia bangun roda depan itu bengkok seperti piring.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_4', 'bok_the-borrowed-bicycle', 4, 'bike-4', 'He could have pushed it back and left it against the wall. Pak Sardi''s eyes were not good. It might have been three days before anybody knew. Fajar stood in the road for a long time thinking about exactly that.', 'Ia bisa saja mendorongnya kembali dan menyandarkannya di tembok. Penglihatan Pak Sardi sudah tidak bagus. Mungkin butuh tiga hari sampai ada yang tahu. Fajar berdiri lama di jalan memikirkan persis hal itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_5', 'bok_the-borrowed-bicycle', 5, 'bike-5', 'Then he pushed it back and knocked on the door and said what he had done, in one sentence, without any of the softening words he had been assembling on the way.', 'Lalu ia mendorongnya kembali, mengetuk pintu, dan mengatakan apa yang telah ia perbuat, dalam satu kalimat, tanpa satu pun kata pelunak yang ia susun sepanjang jalan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_6', 'bok_the-borrowed-bicycle', 6, 'bike-6', 'Pak Sardi did not shout. He looked at the wheel for a while. Then he said, "That is a week of my legs," which was worse than shouting, because it was true and it was not an insult.', 'Pak Sardi tidak berteriak. Ia memandangi roda itu sejenak. Lalu ia berkata, "Itu seminggu kaki saya," yang lebih berat daripada bentakan, karena itu benar dan bukan hinaan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_7', 'bok_the-borrowed-bicycle', 7, 'bike-7', 'The repair cost more than Fajar had. So for three weeks he walked to the mosque with Pak Sardi and back, every day, carrying his bag, at Pak Sardi''s speed, which is slower than you think.', 'Biaya perbaikannya lebih besar daripada uang Fajar. Maka selama tiga minggu ia berjalan ke masjid bersama Pak Sardi dan pulang, setiap hari, membawakan tasnya, dengan kecepatan Pak Sardi, yang lebih lambat daripada yang kau bayangkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_8', 'bok_the-borrowed-bicycle', 8, 'bike-8', 'They talked. It turned out Pak Sardi had been a mechanic for forty years and could explain exactly why a wheel bends the way it does. By the end of the second week Fajar was asking questions on purpose.', 'Mereka mengobrol. Ternyata Pak Sardi pernah menjadi montir selama empat puluh tahun dan bisa menjelaskan persis mengapa sebuah roda bengkok seperti itu. Menjelang akhir minggu kedua Fajar mulai bertanya dengan sengaja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-borrowed-bicycle_9', 'bok_the-borrowed-bicycle', 9, 'bike-9', 'The wheel got fixed. Fajar still walks with him some mornings, which nobody asked him to do. And the blue bicycle is still unlocked against the wall, which is either very trusting or very well judged.', 'Roda itu akhirnya diperbaiki. Fajar masih berjalan bersamanya pada beberapa pagi, tanpa ada yang menyuruhnya. Dan sepeda biru itu masih bersandar di tembok tanpa dikunci, yang entah sangat percaya atau sangat tepat menilai orang.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-borrowed-bicycle_1', 'bok_the-borrowed-bicycle', 1, 'Why did Fajar tell the truth?', 'Mengapa Fajar mengatakan yang sebenarnya?', '["He was caught","He chose to, even though he could have hidden it","Somebody saw him","Pak Sardi asked"]', '["Ia ketahuan","Ia memilih begitu, padahal bisa menyembunyikannya","Ada yang melihatnya","Pak Sardi bertanya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-borrowed-bicycle_2', 'bok_the-borrowed-bicycle', 2, 'What did Pak Sardi say about the broken wheel?', 'Apa kata Pak Sardi tentang roda yang rusak?', '["Nothing","That it was a week of his legs","That Fajar was a thief","That it did not matter"]', '["Tidak berkata apa-apa","Bahwa itu seminggu kakinya","Bahwa Fajar pencuri","Bahwa itu tidak penting"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-borrowed-bicycle_3', 'bok_the-borrowed-bicycle', 3, 'How did Fajar make it right?', 'Bagaimana Fajar menebus kesalahannya?', '["He paid at once","He walked with Pak Sardi every day for three weeks","He bought a new bicycle","He apologised in a letter"]', '["Ia langsung membayar","Ia berjalan bersama Pak Sardi setiap hari selama tiga minggu","Ia membeli sepeda baru","Ia minta maaf lewat surat"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-miller-daughter-and-the-clever-answer', 'the-miller-daughter-and-the-clever-answer', 'The Miller''s Daughter and the Clever Answer', 'Putri Tukang Giling dan Jawaban yang Cerdik', 'A king sets three impossible tasks. A miller''s daughter solves all three by refusing to accept the question as it was asked.', 'Seorang raja memberi tiga tugas mustahil. Putri tukang giling menyelesaikan ketiganya dengan menolak menerima pertanyaannya begitu saja.', 'cat_fairy-tales', 'aut_axto-creative-team', 'twilight', '🏰', 6, 10, 0, 'published', 9, 3858, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_1', 'bok_the-miller-daughter-and-the-clever-answer', 1, 'miller-1', 'There was once a king who liked riddles more than he liked ruling, which is a poor arrangement for a kingdom. He announced that whoever solved his three tasks would sit at his council table.', 'Dahulu ada seorang raja yang lebih menyukai teka-teki daripada memerintah, yang merupakan pengaturan buruk bagi sebuah kerajaan. Ia mengumumkan bahwa siapa pun yang menyelesaikan tiga tugasnya akan duduk di meja dewannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_2', 'bok_the-miller-daughter-and-the-clever-answer', 2, 'miller-2', 'The first task was to come to the palace neither walking nor riding. Forty men tried. They walked, or they rode, or they attempted to hop, which the king ruled was walking badly.', 'Tugas pertama adalah datang ke istana tidak dengan berjalan maupun berkendara. Empat puluh orang mencoba. Mereka berjalan, atau berkendara, atau mencoba melompat-lompat, yang oleh raja diputuskan sebagai berjalan dengan buruk.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_3', 'bok_the-miller-daughter-and-the-clever-answer', 3, 'miller-3', 'The miller''s daughter, whose name was Sekar, came with one foot on a donkey and one foot on the ground, so that she was doing half of each and therefore neither. The king laughed and allowed it.', 'Putri tukang giling, yang bernama Sekar, datang dengan satu kaki di atas keledai dan satu kaki di tanah, sehingga ia melakukan separuh dari masing-masing dan karenanya tidak keduanya. Raja tertawa dan mengizinkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_4', 'bok_the-miller-daughter-and-the-clever-answer', 4, 'miller-4', 'The second task was to bring a gift that was neither given nor kept. Sekar brought a bird in her cupped hands, and when the king reached for it she opened her hands and it flew.', 'Tugas kedua adalah membawa hadiah yang tidak diberikan dan tidak pula disimpan. Sekar membawa seekor burung dalam kedua telapak tangannya, dan ketika raja hendak meraihnya, ia membuka tangannya dan burung itu terbang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_5', 'bok_the-miller-daughter-and-the-clever-answer', 5, 'miller-5', '"You have given me nothing," said the king. "I have given you a bird," said Sekar. "You have simply not kept it. That was the task." The court went very quiet, and then a lord at the back laughed and could not stop.', '"Kau tidak memberiku apa-apa," kata raja. "Saya memberi Baginda seekor burung," kata Sekar. "Baginda yang tidak menyimpannya. Itulah tugasnya." Ruang istana menjadi sangat sunyi, lalu seorang bangsawan di belakang tertawa dan tak bisa berhenti.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_6', 'bok_the-miller-daughter-and-the-clever-answer', 6, 'miller-6', 'The third task was harder and the king set it in a temper. "Tell me," he said, "the one thing I own that I cannot lose." And he sat back, because he believed there was no such thing.', 'Tugas ketiga lebih sulit dan raja menetapkannya dengan kesal. "Katakan padaku," ujarnya, "satu hal yang kumiliki yang tidak bisa kuhilangkan." Lalu ia bersandar, karena ia yakin hal semacam itu tidak ada.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_7', 'bok_the-miller-daughter-and-the-clever-answer', 7, 'miller-7', 'Sekar thought for a day and a night. Then she came back and said, "What you have already given away, Your Majesty. That is the only thing nobody can take from you, because it is not with you any more."', 'Sekar berpikir sehari semalam. Lalu ia kembali dan berkata, "Apa yang telah Baginda berikan kepada orang lain. Hanya itulah yang tidak bisa direbut siapa pun dari Baginda, karena hal itu sudah tidak lagi ada pada Baginda."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_8', 'bok_the-miller-daughter-and-the-clever-answer', 8, 'miller-8', 'The king was quiet for a long time. Then he said, "That is not a riddle answer. That is a true one." And Sekar said, "Yes. You asked for riddles for eleven years and your roads are still bad."', 'Raja terdiam lama. Lalu ia berkata, "Itu bukan jawaban teka-teki. Itu jawaban yang benar." Dan Sekar berkata, "Betul. Baginda meminta teka-teki selama sebelas tahun dan jalan-jalan Baginda masih rusak."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-miller-daughter-and-the-clever-answer_9', 'bok_the-miller-daughter-and-the-clever-answer', 9, 'miller-9', 'She sat at the council table for thirty years. The riddles stopped. The roads were mended. And the story that survived was not about a clever answer at all, but about somebody who kept asking what the question was actually for.', 'Ia duduk di meja dewan selama tiga puluh tahun. Teka-teki itu berhenti. Jalan-jalan diperbaiki. Dan kisah yang bertahan bukanlah tentang jawaban yang cerdik, melainkan tentang seseorang yang terus bertanya untuk apa sebenarnya pertanyaan itu diajukan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-miller-daughter-and-the-clever-answer_1', 'bok_the-miller-daughter-and-the-clever-answer', 1, 'How did Sekar arrive neither walking nor riding?', 'Bagaimana Sekar datang tanpa berjalan maupun berkendara?', '["She was carried","One foot on a donkey, one on the ground","She rowed a boat","She was pulled in a cart"]', '["Ia digendong","Satu kaki di keledai, satu di tanah","Ia mendayung perahu","Ia ditarik dengan gerobak"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-miller-daughter-and-the-clever-answer_2', 'bok_the-miller-daughter-and-the-clever-answer', 2, 'What was her answer to the third task?', 'Apa jawabannya untuk tugas ketiga?', '["His crown","What he had already given away","His name","His palace"]', '["Mahkotanya","Apa yang telah ia berikan kepada orang lain","Namanya","Istananya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-miller-daughter-and-the-clever-answer_3', 'bok_the-miller-daughter-and-the-clever-answer', 3, 'What changed in the kingdom afterwards?', 'Apa yang berubah di kerajaan setelahnya?', '["More riddles","The riddles stopped and the roads were mended","The king left","Nothing"]', '["Teka-tekinya bertambah","Teka-tekinya berhenti dan jalan-jalan diperbaiki","Rajanya pergi","Tidak ada"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-stone-soup-of-tanah-rendah', 'the-stone-soup-of-tanah-rendah', 'The Stone Soup of Tanah Rendah', 'Sup Batu dari Tanah Rendah', 'A traveller arrives in a hungry village with nothing but a pot and a stone, and cooks a meal that nobody quite understands how they made.', 'Seorang musafir tiba di desa yang kelaparan dengan hanya membawa panci dan sebuah batu, lalu memasak hidangan yang tak seorang pun benar-benar paham bagaimana mereka membuatnya.', 'cat_world-cultures', 'aut_axto-creative-team', 'sunrise', '🍲', 5, 9, 0, 'published', 9, 4013, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_1', 'bok_the-stone-soup-of-tanah-rendah', 1, 'soup-1', 'The harvest had failed twice in Tanah Rendah, and the village had learned to keep what little it had behind closed doors. When a traveller came down the road, every shutter in the village closed before she reached the well.', 'Panen di Tanah Rendah gagal dua kali, dan desa itu belajar menyimpan yang sedikit di balik pintu tertutup. Ketika seorang musafir menyusuri jalan, setiap daun jendela di desa itu tertutup sebelum ia sampai di sumur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_2', 'bok_the-stone-soup-of-tanah-rendah', 2, 'soup-2', 'The traveller did not knock on any door. She built a fire in the square, filled a pot from the well, and put in one smooth grey stone. Then she sat down beside it and waited, and stirred it occasionally.', 'Musafir itu tidak mengetuk satu pintu pun. Ia menyalakan api di alun-alun, mengisi panci dari sumur, dan memasukkan sebuah batu kelabu yang licin. Lalu ia duduk di sampingnya dan menunggu, sesekali mengaduknya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_3', 'bok_the-stone-soup-of-tanah-rendah', 3, 'soup-3', 'After an hour a boy came out. "What are you making?" "Stone soup," said the traveller. "It is very good. It is nearly ready." She tasted it thoughtfully. "It wants a little salt, but never mind. It is still good."', 'Setelah satu jam seorang anak lelaki keluar. "Sedang masak apa?" "Sup batu," kata musafir itu. "Rasanya enak sekali. Sebentar lagi matang." Ia mencicipinya sambil berpikir. "Kurang sedikit garam, tapi tidak apa-apa. Tetap enak."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_4', 'bok_the-stone-soup-of-tanah-rendah', 4, 'soup-4', 'The boy went home and came back with salt. His mother came out to see where the salt had gone. She tasted the soup and said it was good, and that it would be better with an onion, and she happened to have one onion.', 'Anak itu pulang dan kembali membawa garam. Ibunya keluar untuk melihat ke mana perginya garam itu. Ia mencicipi sup itu dan berkata rasanya enak, dan akan lebih enak dengan bawang, dan kebetulan ia punya satu bawang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_5', 'bok_the-stone-soup-of-tanah-rendah', 5, 'soup-5', 'The blacksmith brought two carrots that were going soft anyway. The widow at the end brought a handful of rice she had been saving and did not explain why she had decided to stop saving it.', 'Pandai besi membawa dua wortel yang memang mulai lembek. Janda di ujung jalan membawa segenggam beras yang selama ini ia simpan dan tidak menjelaskan mengapa ia memutuskan berhenti menyimpannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_6', 'bok_the-stone-soup-of-tanah-rendah', 6, 'soup-6', 'By dusk there were nineteen people around the fire and the pot was full of soup — real soup, with vegetables and rice and salt and a little dried fish that somebody had produced without being asked.', 'Menjelang senja ada sembilan belas orang mengelilingi api dan panci itu penuh sup — sup sungguhan, dengan sayur dan beras dan garam serta sedikit ikan kering yang dikeluarkan seseorang tanpa diminta.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_7', 'bok_the-stone-soup-of-tanah-rendah', 7, 'soup-7', 'They ate together, which they had not done in two years. Somebody found a drum. The blacksmith''s wife laughed at something, loudly, and several people looked up because they had not heard her laugh since the second failed harvest.', 'Mereka makan bersama, sesuatu yang tidak mereka lakukan selama dua tahun. Seseorang menemukan gendang. Istri pandai besi tertawa keras karena sesuatu, dan beberapa orang menoleh karena mereka belum pernah mendengarnya tertawa sejak gagal panen kedua.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_8', 'bok_the-stone-soup-of-tanah-rendah', 8, 'soup-8', 'In the morning the traveller washed the pot, took out the stone, and put it in her pocket. The boy watched her do it. "It was not the stone, was it," he said. It was not a question.', 'Pagi harinya musafir itu mencuci pancinya, mengeluarkan batunya, dan memasukkannya ke saku. Anak lelaki itu memperhatikannya. "Bukan batunya, kan," katanya. Itu bukan pertanyaan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-stone-soup-of-tanah-rendah_9', 'bok_the-stone-soup-of-tanah-rendah', 9, 'soup-9', '"No," she agreed. "But you all had something. You only needed somewhere to put it that was not your own house." Then she walked on, and the village of Tanah Rendah ate together every week after that, without a stone.', '"Bukan," ia mengiyakan. "Tetapi kalian semua punya sesuatu. Kalian hanya butuh tempat untuk meletakkannya yang bukan rumah kalian sendiri." Lalu ia melanjutkan perjalanan, dan desa Tanah Rendah makan bersama setiap minggu setelah itu, tanpa batu.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stone-soup-of-tanah-rendah_1', 'bok_the-stone-soup-of-tanah-rendah', 1, 'What did the traveller put in the pot first?', 'Apa yang pertama kali dimasukkan musafir ke dalam panci?', '["Rice","A stone","An onion","Fish"]', '["Beras","Sebuah batu","Bawang","Ikan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stone-soup-of-tanah-rendah_2', 'bok_the-stone-soup-of-tanah-rendah', 2, 'Why did the villagers start bringing food?', 'Mengapa warga desa mulai membawa bahan makanan?', '["They were ordered to","Each was invited to add one small thing","They were paid","They were tricked into it by force"]', '["Mereka diperintah","Masing-masing diajak menambahkan satu hal kecil","Mereka dibayar","Mereka dipaksa"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-stone-soup-of-tanah-rendah_3', 'bok_the-stone-soup-of-tanah-rendah', 3, 'What was the real point of the stone?', 'Apa sebenarnya guna batu itu?', '["It flavoured the soup","It gave everyone a shared place to contribute","It was magic","It was food"]', '["Memberi rasa pada sup","Memberi semua orang tempat bersama untuk menyumbang","Ia batu ajaib","Ia bisa dimakan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-word-that-costs-nothing', 'the-word-that-costs-nothing', 'The Word That Costs Nothing', 'Kata yang Tidak Berbiaya', 'A shopkeeper keeps a tally of something unusual for one month, and shows the result to a boy who thinks manners are pointless.', 'Seorang pemilik toko mencatat sesuatu yang tak biasa selama sebulan, lalu menunjukkan hasilnya kepada seorang anak yang menganggap sopan santun itu percuma.', 'cat_manners', 'aut_axto-creative-team', 'meadow', '🙏', 5, 9, 0, 'published', 9, 1374, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_1', 'bok_the-word-that-costs-nothing', 1, 'word-1', 'Bu Ida had run the corner shop for twenty-six years. She knew everybody''s order, everybody''s children, and roughly what kind of week everybody was having by how they came through the door.', 'Bu Ida telah mengelola toko di sudut jalan selama dua puluh enam tahun. Ia hafal pesanan setiap orang, anak-anak setiap orang, dan kira-kira sedang mengalami minggu seperti apa mereka hanya dari cara mereka masuk pintu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_2', 'bok_the-word-that-costs-nothing', 2, 'word-2', 'Dimas came in every day after school and said nothing at all. He put the money down, took the bread, and left. When his aunt told him to say thank you he said, "Why? She has already been paid."', 'Dimas datang setiap hari sepulang sekolah dan tidak berkata apa-apa. Ia meletakkan uangnya, mengambil roti, dan pergi. Ketika bibinya menyuruhnya berterima kasih ia berkata, "Untuk apa? Dia kan sudah dibayar."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_3', 'bok_the-word-that-costs-nothing', 3, 'word-3', 'It was a real question and it deserved a real answer, and Bu Ida did not have one ready. So she said, "Give me a month," and she got out a notebook and started a tally.', 'Itu pertanyaan sungguhan dan layak mendapat jawaban sungguhan, dan Bu Ida tidak punya jawaban yang siap. Maka ia berkata, "Beri saya waktu sebulan," lalu ia mengeluarkan buku catatan dan mulai mencatat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_4', 'bok_the-word-that-costs-nothing', 4, 'word-4', 'She did not tell anybody what she was counting. Every time somebody said thank you, or good morning, or asked how she was and waited for the answer, she made a small mark. Nothing else. Just that.', 'Ia tidak memberi tahu siapa pun apa yang ia hitung. Setiap kali ada yang mengucapkan terima kasih, atau selamat pagi, atau menanyakan kabarnya dan menunggu jawabannya, ia membuat satu coretan kecil. Tidak ada yang lain. Hanya itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_5', 'bok_the-word-that-costs-nothing', 5, 'word-5', 'At the end of the month she showed Dimas the notebook. Then she showed him a second page, which she had also been keeping, listing the things she had done that month that nobody had paid her for.', 'Di akhir bulan ia menunjukkan buku catatan itu kepada Dimas. Lalu ia menunjukkan halaman kedua, yang juga ia catat, berisi daftar hal-hal yang ia lakukan bulan itu tanpa dibayar siapa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_6', 'bok_the-word-that-costs-nothing', 6, 'word-6', 'Held a delivery for Bu Ratmi, who was at the hospital. Let the Ariyanto boys take milk on Tuesday and pay Friday. Watched a pram outside for eleven minutes. Wrote down a phone number for somebody who could not read the label.', 'Menahan kiriman untuk Bu Ratmi, yang sedang di rumah sakit. Membiarkan anak-anak Ariyanto mengambil susu hari Selasa dan bayar hari Jumat. Menjaga kereta bayi di luar selama sebelas menit. Menuliskan nomor telepon untuk seseorang yang tidak bisa membaca labelnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_7', 'bok_the-word-that-costs-nothing', 7, 'word-7', '"You are right," she told Dimas. "I have been paid for the bread. I have not been paid for any of this. Nobody has to do any of this, and I do it more for the people on the first page."', '"Kamu benar," katanya kepada Dimas. "Saya sudah dibayar untuk roti. Saya tidak dibayar untuk semua ini. Tidak ada yang wajib melakukan semua ini, dan saya lebih sering melakukannya untuk orang-orang di halaman pertama."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_8', 'bok_the-word-that-costs-nothing', 8, 'word-8', '"That is not a threat," she added, because Dimas had gone red. "It is just true. Being pleasant is not the same as being paid. It is a different thing entirely, and it buys different things."', '"Itu bukan ancaman," tambahnya, karena wajah Dimas memerah. "Itu hanya kenyataan. Bersikap ramah tidak sama dengan membayar. Itu hal yang sama sekali berbeda, dan yang dibelinya pun berbeda."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-word-that-costs-nothing_9', 'bok_the-word-that-costs-nothing', 9, 'word-9', 'Dimas is nineteen now and works in a bank, and he says good morning to everybody, including the security guard and the woman who empties the bins. He has never once explained why, and Bu Ida has never once mentioned it.', 'Dimas kini berumur sembilan belas tahun dan bekerja di bank, dan ia mengucapkan selamat pagi kepada semua orang, termasuk satpam dan perempuan yang mengosongkan tempat sampah. Ia tidak pernah sekali pun menjelaskan alasannya, dan Bu Ida tidak pernah sekali pun menyinggungnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-word-that-costs-nothing_1', 'bok_the-word-that-costs-nothing', 1, 'What was Dimas''s question?', 'Apa pertanyaan Dimas?', '["Why is bread expensive?","Why say thank you when she has been paid?","Why does the shop close early?","Why is she always there?"]', '["Mengapa roti mahal?","Mengapa berterima kasih kalau dia sudah dibayar?","Mengapa tokonya tutup lebih awal?","Mengapa dia selalu ada di sana?"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-word-that-costs-nothing_2', 'bok_the-word-that-costs-nothing', 2, 'What did Bu Ida count for a month?', 'Apa yang Bu Ida hitung selama sebulan?', '["Her money","Every time somebody was pleasant to her","Loaves of bread","Customers"]', '["Uangnya","Setiap kali ada yang bersikap ramah kepadanya","Roti","Pelanggan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-word-that-costs-nothing_3', 'bok_the-word-that-costs-nothing', 3, 'What was on the second page?', 'Apa isi halaman kedua?', '["Debts","Kind things she had done that nobody paid for","Complaints","Prices"]', '["Utang","Kebaikan yang ia lakukan tanpa dibayar","Keluhan","Daftar harga"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-cave-behind-the-waterfall', 'the-cave-behind-the-waterfall', 'The Cave Behind the Waterfall', 'Gua di Balik Air Terjun', 'Three friends find a way behind the falls. What they discover is not treasure — it is older and stranger than that.', 'Tiga sahabat menemukan jalan ke balik air terjun. Yang mereka temukan bukanlah harta karun — melainkan sesuatu yang jauh lebih tua dan lebih aneh.', 'cat_adventure', 'aut_axto-creative-team', 'forest', '💧', 7, 11, 0, 'published', 9, 2546, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_1', 'bok_the-cave-behind-the-waterfall', 1, 'cave-1', 'The waterfall at Lubuk Panjang came down in one thick rope, and behind it, if you went in at the left where the rock was dry, there was a gap you could turn sideways and fit through.', 'Air terjun di Lubuk Panjang jatuh dalam satu untaian tebal, dan di baliknya, kalau kau masuk dari sisi kiri tempat batunya kering, ada celah yang bisa kau lewati dengan memiringkan badan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_2', 'bok_the-cave-behind-the-waterfall', 2, 'cave-2', 'Rani found it. Then she made Doni and Sofi swear on three separate things before she would show them, which is how you know a discovery is serious.', 'Rani yang menemukannya. Lalu ia membuat Doni dan Sofi bersumpah atas tiga hal berbeda sebelum ia mau menunjukkannya, dan begitulah cara kau tahu sebuah penemuan itu serius.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_3', 'bok_the-cave-behind-the-waterfall', 3, 'cave-3', 'Inside, the sound changed completely. The roar became a hum you could feel in your chest. Light came through the falling water in green sheets that moved, so the whole cave seemed to be breathing.', 'Di dalam, suaranya berubah total. Deru itu menjadi dengung yang bisa kau rasakan di dada. Cahaya menembus air yang jatuh dalam lembaran hijau yang bergerak, sehingga seluruh gua tampak seperti sedang bernapas.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_4', 'bok_the-cave-behind-the-waterfall', 4, 'cave-4', 'They looked for treasure, because that is what you do. There was none. There was sand, and a lot of old bat droppings, and a wall at the back that Sofi put her torch against and then stopped moving entirely.', 'Mereka mencari harta karun, karena itulah yang biasa dilakukan. Tidak ada. Yang ada hanya pasir, banyak kotoran kelelawar tua, dan sebuah dinding di belakang tempat Sofi mengarahkan senternya lalu berhenti bergerak sama sekali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_5', 'bok_the-cave-behind-the-waterfall', 5, 'cave-5', 'There were hands on the wall. Dozens of them, in dark red, made by somebody putting a palm flat on the rock and blowing pigment around it. Small hands. Some no bigger than Sofi''s own.', 'Ada telapak tangan di dinding itu. Puluhan, berwarna merah tua, dibuat oleh seseorang yang menempelkan telapaknya rata di batu lalu menyemburkan pewarna di sekelilingnya. Telapak-telapak kecil. Beberapa tak lebih besar dari telapak Sofi sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_6', 'bok_the-cave-behind-the-waterfall', 6, 'cave-6', 'Nobody said anything for a long time. Then Doni reached out to put his own hand next to one, and Rani caught his wrist. "Don''t," she said. "You don''t know what it does to it." And Doni put his hand back down.', 'Tidak ada yang berbicara untuk waktu yang lama. Lalu Doni mengulurkan tangan hendak menempelkan telapaknya di samping salah satunya, dan Rani menangkap pergelangannya. "Jangan," katanya. "Kau tidak tahu efeknya pada gambar itu." Dan Doni menurunkan tangannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_7', 'bok_the-cave-behind-the-waterfall', 7, 'cave-7', 'They argued about what to do, outside, sitting on wet rocks. Keep it secret and it stays theirs. Tell somebody and it stops being theirs, and might be protected, and might be ruined by visitors instead.', 'Mereka berdebat tentang apa yang harus dilakukan, di luar, sambil duduk di batu basah. Dirahasiakan, maka tetap milik mereka. Diberitahukan, maka berhenti menjadi milik mereka, dan mungkin dilindungi, atau justru dirusak pengunjung.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_8', 'bok_the-cave-behind-the-waterfall', 8, 'cave-8', 'In the end Rani said the thing that decided it. "Those hands are somebody''s kids. Somebody put them there so they would still be there. If we keep it secret and the roof falls in, nobody ever knows they existed."', 'Akhirnya Rani mengucapkan hal yang menentukan. "Telapak-telapak itu milik anak-anak seseorang. Seseorang menaruhnya di sana supaya tetap ada. Kalau kita rahasiakan dan atapnya runtuh, tak seorang pun akan pernah tahu mereka pernah ada."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-cave-behind-the-waterfall_9', 'bok_the-cave-behind-the-waterfall', 9, 'cave-9', 'They told the school, who told the district, who sent two archaeologists in a very old van. The paintings are around nine thousand years old. There is a metal gate now, and a sign, and on the sign there are three names.', 'Mereka memberi tahu sekolah, sekolah memberi tahu kecamatan, kecamatan mengirim dua arkeolog dengan mobil van yang sangat tua. Lukisan itu berumur sekitar sembilan ribu tahun. Kini ada gerbang besi, sebuah papan, dan di papan itu tertulis tiga nama.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-cave-behind-the-waterfall_1', 'bok_the-cave-behind-the-waterfall', 1, 'What did the children find on the cave wall?', 'Apa yang anak-anak temukan di dinding gua?', '["Gold","Ancient painted handprints","Writing","A door"]', '["Emas","Cap telapak tangan kuno","Tulisan","Sebuah pintu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-cave-behind-the-waterfall_2', 'bok_the-cave-behind-the-waterfall', 2, 'Why did Rani stop Doni touching the wall?', 'Mengapa Rani mencegah Doni menyentuh dinding?', '["It was hot","They did not know what touching would do to it","It was dirty","It was forbidden by a sign"]', '["Dindingnya panas","Mereka tidak tahu efek sentuhan terhadapnya","Kotor","Dilarang oleh papan pengumuman"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-cave-behind-the-waterfall_3', 'bok_the-cave-behind-the-waterfall', 3, 'Why did they decide to tell somebody?', 'Mengapa mereka memutuskan memberi tahu orang lain?', '["For a reward","So the paintings would be known about and protected","They were forced to","They were bored of it"]', '["Demi hadiah","Supaya lukisan itu diketahui dan dilindungi","Mereka dipaksa","Mereka sudah bosan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-boy-who-always-won', 'the-boy-who-always-won', 'The Boy Who Always Won', 'Anak yang Selalu Menang', 'Reza wins every game he plays, and slowly runs out of people who want to play with him.', 'Reza memenangi setiap permainan yang ia mainkan, dan perlahan kehabisan orang yang mau bermain dengannya.', 'cat_friendship', 'aut_axto-creative-team', 'twilight', '♟️', 6, 10, 0, 'published', 9, 1189, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_1', 'bok_the-boy-who-always-won', 1, 'reza-1', 'Reza was good at games. Not a bit good — properly good, in a way that was slightly unfair. He won at chess, at cards, at every playground game with a rule in it, and he won almost every time.', 'Reza pandai bermain. Bukan sekadar pandai — benar-benar pandai, dengan cara yang sedikit tidak adil. Ia menang catur, kartu, dan setiap permainan di halaman sekolah yang punya aturan, dan ia menang hampir setiap kali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_2', 'bok_the-boy-who-always-won', 2, 'reza-2', 'He was not unkind about it. He did not gloat. He simply won, and then wanted to play again immediately, and could not really understand why other people did not.', 'Ia tidak jahat soal itu. Ia tidak menyombongkan diri. Ia hanya menang, lalu ingin bermain lagi seketika, dan tidak benar-benar mengerti mengapa orang lain tidak.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_3', 'bok_the-boy-who-always-won', 3, 'reza-3', 'By the middle of the year something had changed. When Reza brought the chess set to the table, people remembered something they had to do. The games at break started before he got there and were somehow always full.', 'Menjelang pertengahan tahun ada yang berubah. Ketika Reza membawa papan caturnya ke meja, orang-orang tiba-tiba ingat ada urusan lain. Permainan saat istirahat dimulai sebelum ia tiba dan entah bagaimana selalu sudah penuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_4', 'bok_the-boy-who-always-won', 4, 'reza-4', 'He thought they were jealous. That is the easiest explanation and it lasted about six weeks, and then it stopped being enough, because he was eating lunch on his own and jealousy did not explain how that felt.', 'Ia mengira mereka iri. Itu penjelasan yang paling mudah dan bertahan sekitar enam minggu, lalu berhenti mencukupi, karena ia makan siang sendirian dan rasa iri tidak menjelaskan bagaimana rasanya itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_5', 'bok_the-boy-who-always-won', 5, 'reza-5', 'He asked Nabila, who was blunt and therefore useful. She said, "You do not play with us. You play against us. There is a difference and you have never noticed it."', 'Ia bertanya kepada Nabila, yang blakblakan dan karenanya berguna. Nabila berkata, "Kau tidak bermain bersama kami. Kau bermain melawan kami. Ada bedanya dan kau tidak pernah menyadarinya."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_6', 'bok_the-boy-who-always-won', 6, 'reza-6', '"That is what a game is," said Reza. "No," said Nabila. "That is what winning is. A game is an hour with your friends that happens to have rules. You have been treating our hour as your test."', '"Memang begitulah permainan," kata Reza. "Bukan," kata Nabila. "Itu namanya menang. Permainan adalah satu jam bersama teman-teman yang kebetulan punya aturan. Kau memperlakukan satu jam kami sebagai ujianmu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_7', 'bok_the-boy-who-always-won', 7, 'reza-7', 'Reza did not like this at all and thought about it for two weeks. Then he did something that cost him a great deal: he asked Doni, who was terrible at chess, to teach him a game Doni was good at instead.', 'Reza sama sekali tidak menyukai ini dan memikirkannya selama dua minggu. Lalu ia melakukan sesuatu yang harganya mahal baginya: ia meminta Doni, yang payah bermain catur, untuk mengajarinya permainan yang Doni kuasai.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_8', 'bok_the-boy-who-always-won', 8, 'reza-8', 'It was a card game with complicated scoring and Reza lost eleven times in a row, which was the most useful afternoon of his year. Doni explained things patiently and enjoyed himself enormously, and Reza noticed that too.', 'Itu permainan kartu dengan penilaian rumit dan Reza kalah sebelas kali berturut-turut, yang menjadi sore paling berguna sepanjang tahunnya. Doni menjelaskan dengan sabar dan sangat menikmatinya, dan Reza menyadari itu juga.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-always-won_9', 'bok_the-boy-who-always-won', 9, 'reza-9', 'He still wins at chess. Nobody has beaten him yet. But now he plays four other games badly, and laughs when he loses, and the table at break is full again — with him at it.', 'Ia masih menang catur. Belum ada yang mengalahkannya. Tetapi kini ia memainkan empat permainan lain dengan payah, tertawa ketika kalah, dan meja saat istirahat kembali penuh — dengan dirinya di sana.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-always-won_1', 'bok_the-boy-who-always-won', 1, 'Why did people stop playing with Reza?', 'Mengapa orang-orang berhenti bermain dengan Reza?', '["He cheated","He played against them rather than with them","He was rude","He was too slow"]', '["Ia curang","Ia bermain melawan mereka, bukan bersama mereka","Ia kasar","Ia terlalu lambat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-always-won_2', 'bok_the-boy-who-always-won', 2, 'What did Nabila say a game is?', 'Menurut Nabila, apa itu permainan?', '["A test of skill","An hour with your friends that happens to have rules","A way to win","A waste of time"]', '["Ujian keterampilan","Satu jam bersama teman yang kebetulan punya aturan","Cara untuk menang","Buang-buang waktu"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-always-won_3', 'bok_the-boy-who-always-won', 3, 'What did Reza do about it?', 'Apa yang Reza lakukan menanggapinya?', '["Stopped playing","Asked Doni to teach him a game he was bad at","Practised chess more","Found new friends"]', '["Berhenti bermain","Meminta Doni mengajarinya permainan yang tidak ia kuasai","Berlatih catur lebih giat","Mencari teman baru"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-fisherman-and-the-two-nets', 'the-fisherman-and-the-two-nets', 'The Fisherman and the Two Nets', 'Nelayan dan Dua Jala', 'One fisherman uses a net with wide holes and catches less. Everybody laughs at him for nine years.', 'Seorang nelayan memakai jala berlubang lebar dan mendapat tangkapan lebih sedikit. Semua orang menertawakannya selama sembilan tahun.', 'cat_moral-stories', 'aut_axto-creative-team', 'ocean', '🎣', 7, 11, 0, 'published', 9, 3769, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_1', 'bok_the-fisherman-and-the-two-nets', 1, 'nets-1', 'In the fishing village of Muara Kecil there were forty boats, and thirty-nine of them used nets with a fine, tight mesh that caught everything that swam into it, large and small alike.', 'Di desa nelayan Muara Kecil ada empat puluh perahu, dan tiga puluh sembilan di antaranya memakai jala bermata rapat yang menangkap segala yang masuk, besar maupun kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_2', 'bok_the-fisherman-and-the-two-nets', 2, 'nets-2', 'Pak Umar used a net with holes wide enough for a young fish to swim straight through. Every evening he came back with less than everybody else, and every evening somebody said something about it.', 'Pak Umar memakai jala berlubang cukup lebar sehingga ikan muda bisa lolos begitu saja. Setiap petang ia pulang dengan tangkapan lebih sedikit daripada yang lain, dan setiap petang ada saja yang mengomentarinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_3', 'bok_the-fisherman-and-the-two-nets', 3, 'nets-3', 'His son asked him why. Pak Umar said, "The small ones are not fish yet. They are next year." His son said this was a nice thing to say and did not put rice on the table, which was fair.', 'Anaknya bertanya mengapa. Pak Umar menjawab, "Yang kecil-kecil itu belum jadi ikan. Mereka itu tahun depan." Anaknya berkata itu ucapan yang bagus tetapi tidak menaruh nasi di meja, dan itu memang benar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_4', 'bok_the-fisherman-and-the-two-nets', 4, 'nets-4', 'For three years it made no visible difference. Everybody caught plenty. Pak Umar caught slightly less than plenty and was the subject of a joke that had stopped being funny to everyone except the man who made it.', 'Selama tiga tahun tidak ada bedanya yang kelihatan. Semua orang mendapat banyak. Pak Umar mendapat sedikit kurang dari banyak dan menjadi bahan lelucon yang sudah tidak lucu bagi siapa pun kecuali si pembuat lelucon.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_5', 'bok_the-fisherman-and-the-two-nets', 5, 'nets-5', 'In the fifth year the catches began to drop. Not sharply. A little each season, the way a thing goes when nobody is measuring it. The boats went further out, which cost more fuel, and caught the same less.', 'Pada tahun kelima tangkapan mulai menurun. Tidak tajam. Sedikit demi sedikit setiap musim, seperti halnya sesuatu yang tidak diukur siapa pun. Perahu-perahu melaut lebih jauh, yang menghabiskan lebih banyak bahan bakar, dan tetap mendapat lebih sedikit.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_6', 'bok_the-fisherman-and-the-two-nets', 6, 'nets-6', 'By the ninth year, four boats had been sold and two families had left the village. And Pak Umar was catching what he had always caught: slightly less than plenty, in the same water, close in.', 'Pada tahun kesembilan, empat perahu telah dijual dan dua keluarga meninggalkan desa. Dan Pak Umar tetap mendapat apa yang selalu ia dapat: sedikit kurang dari banyak, di perairan yang sama, tidak jauh dari pantai.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_7', 'bok_the-fisherman-and-the-two-nets', 7, 'nets-7', 'The village head came to his house, which took some doing, and asked him about the net. Pak Umar showed him. Then he took him out at dawn and showed him the shallows where the young fish were, thick as smoke.', 'Kepala desa datang ke rumahnya, yang butuh keberanian tersendiri, dan bertanya tentang jalanya. Pak Umar menunjukkannya. Lalu ia membawanya melaut saat fajar dan menunjukkan perairan dangkal tempat ikan-ikan muda berkumpul, tebal seperti asap.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_8', 'bok_the-fisherman-and-the-two-nets', 8, 'nets-8', 'It took two years of arguing to change the nets. Some people never forgave him for being right, which is a thing that happens. But the catches came back, slowly, over about six years.', 'Butuh dua tahun perdebatan untuk mengganti jala. Sebagian orang tidak pernah memaafkannya karena telah benar, dan hal semacam itu memang terjadi. Tetapi tangkapan kembali pulih, perlahan, selama sekitar enam tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-fisherman-and-the-two-nets_9', 'bok_the-fisherman-and-the-two-nets', 9, 'nets-9', 'Pak Umar is dead now. The nets in Muara Kecil all have wide holes. Nobody there thinks of it as his idea any more — it is simply how you fish — which is what it looks like when somebody has genuinely won an argument.', 'Pak Umar kini telah tiada. Jala-jala di Muara Kecil semuanya berlubang lebar. Tidak ada lagi yang menganggapnya gagasan Pak Umar — itu sekadar cara orang menjala — dan begitulah rupanya ketika seseorang benar-benar memenangi sebuah perdebatan.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-two-nets_1', 'bok_the-fisherman-and-the-two-nets', 1, 'Why did Pak Umar use a net with wide holes?', 'Mengapa Pak Umar memakai jala berlubang lebar?', '["It was cheaper","So young fish could escape and grow","It was all he had","It was faster"]', '["Lebih murah","Supaya ikan muda bisa lolos dan tumbuh","Hanya itu yang ia punya","Lebih cepat"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-two-nets_2', 'bok_the-fisherman-and-the-two-nets', 2, 'What happened to the other boats after several years?', 'Apa yang terjadi pada perahu-perahu lain setelah beberapa tahun?', '["They caught more","Their catches dropped and some were sold","Nothing changed","They moved to a river"]', '["Tangkapannya bertambah","Tangkapannya menurun dan sebagian dijual","Tidak ada yang berubah","Mereka pindah ke sungai"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-fisherman-and-the-two-nets_3', 'bok_the-fisherman-and-the-two-nets', 3, 'How can you tell Pak Umar won the argument?', 'Bagaimana kita tahu Pak Umar memenangi perdebatan itu?', '["He became rich","Wide nets are simply how everyone fishes now","He was given a prize","He left the village"]', '["Ia menjadi kaya","Jala lebar kini sekadar cara semua orang menjala","Ia diberi hadiah","Ia meninggalkan desa"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-girl-who-swapped-shoes', 'the-girl-who-swapped-shoes', 'The Girl Who Swapped Shoes', 'Gadis yang Bertukar Sepatu', 'An old tale retold: a girl who can walk one day in anybody''s shoes, and the three days that change her mind about everyone.', 'Sebuah kisah lama yang diceritakan ulang: seorang gadis yang bisa berjalan sehari dengan sepatu siapa pun, dan tiga hari yang mengubah pandangannya tentang semua orang.', 'cat_fairy-tales', 'aut_axto-creative-team', 'twilight', '👞', 7, 11, 0, 'published', 9, 2646, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_1', 'bok_the-girl-who-swapped-shoes', 1, 'shoes-1', 'A woman at the market sold Lastri a pair of plain brown shoes for almost nothing, and told her the condition as she wrapped them: put them on with somebody else''s name in your mouth, and you will have their day.', 'Seorang perempuan di pasar menjual sepasang sepatu cokelat polos kepada Lastri dengan harga hampir gratis, dan menyampaikan syaratnya sambil membungkusnya: pakailah sepatu ini sambil menyebut nama orang lain, dan kau akan menjalani hari mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_2', 'bok_the-girl-who-swapped-shoes', 2, 'shoes-2', 'Lastri did not believe it, so she tried it on the person she liked least: Bu Warni, who was sharp with everybody at the shop and had once made a small child cry over a dropped egg.', 'Lastri tidak percaya, maka ia mencobanya pada orang yang paling tidak ia sukai: Bu Warni, yang ketus kepada semua orang di toko dan pernah membuat seorang anak kecil menangis karena telur yang jatuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_3', 'bok_the-girl-who-swapped-shoes', 3, 'shoes-3', 'She had Bu Warni''s day. It began at four in the morning. It contained a husband who had not been well for two years, a stock delivery that came short, and eleven hours on feet that hurt with every step.', 'Ia menjalani hari Bu Warni. Hari itu dimulai pukul empat pagi. Isinya seorang suami yang sudah dua tahun sakit, kiriman barang yang kurang, dan sebelas jam berdiri di atas kaki yang nyeri di setiap langkah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_4', 'bok_the-girl-who-swapped-shoes', 4, 'shoes-4', 'By the afternoon Lastri wanted to snap at somebody, and did, at a child who had dropped something, and heard her own voice come out sharp and was horrified by how easy it had been.', 'Menjelang sore Lastri ingin membentak seseorang, dan ia melakukannya, kepada seorang anak yang menjatuhkan sesuatu, lalu mendengar suaranya sendiri keluar dengan ketus dan ngeri betapa mudahnya itu terjadi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_5', 'bok_the-girl-who-swapped-shoes', 5, 'shoes-5', 'The next day she chose somebody she envied: Ayu, who was beautiful and clever and had, as far as anybody could tell, no problems at all.', 'Keesokan harinya ia memilih seseorang yang ia iri: Ayu, yang cantik dan pintar dan, sejauh yang bisa dilihat siapa pun, sama sekali tidak punya masalah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_6', 'bok_the-girl-who-swapped-shoes', 6, 'shoes-6', 'Ayu''s day was quiet and comfortable and lonely in a way Lastri had not imagined. Nobody said anything to Ayu that was not about how she looked. Not once, all day, did anybody ask her a real question.', 'Hari Ayu tenang dan nyaman dan kesepian dengan cara yang tidak pernah Lastri bayangkan. Tak seorang pun berbicara kepada Ayu tentang hal selain penampilannya. Sepanjang hari itu, tak sekali pun ada yang menanyakan pertanyaan sungguhan kepadanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_7', 'bok_the-girl-who-swapped-shoes', 7, 'shoes-7', 'On the third day, out of curiosity rather than kindness, Lastri said her own name. And she had her own day, from the outside, and watched herself be short with her mother over nothing at all.', 'Pada hari ketiga, karena penasaran dan bukan karena kebaikan hati, Lastri menyebut namanya sendiri. Dan ia menjalani harinya sendiri, dari luar, dan menyaksikan dirinya bersikap ketus kepada ibunya karena hal yang sama sekali sepele.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_8', 'bok_the-girl-who-swapped-shoes', 8, 'shoes-8', 'That was the day that changed things. It is one thing to learn that other people are carrying something. It is quite another to watch yourself from two steps back and see exactly what you look like doing it.', 'Hari itulah yang mengubah segalanya. Satu hal untuk mengetahui bahwa orang lain sedang memikul sesuatu. Hal lain lagi untuk menyaksikan dirimu sendiri dari dua langkah di belakang dan melihat persis seperti apa rupamu saat melakukannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-girl-who-swapped-shoes_9', 'bok_the-girl-who-swapped-shoes', 9, 'shoes-9', 'Lastri gave the shoes back to the woman at the market. "Did they work?" the woman asked. Lastri said, "They were not for finding out about other people, were they." And the woman smiled and wrapped them up for somebody else.', 'Lastri mengembalikan sepatu itu kepada perempuan di pasar. "Berhasilkah?" tanya perempuan itu. Lastri berkata, "Sepatu ini bukan untuk mengetahui tentang orang lain, kan." Dan perempuan itu tersenyum lalu membungkusnya untuk orang berikutnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-swapped-shoes_1', 'bok_the-girl-who-swapped-shoes', 1, 'What did the shoes do?', 'Apa khasiat sepatu itu?', '["Made her run fast","Let her live somebody else''s day","Made her invisible","Took her anywhere"]', '["Membuatnya berlari cepat","Membuatnya menjalani hari orang lain","Membuatnya tak terlihat","Membawanya ke mana saja"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-swapped-shoes_2', 'bok_the-girl-who-swapped-shoes', 2, 'What did she discover about Ayu?', 'Apa yang ia temukan tentang Ayu?', '["She was secretly cruel","She was lonely and never asked a real question","She was very poor","She was pretending"]', '["Ia diam-diam kejam","Ia kesepian dan tak pernah ditanyai hal sungguhan","Ia sangat miskin","Ia berpura-pura"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-girl-who-swapped-shoes_3', 'bok_the-girl-who-swapped-shoes', 3, 'Which day changed her most?', 'Hari mana yang paling mengubahnya?', '["Bu Warni''s","Ayu''s","Her own","The first"]', '["Hari Bu Warni","Hari Ayu","Harinya sendiri","Hari pertama"]', 2, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-house-that-settles-at-night', 'the-house-that-settles-at-night', 'The House That Settles at Night', 'Rumah yang Menghela Napas di Malam Hari', 'Nabil cannot sleep because the house makes noises. His mother explains every single one of them, in order, until he stops hearing them.', 'Nabil tidak bisa tidur karena rumahnya berbunyi-bunyi. Ibunya menjelaskan setiap bunyi itu, satu per satu, sampai ia berhenti mendengarnya.', 'cat_bedtime', 'aut_axto-creative-team', 'twilight', '🏠', 3, 7, 0, 'published', 9, 1238, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_1', 'bok_the-house-that-settles-at-night', 1, 'settle-1', 'Nabil could not sleep, because the house was talking. It only ever talked at night, when everything else had gone quiet, and it said things in creaks and taps and small sighs.', 'Nabil tidak bisa tidur, karena rumahnya sedang berbicara. Rumah itu hanya berbicara di malam hari, ketika semua yang lain sudah senyap, dan ia berkata-kata lewat derit, ketukan, dan helaan kecil.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_2', 'bok_the-house-that-settles-at-night', 2, 'settle-2', 'His mother came and sat on the end of the bed. She did not say there was nothing there. She said, "Let us do them one at a time. Tell me when you hear one."', 'Ibunya datang dan duduk di ujung tempat tidur. Ia tidak berkata bahwa tidak ada apa-apa. Ia berkata, "Mari kita bahas satu per satu. Beri tahu Ibu kalau kamu dengar salah satunya."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_3', 'bok_the-house-that-settles-at-night', 3, 'settle-3', 'A long slow creak from above. "That is the roof beam," she said. "It was warm all day and now it is cooling down, and wood gets very slightly smaller when it cools. That noise is the house getting smaller."', 'Terdengar derit panjang dan lambat dari atas. "Itu balok atap," katanya. "Seharian ia hangat dan sekarang mendingin, dan kayu menyusut sedikit saat mendingin. Bunyi itu adalah rumah yang sedang mengecil."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_4', 'bok_the-house-that-settles-at-night', 4, 'settle-4', 'A tick, tick, tick from the corner. "That is the radiator pipe. There is water in it that was hot and is now not hot, and metal does the same thing as wood. Everything in this house is shrinking a tiny bit."', 'Terdengar tik, tik, tik dari sudut ruangan. "Itu pipa penghangat. Ada air di dalamnya yang tadinya panas dan sekarang tidak lagi, dan logam berperilaku seperti kayu. Semua di rumah ini sedang menyusut sedikit sekali."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_5', 'bok_the-house-that-settles-at-night', 5, 'settle-5', 'A soft thump on the floor above. Nabil sat up. His mother said, "That is the cat getting off the chair. She does it at about this time every night. Listen — in a moment she will scratch the arm." The cat scratched the arm.', 'Terdengar bunyi tumpul lembut di lantai atas. Nabil terduduk. Ibunya berkata, "Itu kucing turun dari kursi. Ia melakukannya sekitar jam segini setiap malam. Dengarkan — sebentar lagi ia akan mencakar sandaran kursi." Kucing itu mencakar sandaran kursi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_6', 'bok_the-house-that-settles-at-night', 6, 'settle-6', 'A rush and a hush outside. "Wind in the mango tree. When it comes from the north it goes through the leaves and sounds like the sea. When it comes from the east it hits the wall and sounds like nothing at all."', 'Terdengar desau lalu senyap di luar. "Angin di pohon mangga. Kalau datang dari utara ia melewati dedaunan dan terdengar seperti laut. Kalau dari timur ia menabrak tembok dan tidak terdengar apa-apa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_7', 'bok_the-house-that-settles-at-night', 7, 'settle-7', 'One more: a small knock, twice, from somewhere he could not place. His mother listened properly, and then said, "I do not know what that one is." And oddly, that helped more than any of the others.', 'Satu lagi: ketukan kecil, dua kali, dari tempat yang tidak bisa ia tentukan. Ibunya mendengarkan baik-baik, lalu berkata, "Ibu tidak tahu yang itu apa." Dan anehnya, itu justru lebih menenangkan daripada semua penjelasan sebelumnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_8', 'bok_the-house-that-settles-at-night', 8, 'settle-8', '"There are things in every house that nobody has worked out," she said. "That does not make them frightening. It makes them unfinished. You can go to sleep in the middle of an unfinished thing."', '"Di setiap rumah ada hal-hal yang belum dipecahkan siapa pun," katanya. "Itu tidak membuatnya menakutkan. Itu membuatnya belum selesai. Kamu boleh tidur di tengah sesuatu yang belum selesai."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-house-that-settles-at-night_9', 'bok_the-house-that-settles-at-night', 9, 'settle-9', 'Nabil listened to the house shrinking, and the cat, and the wind in the mango tree from the north. Somewhere in the middle of the list, without noticing he had done it, he stopped listening and went to sleep.', 'Nabil mendengarkan rumah yang menyusut, kucing itu, dan angin dari utara di pohon mangga. Di suatu titik di tengah daftar itu, tanpa menyadarinya, ia berhenti mendengarkan dan tertidur.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-house-that-settles-at-night_1', 'bok_the-house-that-settles-at-night', 1, 'Why does the roof beam creak at night?', 'Mengapa balok atap berderit di malam hari?', '["Somebody is walking on it","The wood cools and gets slightly smaller","It is broken","Birds sit on it"]', '["Ada yang berjalan di atasnya","Kayunya mendingin dan menyusut sedikit","Ia rusak","Burung hinggap di atasnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-house-that-settles-at-night_2', 'bok_the-house-that-settles-at-night', 2, 'What did his mother say about the noise she could not explain?', 'Apa kata ibunya tentang bunyi yang tidak bisa ia jelaskan?', '["It was dangerous","It was unfinished, not frightening","It was imaginary","To ignore it"]', '["Itu berbahaya","Itu belum selesai, bukan menakutkan","Itu khayalan","Abaikan saja"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-house-that-settles-at-night_3', 'bok_the-house-that-settles-at-night', 3, 'How did Nabil finally fall asleep?', 'Bagaimana akhirnya Nabil tertidur?', '["The noises stopped","He stopped listening without noticing","He counted sheep","He moved rooms"]', '["Bunyinya berhenti","Ia berhenti mendengarkan tanpa sadar","Ia menghitung domba","Ia pindah kamar"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-ants-who-built-a-bridge', 'the-ants-who-built-a-bridge', 'The Ants Who Built a Bridge', 'Semut-semut yang Membangun Jembatan', 'A boy watches a line of ants meet a gap they cannot cross, and discovers what they do about it.', 'Seorang anak mengamati barisan semut menemui celah yang tak bisa mereka seberangi, dan menemukan apa yang mereka lakukan.', 'cat_animals', 'aut_axto-creative-team', 'meadow', '🐜', 5, 9, 0, 'published', 9, 927, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_1', 'bok_the-ants-who-built-a-bridge', 1, 'ants-1', 'There was a crack in the concrete path behind Toni''s house, about as wide as his thumb, and a line of ants ran along the path from the drain to the mango tree and back all day long.', 'Ada retakan di jalan setapak beton di belakang rumah Toni, kira-kira selebar ibu jarinya, dan sebaris semut berjalan di jalan itu dari selokan ke pohon mangga dan kembali sepanjang hari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_2', 'bok_the-ants-who-built-a-bridge', 2, 'ants-2', 'When the ants reached the crack they had to go all the way around, which added a long detour to every single trip. Toni watched them do it for about twenty minutes and found it faintly annoying on their behalf.', 'Ketika semut-semut sampai di retakan itu mereka harus memutar jauh, yang menambah jalan memutar panjang pada setiap perjalanan. Toni mengamati mereka melakukannya sekitar dua puluh menit dan merasa agak jengkel mewakili mereka.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_3', 'bok_the-ants-who-built-a-bridge', 3, 'ants-3', 'Then something changed. Three ants stopped at the edge instead of turning. One reached across with her front legs. Another climbed onto her and reached further. A third gripped the second.', 'Lalu ada yang berubah. Tiga semut berhenti di tepi alih-alih berbelok. Satu mengulurkan kaki depannya menyeberang. Yang lain memanjat ke atasnya dan mengulur lebih jauh. Yang ketiga mencengkeram yang kedua.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_4', 'bok_the-ants-who-built-a-bridge', 4, 'ants-4', 'Toni got down on his stomach on the warm concrete. In eleven minutes the ants had made a chain across the crack out of their own bodies, holding on to one another with their legs and jaws.', 'Toni tiarap di beton yang hangat. Dalam sebelas menit semut-semut itu telah membuat rantai menyeberangi retakan dari tubuh mereka sendiri, saling berpegangan dengan kaki dan rahang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_5', 'bok_the-ants-who-built-a-bridge', 5, 'ants-5', 'And then the rest of the line simply walked over them. Hundreds of ants, carrying crumbs and seeds and one enormous piece of a dead beetle, walking on the backs of the ones holding still.', 'Lalu barisan lainnya berjalan begitu saja di atas mereka. Ratusan semut, membawa remah dan biji dan satu potongan besar kumbang mati, berjalan di punggung semut-semut yang diam menahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_6', 'bok_the-ants-who-built-a-bridge', 6, 'ants-6', 'Toni went and got his mother, who was busy, and made her come and look. She lay down on the concrete next to him in her work clothes and did not say anything for a full minute.', 'Toni pergi memanggil ibunya, yang sedang sibuk, dan memaksanya datang melihat. Ibunya berbaring di beton di sampingnya dengan pakaian kerjanya dan tidak berkata apa-apa selama satu menit penuh.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_7', 'bok_the-ants-who-built-a-bridge', 7, 'ants-7', '"How do they know?" said Toni. His mother said she did not think any single ant knew. "None of them can see the whole crack. They are each doing one small thing. The bridge is what happens when enough of them do it."', '"Bagaimana mereka tahu?" tanya Toni. Ibunya berkata ia tidak yakin ada satu semut pun yang tahu. "Tak satu pun dari mereka bisa melihat seluruh retakan. Masing-masing hanya melakukan satu hal kecil. Jembatan itu terjadi ketika cukup banyak yang melakukannya."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_8', 'bok_the-ants-who-built-a-bridge', 8, 'ants-8', 'The bridge stayed up until dusk. Then, when the traffic stopped, the ants at the bottom let go one at a time and the whole chain came apart and walked home, and there was nothing there at all.', 'Jembatan itu bertahan sampai senja. Lalu, ketika lalu lintas berhenti, semut-semut di bawah melepaskan pegangan satu per satu dan seluruh rantai terurai lalu berjalan pulang, dan tidak ada apa-apa lagi di sana.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ants-who-built-a-bridge_9', 'bok_the-ants-who-built-a-bridge', 9, 'ants-9', 'Toni checked the crack every day for a month. Some days there was a bridge and some days there was not. He never worked out how they decided, and neither, so far, has anybody else.', 'Toni memeriksa retakan itu setiap hari selama sebulan. Ada hari dengan jembatan dan ada hari tanpa jembatan. Ia tidak pernah bisa memecahkan bagaimana mereka memutuskan, dan sejauh ini, tak seorang pun bisa.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ants-who-built-a-bridge_1', 'bok_the-ants-who-built-a-bridge', 1, 'What did the ants do about the crack?', 'Apa yang semut-semut lakukan terhadap retakan itu?', '["Filled it with soil","Made a bridge out of their own bodies","Went around forever","Gave up"]', '["Menimbunnya dengan tanah","Membuat jembatan dari tubuh mereka sendiri","Terus memutar selamanya","Menyerah"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ants-who-built-a-bridge_2', 'bok_the-ants-who-built-a-bridge', 2, 'Does any single ant know the whole plan?', 'Apakah ada satu semut yang tahu seluruh rencananya?', '["Yes, the queen tells them","No — each does one small thing","Yes, the oldest one","They read a map"]', '["Ya, ratunya memberi tahu","Tidak — masing-masing melakukan satu hal kecil","Ya, yang paling tua","Mereka membaca peta"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ants-who-built-a-bridge_3', 'bok_the-ants-who-built-a-bridge', 3, 'What happened to the bridge at dusk?', 'Apa yang terjadi pada jembatan itu saat senja?', '["It stayed forever","The ants let go and walked home","It was washed away","It turned to stone"]', '["Bertahan selamanya","Semut-semut melepas pegangan dan pulang","Hanyut terbawa air","Berubah menjadi batu"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-whale-that-sang-the-wrong-song', 'the-whale-that-sang-the-wrong-song', 'The Whale That Sang the Wrong Song', 'Paus yang Menyanyikan Lagu yang Salah', 'A young whale sings at a pitch no other whale can hear. For eleven years nobody answers — and then somebody does.', 'Seekor paus muda bernyanyi pada nada yang tak bisa didengar paus lain. Selama sebelas tahun tak ada yang menjawab — lalu ada yang menjawab.', 'cat_ocean-life', 'aut_axto-creative-team', 'ocean', '🐋', 6, 10, 0, 'published', 9, 4175, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_1', 'bok_the-whale-that-sang-the-wrong-song', 1, 'whale-1', 'Whale song carries a very long way. A call made off one coast can be heard by a whale hundreds of kilometres away, which is how they find each other across an ocean that has no roads in it.', 'Nyanyian paus merambat sangat jauh. Panggilan dari satu pesisir bisa terdengar oleh paus ratusan kilometer jauhnya, dan begitulah cara mereka saling menemukan di samudra yang tidak punya jalan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_2', 'bok_the-whale-that-sang-the-wrong-song', 2, 'whale-2', 'There was a young whale whose song came out at the wrong pitch. Not a little wrong. So high that the other whales in her family could not hear it at all, the way you cannot hear a dog whistle.', 'Ada seekor paus muda yang nyanyiannya keluar pada nada yang salah. Bukan sedikit salah. Begitu tinggi sampai paus-paus lain di keluarganya sama sekali tidak bisa mendengarnya, seperti manusia tidak bisa mendengar peluit anjing.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_3', 'bok_the-whale-that-sang-the-wrong-song', 3, 'whale-3', 'She sang anyway. She sang across the cold water in the north and the warm water in the south, following the routes her mother had taught her, calling and calling and getting nothing back.', 'Ia tetap bernyanyi. Ia bernyanyi menyeberangi air dingin di utara dan air hangat di selatan, mengikuti rute yang diajarkan ibunya, memanggil dan memanggil dan tidak mendapat balasan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_4', 'bok_the-whale-that-sang-the-wrong-song', 4, 'whale-4', 'Eleven years. That is a long time to keep doing something that has never once worked. She did not stop, because a whale does not really have anything else to do with the inside of her chest.', 'Sebelas tahun. Itu waktu yang panjang untuk terus melakukan sesuatu yang tak pernah sekali pun berhasil. Ia tidak berhenti, karena seekor paus memang tidak punya kegiatan lain untuk isi dadanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_5', 'bok_the-whale-that-sang-the-wrong-song', 5, 'whale-5', 'In the twelfth year, some people on a ship put a microphone in the water to listen for something else entirely, and heard her instead: a single voice at a pitch no whale in the record had ever used.', 'Pada tahun kedua belas, beberapa orang di sebuah kapal menurunkan mikrofon ke dalam air untuk mendengarkan hal lain, dan justru mendengarnya: satu suara pada nada yang belum pernah dipakai paus mana pun dalam catatan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_6', 'bok_the-whale-that-sang-the-wrong-song', 6, 'whale-6', 'They followed her for two seasons. They could not see her often — the ocean is very large and a whale is smaller than the ocean — but they could hear her every night, and they wrote down every note.', 'Mereka mengikutinya selama dua musim. Mereka jarang bisa melihatnya — samudra sangat luas dan seekor paus lebih kecil daripada samudra — tetapi mereka bisa mendengarnya setiap malam, dan mereka mencatat setiap nadanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_7', 'bok_the-whale-that-sang-the-wrong-song', 7, 'whale-7', 'And here is the part that matters. In the second season, the recordings changed. There was her voice — and then, faintly, on some nights, other voices in her family answering slightly higher than they used to.', 'Dan inilah bagian yang penting. Pada musim kedua, rekamannya berubah. Ada suaranya — lalu, samar-samar, pada malam-malam tertentu, suara-suara lain di keluarganya menjawab dengan nada sedikit lebih tinggi daripada biasanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_8', 'bok_the-whale-that-sang-the-wrong-song', 8, 'whale-8', 'Nobody is certain what happened. The kindest explanation, and the one the scientists put in their paper very carefully, is that the others had been slowly learning to hear her.', 'Tidak ada yang yakin apa yang terjadi. Penjelasan yang paling murah hati, dan yang para ilmuwan tuliskan dengan sangat hati-hati dalam makalah mereka, adalah bahwa yang lain perlahan belajar mendengarnya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-whale-that-sang-the-wrong-song_9', 'bok_the-whale-that-sang-the-wrong-song', 9, 'whale-9', 'She is still out there somewhere, singing her wrong song across a very large amount of water. It took eleven years to be heard. That is a long time. It is not, it turns out, forever.', 'Ia masih ada di suatu tempat di sana, menyanyikan lagunya yang salah melintasi hamparan air yang sangat luas. Butuh sebelas tahun untuk didengar. Itu waktu yang panjang. Ternyata, itu bukan selamanya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whale-that-sang-the-wrong-song_1', 'bok_the-whale-that-sang-the-wrong-song', 1, 'Why could the other whales not hear her?', 'Mengapa paus-paus lain tidak bisa mendengarnya?', '["She was too quiet","Her song was at too high a pitch","She was too far away","She never sang"]', '["Suaranya terlalu pelan","Nyanyiannya terlalu tinggi nadanya","Ia terlalu jauh","Ia tidak pernah bernyanyi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whale-that-sang-the-wrong-song_2', 'bok_the-whale-that-sang-the-wrong-song', 2, 'Who heard her first?', 'Siapa yang pertama mendengarnya?', '["Another whale","People with a microphone in the water","A fish","Nobody ever did"]', '["Paus lain","Orang-orang dengan mikrofon di dalam air","Seekor ikan","Tidak pernah ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-whale-that-sang-the-wrong-song_3', 'bok_the-whale-that-sang-the-wrong-song', 3, 'What changed in the second season of recordings?', 'Apa yang berubah pada rekaman musim kedua?', '["She stopped singing","Other whales answered slightly higher than before","The ship left","The sea got louder"]', '["Ia berhenti bernyanyi","Paus lain menjawab dengan nada sedikit lebih tinggi","Kapalnya pergi","Lautnya jadi lebih berisik"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-shadow-that-told-the-time', 'the-shadow-that-told-the-time', 'The Shadow That Told the Time', 'Bayangan yang Menunjukkan Waktu', 'Anisa marks where the shed''s shadow falls, every hour, for a year. What she finds is not what she expected.', 'Anisa menandai letak bayangan gudang, setiap jam, selama setahun. Yang ia temukan bukan seperti yang ia duga.', 'cat_science', 'aut_axto-creative-team', 'citrus', '🌞', 7, 11, 0, 'published', 9, 741, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_1', 'bok_the-shadow-that-told-the-time', 1, 'shadow-1', 'It started because Anisa''s watch broke and nobody would replace it until her birthday. Her grandfather said, "Then use the sun," which she assumed was a joke, and it was not.', 'Semua bermula karena jam tangan Anisa rusak dan tak seorang pun mau menggantinya sampai ulang tahunnya. Kakeknya berkata, "Kalau begitu pakai matahari," yang ia kira lelucon, padahal bukan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_2', 'bok_the-shadow-that-told-the-time', 2, 'shadow-2', 'So she drove a stick into the yard and put a stone where the tip of its shadow fell at nine, and another at ten, and another at eleven, all the way to five. Seven stones in a curve.', 'Maka ia menancapkan sebatang tongkat di halaman dan meletakkan batu di tempat ujung bayangannya jatuh pukul sembilan, satu lagi pukul sepuluh, satu lagi pukul sebelas, sampai pukul lima. Tujuh batu dalam sebuah lengkungan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_3', 'bok_the-shadow-that-told-the-time', 3, 'shadow-3', 'For a week it worked beautifully. She could tell the time to within about ten minutes just by looking out of the window, and she was extremely pleased with herself, and said so, repeatedly.', 'Selama seminggu itu berjalan sempurna. Ia bisa menebak waktu dengan selisih sekitar sepuluh menit hanya dengan melihat dari jendela, dan ia sangat bangga pada dirinya sendiri, dan mengatakannya berulang kali.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_4', 'bok_the-shadow-that-told-the-time', 4, 'shadow-4', 'Then in the second month it started going wrong. The shadow at noon was not reaching the noon stone. By the third month it was falling well short, and she checked her stones four times because she assumed somebody had moved them.', 'Lalu pada bulan kedua mulai meleset. Bayangan tengah hari tidak lagi sampai ke batu tengah hari. Pada bulan ketiga jaraknya jauh kurang, dan ia memeriksa batu-batunya empat kali karena ia mengira ada yang memindahkannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_5', 'bok_the-shadow-that-told-the-time', 5, 'shadow-5', 'Her grandfather did not tell her the answer. He said, "Keep the stones. Add new ones in a different colour. And write the date on a piece of paper each time." So Anisa did, for a whole year, which is a long time when you are nine.', 'Kakeknya tidak memberi tahu jawabannya. Ia berkata, "Simpan batu-batunya. Tambahkan yang baru dengan warna berbeda. Dan tuliskan tanggalnya di secarik kertas setiap kali." Maka Anisa melakukannya, selama setahun penuh, yang terasa lama ketika kau berumur sembilan tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_6', 'bok_the-shadow-that-told-the-time', 6, 'shadow-6', 'By the following autumn there were four curves of stones in the yard, one for each season, and they made a shape: a long flattened figure, wide in winter, tight in summer, sweeping back and forth.', 'Menjelang musim gugur berikutnya ada empat lengkungan batu di halaman, satu untuk setiap musim, dan semuanya membentuk sebuah pola: sosok panjang yang memipih, lebar di musim dingin, rapat di musim panas, menyapu maju mundur.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_7', 'bok_the-shadow-that-told-the-time', 7, 'shadow-7', '"The sun is not in the same place," said Anisa. "Not at the same time. Not on different days." Her grandfather said, "Correct. Now say the other half of it." And Anisa thought, and went slightly pale, and said, "Or we are not."', '"Mataharinya tidak di tempat yang sama," kata Anisa. "Tidak pada jam yang sama. Tidak pada hari yang berbeda." Kakeknya berkata, "Benar. Sekarang sebutkan separuh sisanya." Anisa berpikir, wajahnya sedikit memucat, dan berkata, "Atau kitanya yang tidak."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_8', 'bok_the-shadow-that-told-the-time', 8, 'shadow-8', 'Which is the whole thing, really. The Earth is tilted, and it goes round, and so the sun stands at a different height at noon in January than in July, and a stick in a yard will tell you that if you are patient enough to watch it for a year.', 'Dan sebenarnya itulah intinya. Bumi miring, dan ia mengelilingi matahari, sehingga matahari berdiri pada ketinggian berbeda pada tengah hari di bulan Januari dibanding Juli, dan sebatang tongkat di halaman akan memberitahumu itu kalau kau cukup sabar mengamatinya selama setahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-shadow-that-told-the-time_9', 'bok_the-shadow-that-told-the-time', 9, 'shadow-9', 'She got a watch for her birthday. The stones are still in the yard. Her grandfather mows around them, carefully, every summer, and has never once suggested taking them up.', 'Ia mendapat jam tangan di hari ulang tahunnya. Batu-batu itu masih ada di halaman. Kakeknya memangkas rumput mengitarinya, dengan hati-hati, setiap musim panas, dan tidak pernah sekali pun mengusulkan untuk mengangkatnya.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shadow-that-told-the-time_1', 'bok_the-shadow-that-told-the-time', 1, 'What did Anisa use to tell the time?', 'Apa yang Anisa pakai untuk menentukan waktu?', '["A clock","A stick''s shadow and marker stones","The birds","A candle"]', '["Sebuah jam","Bayangan tongkat dan batu penanda","Burung-burung","Sebatang lilin"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shadow-that-told-the-time_2', 'bok_the-shadow-that-told-the-time', 2, 'Why did the shadow stop matching her stones?', 'Mengapa bayangannya tidak lagi cocok dengan batu-batunya?', '["Somebody moved them","The sun''s height at noon changes through the year","The stick shrank","It was cloudy"]', '["Ada yang memindahkannya","Ketinggian matahari di tengah hari berubah sepanjang tahun","Tongkatnya menyusut","Cuacanya mendung"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-shadow-that-told-the-time_3', 'bok_the-shadow-that-told-the-time', 3, 'What causes it?', 'Apa penyebabnya?', '["The sun moving away","The Earth being tilted as it goes round","Clouds","The seasons changing the sun"]', '["Matahari menjauh","Bumi yang miring saat mengelilingi matahari","Awan","Musim yang mengubah matahari"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-boy-who-could-not-read', 'the-boy-who-could-not-read', 'The Boy Who Could Not Read', 'Anak yang Tidak Bisa Membaca', 'Rangga is nine and the letters move on the page. It takes a long time before anybody realises that is what he means.', 'Rangga berumur sembilan tahun dan huruf-huruf bergerak di halaman. Butuh waktu lama sampai ada yang menyadari itulah yang ia maksud.', 'cat_learning', 'aut_axto-creative-team', 'sunrise', '📖', 7, 11, 0, 'published', 9, 4625, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_1', 'bok_the-boy-who-could-not-read', 1, 'rangga-1', 'Rangga was nine and could not read properly, and everybody had a theory about why. He was lazy. He was not concentrating. He was clever but would not apply himself. He heard all four theories that year.', 'Rangga berumur sembilan tahun dan belum bisa membaca dengan baik, dan semua orang punya teori tentang sebabnya. Ia malas. Ia tidak berkonsentrasi. Ia pintar tapi tidak mau berusaha. Ia mendengar keempat teori itu tahun itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_2', 'bok_the-boy-who-could-not-read', 2, 'rangga-2', 'What Rangga actually experienced, when he looked at a page, was that the letters would not hold still. They swam a little, and swapped places, and the white spaces between the words closed up like water.', 'Yang sebenarnya Rangga alami, ketika menatap halaman, adalah huruf-huruf itu tidak mau diam. Mereka sedikit berenang, bertukar tempat, dan ruang-ruang putih di antara kata menutup seperti air.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_3', 'bok_the-boy-who-could-not-read', 3, 'rangga-3', 'He had said this once, when he was six, in the only words he had. He said, "It moves." The adult had said, "Books do not move, Rangga," quite kindly, and that had been the end of it for three years.', 'Ia pernah mengatakannya sekali, waktu berumur enam tahun, dengan satu-satunya kata yang ia punya. Ia berkata, "Itu bergerak." Orang dewasa itu menjawab, "Buku tidak bergerak, Rangga," dengan cukup ramah, dan itu jadi akhir pembicaraan selama tiga tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_4', 'bok_the-boy-who-could-not-read', 4, 'rangga-4', 'In year four he got a teacher called Pak Anton who asked a different question. Not "why are you not reading" but "tell me exactly what you see." And then he waited, without filling the silence, for a long time.', 'Di kelas empat ia mendapat guru bernama Pak Anton yang mengajukan pertanyaan berbeda. Bukan "mengapa kau tidak membaca" melainkan "ceritakan persis apa yang kau lihat." Lalu ia menunggu, tanpa mengisi keheningan, cukup lama.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_5', 'bok_the-boy-who-could-not-read', 5, 'rangga-5', 'Rangga said the letters moved. Pak Anton did not say books do not move. He said, "Right," and wrote it down, and made a phone call, and six weeks later Rangga saw a specialist who used a word he had never heard.', 'Rangga berkata huruf-hurufnya bergerak. Pak Anton tidak berkata bahwa buku tidak bergerak. Ia berkata, "Baik," lalu mencatatnya, lalu menelepon, dan enam minggu kemudian Rangga bertemu spesialis yang memakai sebuah kata yang belum pernah ia dengar.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_6', 'bok_the-boy-who-could-not-read', 6, 'rangga-6', 'It has a name. Millions of people have it. It has nothing to do with being lazy or stupid, and a great deal to do with how a particular brain handles the shapes of letters, and there are things that help.', 'Ada namanya. Jutaan orang mengalaminya. Itu sama sekali tidak berhubungan dengan malas atau bodoh, dan sangat berhubungan dengan cara suatu otak menangani bentuk huruf, dan ada hal-hal yang membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_7', 'bok_the-boy-who-could-not-read', 7, 'rangga-7', 'Some of them were absurdly simple. A different typeface. Cream paper instead of white. A ruler under the line. A coloured overlay. Reading aloud with somebody. None of it was a cure and all of it was a help.', 'Sebagian sangat sederhana sampai terasa konyol. Jenis huruf yang berbeda. Kertas krem alih-alih putih. Penggaris di bawah baris. Lembar berwarna transparan. Membaca lantang bersama seseorang. Tidak ada yang menyembuhkan, tetapi semuanya membantu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_8', 'bok_the-boy-who-could-not-read', 8, 'rangga-8', 'It still takes Rangga longer than it takes his sister. It will always take longer. But he read a whole book in December, on his own, and phoned Pak Anton from the kitchen to tell him, which Pak Anton has never mentioned to anybody without smiling.', 'Rangga masih butuh waktu lebih lama daripada adiknya. Akan selalu lebih lama. Tetapi ia membaca satu buku utuh pada bulan Desember, sendirian, dan menelepon Pak Anton dari dapur untuk memberitahunya, dan Pak Anton tidak pernah menceritakan itu tanpa tersenyum.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-boy-who-could-not-read_9', 'bok_the-boy-who-could-not-read', 9, 'rangga-9', 'The thing Rangga says now, when he is asked, is this: he had been telling people for three years. The words were right. Nobody had asked the question that would let them be understood.', 'Yang Rangga katakan sekarang, ketika ditanya, adalah ini: ia sudah memberi tahu orang-orang selama tiga tahun. Kata-katanya benar. Tidak ada yang mengajukan pertanyaan yang memungkinkan kata-kata itu dipahami.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-could-not-read_1', 'bok_the-boy-who-could-not-read', 1, 'What did Rangga actually see on the page?', 'Apa yang sebenarnya Rangga lihat di halaman?', '["Nothing","Letters that would not hold still","Pictures","Blank paper"]', '["Tidak ada apa-apa","Huruf-huruf yang tidak mau diam","Gambar","Kertas kosong"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-could-not-read_2', 'bok_the-boy-who-could-not-read', 2, 'What did Pak Anton do differently?', 'Apa yang Pak Anton lakukan secara berbeda?', '["Gave him easier books","Asked exactly what he saw and waited","Told him to try harder","Moved his seat"]', '["Memberinya buku lebih mudah","Bertanya persis apa yang ia lihat lalu menunggu","Menyuruhnya berusaha lebih keras","Memindahkan tempat duduknya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-boy-who-could-not-read_3', 'bok_the-boy-who-could-not-read', 3, 'What helped Rangga?', 'Apa yang membantu Rangga?', '["A cure","Small changes like typeface, cream paper and a ruler","Reading less","Nothing"]', '["Obat penyembuh","Perubahan kecil seperti jenis huruf, kertas krem, dan penggaris","Membaca lebih sedikit","Tidak ada"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-day-i-was-not-chosen', 'the-day-i-was-not-chosen', 'The Day I Was Not Chosen', 'Hari Ketika Aku Tidak Terpilih', 'Ayu practised for six weeks and did not get the part. This is about the fortnight afterwards, which nobody usually writes about.', 'Ayu berlatih selama enam minggu dan tidak mendapat perannya. Ini tentang dua minggu sesudahnya, yang biasanya tidak ditulis siapa pun.', 'cat_emotions', 'aut_axto-creative-team', 'twilight', '🎭', 6, 10, 0, 'published', 9, 3189, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_1', 'bok_the-day-i-was-not-chosen', 1, 'notchosen-1', 'I practised for six weeks. I am telling you that first because it matters. Not two days. Six weeks, in my room, with the door shut, including the part where the bird dies.', 'Aku berlatih selama enam minggu. Aku menyebutkan itu lebih dulu karena itu penting. Bukan dua hari. Enam minggu, di kamarku, dengan pintu tertutup, termasuk bagian ketika burungnya mati.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_2', 'bok_the-day-i-was-not-chosen', 2, 'notchosen-2', 'The list went up on a Thursday. My name was on it, under CHORUS, which is where they put everybody who is not somebody. Dini got the part. Dini had practised for about a week and a half.', 'Daftarnya dipasang hari Kamis. Namaku ada di sana, di bawah PADUAN SUARA, tempat mereka menaruh semua orang yang bukan siapa-siapa. Dini yang mendapat perannya. Dini berlatih sekitar satu setengah minggu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_3', 'bok_the-day-i-was-not-chosen', 3, 'notchosen-3', 'Everybody was very kind, which was the worst part. My mother said there would be other plays. My teacher said I had done really well. Somebody said everything happens for a reason, and I had to leave the room.', 'Semua orang sangat baik, dan itulah bagian terburuknya. Ibuku berkata akan ada pementasan lain. Guruku berkata aku sudah tampil sangat bagus. Seseorang berkata segala sesuatu terjadi karena ada alasannya, dan aku harus keluar ruangan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_4', 'bok_the-day-i-was-not-chosen', 4, 'notchosen-4', 'For four days I was fine in a way that was not fine. I said I did not care. I said the play was stupid anyway. I was extremely pleasant to Dini, which she noticed, and which was not kind of me at all.', 'Selama empat hari aku baik-baik saja dengan cara yang tidak baik-baik saja. Aku berkata aku tidak peduli. Aku berkata pementasan itu memang konyol. Aku sangat manis kepada Dini, yang ia sadari, dan itu sama sekali bukan kebaikan dariku.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_5', 'bok_the-day-i-was-not-chosen', 5, 'notchosen-5', 'On the fifth day my grandmother asked how it was going, and I said fine, and she said, "Yes, but how is it actually going," and I cried for about twenty minutes, which I had needed to do since Thursday.', 'Pada hari kelima nenekku bertanya bagaimana kabarnya, dan aku menjawab baik, dan ia berkata, "Ya, tapi sebenarnya bagaimana," lalu aku menangis sekitar dua puluh menit, yang sebenarnya sudah kubutuhkan sejak Kamis.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_6', 'bok_the-day-i-was-not-chosen', 6, 'notchosen-6', 'She did not tell me it would be all right. She said, "That is a real disappointment and you are allowed to have it for a while." A while turned out to be about nine days, which I would not have believed at the time.', 'Ia tidak berkata semuanya akan baik-baik saja. Ia berkata, "Itu kekecewaan yang nyata dan kau boleh memilikinya beberapa saat." Beberapa saat itu ternyata sekitar sembilan hari, yang tidak akan kupercaya waktu itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_7', 'bok_the-day-i-was-not-chosen', 7, 'notchosen-7', 'On day ten I went back to rehearsal, and I was in the chorus, and it was boring, and then it was not boring, because being in a chorus is quite good fun once you stop thinking about the part you did not get.', 'Pada hari kesepuluh aku kembali ke latihan, dan aku di paduan suara, dan membosankan, lalu tidak lagi membosankan, karena berada di paduan suara cukup menyenangkan begitu kau berhenti memikirkan peran yang tidak kau dapat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_8', 'bok_the-day-i-was-not-chosen', 8, 'notchosen-8', 'Dini was good. I want that written down because for two weeks I very much did not want it to be true. She was good, and I could tell she was good, and being able to tell was the thing that finally let it go.', 'Dini bagus. Aku ingin itu tercatat karena selama dua minggu aku sangat tidak ingin itu benar. Ia bagus, dan aku bisa menilainya bagus, dan kemampuan menilai itulah yang akhirnya melepaskan semuanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-day-i-was-not-chosen_9', 'bok_the-day-i-was-not-chosen', 9, 'notchosen-9', 'I got a part the following year. That is not the point of the story. The point is the nine days, and that they ended, and that nobody had told me they would end on their own if I stopped pretending they had not started.', 'Aku mendapat peran tahun berikutnya. Itu bukan inti ceritanya. Intinya adalah sembilan hari itu, dan bahwa hari-hari itu berakhir, dan bahwa tidak ada yang memberitahuku bahwa hari-hari itu akan berakhir sendiri jika aku berhenti berpura-pura hari-hari itu tidak pernah dimulai.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-i-was-not-chosen_1', 'bok_the-day-i-was-not-chosen', 1, 'How long had Ayu practised?', 'Berapa lama Ayu berlatih?', '["Two days","Six weeks","One year","She had not"]', '["Dua hari","Enam minggu","Satu tahun","Ia tidak berlatih"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-i-was-not-chosen_2', 'bok_the-day-i-was-not-chosen', 2, 'What did her grandmother say?', 'Apa kata neneknya?', '["It will be all right","That it is a real disappointment and she may have it for a while","To try harder","To forget it"]', '["Semua akan baik-baik saja","Bahwa itu kekecewaan nyata dan ia boleh memilikinya sejenak","Berusaha lebih keras","Melupakannya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-day-i-was-not-chosen_3', 'bok_the-day-i-was-not-chosen', 3, 'What finally let Ayu move on?', 'Apa yang akhirnya membuat Ayu bisa melanjutkan hidup?', '["Getting the part","Being able to admit Dini was good","Leaving the play","Ignoring it"]', '["Mendapatkan peran itu","Bisa mengakui bahwa Dini bagus","Keluar dari pementasan","Mengabaikannya"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-goat-in-the-headmasters-office', 'the-goat-in-the-headmasters-office', 'The Goat in the Headmaster''s Office', 'Kambing di Ruang Kepala Sekolah', 'Somebody put a goat in the headmaster''s office. This is the account of the investigation, which took four days and solved nothing.', 'Seseorang menaruh seekor kambing di ruang kepala sekolah. Ini catatan penyelidikannya, yang memakan empat hari dan tidak memecahkan apa pun.', 'cat_humor', 'aut_axto-creative-team', 'citrus', '🐐', 6, 10, 0, 'published', 9, 2812, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_1', 'bok_the-goat-in-the-headmasters-office', 1, 'goat-1', 'On a Monday morning in October, Pak Hendra opened the door of his office and found a goat standing on his desk. The goat looked at him. He looked at the goat. Neither of them said anything.', 'Pada suatu Senin pagi di bulan Oktober, Pak Hendra membuka pintu ruangannya dan menemukan seekor kambing berdiri di atas mejanya. Kambing itu menatapnya. Ia menatap kambing itu. Tidak ada yang berkata apa-apa.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_2', 'bok_the-goat-in-the-headmasters-office', 2, 'goat-2', 'The goat had eaten the top third of a document about fire safety, a bunch of plastic flowers, and — this was the detail that upset him most — one corner of a photograph of his own wedding.', 'Kambing itu telah memakan sepertiga bagian atas dokumen tentang keselamatan kebakaran, seikat bunga plastik, dan — inilah rincian yang paling membuatnya kesal — satu sudut foto pernikahannya sendiri.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_3', 'bok_the-goat-in-the-headmasters-office', 3, 'goat-3', 'An investigation was announced at assembly. Pak Hendra said the school would remain in the hall until somebody came forward. Six hundred children sat in complete silence for eleven minutes, and then somebody laughed, and then it was over.', 'Penyelidikan diumumkan saat apel pagi. Pak Hendra berkata seluruh sekolah akan tetap di aula sampai ada yang mengaku. Enam ratus anak duduk dalam keheningan total selama sebelas menit, lalu ada yang tertawa, dan selesailah sudah.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_4', 'bok_the-goat-in-the-headmasters-office', 4, 'goat-4', 'Evidence was collected. The goat belonged to a farm two kilometres away. The farmer said she had been missing since Sunday afternoon and that this was the fourth time and he was not surprised.', 'Bukti dikumpulkan. Kambing itu milik sebuah peternakan dua kilometer jauhnya. Peternaknya berkata kambing itu hilang sejak Minggu sore dan bahwa ini kali keempat dan ia tidak heran.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_5', 'bok_the-goat-in-the-headmasters-office', 5, 'goat-5', 'The office had been locked. The window was too small. The only key was on Pak Hendra''s own keyring, which had not left his pocket, and this fact was raised at the staff meeting and then quickly dropped.', 'Ruangan itu terkunci. Jendelanya terlalu kecil. Satu-satunya kunci ada di gantungan kunci Pak Hendra sendiri, yang tidak pernah keluar dari sakunya, dan fakta ini disinggung di rapat guru lalu cepat-cepat ditinggalkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_6', 'bok_the-goat-in-the-headmasters-office', 6, 'goat-6', 'Four days of investigation produced: two confessions from children who obviously had not done it, one theory involving the caretaker''s brother, and a drawing of the goat that was pinned up in year three and became quite famous.', 'Empat hari penyelidikan menghasilkan: dua pengakuan dari anak-anak yang jelas bukan pelakunya, satu teori yang melibatkan adik penjaga sekolah, dan sebuah gambar kambing yang dipajang di kelas tiga dan menjadi cukup terkenal.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_7', 'bok_the-goat-in-the-headmasters-office', 7, 'goat-7', 'On the fifth day Pak Hendra stopped the investigation. He announced this at assembly too. He said, "I have concluded that this school contains at least one person cleverer than me, and I would rather not find out who."', 'Pada hari kelima Pak Hendra menghentikan penyelidikan. Ia mengumumkannya juga saat apel. Ia berkata, "Saya menyimpulkan bahwa sekolah ini punya setidaknya satu orang yang lebih pandai daripada saya, dan saya lebih memilih tidak tahu siapa."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_8', 'bok_the-goat-in-the-headmasters-office', 8, 'goat-8', 'Six hundred children applauded for a very long time. It is generally agreed to be the finest thing any headmaster of that school has ever said, and it is quoted at reunions by people who were not even there.', 'Enam ratus anak bertepuk tangan sangat lama. Umumnya disepakati itu ucapan terbaik yang pernah dilontarkan kepala sekolah mana pun di sekolah itu, dan dikutip di reuni-reuni oleh orang-orang yang bahkan tidak hadir saat itu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-goat-in-the-headmasters-office_9', 'bok_the-goat-in-the-headmasters-office', 9, 'goat-9', 'Nobody ever found out. Pak Hendra retired eleven years later. In his last assembly he said he had one regret, and everybody knew what it was before he said it, and six hundred children shouted the word GOAT.', 'Tidak ada yang pernah tahu. Pak Hendra pensiun sebelas tahun kemudian. Di apel terakhirnya ia berkata ia punya satu penyesalan, dan semua orang sudah tahu apa itu sebelum ia mengucapkannya, dan enam ratus anak berteriak KAMBING.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-goat-in-the-headmasters-office_1', 'bok_the-goat-in-the-headmasters-office', 1, 'What had the goat eaten?', 'Apa yang telah dimakan kambing itu?', '["The chairs","A document, plastic flowers and a photo corner","The curtains","Nothing"]', '["Kursi-kursinya","Sebuah dokumen, bunga plastik, dan sudut sebuah foto","Gordennya","Tidak ada"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-goat-in-the-headmasters-office_2', 'bok_the-goat-in-the-headmasters-office', 2, 'Why was the mystery so hard to solve?', 'Mengapa misteri itu sulit dipecahkan?', '["Nobody looked","The office was locked and the only key was in his pocket","The goat ran away","There were no witnesses at all"]', '["Tidak ada yang mencari","Ruangan terkunci dan satu-satunya kunci ada di sakunya","Kambingnya kabur","Sama sekali tidak ada saksi"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-goat-in-the-headmasters-office_3', 'bok_the-goat-in-the-headmasters-office', 3, 'How did Pak Hendra end the investigation?', 'Bagaimana Pak Hendra mengakhiri penyelidikan?', '["He punished everyone","He admitted somebody was cleverer than him and stopped","He found the culprit","He resigned"]', '["Ia menghukum semua orang","Ia mengakui ada yang lebih pandai darinya lalu berhenti","Ia menemukan pelakunya","Ia mengundurkan diri"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-ferry-that-crossed-in-fog', 'the-ferry-that-crossed-in-fog', 'The Ferry That Crossed in Fog', 'Feri yang Menyeberang dalam Kabut', 'Captain Marlina has crossed the strait four thousand times. On the morning the fog comes down, a boy learns how she does it.', 'Kapten Marlina telah menyeberangi selat itu empat ribu kali. Pada pagi ketika kabut turun, seorang anak belajar bagaimana ia melakukannya.', 'cat_vehicles', 'aut_axto-creative-team', 'ocean', '⛴️', 6, 10, 0, 'published', 9, 1514, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_1', 'bok_the-ferry-that-crossed-in-fog', 1, 'ferry-1', 'The ferry crossed the strait six times a day, and Captain Marlina had been steering it for nineteen years. Her son Adi was allowed on the bridge on Saturdays if he stood in the corner and did not touch anything.', 'Feri itu menyeberangi selat enam kali sehari, dan Kapten Marlina telah mengemudikannya selama sembilan belas tahun. Anaknya, Adi, boleh naik ke anjungan pada hari Sabtu asalkan ia berdiri di sudut dan tidak menyentuh apa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_2', 'bok_the-ferry-that-crossed-in-fog', 2, 'ferry-2', 'On the Saturday in question, the fog came down between the harbour and the first buoy. It came down the way fog does — not gradually, but all at once, so that the far shore simply stopped existing.', 'Pada Sabtu yang dimaksud, kabut turun di antara pelabuhan dan pelampung pertama. Ia turun seperti kabut biasanya — bukan berangsur, melainkan sekaligus, sehingga pantai seberang begitu saja berhenti ada.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_3', 'bok_the-ferry-that-crossed-in-fog', 3, 'ferry-3', 'Adi expected his mother to stop. She did not. She reduced speed, put on the lights, sounded the horn twice, and kept going at the same heading she had been on before the fog arrived.', 'Adi mengira ibunya akan berhenti. Tidak. Ia mengurangi kecepatan, menyalakan lampu, membunyikan klakson dua kali, dan terus melaju pada haluan yang sama seperti sebelum kabut datang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_4', 'bok_the-ferry-that-crossed-in-fog', 4, 'ferry-4', '"How do you know where it is?" Adi asked. His mother pointed at three things without taking her eyes off the grey. "Compass. Clock. And that," she said, tapping a screen with a slowly turning green line on it.', '"Bagaimana Ibu tahu letaknya?" tanya Adi. Ibunya menunjuk tiga benda tanpa mengalihkan pandangan dari kelabu di depan. "Kompas. Jam. Dan itu," katanya sambil mengetuk layar dengan garis hijau yang berputar perlahan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_5', 'bok_the-ferry-that-crossed-in-fog', 5, 'ferry-5', '"The compass says which way. The clock says how far, because I know exactly how fast we go. And the radar says what is out there that I cannot see. Three things that do not need eyes."', '"Kompas menunjukkan ke arah mana. Jam menunjukkan seberapa jauh, karena saya tahu persis berapa kecepatan kami. Dan radar menunjukkan apa yang ada di luar sana yang tidak bisa saya lihat. Tiga hal yang tidak butuh mata."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_6', 'bok_the-ferry-that-crossed-in-fog', 6, 'ferry-6', 'At nine minutes past, she said, "Bell buoy in about forty seconds, off the port bow." Adi counted. At thirty-six seconds a bell rang somewhere out in the white, very close, exactly where she had said.', 'Pada menit kesembilan, ia berkata, "Pelampung lonceng sekitar empat puluh detik lagi, di sisi kiri haluan." Adi menghitung. Pada detik ketiga puluh enam sebuah lonceng berbunyi di suatu tempat dalam putih itu, sangat dekat, persis di tempat yang ia sebutkan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_7', 'bok_the-ferry-that-crossed-in-fog', 7, 'ferry-7', '"That is not magic," she said, seeing his face. "That is nineteen years of doing the same crossing and writing down the times. I have made a map of this water in my head. The fog does not move the water."', '"Itu bukan sihir," katanya, melihat wajah Adi. "Itu sembilan belas tahun menyeberang di rute yang sama sambil mencatat waktunya. Saya sudah membuat peta perairan ini di kepala saya. Kabut tidak memindahkan airnya."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_8', 'bok_the-ferry-that-crossed-in-fog', 8, 'ferry-8', 'They docked eleven minutes late, which is nothing. The passengers on the deck below had spent the whole crossing looking at nothing at all and had no idea anything had been required of anybody.', 'Mereka merapat terlambat sebelas menit, yang berarti tidak apa-apa. Penumpang di dek bawah menghabiskan seluruh penyeberangan memandangi ketiadaan dan sama sekali tidak tahu bahwa ada yang dituntut dari siapa pun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-ferry-that-crossed-in-fog_9', 'bok_the-ferry-that-crossed-in-fog', 9, 'ferry-9', 'Adi is a deck officer now on a bigger vessel. He keeps a notebook of crossing times, in pencil, the way his mother taught him, even though the ship he works on has equipment that costs more than a house.', 'Adi kini perwira dek di kapal yang lebih besar. Ia menyimpan buku catatan waktu penyeberangan, dengan pensil, seperti yang diajarkan ibunya, meskipun kapal tempatnya bekerja punya peralatan yang harganya melebihi sebuah rumah.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ferry-that-crossed-in-fog_1', 'bok_the-ferry-that-crossed-in-fog', 1, 'What did Captain Marlina do when the fog came?', 'Apa yang Kapten Marlina lakukan ketika kabut datang?', '["Turned back","Slowed down, sounded the horn and kept her heading","Stopped completely","Went faster"]', '["Berbalik arah","Memperlambat, membunyikan klakson, dan mempertahankan haluan","Berhenti total","Menambah kecepatan"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ferry-that-crossed-in-fog_2', 'bok_the-ferry-that-crossed-in-fog', 2, 'What three things did she rely on?', 'Tiga hal apa yang ia andalkan?', '["Eyes, ears and luck","Compass, clock and radar","Maps, stars and wind","The passengers"]', '["Mata, telinga, dan keberuntungan","Kompas, jam, dan radar","Peta, bintang, dan angin","Para penumpang"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-ferry-that-crossed-in-fog_3', 'bok_the-ferry-that-crossed-in-fog', 3, 'How did she know where the bell buoy was?', 'Bagaimana ia tahu letak pelampung lonceng?', '["She guessed","Nineteen years of recording crossing times","She could see it","Somebody radioed"]', '["Ia menebak","Sembilan belas tahun mencatat waktu penyeberangan","Ia bisa melihatnya","Ada yang mengabari lewat radio"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-nurse-who-remembered-names', 'the-nurse-who-remembered-names', 'The Nurse Who Remembered Names', 'Perawat yang Mengingat Nama', 'On a ward where everybody is busy, one nurse does one small thing differently, and a frightened boy notices.', 'Di bangsal tempat semua orang sibuk, seorang perawat melakukan satu hal kecil secara berbeda, dan seorang anak yang ketakutan menyadarinya.', 'cat_community-helpers', 'aut_axto-creative-team', 'ocean', '🩺', 5, 9, 0, 'published', 9, 2320, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_1', 'bok_the-nurse-who-remembered-names', 1, 'nurse-1', 'Beni was in hospital for nine days with something that turned out to be fine but did not feel fine at the time. He was seven. The ward was bright and loud and full of people moving quickly.', 'Beni dirawat di rumah sakit selama sembilan hari karena sesuatu yang ternyata tidak berbahaya tetapi saat itu sama sekali tidak terasa begitu. Ia berumur tujuh tahun. Bangsalnya terang dan berisik dan penuh orang yang bergerak cepat.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_2', 'bok_the-nurse-who-remembered-names', 2, 'nurse-2', 'Everybody was kind. Everybody was in a hurry. Doctors came and said things to his mother over his head, and he understood about a third of it, which is the worst possible amount to understand.', 'Semua orang baik. Semua orang terburu-buru. Para dokter datang dan mengatakan sesuatu kepada ibunya di atas kepalanya, dan ia memahami sekitar sepertiganya, yang merupakan porsi pemahaman paling buruk yang mungkin.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_3', 'bok_the-nurse-who-remembered-names', 3, 'nurse-3', 'There was a nurse called Bu Winda who did one thing differently. Every time she came to the bed, she said his name first. Not "how are we today" — she said, "Beni. It is Winda. I am going to check your arm."', 'Ada seorang perawat bernama Bu Winda yang melakukan satu hal secara berbeda. Setiap kali datang ke tempat tidurnya, ia menyebut namanya lebih dulu. Bukan "bagaimana kabar kita hari ini" — ia berkata, "Beni. Ini Winda. Saya mau periksa lenganmu."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_4', 'bok_the-nurse-who-remembered-names', 4, 'nurse-4', 'And then she said what she was going to do before she did it. Every time. "This will be cold. This will be a small sharp thing for two seconds. This will not hurt at all and I will tell you if that changes."', 'Lalu ia mengatakan apa yang akan ia lakukan sebelum melakukannya. Setiap kali. "Ini akan terasa dingin. Ini akan terasa tajam sebentar, dua detik. Ini sama sekali tidak sakit dan saya akan bilang kalau itu berubah."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_5', 'bok_the-nurse-who-remembered-names', 5, 'nurse-5', 'It sounds like almost nothing. It was not almost nothing. It was the difference between being a thing on a bed that people did things to, and being a person on a bed who knew what was about to happen.', 'Kedengarannya hampir tidak berarti. Itu bukan hampir tidak berarti. Itu adalah perbedaan antara menjadi benda di atas ranjang yang dikerjai orang, dan menjadi seorang manusia di atas ranjang yang tahu apa yang akan terjadi.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_6', 'bok_the-nurse-who-remembered-names', 6, 'nurse-6', 'On the fourth night Beni was frightened and could not say why, and Bu Winda did not ask why. She sat on the chair for four minutes and said nothing at all, and then said, "Right," and went back to work.', 'Pada malam keempat Beni ketakutan dan tidak bisa menjelaskan sebabnya, dan Bu Winda tidak bertanya mengapa. Ia duduk di kursi selama empat menit tanpa berkata apa-apa, lalu berkata, "Baik," dan kembali bekerja.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_7', 'bok_the-nurse-who-remembered-names', 7, 'nurse-7', 'Beni''s mother said afterwards that she had watched Bu Winda do this with eleven other beds, and that she never once looked as if she was in a hurry, and that she must have been, because everybody was.', 'Ibu Beni kemudian berkata bahwa ia mengamati Bu Winda melakukan hal yang sama di sebelas ranjang lain, dan bahwa ia tidak pernah sekali pun tampak terburu-buru, padahal pasti ia terburu-buru, karena semua orang begitu.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_8', 'bok_the-nurse-who-remembered-names', 8, 'nurse-8', 'When Beni went home he made a card. It said THANK YOU BU WINDA and inside, in enormous letters, it said YOU ALWAYS SAID MY NAME FIRST, which is not a thing anybody had ever thanked her for in seventeen years.', 'Ketika Beni pulang ia membuat kartu. Tulisannya TERIMA KASIH BU WINDA dan di dalamnya, dengan huruf besar sekali, tertulis IBU SELALU MENYEBUT NAMA SAYA LEBIH DULU, yang tidak pernah menjadi alasan siapa pun berterima kasih kepadanya selama tujuh belas tahun.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-nurse-who-remembered-names_9', 'bok_the-nurse-who-remembered-names', 9, 'nurse-9', 'It is on the wall of the staff room. It has been there for six years. New nurses ask about it, and somebody explains, and then most of them start saying the name first, which is how a small thing gets bigger.', 'Kartu itu terpasang di dinding ruang staf. Sudah enam tahun di sana. Perawat-perawat baru menanyakannya, ada yang menjelaskan, lalu kebanyakan dari mereka mulai menyebut nama lebih dulu, dan begitulah caranya sebuah hal kecil menjadi lebih besar.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-nurse-who-remembered-names_1', 'bok_the-nurse-who-remembered-names', 1, 'What did Bu Winda always do first?', 'Apa yang selalu Bu Winda lakukan lebih dulu?', '["Check the chart","Say his name","Call the doctor","Open the window"]', '["Memeriksa catatan medis","Menyebut namanya","Memanggil dokter","Membuka jendela"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-nurse-who-remembered-names_2', 'bok_the-nurse-who-remembered-names', 2, 'What else did she do differently?', 'Apa lagi yang ia lakukan secara berbeda?', '["Worked faster","Told him what would happen before it did","Brought toys","Stayed all night"]', '["Bekerja lebih cepat","Memberitahunya apa yang akan terjadi sebelum terjadi","Membawa mainan","Menemani semalaman"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-nurse-who-remembered-names_3', 'bok_the-nurse-who-remembered-names', 3, 'What happened to Beni''s card?', 'Apa yang terjadi pada kartu Beni?', '["It was lost","It has been on the staff room wall for six years","It was thrown away","It was returned"]', '["Hilang","Terpasang di dinding ruang staf selama enam tahun","Dibuang","Dikembalikan"]', 1, 10);

INSERT OR IGNORE INTO books (id, slug, title_en, title_id, description_en, description_id, category_id, author_id, cover_palette, cover_emoji, age_min, age_max, is_premium, status, page_count, read_count, created_at, updated_at) VALUES ('bok_the-race-i-did-not-finish', 'the-race-i-did-not-finish', 'The Race I Did Not Finish', 'Lomba yang Tidak Aku Selesaikan', 'Halfway through the cross-country, Tama''s knee gives out. What he does in the next four minutes is the part people still talk about.', 'Di tengah lomba lintas alam, lutut Tama tidak kuat lagi. Yang ia lakukan dalam empat menit berikutnya adalah bagian yang masih dibicarakan orang.', 'cat_health-body', 'aut_axto-creative-team', 'meadow', '🦵', 7, 11, 0, 'published', 9, 1651, 1785528005034, 1785528005034);
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_1', 'bok_the-race-i-did-not-finish', 1, 'knee-1', 'Tama had trained for the cross-country since August. Four mornings a week, up the hill behind the estate, in the dark half the time. He was going to come in the first three. Everybody said so, including him.', 'Tama berlatih untuk lomba lintas alam sejak Agustus. Empat pagi seminggu, mendaki bukit di belakang perumahan, separuh waktunya dalam gelap. Ia akan finis tiga besar. Semua orang mengatakannya, termasuk dirinya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_2', 'bok_the-race-i-did-not-finish', 2, 'knee-2', 'At the two-kilometre mark his right knee did something it had been threatening to do for a fortnight. He had felt it twice in training and had told nobody, because telling somebody meant not running.', 'Di kilometer kedua lutut kanannya melakukan hal yang sudah dua minggu ia rasakan akan terjadi. Ia merasakannya dua kali saat latihan dan tidak memberi tahu siapa pun, karena memberi tahu berarti tidak boleh berlari.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_3', 'bok_the-race-i-did-not-finish', 3, 'knee-3', 'He went down in the mud. Runners went past him on both sides. He got up, ran nine more steps, and went down again, and the second time it was very clear that this was not something he could run through.', 'Ia jatuh di lumpur. Para pelari melewatinya dari kedua sisi. Ia bangkit, berlari sembilan langkah lagi, lalu jatuh lagi, dan pada kali kedua sudah sangat jelas bahwa ini bukan sesuatu yang bisa ia paksakan.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_4', 'bok_the-race-i-did-not-finish', 4, 'knee-4', 'Here is what happened in the next four minutes. A girl from another school, who was in fourth place and running a personal best, stopped beside him. She was called Reni. He had never met her.', 'Inilah yang terjadi dalam empat menit berikutnya. Seorang gadis dari sekolah lain, yang berada di posisi keempat dan sedang mencetak catatan terbaiknya, berhenti di sampingnya. Namanya Reni. Tama belum pernah bertemu dengannya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_5', 'bok_the-race-i-did-not-finish', 5, 'knee-5', 'She did not help him up, which was the right thing, because you do not move somebody whose knee has gone. She knelt in the mud, said do not get up, and shouted for a marshal until one came.', 'Ia tidak membantunya berdiri, dan itu tindakan yang benar, karena kau tidak boleh memindahkan orang yang lututnya cedera. Ia berlutut di lumpur, berkata jangan bangun, dan berteriak memanggil petugas sampai ada yang datang.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_6', 'bok_the-race-i-did-not-finish', 6, 'knee-6', 'She lost about four minutes and finished nineteenth. Her own coach was furious, then stopped being furious about an hour later, which is roughly the correct sequence for a coach.', 'Ia kehilangan sekitar empat menit dan finis di urutan sembilan belas. Pelatihnya sendiri marah besar, lalu berhenti marah sekitar satu jam kemudian, yang kira-kira merupakan urutan yang tepat bagi seorang pelatih.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_7', 'bok_the-race-i-did-not-finish', 7, 'knee-7', 'Tama''s knee needed eleven weeks and a physiotherapist called Pak Doni who explained, in detail, that the injury had been building since August and that the two warnings he had ignored were the whole story.', 'Lutut Tama butuh sebelas minggu dan seorang fisioterapis bernama Pak Doni yang menjelaskan, dengan rinci, bahwa cedera itu sudah menumpuk sejak Agustus dan bahwa dua peringatan yang ia abaikan adalah inti seluruh ceritanya.');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_8', 'bok_the-race-i-did-not-finish', 8, 'knee-8', '"Pain is information," Pak Doni said. "It is not weakness and it is not the enemy. It is your body sending you a message, and you read two of them and put them in your pocket."', '"Nyeri itu informasi," kata Pak Doni. "Ia bukan kelemahan dan bukan musuh. Ia pesan dari tubuhmu, dan kau membaca dua di antaranya lalu memasukkannya ke saku."');
INSERT OR IGNORE INTO book_pages (id, book_id, page_number, illustration_seed, text_en, text_id) VALUES ('pag_the-race-i-did-not-finish_9', 'bok_the-race-i-did-not-finish', 9, 'knee-9', 'Tama runs again now. He also stops when something is wrong, which costs him races and has kept him running for four years. And every year, at the cross-country, he looks for a girl from another school to say hello to.', 'Tama kini berlari lagi. Ia juga berhenti ketika ada yang tidak beres, yang membuatnya kehilangan beberapa lomba dan membuatnya tetap bisa berlari selama empat tahun. Dan setiap tahun, di lomba lintas alam, ia mencari seorang gadis dari sekolah lain untuk disapa.');
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-race-i-did-not-finish_1', 'bok_the-race-i-did-not-finish', 1, 'Why did Tama''s knee give way?', 'Mengapa lutut Tama cedera?', '["He tripped","An injury had been building and he ignored two warnings","The mud","Somebody pushed him"]', '["Ia tersandung","Cederanya sudah menumpuk dan ia mengabaikan dua peringatan","Karena lumpur","Ada yang mendorongnya"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-race-i-did-not-finish_2', 'bok_the-race-i-did-not-finish', 2, 'What did Reni do?', 'Apa yang Reni lakukan?', '["Ran past","Stopped, kept him still and called a marshal","Carried him","Finished first"]', '["Berlari melewatinya","Berhenti, menahannya agar tidak bergerak, dan memanggil petugas","Menggendongnya","Finis pertama"]', 1, 10);
INSERT OR IGNORE INTO quiz_questions (id, book_id, sort_order, question_en, question_id, options_en_json, options_id_json, correct_index, xp_reward) VALUES ('qz_the-race-i-did-not-finish_3', 'bok_the-race-i-did-not-finish', 3, 'What did Pak Doni say pain is?', 'Menurut Pak Doni, nyeri itu apa?', '["Weakness","Information from your body","Something to ignore","Always serious"]', '["Kelemahan","Informasi dari tubuhmu","Sesuatu yang harus diabaikan","Selalu berbahaya"]', 1, 10);

